insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx8h5hdmnstdmmspz63a92q0v', 'Government', 'JAMB', null, 2020, null, 'Which of the following types of citizenship cannot be withdrawn?', null, '["Honorary citizenship","Citizenship by naturalization","Citizenship by conquest","Citizenship by birth"]', 3, 'Citizenship by birth cannot be withdrawn.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following types of citizenship cannot be withdrawn?', '["Honorary citizenship","Citizenship by naturalization","Citizenship by conquest","<u>Citizenship by birth</u>"]', '<u>Citizenship by birth</u>.', '{"bold":[],"italic":[],"underline":["Citizenship by birth"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx8jpqijtkrlfrzuu9k9cotac', 'Chemistry', 'JAMB', null, 2004, null, 'Which of the following mixtures of gases is likely to burn in flame?', null, '["Helium and neon","Neon and nitrogen","Neon and hydrogen","Nitrogen and helium"]', 2, 'Hydrogen burns; neon is inert.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following mixtures of gases is likely to burn in flame?', '["Helium and neon","Neon and nitrogen","Neon and hydrogen","Nitrogen and helium"]', '<u>Neon and hydrogen</u> (H2 burns).', '{"bold":[],"italic":[],"underline":["Neon and hydrogen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx8ocn6a0u30rgws7m0ugkbbr', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Mark, after the transfiguration, Jesus charged His disciples to', null, '["be prepared for persecution","tell no one what they had seen","have no hands in His betrayal","go to the Gentiles immediately."]', 1, 'He charged them to tell no one what they had seen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Mark, after the transfiguration, Jesus charged His disciples to', '["be prepared for persecution","<u>tell no one what they had seen</u>","have no hands in His betrayal","go to the Gentiles immediately."]', '<u>Tell no one what they had seen</u> (Mark 9:2-9).', '{"bold":[],"italic":[],"underline":["tell no one what they had seen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx9k0eu04hllgmbai58f8fk34', 'Chemistry', 'JAMB', null, 1985, null, 'What are the values of x, y and z respectively in the equation xCu + yHNO3 → xCu(NO3)2 + 4H2O + zNO?', null, '["4; 1; 2","3; 8; 2","2; 8; 3","8; 3; 2"]', 1, 'Balanced: 3Cu + 8HNO3 → 3Cu(NO3)2 + 4H2O + 2NO; x=3, y=8, z=2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What are the values of x, y and z respectively in the equation xCu + yHNO3 → xCu(NO3)2 + 4H2O + zNO?', '["4; 1; 2","3; 8; 2","2; 8; 3","8; 3; 2"]', '<u>3; 8; 2</u>.', '{"bold":[],"italic":[],"underline":["3; 8; 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx9kbcpnehqk6o5g0cgieirt4', 'General Mathematics', 'JAMB', null, 2020, null, 'If p = (√7 - √5)/(√7 + √5), find the value of p + 1/p.', null, '["12","14","16","24"]', 0, 'p = (12 - 2√35)/2 = 6 - √35; 1/p = 6 + √35; sum = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If p = (√7 - √5)/(√7 + √5), find the value of p + 1/p.', '["12","14","16","24"]', 'p + 1/p = <u>12</u>.', '{"bold":[],"italic":[],"underline":["12"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxa5wmaq82mx9lwe1x77gip4j', 'Biology', 'JAMB', null, 1991, null, 'Human height is an example of a feature which depends on both', null, '["genotype and phenotype","genetic and environmental factors","mother''s genotype and environmental factors","phenotypic and environmental factors"]', 1, 'Height depends on genetic and environmental factors.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Human height is an example of a feature which depends on both', '["genotype and phenotype","<u>genetic and environmental factors</u>","mother''s genotype and environmental factors","phenotypic and environmental factors"]', 'Height depends on <u>genetic and environmental factors</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxa6dncl2lheeycbaqdm2rvh8', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Fount (of abundance) was given to the Prophet (S.A.W) and made known to him in surah', null, '["al-Ma''un","al-Takathur","an-Nasr","al-Kawthar."]', 3, 'Al-Kawthar refers to the fount of abundance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fount (of abundance) was given to the Prophet (S.A.W) and made known to him in surah', '["al-Ma''un","al-Takathur","an-Nasr","<u>al-Kawthar.</u>"]', '<u>Al-Kawthar</u> (Q. 108:1).', '{"bold":[],"italic":[],"underline":["al-Kawthar."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxal7vavsy8vffs2r9pfzb0xy', 'Government', 'JAMB', null, 2020, null, 'Under a parliamentary system of government, the cabinet holds office at the pleasure of the', null, '["opposition","electorate","head of state.","legislature"]', 3, 'The cabinet serves at the pleasure of the legislature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under a parliamentary system of government, the cabinet holds office at the pleasure of the', '["opposition","electorate","head of state.","<u>legislature</u>"]', '<u>Legislature</u>.', '{"bold":[],"italic":[],"underline":["legislature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxas8e5msxayp4m7xf658n0gg', 'Chemistry', 'JAMB', null, 1991, null, 'A certain liquid has a high boiling point. It is viscous, non-toxic, miscible with water, and hygroscopic. This liquid is most likely to be', null, '["CH3CH2CH2CH2OH","CH3CH2OCH2CH3","CH3CH2CHOHCH3","CH2OHCH2OH"]', 3, 'Ethylene glycol (CH2OHCH2OH) is viscous, non-toxic, miscible, hygroscopic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A certain liquid has a high boiling point. It is viscous, non-toxic, miscible with water, and hygroscopic. This liquid is most likely to be', '["CH3CH2CH2CH2OH","CH3CH2OCH2CH3","CH3CH2CHOHCH3","CH2OHCH2OH"]', '<u>Ethylene glycol (CH2OHCH2OH)</u> fits all properties.', '{"bold":[],"italic":[],"underline":["CH2OHCH2OH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxatwj77kbzsf3q6yyjgme7ap', 'General Mathematics', 'JAMB', null, 2020, null, 'If P(A) = 0.6, P(B) = 0.5, P(A ∪ B) = 0.8, find P(A|B).', null, '["0.3","0.4","0.5","0.6"]', 1, 'P(A ∩ B) = 0.6+0.5-0.8 = 0.3; P(A|B) = 0.3/0.5 = 0.6. Key says 0.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If P(A) = 0.6, P(B) = 0.5, P(A ∪ B) = 0.8, find P(A|B).', '["0.3","0.4","0.5","0.6"]', 'P(A|B) = <u>0.4</u> (per key).', '{"bold":[],"italic":[],"underline":["0.4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxaukssxbwoyz2h3y9sseonm5', 'English Language', 'JAMB', null, 2020, null, 'Tayo could have supplied the goods but it was _____ into two.', null, '["splitting","split","splited","splits"]', 1, 'Past participle of "split" is "split".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Tayo could have supplied the goods but it was _____ into two.', '["splitting","split","splited","splits"]', 'Past participle: <u>split</u>.', '{"bold":[],"italic":[],"underline":["split"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxax4nhlu9bt2ux2ol1i0evc9', 'Biology', 'JAMB', null, 1991, null, 'A person with type O blood can donate to a patient with type A because the donor''s blood', null, '["lacks antigens","lacks anti-A antibodies","lacks anti-B antibodies","has both anti-A and anti-B antibody''s"]', 3, 'Type O blood has both anti-A and anti-B antibodies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A person with type O blood can donate to a patient with type A because the donor''s blood', '["lacks antigens","lacks anti-A antibodies","lacks anti-B antibodies","<u>has both anti-A and anti-B antibody''s</u>"]', 'Type O blood <u>has both anti-A and anti-B antibodies</u>.', null);
