insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxayrrssmnhxwo5zhv3crwree', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When the Babylonians captured King Zedekiah, they', null, '["killed him immediately","put out his eyes","assaulted his wives in his presence","took his sons to Babylon."]', 1, 'They put out Zedekiah''s eyes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When the Babylonians captured King Zedekiah, they', '["killed him immediately","<u>put out his eyes</u>","assaulted his wives in his presence","took his sons to Babylon."]', '<u>Put out his eyes</u> (2 Kings 25:6-7).', '{"bold":[],"italic":[],"underline":["put out his eyes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxbmt4i77pqlhg7u8xjnomhse', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the geometric mean of 4 and 16.', null, '["8","10","12","14"]', 0, 'GM = √(4×16) = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the geometric mean of 4 and 16.', '["8","10","12","14"]', 'GM = <u>8</u>.', null);
