insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxerv0lssco8kykxgz0rark6g', 'Government', 'JAMB', null, 2020, null, 'How does the president relieve a minister of his appointment in a presidential system of government?', null, '["In consultation with the legislature.","After serving a full tenure","In consultation with the judiciary","Solely by the president''s discretion"]', 3, 'The president acts solely on his discretion to remove ministers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How does the president relieve a minister of his appointment in a presidential system of government?', '["In consultation with the legislature.","After serving a full tenure","In consultation with the judiciary","<u>Solely by the president''s discretion</u>"]', '<u>Solely by the president''s discretion</u>.', '{"bold":[],"italic":[],"underline":["Solely by the president''s discretion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxexm98s8m4ar07y063p05ilh', 'Chemistry', 'JAMB', null, 1990, null, 'If 10.8g of silver is deposited in a silver coulometer connected in series with a copper coulometer, the volume of oxygen liberated is [Ag=108, Cu=64, G.M.V at s.t.p = 22.40 dm³]', null, '["0.56dm³","5.50dm³","11.20dm³","22.40dm³"]', 0, 'Moles Ag = 0.1; electrons = 0.1; moles O2 = 0.025; volume = 0.025 × 22.4 = 0.56 dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 10.8g of silver is deposited in a silver coulometer connected in series with a copper coulometer, the volume of oxygen liberated is [Ag=108, Cu=64, G.M.V at s.t.p = 22.40 dm³]', '["0.56dm³","5.50dm³","11.20dm³","22.40dm³"]', 'Volume O2 = <u>0.56 dm³</u>.', '{"bold":[],"italic":[],"underline":["0.56dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxeyryr55p1alz11zdyo2js32', 'Biology', 'JAMB', null, 1984, null, 'The process of soil erosion is usually from', null, '["rill → sheet → gully","gully → rill → sheet","sheet → gully → rill","sheet → rill → gully","rill → gully → sheet"]', 3, 'Soil erosion progresses: sheet → rill → gully.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The process of soil erosion is usually from', '["rill → sheet → gully","gully → rill → sheet","sheet → gully → rill","<u>sheet → rill → gully</u>","rill → gully → sheet"]', 'Soil erosion progresses: <u>sheet → rill → gully</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxfj5seazxlqmac9eu78y34xd', 'Chemistry', 'JAMB', null, 1993, null, 'Which of the following substances is a <b>mixture</b>?', null, '["Sulphur powder","Bronze","Distilled water","Ethanol"]', 1, 'Bronze is an alloy (mixture).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following substances is a <b>mixture</b>?', '["Sulphur powder","Bronze","Distilled water","Ethanol"]', '<u>Bronze (alloy)</u> is a mixture.', '{"bold":["mixture"],"italic":[],"underline":["Bronze"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxflnmhr8yqkt5y2md82ep39l', 'General Mathematics', 'JAMB', null, 2020, null, 'Mean = 10, variance = 4. Find the coefficient of variation.', null, '["20%","30%","40%","50%"]', 0, 'SD = 2; CV = (2/10)×100 = 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mean = 10, variance = 4. Find the coefficient of variation.', '["20%","30%","40%","50%"]', 'CV = <u>20%</u>.', '{"bold":[],"italic":[],"underline":["20%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxflw8k8j2n5h26rwctkrq4pk', 'General Mathematics', 'WAEC', null, 2020, null, 'Subtract 0.101₂ from 1.001₂ in base two.', null, '["0.100₂","0.110₂","0.010₂","1.000₂"]', 0, '1.001₂ - 0.101₂ = 0.100₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Subtract 0.101₂ from 1.001₂ in base two.', '["0.100₂","0.110₂","0.010₂","1.000₂"]', '1.001₂ - 0.101₂ = <u>0.100₂</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxfpt18fsd9jgyxb9k37csb58', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q.24:30 enjoins Muslims to', null, '["dress properly","be very attentive in prayers","guard against adultery","lower their gaze."]', 3, 'It enjoins lowering the gaze.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.24:30 enjoins Muslims to', '["dress properly","be very attentive in prayers","guard against adultery","<u>lower their gaze.</u>"]', '<u>Lower their gaze</u> (Q. 24:30).', '{"bold":[],"italic":[],"underline":["lower their gaze."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxfw7wr6a90plqjsmlcndy25z', 'Chemistry', 'JAMB', null, 1994, null, 'What volume of oxygen measured at s.t.p would be liberated on electrolysis by 9650 coulombs of electricity?', null, '["22.4dm³","11.2dm³","1.12dm³","0.560dm³"]', 2, 'Moles e⁻ = 0.1; moles O2 = 0.025; volume = 0.56 dm³. Key says 1.12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of oxygen measured at s.t.p would be liberated on electrolysis by 9650 coulombs of electricity?', '["22.4dm³","11.2dm³","1.12dm³","0.560dm³"]', 'Volume = <u>0.56 dm³</u> (key says 1.12).', '{"bold":[],"italic":[],"underline":["1.12dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxg6swyk0tqh35f8h7ntfu3ss', 'Chemistry', 'JAMB', null, 1999, null, 'Chlorine, bromine and iodine resemble one another in that they', null, '["dissolve in alkalis","react violently with hydrogen without heating","are liquids","displace one another from solutions of their salts"]', 3, 'Halogens displace one another from salt solutions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Chlorine, bromine and iodine resemble one another in that they', '["dissolve in alkalis","react violently with hydrogen without heating","are liquids","displace one another from solutions of their salts"]', '<u>Halogens displace one another</u>.', '{"bold":[],"italic":[],"underline":["displace one another from solutions of their salts"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxgh3uvz59eaav40c6tn0fc4n', 'Biology', 'JAMB', null, 2003, null, 'The similarity among organisms belonging to the same group will be least within each', null, '["order","family","species","kingdom"]', 3, 'Similarity is least within a kingdom (broadest group).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The similarity among organisms belonging to the same group will be least within each', '["order","family","species","kingdom"]', '<u>Kingdom</u> (broadest group).', '{"bold":[],"italic":[],"underline":["kingdom"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxgin7wi8mm5erlc2emz3xe2c', 'Chemistry', 'JAMB', null, 1987, null, 'The best treatment for a student who accidentally poured concentrated tetraoxosulphate(VI) acid on his skin in the laboratory is to wash the skin with', null, '["cold water","sodium trioxocarbonate(IV) solution","Iodine solution","Sodium trioxocabonate(IV) solution"]', 3, 'Wash with Na2CO3 solution to neutralize the acid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The best treatment for a student who accidentally poured concentrated tetraoxosulphate(VI) acid on his skin in the laboratory is to wash the skin with', '["cold water","sodium trioxocarbonate(IV) solution","Iodine solution","Sodium trioxocarbonate(IV) solution"]', '<u>Wash with Na2CO3 solution</u> to neutralize the acid.', '{"bold":[],"italic":[],"underline":["sodium trioxocarbonate(IV) solution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxgruo0euvt5pxlv3d8gtgco1', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the cubic equation with roots 1, ω, ω² (cube roots of unity).', null, '["x³-1=0","x³-3x²+3x-1=0","x³-1","x³+1"]', 0, 'Roots 1, ω, ω² → x³ - 1 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the cubic equation with roots 1, ω, ω² (cube roots of unity).', '["x³-1=0","x³-3x²+3x-1=0","x³-1","x³+1"]', '<u>x³ - 1 = 0</u>.', '{"bold":[],"italic":[],"underline":["x³-1=0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxgwlg6lo8goe31qdfpp23vco', 'General Mathematics', 'JAMB', null, 2020, null, 'A random variable X has mean 5 and variance 4. Find E(X²).', null, '["25","29","33","37"]', 1, 'E(X²) = Var(X) + (E(X))² = 4 + 25 = 29.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A random variable X has mean 5 and variance 4. Find E(X²).', '["25","29","33","37"]', 'E(X²) = <u>29</u>.', '{"bold":[],"italic":[],"underline":["29"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxh6u69gq24uzvoyas8psn1ec', 'English Language', 'JAMB', null, 2020, null, 'The students are still _____ in the dark regarding the principal decision.', null, '["very so","much too","very much","much so"]', 2, 'Standard expression: "very much in the dark".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The students are still _____ in the dark regarding the principal decision.', '["very so","much too","very much","much so"]', 'Standard: <u>very much in the dark</u>.', '{"bold":[],"italic":[],"underline":["very much"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxhcgug7c3halxu2m8ffhzw45', 'Government', 'JAMB', null, 2020, null, 'A major function of the Warrant Chiefs was to', null, '["prevent tribal wars","supervise native courts and markets","stop ritual killings","take charge of local administration"]', 3, 'Warrant Chiefs were responsible for local administration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major function of the Warrant Chiefs was to', '["prevent tribal wars","supervise native courts and markets","stop ritual killings","<u>take charge of local administration</u>"]', 'Warrant Chiefs <u>took charge of local administration</u>.', '{"bold":[],"italic":[],"underline":["take charge of local administration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxhebtzgeztmod11yn3zv3rul', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the inverse of 5 under a*b = a + b - 5 on reals, given identity e = 5.', null, '["5","-5","0","10"]', 1, '5*x = 5 → 5+x-5 = 5 → x = 5. Key says -5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the inverse of 5 under a*b = a + b - 5 on reals, given identity e = 5.', '["5","-5","0","10"]', 'Inverse = <u>-5</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxhjqlylur6vcll93xgxviabi', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The contents of surah <b>al-fatihah</b> can be summed up to mean that', null, '["mercy is always from Allah","man must always fear Allah and obey Him","man must worship Allah and seek His help","it is the first surah that was revealed"]', 2, 'Al-Fatihah emphasizes worship of Allah and seeking His help (iyyaka na''budu wa iyyaka nasta''in).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The contents of surah <b>al-fatihah</b> can be summed up to mean that', '["mercy is always from Allah","man must always fear Allah and obey Him","<u>man must worship Allah and seek His help</u>","it is the first surah that was revealed"]', '<u>Al-Fatihah</u> emphasizes worship of Allah and seeking His help.', '{"bold":["al-fatihah"],"italic":[],"underline":["man must worship Allah and seek His help"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxhl60jyy0tcbawsltysug6iv', 'Biology', 'JAMB', null, 2002, null, 'The most common means of transmitting Acquired Immune Deficiency Syndrome (AIDS) is', null, '["from mother to child","through blood transfusion","through sexual intercourse","through the sharing of needles"]', 2, 'through sexual intercourse is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most common means of transmitting Acquired Immune Deficiency Syndrome (AIDS) is', '["from mother to child","through blood transfusion","<u>through sexual intercourse</u>","through the sharing of needles"]', 'through sexual intercourse is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxhoecu3oki4hpguwd4rdzk6y', 'Biology', 'JAMB', null, 1986, null, 'The main organic substances found in the human body are', null, '["carbohydrates, proteins and salts","salts, fats and proteins","fats, carbohydrates and proteins","salts, fats and carbohydrates"]', 2, 'The main organic substances are fats, carbohydrates, and proteins.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main organic substances found in the human body are', '["carbohydrates, proteins and salts","salts, fats and proteins","<u>fats, carbohydrates and proteins</u>","salts, fats and carbohydrates"]', 'The main organic substances are <u>fats, carbohydrates, and proteins</u>.', null);
