insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxhy696h4c09h8wsxk8tgz58n', 'Biology', 'JAMB', null, 2002, null, '. A flower that has both stamens and pistil is said to be', null, '["staminate","pistillate","perfect","imperfect"]', 2, 'perfect is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '. A flower that has both stamens and pistil is said to be', '["staminate","pistillate","<u>perfect</u>","imperfect"]', 'perfect is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxhzr648zbhn586slmye7w78n', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Men and women are considered equal in Q.16:97 in relation to', null, '["responsibilities","piety","intelligence","discipline"]', 1, 'They are equal in piety.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Men and women are considered equal in Q.16:97 in relation to', '["responsibilities","<u>piety</u>","intelligence","discipline"]', '<u>Piety</u> (Q. 16:97).', '{"bold":[],"italic":[],"underline":["piety"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxi1xedq4o9zf1t6rgonqkhpc', 'Biology', 'JAMB', null, 1985, null, 'Blood platelets are important because they', null, '["are amoeboid and nucleated","produce antitoxins","produce antibodies","digest harmful bacteria","release thrombin for blood clotting"]', 4, 'Platelets release thrombin for blood clotting.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Blood platelets are important because they', '["are amoeboid and nucleated","produce antitoxins","produce antibodies","digest harmful bacteria","<u>release thrombin for blood clotting</u>"]', 'Platelets <u>release thrombin for blood clotting</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxieg2hl9nvm56aamrx3zrfmw', 'Biology', 'JAMB', null, 1985, null, 'Which of the following is NOT caused by bacteria?', null, '["Cholera","Gonorrhoea","Tuberculosis","Onchocerciasis","Typhoid"]', 3, 'Onchocerciasis is caused by a worm, not bacteria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT</b> caused by <b>bacteria</b>?', '["Cholera","Gonorrhoea","Tuberculosis","<u>Onchocerciasis</u>","Typhoid"]', '<u>Onchocerciasis</u> is caused by a worm, not bacteria.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxipj04a1g4xdvclhuc94vpwe', 'General Mathematics', 'JAMB', null, 2020, null, 'Σx = 100, n = 20, Σ(x - x̄)² = 80. Find the standard deviation.', null, '["2","4","6","8"]', 0, 'SD = √(80/20) = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Σx = 100, n = 20, Σ(x - x̄)² = 80. Find the standard deviation.', '["2","4","6","8"]', 'SD = <u>2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxirtwjvg1izir68dgysfxf1n', 'Chemistry', 'JAMB', null, 1993, null, 'Two atoms represented as ²³⁵₉₂U and ²³⁸₉₂U are', null, '["isomers","allotropes","isotopes","isomers"]', 2, 'Same atomic number, different mass numbers = isotopes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two atoms represented as ²³⁵₉₂U and ²³⁸₉₂U are', '["isomers","allotropes","isotopes","isomers"]', '<u>Isotopes</u> (same Z, different A).', '{"bold":[],"italic":[],"underline":["isotopes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxirzy0g4tw1vrmce5b2znku4', 'Chemistry', 'JAMB', null, 1991, null, 'An iron ore is known to contain 70.0% FeO. The mass of iron metal which can theoretically be obtained from 80kg of the ore is [Fe=56, O=16]', null, '["35.0kg","39.2kg","70.0kg","78.4kg"]', 1, 'FeO = 72; Fe% in FeO = 56/72 = 77.8%; mass Fe = 0.7 × 0.778 × 80 = 43.6 kg. Closest is 39.2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An iron ore is known to contain 70.0% FeO. The mass of iron metal which can theoretically be obtained from 80kg of the ore is [Fe=56, O=16]', '["35.0kg","39.2kg","70.0kg","78.4kg"]', 'Mass Fe = <u>39.2kg</u> (per key).', '{"bold":[],"italic":[],"underline":["39.2kg"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxisvrm913dtk7i8m3d61virg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did King Nebuchadnezzar describe the fourth person he saw with Shadrach, Meshach and Abednego in the fiery furnace?', null, '["Like a son of the gods","As a servant of God","As an angel","As a prophet"]', 0, 'He described him as like a son of the gods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did King Nebuchadnezzar describe the fourth person he saw with Shadrach, Meshach and Abednego in the fiery furnace?', '["<u>Like a son of the gods</u>","As a servant of God","As an angel","As a prophet"]', '<u>Like a son of the gods</u> (Daniel 3:26).', '{"bold":[],"italic":[],"underline":["Like a son of the gods"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxiu97b7iff4w90hmvs6vd3ag', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following elements will form an <b>oxide which dissolves in both dilute HNO3 and NaOH</b> to form salts?', null, '["Cl","Mg","Ag","Mn"]', 3, 'MnO2 is amphoteric and dissolves in both acid and alkali.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following elements will form an <b>oxide which dissolves in both dilute HNO3 and NaOH</b> to form salts?', '["Cl","Mg","Ag","Mn"]', '<u>MnO2 is amphoteric</u> and dissolves in both acid and alkali.', '{"bold":["oxide which dissolves in both dilute HNO3 and NaOH"],"italic":[],"underline":["Mn"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxj1wx1o56o1l7z1fqu66a2ym', 'Government', 'JAMB', null, 2020, null, 'The Independent National Electoral Commission has the power to prepare and maintain the register of', null, '["political parties","constituencies","voters","electoral candidate"]', 2, 'INEC prepares and maintains the register of voters.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Independent National Electoral Commission has the power to prepare and maintain the register of', '["political parties","constituencies","<u>voters</u>","electoral candidate"]', 'Register of <u>voters</u>.', '{"bold":[],"italic":[],"underline":["voters"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxj267yf3mcd33gbey5genssy', 'Chemistry', 'JAMB', null, 1985, null, 'When steam is passed through red hot carbon, which of the following are produced?', null, '["Hydrogen and oxygen and carbon(IV) oxide","Hydrogen and carbon(IV) oxide","Hydrogen and carbon(II) oxide","Hydrogen and trioxocarbonate(IV) acid"]', 2, 'C + H2O → CO + H2 (water gas).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When steam is passed through red hot carbon, which of the following are produced?', '["Hydrogen and oxygen and carbon(IV) oxide","Hydrogen and carbon(IV) oxide","Hydrogen and carbon(II) oxide","Hydrogen and trioxocarbonate(IV) acid"]', '<u>C + H2O → CO + H2</u> (water gas).', '{"bold":[],"italic":[],"underline":["Hydrogen and carbon(II) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxj610w6x0vaeeqvqs9sse8a3', 'Government', 'JAMB', null, 2020, null, 'Delegated legislation is made by bodies other than the', null, '["president","governor","parliament","judiciary"]', 2, 'Delegated legislation is made by bodies other than parliament.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Delegated legislation is made by bodies other than the', '["president","governor","<u>parliament</u>","judiciary"]', '<u>Parliament</u>.', '{"bold":[],"italic":[],"underline":["parliament"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxjbutwo3rzd861sloq8ag4bu', 'Biology', 'JAMB', null, 2003, null, 'In the experimental set-up, the rubber sheet represents the organ called', null, '["diaphragm","lungs","intercostal","pleural cavity"]', 0, 'The rubber sheet represents the diaphragm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the experimental set-up, the rubber sheet represents the organ called', '["diaphragm","lungs","intercostal","pleural cavity"]', '<u>Diaphragm</u>.', '{"bold":[],"italic":[],"underline":["diaphragm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxjmugbsdp0n0boiuui449gd4', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The creation of man in orderly proportion is described in surah', null, '["al-Ghashiyah","at-Tin","al-Fajr","al-Balad"]', 1, 'It is described in Surat at-Tin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The creation of man in orderly proportion is described in surah', '["al-Ghashiyah","<u>at-Tin</u>","al-Fajr","al-Balad"]', '<u>At-Tin</u> (Q. 95:4).', '{"bold":[],"italic":[],"underline":["at-Tin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxk6e763p2qu6tqaux6693pik', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the sum of n terms: 1² + 3² + 5² + ...', null, '["n(4n² - 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n - 1)/6","n(4n² + 1)/3"]', 0, 'Sum = n(2n-1)(2n+1)/3 = n(4n²-1)/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of n terms: 1² + 3² + 5² + ...', '["n(4n² - 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n - 1)/6","n(4n² + 1)/3"]', 'Sum = <u>n(4n² - 1)/3</u>.', '{"bold":[],"italic":[],"underline":["n(4n² - 1)/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxk95k9xfge0vxqn3znt8hgay', 'Chemistry', 'JAMB', null, 2004, null, 'What volume of gas is evolved at s.t.p. if 2g of calcium trioxocarbonate(IV) is added to a solution of hydrochloric acid?', null, '["224cm³","112cm³","2240cm³","448cm³ [Ca=40, C=12, O=16, Cl=35.5, H=1, Molar volume = 22.4 dm³]"]', 0, 'Moles CaCO3 = 0.02; CO2 = 0.02; volume = 0.02 × 22400 = 448 cm³. Key says 224.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of gas is evolved at s.t.p. if 2g of calcium trioxocarbonate(IV) is added to a solution of hydrochloric acid?', '["224cm³","112cm³","2240cm³","448cm³"]', 'Volume = <u>448 cm³</u> (key says 224).', '{"bold":[],"italic":[],"underline":["224cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxkvgddfjzdklhd9aa103unrv', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the equation of the tangent to the circle x² + y² - 4x + 6y - 12 = 0 at the point (5, 1).', null, '["3x + 4y - 19 = 0","3x - 4y + 19 = 0","3x - 4y - 11 = 0","3x + 4y - 11 = 0"]', 0, 'Center (2, -3); radius to (5,1) slope = 4/3; tangent slope = -3/4; equation: 3x + 4y = 19.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the tangent to the circle x² + y² - 4x + 6y - 12 = 0 at the point (5, 1).', '["3x + 4y - 19 = 0","3x - 4y + 19 = 0","3x - 4y - 11 = 0","3x + 4y - 11 = 0"]', 'Tangent: <u>3x + 4y - 19 = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxkylu9a9bbbzrjxeiwyldor4', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God said that any member of Ahab''s family who died in the open country would be', null, '["eaten up by the dogs","buried by foreigners","eaten by the birds","left unburied."]', 2, 'They would be eaten by the birds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God said that any member of Ahab''s family who died in the open country would be', '["eaten up by the dogs","buried by foreigners","<u>eaten by the birds</u>","left unburied."]', '<u>Eaten by the birds</u> (1 Kings 21:24).', '{"bold":[],"italic":[],"underline":["eaten by the birds"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxldnq4sm44wxc2c0rtj3ad48', 'General Mathematics', 'JAMB', null, 2020, null, 'From an external point T, tangents TP and TQ are drawn to a circle with center O. A third tangent touches the circle at R and meets TP and TQ at X and Y respectively. If the radius is 6 cm and OT = 10 cm, find the perimeter of triangle TXY.', null, '["12 cm","14 cm","16 cm","20 cm"]', 2, 'Tangent length = 8; perimeter = 2 × 8 = 16 cm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From an external point T, tangents TP and TQ are drawn to a circle with center O. A third tangent touches the circle at R and meets TP and TQ at X and Y respectively. If the radius is 6 cm and OT = 10 cm, find the perimeter of triangle TXY.', '["12 cm","14 cm","16 cm","20 cm"]', 'Perimeter = <u>16 cm</u>.', '{"bold":[],"italic":[],"underline":["16 cm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxlhre10sxh0rith5oqto6jrw', 'Biology', 'JAMB', null, 1985, null, 'A food substance which produces red colouration with Sudan III contains', null, '["protein","sugar","starch","cellulose","fat"]', 4, 'Sudan III tests for fats, producing a red colour.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A food substance which produces red colouration with <b>Sudan III</b> contains', '["protein","sugar","starch","cellulose","<u>fat</u>"]', 'Sudan III tests for <u>fats</u>, producing a red colour.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxltqfeeq2jfewax4s8llt1k2', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin x = 3/5 and x is in QII, find cos 2x.', null, '["7/25","-7/25","24/25","-24/25"]', 0, 'cos 2x = 1 - 2sin²x = 1 - 18/25 = 7/25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin x = 3/5 and x is in QII, find cos 2x.', '["7/25","-7/25","24/25","-24/25"]', 'cos 2x = <u>7/25</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxlz404ccsmoq554xyh1gbqtd', 'General Mathematics', 'JAMB', null, 2020, null, 'Two numbers are drawn from {1, ..., 10} without replacement. Find the probability their sum is even.', null, '["4/9","1/2","5/9","2/3"]', 1, 'P(even) = (5C2 + 5C2)/10C2 = 20/45 = 4/9. Key says 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two numbers are drawn from {1, ..., 10} without replacement. Find the probability their sum is even.', '["4/9","1/2","5/9","2/3"]', 'P = <u>1/2</u> (per key).', '{"bold":[],"italic":[],"underline":["1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxm1s4e1td79txrccmhvqd8mr', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A Muslim who joins the Imam while he is rising from the last ruku'' of the last rak''ah has to', null, '["repeat the rak''ah as if he did not join in it","complete the remaining except the last rak''ah","continue the prayer and thereafter observe all the rak''at","end up the prayer with the Imam."]', 2, 'He continues and observes all the rak''at.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Muslim who joins the Imam while he is rising from the last ruku'' of the last rak''ah has to', '["repeat the rak''ah as if he did not join in it","complete the remaining except the last rak''ah","<u>continue the prayer and thereafter observe all the rak''at</u>","end up the prayer with the Imam."]', '<u>Continue the prayer and thereafter observe all the rak''at</u>.', '{"bold":[],"italic":[],"underline":["continue the prayer and thereafter observe all the rak''at"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxm624k7hdnab1wbs7mcn6qxl', 'Chemistry', 'JAMB', null, 1990, null, 'If a gas occupies a container of volume 146cm³ at 18°C and 0.971 atm, its volume in cm³ at s.t.p is', null, '["133","146","266","292"]', 0, 'V2 = (P1V1T2)/(P2T1) = (0.971×146×273)/(1×291) = 133 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a gas occupies a container of volume 146cm³ at 18°C and 0.971 atm, its volume in cm³ at s.t.p is', '["133","146","266","292"]', 'V2 = <u>133 cm³</u>.', '{"bold":[],"italic":[],"underline":["133"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxmc2mp2td1fg2m6i1qs38r8x', 'General Mathematics', 'JAMB', null, 2020, null, 'The coordinates of A, B, C are (6, 3), (-3, 5), (4, -2) respectively. Find the area of triangle ABC.', null, '["24.5 sq units","28.5 sq units","32.5 sq units","36.5 sq units"]', 0, 'Area = ½|6(5+2) - 3(-2-3) + 4(3-5)| = ½|42 + 15 - 8| = 24.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The coordinates of A, B, C are (6, 3), (-3, 5), (4, -2) respectively. Find the area of triangle ABC.', '["24.5 sq units","28.5 sq units","32.5 sq units","36.5 sq units"]', 'Area = <u>24.5 sq units</u>.', '{"bold":[],"italic":[],"underline":["24.5 sq units"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxmiwjs2jtx9l9rg60nfxpjh6', 'Chemistry', 'JAMB', null, 1983, null, 'Zn + H2SO4 → ZnSO4 + H2. How much zinc will be left undissolved if 2.00g of zinc is treated with 10cm³ of 1.0M H2SO4? [Zn=65, S=32, O=16, H=1]', null, '["1.35g","1.00g","0.70g","0.65g","0.06g"]', 2, 'Moles H2SO4 = 0.01; moles Zn reacted = 0.01 (0.65g); Zn left = 2.00 - 0.65 = 1.35g. Answer key says 0.70g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Zn + H2SO4 → ZnSO4 + H2. How much zinc will be left undissolved if 2.00g of zinc is treated with 10cm³ of 1.0M H2SO4? [Zn=65, S=32, O=16, H=1]', '["1.35g","1.00g","0.70g","0.65g","0.06g"]', 'Moles H2SO4 = 0.01; Zn left = 2.00 - 0.65 = <u>1.35g</u> (key says 0.70g).', '{"bold":[],"italic":[],"underline":["0.70g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxmljrdx5zynzuzemt92oa4n7', 'Biology', 'JAMB', null, 1983, null, 'Groundnut is not really a ''nut'' in the biological sense because', null, '["it is harvested from inside the ground","its pericarp is not hard and tough","the fruit is succulent","it is an achene"]', 1, 'A true nut has a hard and tough pericarp.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Groundnut is not really a ''nut'' in the biological sense because', '["it is harvested from inside the ground","<u>its pericarp is not hard and tough</u>","the fruit is succulent","it is an achene"]', 'A true nut has a <u>hard and tough pericarp</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxmn4m9x016ozxgokhbo2je3l', 'Chemistry', 'JAMB', null, 1987, null, 'Stainless steel is an alloy of', null, '["iron, carbon and silver","iron, carbon and lead","iron, carbon and chromium","iron and carbon only"]', 2, 'Stainless steel = iron + carbon + chromium.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Stainless steel is an alloy of', '["iron, carbon and silver","iron, carbon and lead","iron, carbon and chromium","iron and carbon only"]', '<u>Iron + carbon + chromium</u>.', '{"bold":[],"italic":[],"underline":["iron, carbon and chromium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxmnzzbbe5pgt7acbw1z709o2', 'Chemistry', 'JAMB', null, 1992, null, 'The IUPAC name for the hydrocarbon above is', null, '["2-ethyl-5-methylhex-2-ene","2,5-dimethylhex-2-ene","3,5-dimethylhept-3-ene","3,6-dimethylhept-3-ene"]', 1, 'The compound is 2,5-dimethylhex-2-ene.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The IUPAC name for the hydrocarbon above is', '["2-ethyl-5-methylhex-2-ene","2,5-dimethylhex-2-ene","3,5-dimethylhept-3-ene","3,6-dimethylhept-3-ene"]', '<u>2,5-dimethylhex-2-ene</u>.', '{"bold":[],"italic":[],"underline":["2,5-dimethylhex-2-ene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxmofs2ef3thdgxzdvxv1w9b4', 'Chemistry', 'JAMB', null, 1998, null, 'The reactions represented by the equations above demonstrate the', null, '["basic properties of ammonia","acidic properties of ammonia","reducing properties of ammonia","oxidizing properties of ammonia"]', 2, 'NH3 reduces CuO to Cu (reducing properties).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reactions represented by the equations above demonstrate the', '["basic properties of ammonia","acidic properties of ammonia","reducing properties of ammonia","oxidizing properties of ammonia"]', '<u>Reducing properties of ammonia</u>.', '{"bold":[],"italic":[],"underline":["reducing properties of ammonia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxmvtt6vqqcoag2xz91b764wd', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The disciples celebrated the Passover with Jesus because', null, '["He was going to be betrayed by one of them","it was the first day of unleavened bread","they had sacrificed the Passover lamb","they wanted to keep the Passover feast with Him."]', 2, 'They had sacrificed the Passover lamb.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The disciples celebrated the Passover with Jesus because', '["He was going to be betrayed by one of them","it was the first day of unleavened bread","<u>they had sacrificed the Passover lamb</u>","they wanted to keep the Passover feast with Him."]', '<u>They had sacrificed the Passover lamb</u> (Mark 14:12).', '{"bold":[],"italic":[],"underline":["they had sacrificed the Passover lamb"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxn167ieb0tf90hvghn5b3032', 'Biology', 'JAMB', null, 2000, null, 'Use the diagram to answer questions 14 and 15. The substance labelled II originates from', null, '["III only","IV only","I and IV","III and IV"]', 3, 'Substance II originates from III and IV.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 14 and 15. The substance labelled II originates from', '["III only","IV only","I and IV","III and IV"]', '<u>II originates from III and IV</u>.', '{"bold":[],"italic":[],"underline":["III and IV"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxnav8ukj5t2898rltsq5on5v', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x³ - 6x² + 11x - 6 < 0.', null, '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', 1, '(x-1)(x-2)(x-3) < 0 → x < 1 or 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x³ - 6x² + 11x - 6 < 0.', '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', '<u>x < 1 or 2 < x < 3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxneuk7cnha17rqmmdsj8nips', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the centroid of triangle with vertices (1,2), (3,4), and (5,6).', null, '["(3,4)","(4,5)","(2,3)","(5,6)"]', 0, 'Centroid = ((1+3+5)/3, (2+4+6)/3) = (3,4).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the centroid of triangle with vertices (1,2), (3,4), and (5,6).', '["(3,4)","(4,5)","(2,3)","(5,6)"]', 'Centroid = <u>(3,4)</u>.', '{"bold":[],"italic":[],"underline":["(3,4)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxnmd1m109mxqgm681elkp07b', 'General Mathematics', 'JAMB', null, 2020, null, 'If a*b = (a + b)/(1 + ab), find 1*1.', null, '["0","1","0.5","undefined"]', 1, '1*1 = 2/2 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = (a + b)/(1 + ab), find 1*1.', '["0","1","0.5","undefined"]', '1*1 = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxnrdpugxuy6i7v43veat6zxu', 'Chemistry', 'JAMB', null, 1984, null, 'Tetraoxosulphate(VI) ions are finally tested using', null, '["acidified silver nitrate","acidified barium chloride","lime-water","dilute hydrochloric acid","acidified lead nitrate"]', 1, 'Acidified BaCl2 gives a white BaSO4 precipitate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Tetraoxosulphate(VI) ions are finally tested using', '["acidified silver nitrate","acidified barium chloride","lime-water","dilute hydrochloric acid","acidified lead nitrate"]', '<u>Acidified BaCl2</u> gives a white BaSO4 precipitate.', '{"bold":[],"italic":[],"underline":["acidified barium chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxnrha9fug4ouxenk5xs0w6zz', 'General Mathematics', 'JAMB', null, 2020, null, 'Two forces F₁ = 2i + 3j - k and F₂ = -i - 2j + 4k act on a particle and displace it from point A(2, 1, -3) to B(4, -2, 5). Find the total work done.', null, '["26 J","23 J","38 J","44 J"]', 1, 'F = F₁ + F₂ = i + j + 3k; d = 2i - 3j + 8k; W = F·d = 2 - 3 + 24 = 23 J.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Two forces F₁ = 2i + 3j - k and F₂ = -i - 2j + 4k act on a particle and displace it from point A(2, 1, -3) to B(4, -2, 5). Find the total work done.', '["26 J","23 J","38 J","44 J"]', 'F = F₁ + F₂ = i + j + 3k; d = 2i - 3j + 8k; W = F·d = 2 - 3 + 24 = 23 J.', '{"bold":[],"italic":[],"underline":["32 J"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxnvwfwxmkcrsb0k60rrbkzu2', 'Chemistry', 'JAMB', null, 1990, null, 'What volume of 11.0M hydrochloric acid must be diluted to obtain 1dm³ of 0.05M acid?', null, '["0.05dm³","0.10dm³","0.55dm³","11.0dm³"]', 1, 'M1V1 = M2V2; V1 = (0.05 × 1)/11 = 0.0045 dm³. Closest is 0.05.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of 11.0M hydrochloric acid must be diluted to obtain 1dm³ of 0.05M acid?', '["0.05dm³","0.10dm³","0.55dm³","11.0dm³"]', 'V1 = <u>0.0045 dm³</u> (closest 0.05).', '{"bold":[],"italic":[],"underline":["0.10dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxny4milx5vv8w4wf22u461sb', 'Chemistry', 'JAMB', null, 1993, null, 'For iodine crystals to sublime on heating, the molecules must acquire energy that is', null, '["less than the forces of attraction in the solid","equal to the forces of attraction in the solid","necessary to melt the solid","greater than the forces of attraction in both solid and the liquid phases"]', 3, 'Sublimation requires overcoming forces in both solid and liquid phases.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For iodine crystals to sublime on heating, the molecules must acquire energy that is', '["less than the forces of attraction in the solid","equal to the forces of attraction in the solid","necessary to melt the solid","greater than the forces of attraction in both solid and the liquid phases"]', '<u>Greater than forces in both solid and liquid phases</u>.', '{"bold":[],"italic":[],"underline":["greater than the forces of attraction in both solid and the liquid phases"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxnzok3x4otqy5evj50tshf4j', 'Physics', 'JAMB', null, 1983, null, 'The specific latent heat of vaporization of a substance is always', null, '["Less than its specific latent heat of fusion.","Greater than its specific latent heat of fusion.","Equal to its specific latent heat of fusion.","All of the above depending on the nature of the substance","None of the above"]', 1, 'Vaporization needs far more energy than fusion because the molecules must be completely separated, so it is always greater.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'The specific latent heat of vaporization of a substance is always', '["Less than its specific latent heat of fusion.","Greater than its specific latent heat of fusion.","Equal to its specific latent heat of fusion.","All of the above depending on the nature of the substance","None of the above"]', 'Vaporization needs far more energy than fusion because the molecules must be completely separated, so it is always greater.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxo2ddiejjl9q45wnbr7z1uqk', 'Government', 'JAMB', null, 2020, null, 'The General Purpose Committee of the local government is the', null, '["cabinet of the local government","body responsible for supervising self-help projects","local government public relations unit","body for awarding contracts."]', 0, 'The General Purpose Committee is the cabinet of the local government.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The General Purpose Committee of the local government is the', '["<u>cabinet of the local government</u>","body responsible for supervising self-help projects","local government public relations unit","body for awarding contracts."]', '<u>Cabinet of the local government</u>.', '{"bold":[],"italic":[],"underline":["cabinet of the local government"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxoa0qrqh51hzioj0llbka30o', 'Biology', 'JAMB', null, 2003, null, 'Mycorrhiza is an association between fungi and', null, '["roots of higher plants","alimentous algae","bacteria","protozoans"]', 0, 'Mycorrhiza = fungi + plant roots.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mycorrhiza is an association between fungi and', '["roots of higher plants","alimentous algae","bacteria","protozoans"]', '<u>Roots of higher plants</u>.', '{"bold":[],"italic":[],"underline":["roots of higher plants"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxocyiejyojnq66fa6mz6aee3', 'Government', 'JAMB', null, 2020, null, 'A problem of Nigerian federalism that was resolved by the Supreme Court between the federal government and the littoral states centred on resource', null, '["maximization","generation","derivation","control"]', 3, 'The dispute was over resource control.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A problem of Nigerian federalism that was resolved by the Supreme Court between the federal government and the littoral states centred on resource', '["maximization","generation","derivation","<u>control</u>"]', '<u>Control</u>.', '{"bold":[],"italic":[],"underline":["control"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxof3ephewgm7rxm02kcoo9uf', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the harmonic mean of 2 and 8.', null, '["3.2","4","5","6"]', 0, 'HM = 2ab/(a+b) = 2(16)/10 = 3.2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the harmonic mean of 2 and 8.', '["3.2","4","5","6"]', 'HM = <u>3.2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxog94yy02ki8hskw10298sis', 'Biology', 'JAMB', null, 1985, null, 'The initial volume of water poured into a bag of dry soil was 50ml and the amount that drained through was 35ml. The percentage water content of the fully soaked soil is therefore', null, '["46.7","25.0","20.0","30.0","58.3"]', 3, 'Water absorbed = 50-35 = 15ml. Percentage = 15/50 × 100 = 30%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The initial volume of water poured into a bag of dry soil was 50ml and the amount that drained through was 35ml. The percentage water content of the fully soaked soil is therefore', '["46.7","25.0","20.0","<u>30.0</u>","58.3"]', 'Water absorbed = 50-35 = 15ml. Percentage = 15/50 × 100 = <u>30%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxoi0sh6o93mg3wc5pctsvvym', 'General Mathematics', 'JAMB', null, 2020, null, 'A variable point P(x, y) moves such that the area of triangle PAB is 10 square units, where A(2, 3) and B(4, -1). Find the equation of the locus of P.', null, '["2x + 2y - 10","= 10","2x - 2y - 10","= 10","2x + 2y + 10","= 10","2x - 2y + 10","= 10"]', 0, 'Area = ½|2(y-3) + 4(3-y) + x(-1-3)| = ½|-4x + 4y - 8| = 10 → |2x - 2y + 4| = 10. Key says |2x + 2y - 10| = 10.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A variable point P(x, y) moves such that the area of triangle PAB is 10 square units, where A(2, 3) and B(4, -1). Find the equation of the locus of P.', '["2x + 2y - 10","= 10","2x - 2y - 10","= 10","2x + 2y + 10","= 10","2x - 2y + 10","= 10"]', 'Locus: <u>|2x + 2y - 10| = 10</u> (per key).', '{"bold":[],"italic":[],"underline":["|2x + 2y - 10| = 10"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxolv918xwe9w5y75evlnxw6u', 'Chemistry', 'JAMB', null, 1990, null, 'A metallic oxide which reacts with both HCl and NaOH to give salt and water only can be classified as', null, '["an acidic oxide","an atmospheric oxide","a neutral oxide","an amphoteric oxide"]', 3, 'Amphoteric oxides react with both acids and bases.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A metallic oxide which reacts with both HCl and NaOH to give salt and water only can be classified as', '["an acidic oxide","an atmospheric oxide","a neutral oxide","an amphoteric oxide"]', '<u>Amphoteric oxide</u> reacts with both acid and base.', '{"bold":[],"italic":[],"underline":["an amphoteric oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxpe458xfo8u9puyh3vlrslxo', 'Chemistry', 'JAMB', null, 1985, null, 'How many isomers can be formed from organic compounds with the formula C3H8O?', null, '["2","3","4","5"]', 0, 'C3H8O has 2 isomers: propan-1-ol and propan-2-ol (and methoxyethane).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many isomers can be formed from organic compounds with the formula C3H8O?', '["2","3","4","5"]', '<u>C3H8O has 3 isomers</u> including ethers; but among alcohols, 2.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxphdrtovhpmx2lyzwyuc42og', 'Biology', 'JAMB', null, 2002, null, 'A person that is obese must avoid meals containing', null, '["carrots and oranges","margarine and butter","beef and beans","rice and yam"]', 1, 'margarine and butter is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A person that is obese must avoid meals containing', '["carrots and oranges","<u>margarine and butter</u>","beef and beans","rice and yam"]', 'margarine and butter is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxpix4qlzsjl55e6f5d6rgfhg', 'Chemistry', 'JAMB', null, 1998, null, 'A given amount of gas occupies 10.0dm³ at 4atm and 273°C. The number of moles of the gas present is', null, '["0.89mol","1.90mol","3.80mol","5.70mol [Molar volume of gas at s.t.p. = 22.4dm³]"]', 0, 'At s.t.p. V = 4×10×273/546 = 20 dm³; n = 20/22.4 = 0.89 mol.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A given amount of gas occupies 10.0dm³ at 4atm and 273°C. The number of moles of the gas present is', '["0.89mol","1.90mol","3.80mol","5.70mol"]', 'At s.t.p. V = 4×10×273/546 = 20 dm³; n = 20/22.4 = 0.89 mol.', '{"bold":[],"italic":[],"underline":["1.90mol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxpkbuh4z655rjdl6t2eo3hm5', 'General Mathematics', 'WAEC', null, 2020, null, 'If (1,2) is the midpoint of (3,a) and (b,6), find a + b.', null, '["5","6","-3","8"]', 2, '(3+b)/2 = 1 → b = -1; (a+6)/2 = 2 → a = -2; a + b = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If (1,2) is the midpoint of (3,a) and (b,6), find a + b.', '["5","6","-3","8"]', '(3+b)/2 = 1 → b = -1; (a+6)/2 = 2 → a = -2; a + b = -3.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxpkimw0go5d3daa7e9ik70zw', 'Government', 'JAMB', null, 2020, null, 'A fundamental component of political culture is', null, '["social values","community structure","family values","economic values."]', 1, 'Community structure is a fundamental component of political culture.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A fundamental component of political culture is', '["social values","<u>community structure</u>","family values","economic values."]', '<u>Community structure</u>.', '{"bold":[],"italic":[],"underline":["community structure"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxq8it43youvlbza502xg8x34', 'General Mathematics', 'JAMB', null, 2020, null, 'The equation of a curve is y = x³ - 3x² + 3x - 1. Find the point on the curve where the tangent is parallel to the x-axis.', null, '["(1, 0)","(1, -1)","(1, 1)","(2, 1)"]', 0, 'y'' = 3(x-1)² = 0 → x = 1; y = 0. Point (1, 0).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The equation of a curve is y = x³ - 3x² + 3x - 1. Find the point on the curve where the tangent is parallel to the x-axis.', '["(1, 0)","(1, -1)","(1, 1)","(2, 1)"]', 'Point = <u>(1, 0)</u>.', '{"bold":[],"italic":[],"underline":["(1, 0)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxqciq52cb8ss7sbomendaqsr', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 2x² - 4 < 8x.', null, '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 0, 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve 2x² - 4 < 8x.', '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxqf7u33ufq6uvmha8h0248i8', 'Biology', 'JAMB', null, 1987, null, 'A gene which expresses itself only in the homozygous condition is', null, '["a mutant","dominant","recessive","lethal"]', 2, 'A recessive gene expresses only in homozygous condition.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A gene which expresses itself only in the homozygous condition is', '["a mutant","dominant","<u>recessive</u>","lethal"]', 'A <u>recessive gene</u> expresses only in homozygous condition.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxqukwvjafpo9geef40z92uen', 'Chemistry', 'JAMB', null, 1987, null, 'The reaction between sulphur(IV) oxide and oxygen is represented by the equilibrium reaction 2SO2(g) + O2(g) ⇌ 2SO3(g), ΔH = -196 kJ. What factor would influence increased production of SO3(g)?', null, '["Addition of a suitable catalyst","Increase in the temperature of the reaction","Decrease in the temperature of the reaction","Decrease in the concentration of SO2(g)"]', 2, 'Exothermic reaction favours lower temperature for product formation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reaction between sulphur(IV) oxide and oxygen is represented by the equilibrium reaction 2SO2(g) + O2(g) ⇌ 2SO3(g), ΔH = -196 kJ. What factor would influence increased production of SO3(g)?', '["Addition of a suitable catalyst","Increase in the temperature of the reaction","Decrease in the temperature of the reaction","Decrease in the concentration of SO2(g)"]', '<u>Decrease in temperature</u> favours SO3 production.', '{"bold":[],"italic":[],"underline":["Decrease in the temperature of the reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxqvf81mv5q2ds8j3y40kmsjn', 'Chemistry', 'JAMB', null, 2004, null, 'Given that ΔHf[CO] is -110.4 kJ mol⁻¹ and ΔHf[CO2] is -393.5 kJ mol⁻¹, the energy change for the reaction CO(g) + ½O2(g) → CO2(g) is', null, '["-282.6kJ","+503.7kJ","-503.7kJ","+282.6kJ"]', 0, 'ΔH = -393.5 - (-110.4) = -282.6 kJ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given that ΔHf[CO] is -110.4 kJ mol⁻¹ and ΔHf[CO2] is -393.5 kJ mol⁻¹, the energy change for the reaction CO(g) + ½O2(g) → CO2(g) is', '["-282.6kJ","+503.7kJ","-503.7kJ","+282.6kJ"]', 'ΔH = <u>-282.6 kJ</u>.', '{"bold":[],"italic":[],"underline":["-282.6kJ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxqyh7b1qho80t3xfhm3gwezl', 'Chemistry', 'JAMB', null, 1995, null, 'Sodium hydroxide should be stored in properly closed containers because it', null, '["readily absorbs water vapour from the air","is easily oxidized by atmospheric oxygen","turns golden yellow when exposed to light","melts at a low temperature"]', 0, 'NaOH is deliquescent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sodium hydroxide should be stored in properly closed containers because it', '["readily absorbs water vapour from the air","is easily oxidized by atmospheric oxygen","turns golden yellow when exposed to light","melts at a low temperature"]', '<u>NaOH absorbs water vapour</u> from air.', '{"bold":[],"italic":[],"underline":["readily absorbs water vapour from the air"],"fillBlanks":[]}');
