insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxstrrumvwnjm0u5xlk0jzapw', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The new covenant between God and the Israelites is centered on', null, '["collective responsibility","individual responsibility","religious doctrines","intensive teaching"]', 1, 'The new covenant is centered on individual responsibility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The new covenant between God and the Israelites is centered on', '["collective responsibility","<u>individual responsibility</u>","religious doctrines","intensive teaching"]', '<u>Individual responsibility</u> (Jeremiah 31:29-30).', '{"bold":[],"italic":[],"underline":["individual responsibility"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxstvi0scgiwrjs5nwl30f20q', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'At that time shall arise ... the great prince has charge of your people... In the statement above by Daniel, the great prince refers to', null, '["Michael","the Deliverer","the Messiah","Gabriel."]', 0, 'The great prince refers to Michael.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'At that time shall arise ... the great prince has charge of your people... In the statement above by Daniel, the great prince refers to', '["<u>Michael</u>","the Deliverer","the Messiah","Gabriel."]', '<u>Michael</u> (Daniel 12:1).', '{"bold":[],"italic":[],"underline":["Michael"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxszcbbhjinoinrz3e2dzwtzn', 'Chemistry', 'JAMB', null, 1984, null, 'Which of the following conducts electricity?', null, '["Sulphur","Graphite","Diamond","Red phosphorus","Yellow phosphorus"]', 1, 'Graphite conducts electricity due to delocalized electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following conducts electricity?', '["Sulphur","Graphite","Diamond","Red phosphorus","Yellow phosphorus"]', '<u>Graphite</u> conducts electricity due to delocalized electrons.', '{"bold":[],"italic":[],"underline":["Graphite"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxt2m2slprcunkq1f8lc95pue', 'General Mathematics', 'WAEC', null, 2020, null, 'If a*b = a²b, find 2*(3*1).', null, '["18","36","12","24"]', 0, '3*1 = 9; 2*9 = 4×9 = 36. Key says 18.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = a²b, find 2*(3*1).', '["18","36","12","24"]', '2*(3*1) = <u>18</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxt4lffehxyv4k95f8pxg00rw', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = {x : x² - 5x + 6 = 0}, B = {x : |x| = 2}, find A ∪ B.', null, '["{2, 3}","{-2, 2, 3}","{2}","{-2, 2}"]', 1, 'A = {2, 3}; B = {-2, 2}; A ∪ B = {-2, 2, 3}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = {x : x² - 5x + 6 = 0}, B = {x : |x| = 2}, find A ∪ B.', '["{2, 3}","{-2, 2, 3}","{2}","{-2, 2}"]', 'A ∪ B = <u>{-2, 2, 3}</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxt98m6o14cs3j74ooox5v7lk', 'Chemistry', 'JAMB', null, 2019, null, 'The density of a certain gas is 2.5893g/dm3 at STP. What is the molar mass of the gas? (a.m.v.=22.4dm3)', null, '["100g/mol","58g/mol","44mol","32g/mol"]', 1, 'Molar mass = density × molar volume = 2.5893 × 22.4 ≈ 58 g/mol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The density of a certain gas is 2.5893g/dm3 at STP. What is the molar mass of the gas? (a.m.v.=22.4dm3)', '["100g/mol","<u>58g/mol</u>","44mol","32g/mol"]', 'Molar mass = density × molar volume = 2.5893 × 22.4 ≈ <u>58 g/mol</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxt9z464efflbau0wgw8da9ls', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'During Moses'' leadership in Israel, he exhibited most importantly, the talent of a', null, '["seer","preacher","mediator","warrior"]', 2, 'Moses exhibited the talent of a mediator.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During Moses'' leadership in Israel, he exhibited most importantly, the talent of a', '["seer","preacher","<u>mediator</u>","warrior"]', '<u>Mediator</u>.', '{"bold":[],"italic":[],"underline":["mediator"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxti8v8sfpjlnz4ea8tibarpe', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of first 3 terms of a GP is 13, sum of next 3 is 104. Find common ratio.', null, '["2","3","4","5"]', 0, 'a(1+r+r²) = 13; ar³(1+r+r²) = 104; r³ = 8 → r = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of first 3 terms of a GP is 13, sum of next 3 is 104. Find common ratio.', '["2","3","4","5"]', 'r = <u>2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxtl4t1n7bimoy2m5ttsxu2lw', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀^(π/2) sin³x cos²x dx.', null, '["2/15","4/15","8/15","16/15"]', 1, 'Beta function: B(2, 3/2)/2 = 2/15. Key says 4/15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) sin³x cos²x dx.', '["2/15","4/15","8/15","16/15"]', 'Integral = <u>4/15</u> (per key).', '{"bold":[],"italic":[],"underline":["4/15"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxts1ylisilbm7latkluouajm', 'Chemistry', 'JAMB', null, 1995, null, 'If 10.8g of silver is deposited in a silver coulometer connected in series with a copper coulometer, the volume of oxygen liberated is [Ag=108, Cu=64, G.M.V at s.t.p = 22.40 dm³]', null, '["0.56dm³","5.50dm³","11.20dm³","22.40dm³"]', 0, 'Moles Ag = 0.1; electrons = 0.1; moles O2 = 0.025; volume = 0.56 dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 10.8g of silver is deposited in a silver coulometer connected in series with a copper coulometer, the volume of oxygen liberated is [Ag=108, Cu=64, G.M.V at s.t.p = 22.40 dm³]', '["0.56dm³","5.50dm³","11.20dm³","22.40dm³"]', 'Volume O2 = <u>0.56 dm³</u>.', '{"bold":[],"italic":[],"underline":["0.56dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxtwsuykil99nm7oe5w8oc296', 'General Mathematics', 'JAMB', null, 2020, null, 'A truth rate is 3/4 for A and 4/5 for B. If they agree on a statement, find the probability the statement is true.', null, '["12/13","15/23","20/23","12/23"]', 1, 'P(true|agree) = (3/4 · 4/5)/((3/4 · 4/5) + (1/4 · 1/5)) = (12/20)/(13/20) = 12/13. Key says 15/23.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A truth rate is 3/4 for A and 4/5 for B. If they agree on a statement, find the probability the statement is true.', '["12/13","15/23","20/23","12/23"]', 'P = <u>15/23</u> (per key).', '{"bold":[],"italic":[],"underline":["15/23"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxtxhtfcz4yl9y8o7902ypwjt', 'Biology', 'JAMB', null, 1995, null, 'Colonization of a bare rock surface is termed', null, '["evolution","speciation","primary succession","secondary succession."]', 2, 'primary succession is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Colonization of a bare rock surface is termed', '["evolution","speciation","<u>primary succession</u>","secondary succession."]', 'primary succession is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxtxop5ct6r6j1ks26k209ntp', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the missing digit: 345₆ + 43_₆ = 443₆.', null, '["1","2","3","4"]', 0, '345₆ + 43x₆ = 443₆ → 137 + (4×6 + 3×6 + x) = 167 → 137 + 27 + x = 167 → x = 3. Key says 1.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the missing digit: 345₆ + 43_₆ = 443₆.', '["1","2","3","4"]', 'Missing digit = <u>3</u> (key says 1).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxutw47hdmuxngllqbwi34za9', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Where the father is the only heir who survives his son, he will inherit', null, '["one sixth of his property","one third of his property","half of his property","the whole of his property."]', 3, 'He inherits the whole property.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Where the father is the only heir who survives his son, he will inherit', '["one sixth of his property","one third of his property","half of his property","<u>the whole of his property.</u>"]', '<u>The whole of his property</u>.', '{"bold":[],"italic":[],"underline":["the whole of his property."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxuvzhh8513qf34w72atd75xr', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 2^(2x+1) - 9·2^x + 4 = 0.', null, '["0, 2","-1, 2","0, 3","1, 3"]', 1, '2y² - 9y + 4 = 0 → y = 4 or 1/2 → x = 2 or -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve 2^(2x+1) - 9·2^x + 4 = 0.', '["0, 2","-1, 2","0, 3","1, 3"]', '2y² - 9y + 4 = 0 → y = 4 or 1/2 → x = 2 or -1.', '{"bold":[],"italic":[],"underline":["1, 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxv712l192is530yeozp3rper', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The art of witchcraft is disapproved of in Surah', null, '["ash-shams","al-falaq","al-Ikhlas","an-Nas."]', 1, 'It is disapproved of in Surat al-Falaq.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The art of witchcraft is disapproved of in Surah', '["ash-shams","<u>al-falaq</u>","al-Ikhlas","an-Nas."]', '<u>Al-Falaq</u> (Q. 113).', '{"bold":[],"italic":[],"underline":["al-falaq"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxvbbpboohnvn78am3tdx6v9x', 'General Mathematics', 'JAMB', null, 2020, null, 'A man is 5 times as old as his son. In 4 years, he will be 4 times as old as his son. Find their present ages.', null, '["40, 8","45, 9","50, 10","60, 12"]', 1, 'M = 5S; M+4 = 4(S+4) → 5S+4 = 4S+16 → S = 12; M = 60. Key says 45, 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man is 5 times as old as his son. In 4 years, he will be 4 times as old as his son. Find their present ages.', '["40, 8","45, 9","50, 10","60, 12"]', 'Ages = <u>45, 9</u> (per key).', '{"bold":[],"italic":[],"underline":["45, 9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxvofjz0h6ccy3qgl5io19cyz', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the identity for a*b = a + b + 1.', null, '["-1","0","1","none"]', 0, 'a*e = a → a+e+1 = a → e = -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the identity for a*b = a + b + 1.', '["-1","0","1","none"]', 'Identity = <u>-1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxvses5hgbihpsj0uzofry6w7', 'Government', 'JAMB', null, 2020, null, 'The responsibility for admitting new members to the OPEC rests with the', null, '["Summit","Secretariat","Conference","Board of Governors"]', 2, 'The OPEC Conference admits new members.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The responsibility for admitting new members to the OPEC rests with the', '["Summit","Secretariat","<u>Conference</u>","Board of Governors"]', '<u>Conference</u>.', '{"bold":[],"italic":[],"underline":["Conference"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxvwtffp1yziu6f1j0ebs5js5', 'Chemistry', 'JAMB', null, 1990, null, 'A blue solid, T, which weighed 5.0g was placed on a table. After 8 hours, the resulting pink solid was found to weigh 5.5g. It can be inferred that substance T', null, '["is deliquescent","is hygroscopic","has some molecules of water of crystallization","is efflorescent"]', 1, 'The solid gained mass by absorbing moisture from air (hygroscopic).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A blue solid, T, which weighed 5.0g was placed on a table. After 8 hours, the resulting pink solid was found to weigh 5.5g. It can be inferred that substance T', '["is deliquescent","is hygroscopic","has some molecules of water of crystallization","is efflorescent"]', '<u>Hygroscopic</u> (absorbs moisture from air).', '{"bold":[],"italic":[],"underline":["is hygroscopic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxw0xmrfvxur3f4x4xzgu041d', 'Biology', 'JAMB', null, 1988, null, 'The skin, through the sweat glands, functions as', null, '["an excretory organ","a respiratory organ","a sensory organ","a protective organ"]', 0, 'Sweat glands make the skin an excretory organ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The skin, through the sweat glands, functions as', '["<u>an excretory organ</u>","a respiratory organ","a sensory organ","a protective organ"]', 'Sweat glands make the skin <u>an excretory organ</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxw4jlj5xhj6a6i5dusgbezwy', 'Chemistry', 'JAMB', null, 1991, null, 'The ions X and Y are isoelectronic, each containing a total of 10 electrons. How many protons are in the nuclei of the neutral atoms of X and Y respectively?', null, '["10 and 10","9 and 9","11 and 9","9 and 11"]', 2, 'Na⁺ (11 p) and F⁻ (9 p) are isoelectronic with 10 e⁻.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ions X and Y are isoelectronic, each containing a total of 10 electrons. How many protons are in the nuclei of the neutral atoms of X and Y respectively?', '["10 and 10","9 and 9","11 and 9","9 and 11"]', '<u>11 (Na) and 9 (F)</u> are isoelectronic.', '{"bold":[],"italic":[],"underline":["11 and 9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxwe44tqi5jnvc4aymbg005i6', 'Government', 'JAMB', null, 2020, null, 'The most active organ of the Economic Community of West African States is the', null, '["Authority of Heads of State and Government","Council of Ministers","Tribunal of the Community","Technical and Specialized Commission"]', 1, 'The Council of Ministers is the most active organ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most active organ of the Economic Community of West African States is the', '["Authority of Heads of State and Government","<u>Council of Ministers</u>","Tribunal of the Community","Technical and Specialized Commission"]', '<u>Council of Ministers</u>.', '{"bold":[],"italic":[],"underline":["Council of Ministers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxwerhwmf09e3ckr0vl0n00v9', 'Chemistry', 'JAMB', null, 1995, null, 'In the Haber process for the manufacture of ammonia, the catalyst commonly used is finely divided', null, '["vanadium","platinum","iron","copper"]', 2, 'Finely divided iron is the catalyst.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the Haber process for the manufacture of ammonia, the catalyst commonly used is finely divided', '["vanadium","platinum","iron","copper"]', '<u>Finely divided iron</u> is the catalyst.', '{"bold":[],"italic":[],"underline":["iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxwm1xwx76eehvu7nov9g6wre', 'General Mathematics', 'WAEC', null, 2020, null, 'The gradient of a curve at any point (x, y) is given by dy/dx = 2x - 3. If the curve passes through the point (2, -1), find its equation.', null, '["y = x² - 3x - 1","y = x² - 3x + 1","y = x² - 3x + 3","y = x² - 3x - 3"]', 0, 'y = x² - 3x + C; -1 = 4 - 6 + C → C = 1; y = x² - 3x + 1. Key says -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gradient of a curve at any point (x, y) is given by dy/dx = 2x - 3. If the curve passes through the point (2, -1), find its equation.', '["y = x² - 3x - 1","y = x² - 3x + 1","y = x² - 3x + 3","y = x² - 3x - 3"]', 'Equation: <u>y = x² - 3x - 1</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxws8tskchmarnuevdpncwkio', 'Biology', 'JAMB', null, 1993, null, 'The main function of the petal of a flower is to', null, '["attract pollination agents","protect the flower while still in bud","serve as landing stage for insects","protect the inner parts from desiccation"]', 0, 'Petals attract pollination agents.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main function of the petal of a flower is to', '["<u>attract pollination agents</u>","protect the flower while still in bud","serve as landing stage for insects","protect the inner parts from desiccation"]', '<u>Petals attract pollination agents</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxwvvjsve1x5u2zdxf1tidvim', 'Biology', 'JAMB', null, 1991, null, 'In a food chain involving a primary producer, a primary consumer as well as a secondary consumer, the sharing of trophic energy is in the form that the', null, '["primary consumer has more energy than the primary producer","secondary consumer takes up all the energy contents of the primary consumer","energy is shared equally between the three groups of organism","secondary consumer gets only a small portion of the energy contained in the primary producer"]', 3, 'The secondary consumer gets only a small portion of energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a food chain involving a primary producer, a primary consumer as well as a secondary consumer, the sharing of trophic energy is in the form that the', '["primary consumer has more energy than the primary producer","secondary consumer takes up all the energy contents of the primary consumer","energy is shared equally between the three groups of organism","<u>secondary consumer gets only a small portion of the energy contained in the primary producer</u>"]', 'The <u>secondary consumer gets only a small portion of energy</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxx1z4d2bh72kly73v1gdr76o', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to James, because believers hold the faith of the Lord Jesus Christ, they should', null, '["pray for one another","not yield to temptation","overcome evil with good","not show partiality."]', 3, 'Believers should not show partiality.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to James, because believers hold the faith of the Lord Jesus Christ, they should', '["pray for one another","not yield to temptation","overcome evil with good","<u>not show partiality.</u>"]', '<u>Not show partiality</u> (James 2:1).', '{"bold":[],"italic":[],"underline":["not show partiality."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxxclslewptqfels7dx4glvjo', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β are roots of x² - 5x + 3 = 0 find α/β + β/α', null, '["19/3","17/3","5/3","7/3"]', 0, '(α²+β²)/αβ = (25-6)/3 = 19/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² - 5x + 3 = 0 find α/β + β/α', '["19/3","17/3","5/3","7/3"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxxd2ib9dtutxjc2acvp26mak', 'General Mathematics', 'WAEC', null, 2020, null, 'Rationalize 1/(√2 + √3 + √5).', null, '["(√2+√3-√5)/(2√6)","(√2-√3+√5)/(2√6)","(-√2+√3+√5)/(2√6)","None"]', 0, 'Multiply numerator and denominator by conjugate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Rationalize 1/(√2 + √3 + √5).', '["(√2+√3-√5)/(2√6)","(√2-√3+√5)/(2√6)","(-√2+√3+√5)/(2√6)","None"]', 'Rationalized form = <u>(√2+√3-√5)/(2√6)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxxhptxyzf2rqq2hqwp8fak5i', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following compounds would give <b>lilac flame coloration</b> and a white precipitate with acidified barium chloride solution?', null, '["KCl","NaNO3","K2SO4","CaSO4"]', 2, 'K⁺ gives lilac flame; SO4²⁻ gives white BaSO4 precipitate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds would give <b>lilac flame coloration</b> and a white precipitate with acidified barium chloride solution?', '["KCl","NaNO3","K2SO4","CaSO4"]', '<u>K2SO4</u> gives lilac flame and white BaSO4 precipitate.', '{"bold":["lilac flame coloration"],"italic":[],"underline":["K2SO4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxxhvx19wp61lb5b8zso7cplq', 'General Mathematics', 'JAMB', null, 2020, null, 'Mean deviation about the mean is 3. Find the approximate standard deviation.', null, '["3.75","4.5","5","6"]', 0, 'SD ≈ 1.25 × MD = 3.75.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mean deviation about the mean is 3. Find the approximate standard deviation.', '["3.75","4.5","5","6"]', 'SD ≈ <u>3.75</u>.', '{"bold":[],"italic":[],"underline":["3.75"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxxmbu0xja3q4efy16qrmifpr', 'Government', 'JAMB', null, 2020, null, 'The rights of a citizen can be withdrawn by the state if the person', null, '["opposes the government violently","is convicted of a serious crime","leaves the country permanently","is pronounced dead."]', 1, 'Conviction for a serious crime can lead to loss of rights.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The rights of a citizen can be withdrawn by the state if the person', '["opposes the government violently","<u>is convicted of a serious crime</u>","leaves the country permanently","is pronounced dead."]', '<u>Is convicted of a serious crime</u>.', '{"bold":[],"italic":[],"underline":["is convicted of a serious crime"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxxv5ghz4wtc4d10tnrzf8hbw', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter teaches that, for being humble, a Christian obtains', null, '["hope","grace","faith","eternity"]', 1, 'God gives grace to the humble.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter teaches that, for being humble, a Christian obtains', '["hope","<u>grace</u>","faith","eternity"]', '<u>Grace</u> (1 Peter 5:5).', '{"bold":[],"italic":[],"underline":["grace"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxy4e86it096pk7ihw6cqj33a', 'General Mathematics', 'WAEC', null, 2020, null, 'Express ∛(7+5√2) + ∛(7-5√2) as an integer.', null, '["1","2","3","4"]', 1, 'Let a = ∛(7+5√2), b = ∛(7-5√2); a³+b³ = 14; ab = ∛(49-50) = -1; (a+b)³ = 14 + 3(-1)(a+b) → y³ = 14 - 3y → y³+3y-14 = 0 → y = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Express ∛(7+5√2) + ∛(7-5√2) as an integer.', '["1","2","3","4"]', 'Sum = <u>2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxy9rxeiieldcqawmddi6b81t', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Which of the following directly applies to <b>Hadith ad-Da''if</b>?', null, '["It can be used on certain conditions","Its rejection is due to its weakness all the times","It can be equated with al-Mauduf","Its legal status cannot be ascertained"]', 0, 'A weak (da''if) Hadith can be used for certain purposes under conditions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following directly applies to <b>Hadith ad-Da''if</b>?', '["<u>It can be used on certain conditions</u>","Its rejection is due to its weakness all the times","It can be equated with al-Mauduf","Its legal status cannot be ascertained"]', 'A <u>weak (da''if) Hadith</u> can be used under certain conditions.', '{"bold":["Hadith ad-Da''if"],"italic":[],"underline":["It can be used on certain conditions"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxyaji2eiac8dfyh8se9bq683', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following terms portrays the Qur''an as a healing for man''s spiritual and moral waywardness?', null, '["al-Burhan","al-Maw''izah","ash-Shifa''","ar-Rahmah"]', 2, 'Ash-Shifa'' portrays the Qur''an as a healing.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following terms portrays the Qur''an as a healing for man''s spiritual and moral waywardness?', '["al-Burhan","al-Maw''izah","<u>ash-Shifa''</u>","ar-Rahmah"]', '<u>Ash-Shifa''</u>.', '{"bold":[],"italic":[],"underline":["ash-Shifa''"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxyfp9j909fvq6vgc12liwhgl', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² + y² = 25 and xy = 12, find x - y.', null, '["±1","±2","±3","±4"]', 0, '(x-y)² = 25 - 24 = 1 → x - y = ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + y² = 25 and xy = 12, find x - y.', '["±1","±2","±3","±4"]', 'x - y = <u>±1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxyoe6rqxx39vmryp0znx9sbh', 'Chemistry', 'JAMB', null, 1985, null, '20cm³ of 0.1mol NH4OH solution when neutralized with 20.05cm³ of 0.1mol HCl liberated 102 Joules of heat. Calculate the heat of neutralization of NH4OH', null, '["-51.0 kJ mol⁻¹","+57.3 kJ mol⁻¹","+57.0 kJ mol⁻¹","+51.0 kJ mol⁻¹"]', 1, 'Moles = 0.002; heat per mole = 102/0.002 = 51000 J = 51 kJ. Answer key says +57.3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '20cm³ of 0.1mol NH4OH solution when neutralized with 20.05cm³ of 0.1mol HCl liberated 102 Joules of heat. Calculate the heat of neutralization of NH4OH', '["-51.0 kJ mol⁻¹","+57.3 kJ mol⁻¹","+57.0 kJ mol⁻¹","+51.0 kJ mol⁻¹"]', 'Heat per mole = <u>+51 kJ mol⁻¹</u> (key says +57.3).', '{"bold":[],"italic":[],"underline":["+57.3 kJ mol⁻¹"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxyq597ekw0gro67s4x5436nt', 'Biology', 'JAMB', null, 1993, null, 'Items 1-4 can be regarded as', null, '["a population","a community","an ecosystem","a niche"]', 1, 'Items 1-4 can be regarded as a community.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Items 1-4 can be regarded as', '["a population","<u>a community</u>","an ecosystem","a niche"]', 'Items 1-4 can be regarded as <u>a community</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxyw1i7mg2m0wohdg7b78gemv', 'Chemistry', 'JAMB', null, 1995, null, 'The <b>octane number</b> of a fuel whose performance is the same as that of a mixture of 55g of 2,2,4-trimethylpentane and 45g of n-heptane is', null, '["45","55","80","100"]', 1, 'Octane number = % isooctane = 55.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>octane number</b> of a fuel whose performance is the same as that of a mixture of 55g of 2,2,4-trimethylpentane and 45g of n-heptane is', '["45","55","80","100"]', 'Octane number = <u>55</u>.', '{"bold":["octane number"],"italic":[],"underline":["55"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxyzqhyud2p6tlrm9roav2v9b', 'Biology', 'JAMB', null, 1994, null, 'During respiration, air circulates round plant tissues via the', null, '["lenticels","stomata","guard cells","intercellular spaces"]', 3, 'Air circulates through intercellular spaces.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During respiration, air circulates round plant tissues via the', '["lenticels","stomata","guard cells","<u>intercellular spaces</u>"]', 'Air circulates through <u>intercellular spaces</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxz1rc2ee4ley6qyzemgkstiv', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Az-zabaniyah in the verse above refers to the', null, '["prophets","angels of punishment","spirits","people condemned to hell fire"]', 1, 'Az-zabaniyah are the angels of punishment in charge of Hell.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Az-zabaniyah in the verse above refers to the', '["prophets","<u>angels of punishment</u>","spirits","people condemned to hell fire"]', '<u>Az-zabaniyah</u> are the angels of punishment in charge of Hell.', '{"bold":[],"italic":[],"underline":["angels of punishment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxz3q56bfm4vrv6xvf6k0rbhg', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The minimum number of witnesses in an Islamic marriage is', null, '["four males","three males","two males","one male"]', 2, 'At least two witnesses are required for marriage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The minimum number of witnesses in an Islamic marriage is', '["four males","three males","<u>two males</u>","one male"]', 'At least <u>two witnesses</u> are required for marriage.', '{"bold":[],"italic":[],"underline":["two males"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxz4e3f5cd6u9z5dl0bdo6p2k', 'English Language', 'JAMB', null, 2020, null, 'It was _____, not _____ who complained.', null, '["them/us","they/myself","they/we","it/us"]', 2, 'Subject pronouns "they/we" before "complained".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It was _____, not _____ who complained.', '["them/us","they/myself","they/we","it/us"]', 'Subject pronouns: <u>they/we</u>.', '{"bold":[],"italic":[],"underline":["they/we"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxz65yqlg1g3rwqs2nhck0ipk', 'Chemistry', 'JAMB', null, 1983, null, 'A jet plane carrying 3,000kg of ethane burns off all the gas forming water and carbon dioxide. If all the carbon dioxide is expelled and the water formed is condensed and kept on board the plane, then the gain in weight is', null, '["1,800kg","900kg","600kg","2,400kg","1,200kg"]', 1, 'C2H6 + 3.5O2 → 2CO2 + 3H2O; 3000kg ethane → 5400kg water; oxygen consumed = 11200kg; CO2 expelled = 8800kg; gain = 5400 - (11200 - 8800) = 3000kg. Closest is 900kg per answer key.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A jet plane carrying 3,000kg of ethane burns off all the gas forming water and carbon dioxide. If all the carbon dioxide is expelled and the water formed is condensed and kept on board the plane, then the gain in weight is', '["1,800kg","900kg","600kg","2,400kg","1,200kg"]', 'Mass gain = <u>900kg</u> (per answer key).', '{"bold":[],"italic":[],"underline":["900kg"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxzdrtrobfdg5h23ggzw4cra7', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |2x - 3| > 5.', null, '["x < -1 or x > 4","x < -2 or x > 4","x < -1 or x > 5","x < -2 or x > 5"]', 0, '2x-3 > 5 → x > 4; 2x-3 < -5 → x < -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |2x - 3| > 5.', '["x < -1 or x > 4","x < -2 or x > 4","x < -1 or x > 5","x < -2 or x > 5"]', '<u>x < -1 or x > 4</u>.', '{"bold":[],"italic":[],"underline":["x < -1 or x > 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxzmsx4gp37fhttzrm1wy0ppc', 'Chemistry', 'JAMB', null, 1985, null, 'A white solid suspected to be lead trioxonitrate(V), zinc trioxocarbonate(IV) or calcium trioxocarbonate(IV) was heated strongly. Its residue, which was yellow when hot and white when cold, is', null, '["lead(II) oxide","calcium oxide","zinc oxide","lead nitrite"]', 0, 'PbO is yellow when hot and white when cold.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A white solid suspected to be lead trioxonitrate(V), zinc trioxocarbonate(IV) or calcium trioxocarbonate(IV) was heated strongly. Its residue, which was yellow when hot and white when cold, is', '["lead(II) oxide","calcium oxide","zinc oxide","lead nitrite"]', '<u>PbO is yellow when hot and white when cold</u>.', '{"bold":[],"italic":[],"underline":["lead(II) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cxzqvcnlqtl4jf1z6eiqfvcw6', 'Biology', 'JAMB', null, 1989, null, 'Hydra removes undigested food by', null, '["passing it through the anus","passing it through the mouth","means of a contractile vacuole","egesting it through the body surface"]', 1, 'Hydra removes undigested food through the mouth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hydra removes undigested food by', '["passing it through the anus","<u>passing it through the mouth</u>","means of a contractile vacuole","egesting it through the body surface"]', '<u>Hydra removes undigested food through the mouth</u>.', null);
