insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy0wz1j8arm3kgmtj9nb7sgvk', 'Biology', 'JAMB', null, 1993, null, 'Green plants are distinguished from other living organisms by their ability to', null, '["make use of water","make use of oxygen","respond to sunlight","manufacture their own food"]', 3, 'Green plants manufacture their own food.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Green plants are distinguished from other living organisms by their ability to', '["make use of water","make use of oxygen","respond to sunlight","<u>manufacture their own food</u>"]', '<u>Green plants manufacture their own food</u>.', null);
