insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy10vicww28tmnb95m9rahfnl', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^π sin x cos 2x dx.', null, '["-2/3","0","2/3","4/3"]', 1, 'Using product-to-sum: sin x cos 2x = ½(sin 3x - sin x); integral over 0 to π = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^π sin x cos 2x dx.', '["-2/3","0","2/3","4/3"]', 'Integral = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy12m8cq4zjqttdklt1h3q7o7', 'Biology', 'JAMB', null, 2003, null, 'The correct sequence of biomes from northern to southern Nigeria is', null, '["estuarine → tropical rain forest → guinea savanna → sahel savanna","sahel savanna → sudan savanna → guinea savanna → tropical rainforest → estuarine","sahel savanna → tropical rain forest → estuarine → guinea savanna","guinea savanna → sudan savanna → tropical rainforest → sahel savanna → estuarine"]', 1, 'North to south: sahel → sudan → guinea → rainforest → estuarine.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The correct sequence of biomes from northern to southern Nigeria is', '["estuarine → tropical rain forest → guinea savanna → sahel savanna","sahel savanna → sudan savanna → guinea savanna → tropical rainforest → estuarine","sahel savanna → tropical rain forest → estuarine → guinea savanna","guinea savanna → sudan savanna → tropical rainforest → sahel savanna → estuarine"]', '<u>Sahel → sudan → guinea → rainforest → estuarine</u>.', '{"bold":[],"italic":[],"underline":["sahel savanna → sudan savanna → guinea savanna → tropical rainforest → estuarine"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy18d7pflgez6boj1fn4b9czf', 'Chemistry', 'JAMB', null, 2024, null, 'Hydrogenation is ____ process. I. Endothermic II. Isothermic III. Exothermic', null, '["III only","Either I or III","II only","I only","Neither I,II nor III"]', 0, 'Hydrogenation is an exothermic process (heat is released).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hydrogenation is ____ process.<br>I. Endothermic<br>II. Isothermic<br>III. Exothermic', '["<u>III only</u>","Either I or III","II only","I only","Neither I,II nor III"]', '<u>Hydrogenation is an exothermic process</u> (heat is released).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy19plfbmsw0360jl27mr3yy6', 'Chemistry', 'JAMB', null, 1987, null, 'Which is the correct set of results for tests conducted respectively on fresh lime and ethanol?', null, '["Add crystals of NaHCO3: Gas evolved / No gas evolved","Test with methyl orange: Turns colourless / No change","Taste: Bitter / Sour","Add a piece of sodium: No gas evolved / H2 evolved"]', 0, 'Lime juice (acid) reacts with NaHCO3 to give CO2; ethanol does not.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is the correct set of results for tests conducted respectively on fresh lime and ethanol?', '["Add crystals of NaHCO3: Gas evolved / No gas evolved","Test with methyl orange: Turns colourless / No change","Taste: Bitter / Sour","Add a piece of sodium: No gas evolved / H2 evolved"]', '<u>Lime juice reacts with NaHCO3</u> to give CO2; ethanol does not.', '{"bold":[],"italic":[],"underline":["Add crystals of NaHCO3: Gas evolved / No gas evolved"],"fillBlanks":[]}');
