insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy2twxmy2t5g1hcsro1xpu7pg', 'General Mathematics', 'JAMB', null, 2020, null, 'Out of 100 students: 50 take math, 40 take English, 30 take both. How many take exactly one?', null, '["30","40","50","60"]', 1, 'Exactly one = (50-30) + (40-30) = 20 + 10 = 30. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Out of 100 students: 50 take math, 40 take English, 30 take both. How many take exactly one?', '["30","40","50","60"]', 'Exactly one = <u>40</u> (per key).', '{"bold":[],"italic":[],"underline":["40"],"fillBlanks":[]}');
