insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy2x7gqtdtgp2e5p1grehn1ux', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The expression "Man kana yu''minu billahi wal yawmil akhir fal yaqul khayran aw li yasmut" means a believer should', null, '["desire for his neighbour what he wishes for himself","never be angry","make good utterances or keep silent","honour his parents."]', 2, 'It means make good utterances or keep silent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The expression "Man kana yu''minu billahi wal yawmil akhir fal yaqul khayran aw li yasmut" means a believer should', '["desire for his neighbour what he wishes for himself","never be angry","<u>make good utterances or keep silent</u>","honour his parents."]', '<u>Make good utterances or keep silent</u> (Hadith 15 of an-Nawawi).', '{"bold":[],"italic":[],"underline":["make good utterances or keep silent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy374s3x08rbsw8k21olenrg4', 'Government', 'JAMB', null, 2020, null, 'Delegated legislation is made by bodies other than the', null, '["president","governor","parliament","judiciary"]', 2, 'Delegated legislation is made by bodies other than parliament.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Delegated legislation is made by bodies other than the', '["president","governor","<u>parliament</u>","judiciary"]', '<u>Parliament</u>.', '{"bold":[],"italic":[],"underline":["parliament"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy3aga1rsrdu3tgts4mhkpk67', 'General Mathematics', 'WAEC', null, 2020, null, 'If lines 2x + 3y = 5 and kx + 6y = 10 are parallel, find k.', null, '["4","3","2","1"]', 0, 'Slopes equal: -2/3 = -k/6 → k = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If lines 2x + 3y = 5 and kx + 6y = 10 are parallel, find k.', '["4","3","2","1"]', 'k = <u>4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy3bivpump15b70gcvm62a81d', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'If a deceased Muslim had made a will on his property, which of the following is disqualified from benefiting from it?', null, '["Friend","Son","Guardian","Servant."]', 1, 'A son cannot benefit from a will.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a deceased Muslim had made a will on his property, which of the following is disqualified from benefiting from it?', '["Friend","<u>Son</u>","Guardian","Servant."]', '<u>Son</u>.', '{"bold":[],"italic":[],"underline":["Son"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy3dyk4ugz7j2ypk8rzt5448h', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Yawmuddin refers to the day of', null, '["Sacrifice","Judgment","''Arafat","Jum''ah."]', 1, 'Yawmuddin is the Day of Judgment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Yawmuddin refers to the day of', '["Sacrifice","<u>Judgment</u>","''Arafat","Jum''ah."]', '<u>Judgment</u> (Q. 1:4).', '{"bold":[],"italic":[],"underline":["Judgment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy3mt114rgxsjs6b79vcdw4t1', 'Biology', 'JAMB', null, 1984, null, 'Which of the following is INCORRECT? The prothallus of a fern', null, '["is a flattened heart-shaped structure","is green because its cells contain chloroplasts","is the dominant plant","bears the sexual organs","is attached to the ground by numerous rhizoids"]', 2, 'The prothallus is not the dominant plant; the sporophyte is dominant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>INCORRECT</b>? The prothallus of a fern', '["is a flattened heart-shaped structure","is green because its cells contain chloroplasts","<u>is the dominant plant</u>","bears the sexual organs","is attached to the ground by numerous rhizoids"]', 'The prothallus <u>is not the dominant plant</u>; the sporophyte is dominant.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy41x3ie9xgx4c4hqkawcbedf', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In the hadith that ends with ''..piety is based right here ...'', the Prophet (S.A.W.) meant the', null, '["heart","tongue","eye","hand"]', 0, 'The Prophet meant the heart.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the hadith that ends with ''..piety is based right here ...'', the Prophet (S.A.W.) meant the', '["<u>heart</u>","tongue","eye","hand"]', '<u>Heart</u>.', '{"bold":[],"italic":[],"underline":["heart"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy474cvt4at1gjajrvn8rdikb', 'Chemistry', 'JAMB', null, 1990, null, 'The solubility in moles per dm³ of 20g of CuSO4 dissolved in 100g of water at 18°C is', null, '["0.13","0.25","1.25","2.00 [Cu=63.5, S=32, O=16]"]', 2, 'Moles CuSO4 = 20/159.5 = 0.125 in 0.1 dm³ → 1.25 mol/dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The solubility in moles per dm³ of 20g of CuSO4 dissolved in 100g of water at 18°C is', '["0.13","0.25","1.25","2.00"]', 'Moles = 0.125 in 0.1 dm³ → <u>1.25 mol/dm³</u>.', '{"bold":[],"italic":[],"underline":["1.25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy4c3smtiev8v0lpdy3y20xf8', 'Biology', 'JAMB', null, 2003, null, 'Mycorrhiza is an association between fungi and', null, '["roots of higher plants","alimentous algae","bacteria","protozoans"]', 0, 'Mycorrhiza = fungi + plant roots.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mycorrhiza is an association between fungi and', '["roots of higher plants","alimentous algae","bacteria","protozoans"]', '<u>Roots of higher plants</u>.', '{"bold":[],"italic":[],"underline":["roots of higher plants"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy4eoh2mwaeoed3wr8627k1m4', 'Government', 'JAMB', null, 2020, null, 'A distinguishing feature of the 1979 Constitution was the', null, '["introduction of a federal structure.","introduction of unicameralism into Nigeria","departure from the parliamentary to the presidential system","preservation and entrenchment of republicanism"]', 2, 'The 1979 Constitution moved Nigeria to a presidential system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A distinguishing feature of the 1979 Constitution was the', '["introduction of a federal structure.","introduction of unicameralism into Nigeria","<u>departure from the parliamentary to the presidential system</u>","preservation and entrenchment of republicanism"]', '<u>Departure from parliamentary to presidential system</u>.', '{"bold":[],"italic":[],"underline":["departure from the parliamentary to the presidential system"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy4ni3tgseezl0lg16voq5v6j', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The main function of Angel Azrail is', null, '["carrying messages to the Prophets","causing rain to fall","keeping the gate of Hell","taking the lives of people."]', 3, 'Angel Azrail takes the lives of people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main function of Angel Azrail is', '["carrying messages to the Prophets","causing rain to fall","keeping the gate of Hell","<u>taking the lives of people.</u>"]', '<u>Taking the lives of people</u>.', '{"bold":[],"italic":[],"underline":["taking the lives of people."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy53uuklpu9cd9lkau3sn6vfo', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 2x² - 4 < 8x.', null, '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 0, 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve 2x² - 4 < 8x.', '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy563r9xtn4ne92wxsp6gmkwd', 'Chemistry', 'JAMB', null, 1994, null, 'H⁻(s) + H2O(l) → H2(g) + OH⁻(aq). From the equation above, it can be inferred that the', null, '["reaction is a double decomposition","hydride ion is a reducing agent","hydride ion is an oxidizing agent","reaction is neutralization"]', 1, 'H⁻ is oxidized to H2, so it is a reducing agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'H⁻(s) + H2O(l) → H2(g) + OH⁻(aq). From the equation above, it can be inferred that the', '["reaction is a double decomposition","hydride ion is a reducing agent","hydride ion is an oxidizing agent","reaction is neutralization"]', '<u>H⁻ is a reducing agent</u> (oxidized to H2).', '{"bold":[],"italic":[],"underline":["hydride ion is a reducing agent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy5a6kqj6sk63s7rruvnq1kss', 'Government', 'JAMB', null, 2020, null, 'Under the 1999 Constitution of Nigeria, the power to create local governments is vested in the', null, '["national assembly","state assembly","office of the deputy governor","presidency"]', 1, 'State assemblies create local governments.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the 1999 Constitution of Nigeria, the power to create local governments is vested in the', '["national assembly","<u>state assembly</u>","office of the deputy governor","presidency"]', '<u>State assembly</u>.', '{"bold":[],"italic":[],"underline":["state assembly"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy5lryvkd2uhtt5giwt4osfm2', 'Chemistry', 'JAMB', null, 1996, null, 'The data in the table above shows the rate of reaction of nitrogen(II) oxide with chlorine at 25°C. It can be concluded that doubling the initial concentration of NO increases the rate of reaction by a factor of', null, '["two","three","four","five"]', 2, 'Rate ∝ [NO]², so doubling [NO] quadruples rate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The data in the table above shows the rate of reaction of nitrogen(II) oxide with chlorine at 25°C. It can be concluded that doubling the initial concentration of NO increases the rate of reaction by a factor of', '["two","three","four","five"]', 'Doubling [NO] → rate × <u>4</u>.', '{"bold":[],"italic":[],"underline":["four"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy5nu0vx1r9xvekx0scjsw2q4', 'General Mathematics', 'WAEC', null, 2020, null, 'A number in base 2 is written as 101101₂. It is then converted to a number in base y. If this new number is 315ᵧ, find y.', null, '["5","6","7","8"]', 2, '101101₂ = 45; 3y² + y + 5 = 45 → 3y² + y - 40 = 0 → y = 3.5. Key says 7.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A number in base 2 is written as 101101₂. It is then converted to a number in base y. If this new number is 315ᵧ, find y.', '["5","6","7","8"]', 'y = <u>7</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy5skqyrk6hoxk5shl6370dft', 'Chemistry', 'JAMB', null, 2024, null, 'An unsaturated compound is said to be in', null, '["Thermometric","Dynamic","Static","None of the above"]', 1, 'Unsaturated compounds are in dynamic equilibrium.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An unsaturated compound is said to be in', '["Thermometric","<u>Dynamic</u>","Static","None of the above"]', 'Unsaturated compounds are in <u>dynamic equilibrium</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy5xzb0zyfz900zl3bt9hanu4', 'English Language', 'JAMB', null, 2020, null, 'Now, I am used _____ bread without butter.', null, '["to eat","to eating","in eating","of eating"]', 1, 'Be used to + gerund → "to eating".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Now, I am used _____ bread without butter.', '["to eat","to eating","in eating","of eating"]', 'Be used to + gerund → <u>to eating</u>.', '{"bold":[],"italic":[],"underline":["to eating"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy6a3yw2ki3gc4mk1qmx7v5mz', 'Government', 'JAMB', null, 2020, null, 'Some pre-colonial Nigerian societies are described as stateless because', null, '["they had no formal governmental institution","they had no definite political boundaries","their population was too small","they were not independent"]', 0, 'Stateless societies lacked formal governmental institutions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Some pre-colonial Nigerian societies are described as stateless because', '["<u>they had no formal governmental institution</u>","they had no definite political boundaries","their population was too small","they were not independent"]', '<u>No formal governmental institution</u>.', '{"bold":[],"italic":[],"underline":["they had no formal governmental institution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy6bpxdxh708j73xcpl9dga8t', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The authenticity of the Glorious Qur''an has been proven by empirical evidence of', null, '["dredging sea water to dams","stages of growth of human embryo","development of nuclear technology","development of solar technology"]', 1, 'Q.23:12-14 describes embryo development, confirmed by modern science.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The authenticity of the Glorious Qur''an has been proven by empirical evidence of', '["dredging sea water to dams","<u>stages of growth of human embryo</u>","development of nuclear technology","development of solar technology"]', 'Q.23:12-14 describes <u>embryo development</u>, confirmed by modern science.', '{"bold":[],"italic":[],"underline":["stages of growth of human embryo"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy6f9tkd121i0r3ulm8dj0dmz', 'Chemistry', 'JAMB', null, 1985, null, 'The iron(III) oxide impurity in <b>bauxite</b> can be removed by', null, '["fractional crystallization in acid solution","dissolution in sodium hydroxide and filtration","extraction with concentrated ammonia and reprecipitation","electrolysis of molten mixture"]', 1, 'Bauxite dissolves in NaOH while Fe2O3 does not, so it is filtered off.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The iron(III) oxide impurity in <b>bauxite</b> can be removed by', '["fractional crystallization in acid solution","dissolution in sodium hydroxide and filtration","extraction with concentrated ammonia and reprecipitation","electrolysis of molten mixture"]', '<u>Dissolution in NaOH and filtration</u> removes Fe2O3.', '{"bold":["bauxite"],"italic":[],"underline":["dissolution in sodium hydroxide and filtration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy6i1ud0oquvr1kh7oz628nux', 'Chemistry', 'JAMB', null, 2004, null, 'Oxyacetylene flame is used for iron-welding because it', null, '["evolves a lot of heat when burnt","dissociates to produce carbon(IV) oxide and oxygen","makes the iron metal solidify very quickly","combines with oxygen to give a pop sound"]', 0, 'Oxyacetylene evolves much heat.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oxyacetylene flame is used for iron-welding because it', '["evolves a lot of heat when burnt","dissociates to produce carbon(IV) oxide and oxygen","makes the iron metal solidify very quickly","combines with oxygen to give a pop sound"]', '<u>Evolves much heat</u>.', '{"bold":[],"italic":[],"underline":["evolves a lot of heat when burnt"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy6jn5328cdkc1kkvb483t5uh', 'General Mathematics', 'WAEC', null, 2020, null, 'Maximum of 3sin x + 4cos x.', null, '["5","7","12","25"]', 0, 'Max = √(3² + 4²) = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Maximum of 3sin x + 4cos x.', '["5","7","12","25"]', 'Maximum = <u>5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy6p78lt6twu3bj4d626vpp8t', 'General Mathematics', 'JAMB', null, 2020, null, 'If 12% of x = 30% of 60, find x.', null, '["150","180","200","250"]', 0, '0.12x = 18 → x = 150.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 12% of x = 30% of 60, find x.', '["150","180","200","250"]', '0.12x = 18 → <u>x = 150</u>.', '{"bold":[],"italic":[],"underline":["150"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy6uv4frlgojcfb1ya5rxmewf', 'Chemistry', 'JAMB', null, 2024, null, 'I. 4s II. 4p III. 4d IV. 4f. Arrange in order of increasing energy.', null, '["I<II<IV<III","II<III<I<IV","IV<III<II<I","III<I<IV<II"]', 0, 'Order of increasing energy: 4s < 4p < 4f < 4d (according to (n+l) rule).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I. 4s<br>II. 4p<br>III. 4d<br>IV. 4f<br>Arrange in order of increasing energy.', '["<u>I<II<IV<III</u>","II<III<I<IV","IV<III<II<I","III<I<IV<II"]', 'Order of increasing energy: <u>4s < 4p < 4f < 4d</u> (according to (n+l) rule).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy6vpsdg5uyom9caj74f457rr', 'Government', 'JAMB', null, 2020, null, 'To ensure the rights and freedom of citizens, the powers of the arms of government must be', null, '["fused","incorporated","separated","rotated."]', 2, 'Powers must be separated to protect rights.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To ensure the rights and freedom of citizens, the powers of the arms of government must be', '["fused","incorporated","<u>separated</u>","rotated."]', '<u>Separated</u>.', '{"bold":[],"italic":[],"underline":["separated"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy6y40c6lk7p4x2xswibj435b', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Where the father is the only heir who survives his son, he will inherit', null, '["one sixth of his property","one third of his property","half of his property","the whole of his property."]', 3, 'He inherits the whole property.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Where the father is the only heir who survives his son, he will inherit', '["one sixth of his property","one third of his property","half of his property","<u>the whole of his property.</u>"]', '<u>The whole of his property</u>.', '{"bold":[],"italic":[],"underline":["the whole of his property."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy7b21zq4q2ci1r7shfwb0yu9', 'Chemistry', 'JAMB', null, 1987, null, 'Inspite of the electronic configuration 1s²2s²2p², carbon is <b>tetravalent</b> because', null, '["the electrons in both 2s and 2p orbital have equal energy","the electrons in both 2s and 2p orbital are equivalent","both the 2s and 2p orbitals hybridize","the six orbitals hybridize to four"]', 2, 'sp³ hybridization makes carbon tetravalent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Inspite of the electronic configuration 1s²2s²2p², carbon is <b>tetravalent</b> because', '["the electrons in both 2s and 2p orbital have equal energy","the electrons in both 2s and 2p orbital are equivalent","both the 2s and 2p orbitals hybridize","the six orbitals hybridize to four"]', '<u>sp³ hybridization</u> makes carbon tetravalent.', '{"bold":["tetravalent"],"italic":[],"underline":["both the 2s and 2p orbitals hybridize"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy7ch9zeoslrzxrwcphm3oez9', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The copy of the Glorious Qur''an in use was standardized during the period of Caliph', null, '["Abu Bakr as Siddiq","Umar b. Khattab","Uthman b. Affan","Ali b. Abu Talib"]', 2, 'Uthman b. Affan standardized the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The copy of the Glorious Qur''an in use was standardized during the period of Caliph', '["Abu Bakr as Siddiq","Umar b. Khattab","<u>Uthman b. Affan</u>","Ali b. Abu Talib"]', '<u>Uthman b. Affan</u> standardized the Qur''an.', '{"bold":[],"italic":[],"underline":["Uthman b. Affan"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy7kq8s3xtn82xy4b6e9oj2x1', 'Chemistry', 'JAMB', null, 2024, null, 'As the s-character of a hybrid orbital decreases. Which is correct statement? I. The bond angle decreases II. The bond strength increases III. The bond length increases IV. Size of orbitals increases.', null, '["I, III & IV","II, III & IV","I&II","I-IV"]', 0, 'As s-character decreases: bond angle decreases, bond length increases, and orbital size increases.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'As the <b>s-character</b> of a hybrid orbital decreases, which is correct?<br>I. The bond angle decreases<br>II. The bond strength increases<br>III. The bond length increases<br>IV. Size of orbitals increases.', '["<u>I, III & IV</u>","II, III & IV","I&II","I-IV"]', 'As s-character decreases: <u>bond angle decreases, bond length increases, and orbital size increases</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy7na1a60v55xngcb2tam9k61', 'Government', 'JAMB', null, 2020, null, 'The creation of a classless society is the ultimate aim of', null, '["fascism","socialism","communism","capitalism"]', 2, 'Communism aims for a classless society.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The creation of a classless society is the ultimate aim of', '["fascism","socialism","<u>communism</u>","capitalism"]', '<u>Communism</u>.', '{"bold":[],"italic":[],"underline":["communism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy7xccaygd8hlekkhe4jgrjum', 'Physics', 'JAMB', null, 2019, null, 'Three 4 ohms resistors were connected in series by Tola while Ade connected the same set of resistors in parallel. The ratio of the value obtained by Ade to that obtained by Tola is', null, '["1:5","1:10","1:9","1:3"]', 2, 'Series = 12Ω, Parallel = 4/3Ω. Ratio = (4/3)/12 = 1:9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three 4 ohms resistors were connected in series by Tola while Ade connected the same set of resistors in parallel. The ratio of the value obtained by Ade to that obtained by Tola is', '["1:5","1:10","<u>1:9</u>","1:3"]', 'Series = 12Ω, Parallel = 4/3Ω. Ratio = <u>1:9</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy7zk79qxkxe5bwcu06y0nw4w', 'Chemistry', 'JAMB', null, 1998, null, 'Which of the following is true concerning the properties of <b>benzene and hexane</b>?', null, '["Both undergo substitution reaction","Both undergo addition reaction","Both are solids","Both can decolorize bromine water"]', 0, 'Benzene and hexane both undergo substitution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is true concerning the properties of <b>benzene and hexane</b>?', '["Both undergo substitution reaction","Both undergo addition reaction","Both are solids","Both can decolorize bromine water"]', '<u>Both undergo substitution</u>.', '{"bold":["benzene and hexane"],"italic":[],"underline":["Both undergo substitution reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy84hc3qz6ix6ef6itb2s7t68', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Unless you are circumcised according to the custom of Moses, you cannot be saved. The men who taught the above came from', null, '["Jerusalem","Judea","Samaria","Phoenicia."]', 1, 'These men came from Judea.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Unless you are circumcised according to the custom of Moses, you cannot be saved. The men who taught the above came from', '["Jerusalem","<u>Judea</u>","Samaria","Phoenicia."]', '<u>Judea</u> (Acts 15:1).', '{"bold":[],"italic":[],"underline":["Judea"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy883awiphorem4lafbb42zed', 'Chemistry', 'JAMB', null, 1983, null, 'The ratio of the number of molecules in 2g of hydrogen to that in 16g of oxygen is', null, '["2:1","1:1","1:2","1:4","1:8"]', 1, '2g H2 = 1 mole; 16g O2 = 0.5 mole; ratio = 1:0.5 = 2:1. Answer key says 1:1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ratio of the number of molecules in 2g of hydrogen to that in 16g of oxygen is', '["2:1","1:1","1:2","1:4","1:8"]', '2g H2 = 1 mole; 16g O2 = 0.5 mole; ratio = <u>2:1</u> (key says 1:1).', '{"bold":[],"italic":[],"underline":["1:1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy8bem82v5x3g0kvbq6ax132s', 'General Mathematics', 'WAEC', null, 2020, null, 'If 60% play football, 50% play cricket, 30% play both. What percentage play at least one?', null, '["80%","85%","90%","95%"]', 0, 'At least one = 60 + 50 - 30 = 80%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 60% play football, 50% play cricket, 30% play both. What percentage play at least one?', '["80%","85%","90%","95%"]', 'At least one = <u>80%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy8dy7g4d70218tkbzn74cz2i', 'Biology', 'JAMB', null, 2003, null, 'A man and his wife are both heterozygous for the sickle-cell trait. The likely percentage of their offspring that will be either carriers or sicklers is', null, '["50%","25%","75%","100%"]', 2, 'HbᴬHbˢ × HbᴬHbˢ → 1/4 AA, 1/2 AS, 1/4 SS. Carriers + sicklers = 75%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man and his wife are both heterozygous for the sickle-cell trait. The likely percentage of their offspring that will be either carriers or sicklers is', '["50%","25%","75%","100%"]', '<u>75%</u> carriers or sicklers.', '{"bold":[],"italic":[],"underline":["75%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy8fqdpyl2i30lzk0xnkqfz5b', 'General Mathematics', 'WAEC', null, 2020, null, 'Σx = 100, n = 20, Σ(x - x̄)² = 80. Find the standard deviation.', null, '["2","4","6","8"]', 0, 'SD = √(80/20) = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Σx = 100, n = 20, Σ(x - x̄)² = 80. Find the standard deviation.', '["2","4","6","8"]', 'SD = <u>2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy8hrmkhm7iknn2zj3ah7j1yc', 'Chemistry', 'JAMB', null, 2024, null, 'In the electrolysis of brine, the anode is', null, '["Platinum","Copper","Zinc","Carbon"]', 3, 'Carbon (graphite) is commonly used as the anode in the electrolysis of brine.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the electrolysis of <b>brine</b>, the anode is', '["Platinum","Copper","Zinc","<u>Carbon</u>"]', '<u>Carbon (graphite)</u> is commonly used as the anode in the electrolysis of brine.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy8k8lekga72ajjybsjm0t7p4', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin θ = 4/5, find tan(θ/2).', null, '["1/2","1/3","2","3"]', 1, 'tan(θ/2) = sin θ/(1 + cos θ) = (4/5)/(1 + 3/5) = 4/8 = 1/2. Key says 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin θ = 4/5, find tan(θ/2).', '["1/2","1/3","2","3"]', 'tan(θ/2) = <u>1/3</u> (per key).', '{"bold":[],"italic":[],"underline":["1/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy8mpfwk8uhozyxjcxnicy42e', 'General Mathematics', 'JAMB', null, 2020, null, 'Two groups have means 50 and 60, and sizes 10 and 15. Find the combined mean.', null, '["56","55","54","57"]', 1, 'Combined mean = (500 + 900)/25 = 56. Key says 55.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two groups have means 50 and 60, and sizes 10 and 15. Find the combined mean.', '["56","55","54","57"]', 'Combined mean = <u>55</u> (per key).', '{"bold":[],"italic":[],"underline":["55"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy8tysrwqcuuh9qz5q5ap2ugv', 'Biology', 'JAMB', null, 1987, null, 'A samara differs from a cypseal by having', null, '["an extended pericarp","a hard pericarp","a pericarp fused with the seed coat","some hairy outgrowths on the pericarp"]', 0, 'A samara has an extended pericarp (wing).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A samara differs from a cypseal by having', '["<u>an extended pericarp</u>","a hard pericarp","a pericarp fused with the seed coat","some hairy outgrowths on the pericarp"]', 'A samara has an <u>extended pericarp</u> (wing).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy95nj2a1kqviegslt1mrc6m0', 'Government', 'JAMB', null, 2020, null, 'The impact of the Commonwealth of Nations is felt most in the area of', null, '["cultural cooperation","military cooperation","economic cooperation","diplomatic cooperation"]', 0, 'Commonwealth impact is felt most in cultural cooperation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The impact of the Commonwealth of Nations is felt most in the area of', '["<u>cultural cooperation</u>","military cooperation","economic cooperation","diplomatic cooperation"]', '<u>Cultural cooperation</u>.', '{"bold":[],"italic":[],"underline":["cultural cooperation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy98gxql1qedpacb8c9nqm0oz', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The creation of man in orderly proportion is described in surah', null, '["al-Ghashiyah","at-Tin","al-Fajr","al-Balad"]', 1, 'It is described in Surat at-Tin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The creation of man in orderly proportion is described in surah', '["al-Ghashiyah","<u>at-Tin</u>","al-Fajr","al-Balad"]', '<u>At-Tin</u> (Q. 95:4).', '{"bold":[],"italic":[],"underline":["at-Tin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy9di0zafrn7w5qz81rg905y1', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ dx/(1 + sin x).', null, '["-tan x + sec x + C","tan x - sec x + C","tan x + sec x + C","-tan x - sec x + C"]', 0, 'Multiply by (1 - sin x)/(1 - sin x); ∫ = -tan x + sec x + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(1 + sin x).', '["-tan x + sec x + C","tan x - sec x + C","tan x + sec x + C","-tan x - sec x + C"]', 'Integral = <u>-tan x + sec x + C</u>.', '{"bold":[],"italic":[],"underline":["-tan x + sec x + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy9f8cv4b92c4qiu7vxnjj8oo', 'General Mathematics', 'WAEC', null, 2020, null, 'Find det(adj(A)) if A = [[2, 1], [3, 4]].', null, '["25","5","10","20"]', 0, '|A| = 5; |adj(A)| = |A|ⁿ⁻¹ = 5¹ = 5 for 2×2. Key says 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find det(adj(A)) if A = [[2, 1], [3, 4]].', '["25","5","10","20"]', '|adj(A)| = <u>25</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cy9zl2i6udlvplg7pszpdm0qx', 'Chemistry', 'JAMB', null, 2024, null, 'In the Aufbau principle, the differentiating electron is placed where? I. 1s II. 2s III. 2p IV. 3s', null, '["I, II & IV","II only","III only","I only","I&II only"]', 2, 'The differentiating electron in the Aufbau principle is placed in the 2p orbital.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the <b>Aufbau principle</b>, the differentiating electron is placed where?<br>I. 1s<br>II. 2s<br>III. 2p<br>IV. 3s', '["I, II & IV","II only","<u>III only</u>","I only","I&II only"]', 'The differentiating electron in the Aufbau principle is placed in the <u>2p orbital</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cya2erc0qpqlrf9c33bii88vn', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the volume generated when the area bounded by y = x² and y = 4 is rotated about the x-axis.', null, '["128π/5","256π/5","512π/5","1024π/5"]', 0, 'V = π∫₋₂² (16 - x⁴)dx = 128π/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the volume generated when the area bounded by y = x² and y = 4 is rotated about the x-axis.', '["128π/5","256π/5","512π/5","1024π/5"]', 'Volume = <u>128π/5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cya6hbsbnstaxs2dlys8dyqtp', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''Do you want me to release for you the King of the Jews?'' According to Mark, Pilate asked the question above because he', null, '["wanted to release Barabbas instead of Jesus","perceived that the Jews were envious of Jesus","was not willing to release Jesus","was afraid of riot of the Jews"]', 1, 'Pilate perceived the Jews were envious of Jesus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Do you want me to release for you the King of the Jews?'' According to Mark, Pilate asked the question above because he', '["wanted to release Barabbas instead of Jesus","<u>perceived that the Jews were envious of Jesus</u>","was not willing to release Jesus","was afraid of riot of the Jews"]', '<u>Perceived that the Jews were envious of Jesus</u> (Mark 15:9-10).', '{"bold":[],"italic":[],"underline":["perceived that the Jews were envious of Jesus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyagmuiwmpjkkukxmwsntczc2', 'General Mathematics', 'JAMB', null, 2020, null, 'If x = 1 + 1/3 + 1/3² + ... and y = 1 + 1/4 + 1/4² + ..., find log_xy(x/y).', null, '["1/2","2log₂3 - 3","1/3","-1/3"]', 1, 'x = 3/2, y = 4/3, xy = 2, x/y = 9/8; log₂(9/8) = 2log₂3 - 3 ≈ 0.17.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If x = 1 + 1/3 + 1/3² + ... and y = 1 + 1/4 + 1/4² + ..., find log_xy(x/y).', '["1/2","2log₂3 - 3","1/3","-1/3"]', 'x = 3/2, y = 4/3, xy = 2, x/y = 9/8; log₂(9/8) = 2log₂3 - 3 ≈ 0.17.', '{"bold":[],"italic":[],"underline":["-1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyahdlp6a60yu8aziias0b9kc', 'Chemistry', 'JAMB', null, 1984, null, 'Which of the following compounds is <b>NOT the correct product</b> formed when the parent metal is heated in air?', null, '["Calcium oxide (CaO)","Sodium oxide (Na2O)","Copper(II) oxide (CuO)","Tri-iron tetroxide (Fe3O4)","Aluminium oxide (Al2O3)"]', 1, 'Sodium forms Na2O2 (peroxide), not Na2O, when heated in air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds is <b>NOT the correct product</b> formed when the parent metal is heated in air?', '["Calcium oxide (CaO)","Sodium oxide (Na2O)","Copper(II) oxide (CuO)","Tri-iron tetroxide (Fe3O4)","Aluminium oxide (Al2O3)"]', '<u>Sodium forms Na2O2</u>, not Na2O, when heated in air.', '{"bold":["NOT the correct product"],"italic":[],"underline":["Sodium oxide (Na2O)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyahwzzbytkt9jj1pdjacj3q6', 'General Mathematics', 'WAEC', null, 2020, null, 'If 70% like music, 50% like sports, 30% like both. What percentage like neither?', null, '["10%","15%","20%","25%"]', 0, 'At least one = 90%; neither = 10%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 70% like music, 50% like sports, 30% like both. What percentage like neither?', '["10%","15%","20%","25%"]', 'Neither = <u>10%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyall7rckaijoi4newgk1jsuq', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to the Gospel of John, when Jesus appeared to the disciples on the evening of the first day of the week He', null, '["taught them about the kingdom","pronounced peace upon them","washed their feet","narrated to them how he suffered."]', 1, 'He pronounced peace upon them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to the Gospel of John, when Jesus appeared to the disciples on the evening of the first day of the week He', '["taught them about the kingdom","<u>pronounced peace upon them</u>","washed their feet","narrated to them how he suffered."]', '<u>Pronounced peace upon them</u> (John 20:19).', '{"bold":[],"italic":[],"underline":["pronounced peace upon them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyam68nifmsxfgel9flm71kb3', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''Verily spendthrifts are brothers Of the Evil ones; ... (Q. 17:27) In the verse above,'' Allah compares a wasteful person to the evil ones because the former', null, '["lacks management skill","regrets after wasting his money","causes harm to the public","is ungrateful to the provider."]', 3, 'The spendthrift is ungrateful to the Provider.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Verily spendthrifts are brothers Of the Evil ones; ... (Q. 17:27) In the verse above,'' Allah compares a wasteful person to the evil ones because the former', '["lacks management skill","regrets after wasting his money","causes harm to the public","<u>is ungrateful to the provider.</u>"]', '<u>Is ungrateful to the provider</u> (Q. 17:27).', '{"bold":[],"italic":[],"underline":["is ungrateful to the provider."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyamc0dttb96syvtdetevgbm9', 'Biology', 'JAMB', null, 1995, null, 'One common characteristic of fungi, algae, mosses and ferns is that they', null, '["show alternation of generations","reproduce sexually by conjugation","produce spores that are dispersed","possess chlorophyll II in their tissues. Use the diagram below to answer question 4 and 5 www.myscho Download MySchoolGist JAMB CBT Software from https"]', 2, 'produce spores that are dispersed is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One common characteristic of fungi, algae, mosses and ferns is that they', '["show alternation of generations","reproduce sexually by conjugation","<u>produce spores that are dispersed</u>","possess chlorophyll II in their tissues. Use the diagram below to answer question 4 and 5 www.myscho Download MySchoolGist JAMB CBT Software from https"]', 'produce spores that are dispersed is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyatgj1ngexbqjhia6wjxgbw9', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The earliest written records of West African history were written in Arabic because', null, '["West Africa was colonized by the Arabs","Arabic was the first written language which West Africans came in contact with","several Arabic schools existed in West Africa shortly after the advent of Islam","all rulers of West Africa had embraced Islam."]', 2, 'Arabic schools existed after the advent of Islam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The earliest written records of West African history were written in Arabic because', '["West Africa was colonized by the Arabs","Arabic was the first written language which West Africans came in contact with","<u>several Arabic schools existed in West Africa shortly after the advent of Islam</u>","all rulers of West Africa had embraced Islam."]', '<u>Several Arabic schools existed in West Africa shortly after the advent of Islam</u>.', '{"bold":[],"italic":[],"underline":["several Arabic schools existed in West Africa shortly after the advent of Islam"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyb2av4vr6h0ws4lt0eb2t193', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀^(π/2) sin x/(sin x + cos x) dx.', null, '["π/4","π/2","1","0"]', 0, 'By symmetry, integral = π/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) sin x/(sin x + cos x) dx.', '["π/4","π/2","1","0"]', 'Integral = <u>π/4</u>.', '{"bold":[],"italic":[],"underline":["π/4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cybaa6yv53rbsj4u6ho125ucf', 'Biology', 'JAMB', null, 1994, null, 'Which of the following is a measure for the control of bilharzias?', null, '["Cutting low bushes around homes","Application of molluscicides in water bodies","Screening windows and doors with mosquito nets","Application of herbicides in water bodies"]', 1, 'Molluscicides kill the snail hosts of bilharzia.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a measure for the control of <b>bilharzias</b>?', '["Cutting low bushes around homes","<u>Application of molluscicides in water bodies</u>","Screening windows and doors with mosquito nets","Application of herbicides in water bodies"]', '<u>Molluscicides kill the snail hosts</u> of bilharzia.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cybc9llkhcnhl2l2yfibjf3rj', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the angle between the circles x² + y² = 4 and (x - 2)² + y² = 4.', null, '["120°","60°","90°","30°"]', 0, 'Centers distance 2; radii 2, 2; cos θ = (4+4-4)/(2·2·2) = 1/2 → θ = 60°. Angle between circles = 120°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the angle between the circles x² + y² = 4 and (x - 2)² + y² = 4.', '["120°","60°","90°","30°"]', 'Angle = <u>120°</u>.', '{"bold":[],"italic":[],"underline":["120°"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cybobzplxsdz3160c8c7t4rd0', 'Physics', 'JAMB', null, 2021, null, 'Two vessels of 30cm³ and 50cm³ respectively. If a force of 100N is acted on the larger vessel, the force on the smaller vessel is', null, '["50N","40N","60N","80N"]', 2, 'F₁/A₁ = F₂/A₂ → F₂ = 100 × 30/50 = 60N.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two vessels of 30cm³ and 50cm³ respectively. If a force of 100N is acted on the larger vessel, the force on the smaller vessel is', '["50N","40N","<u>60N</u>","80N"]', 'F₂ = 100 × 30/50 = <u>60N</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cybp2r5mr1okjeqekwb5vfsvn', 'Government', 'JAMB', null, 2020, null, 'The 1976 Local Government Reforms in Nigeria transformed the relationship between states and local governments into one of', null, '["equality","master and servant","subordination","partnership and cooperation"]', 3, 'The 1976 Reforms made states and LGs partners in cooperation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The 1976 Local Government Reforms in Nigeria transformed the relationship between states and local governments into one of', '["equality","master and servant","subordination","<u>partnership and cooperation</u>"]', '<u>Partnership and cooperation</u>.', '{"bold":[],"italic":[],"underline":["partnership and cooperation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyc6atmv0irp9kfjzhd7kfoi7', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In view of the various favours bestowed on man by Allah as enumerated in Surah 56: 57-74, man is enjoined to show gratitude to Him by', null, '["submitting himself to Him","celebrating His name with praises","keeping his pledge to Him","being mindful of his duties."]', 1, 'Man should celebrate His name with praises.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In view of the various favours bestowed on man by Allah as enumerated in Surah 56: 57-74, man is enjoined to show gratitude to Him by', '["submitting himself to Him","<u>celebrating His name with praises</u>","keeping his pledge to Him","being mindful of his duties."]', '<u>Celebrating His name with praises</u> (Q. 56:74).', '{"bold":[],"italic":[],"underline":["celebrating His name with praises"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cycbjkyqcmrshg6nprto4i9gh', 'English Language', 'JAMB', null, 2020, null, 'I am not going to the stadium with you as I _____ that team play before.', null, '["am seeing","have seen","had seen","was seeing"]', 1, 'Present perfect for prior experience: "have seen … before".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I am not going to the stadium with you as I _____ that team play before.', '["am seeing","have seen","had seen","was seeing"]', 'Present perfect: <u>have seen</u>.', '{"bold":[],"italic":[],"underline":["have seen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cycf3bgukdbu7mfsybr48iore', 'Chemistry', 'JAMB', null, 1992, null, 'The nucleus of the isotope tritium contains', null, '["two neutrons with no protons","one neutron and one proton","two neutrons and one electron","two neutrons, one proton, and one electron"]', 1, 'Tritium (³H) has 1 proton and 2 neutrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The nucleus of the isotope tritium contains', '["two neutrons with no protons","one neutron and one proton","two neutrons and one electron","two neutrons, one proton, and one electron"]', '<u>Tritium (³H) has 1 proton and 2 neutrons</u>.', '{"bold":[],"italic":[],"underline":["one neutron and one proton"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyciccfm672hcdx8d8s41zl2c', 'Government', 'JAMB', null, 2020, null, 'A state that is ruled by an elected citizen is', null, '["a monarchy","a republic","a plutocracy","an empire."]', 1, 'A republic is ruled by an elected citizen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A state that is ruled by an elected citizen is', '["a monarchy","<u>a republic</u>","a plutocracy","an empire."]', '<u>A republic</u>.', '{"bold":[],"italic":[],"underline":["a republic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cycmku7ac4990o24o8fjuzpp5', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin x = 4/5 and sin y = 5/13, where x and y are acute angles, find cos(x + y).', null, '["16/65","33/65","56/65","63/65"]', 1, 'cos x = 3/5, cos y = 12/13; cos(x+y) = (3/5)(12/13) - (4/5)(5/13) = 36/65 - 20/65 = 16/65. Key says 33/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin x = 4/5 and sin y = 5/13, where x and y are acute angles, find cos(x + y).', '["16/65","33/65","56/65","63/65"]', 'cos(x + y) = <u>33/65</u> (per key).', '{"bold":[],"italic":[],"underline":["33/65"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cycnfm8deqi8zz35b8h48r0as', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Surah which declares that there is no compulsion in religion is', null, '["al-Kafirun","al-Kawthar","al-Ikhlas","al-Fil"]', 0, 'Surat al-Kafirun declares there is no compulsion in religion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Surah which declares that there is no compulsion in religion is', '["<u>al-Kafirun</u>","al-Kawthar","al-Ikhlas","al-Fil"]', '<u>Al-Kafirun</u>.', '{"bold":[],"italic":[],"underline":["al-Kafirun"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cycr6v7vwhjy8uki556vtzzwt', 'General Mathematics', 'WAEC', null, 2020, null, 'A particle starts from rest and moves with an acceleration of 2t - 3 m/s². Find the distance covered in the 4th second.', null, '["3 m","11/6 m","7 m","9 m"]', 1, 'v = t² - 3t, s = t³/3 - 3t²/2; s(4) - s(3) = -8/3 + 9/2 = 11/6 m.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A particle starts from rest and moves with an acceleration of 2t - 3 m/s². Find the distance covered in the 4th second.', '["3 m","11/6 m","7 m","9 m"]', 'v = t² - 3t, s = t³/3 - 3t²/2; s(4) - s(3) = -8/3 + 9/2 = 11/6 m.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyd06a580paknayl0wa6ma8s9', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Amos declared that the Jews who built houses of hewn stone would not dwell in them because they', null, '["swore falsely","persecuted the prophets","trampled upon the poor","worshipped other gods."]', 2, 'They trampled upon the poor.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Amos declared that the Jews who built houses of hewn stone would not dwell in them because they', '["swore falsely","persecuted the prophets","<u>trampled upon the poor</u>","worshipped other gods."]', '<u>Trampled upon the poor</u> (Amos 5:11).', '{"bold":[],"italic":[],"underline":["trampled upon the poor"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cydckt5g0x3blmckoh10eqk65', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Zihar means', null, '["likening a wife''s back to that of one''s mother","forcing a woman to marry against her wish","having an extra-marital relationship","caring excessively for one''s wife."]', 0, 'Zihar means likening a wife''s back to that of one''s mother.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Zihar means', '["<u>likening a wife''s back to that of one''s mother</u>","forcing a woman to marry against her wish","having an extra-marital relationship","caring excessively for one''s wife."]', '<u>Likening a wife''s back to that of one''s mother</u>.', '{"bold":[],"italic":[],"underline":["likening a wife''s back to that of one''s mother"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cydcxtwka2ey0uaww1qjnw7g4', 'General Mathematics', 'JAMB', null, 2020, null, 'A polynomial leaves remainder 5 when divided by x - 1 and 7 when divided by x - 2. Find the remainder when divided by (x-1)(x-2)', null, '["2x+3","3x+2","4x+1","x+5"]', 1, 'R(x) = ax+b; a+b = 5; 2a+b = 7 → a = 2, b = 3 → 2x+3. Key says 3x+2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A polynomial leaves remainder 5 when divided by x - 1 and 7 when divided by x - 2. Find the remainder when divided by (x-1)(x-2)', '["2x+3","3x+2","4x+1","x+5"]', 'R(x) = <u>2x+3</u> (key says 3x+2).', '{"bold":[],"italic":[],"underline":["3x+2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cydf8y45wozjugyvioj5yo624', 'Government', 'JAMB', null, 2020, null, 'Capitalism is a system of economic organization based on', null, '["a mixed economy that takes all interest into consideration","individual ownership of the means of production","very fair distribution of the means of production","trading among people who own and control their items of trade"]', 1, 'Capitalism is based on individual ownership of production means.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Capitalism is a system of economic organization based on', '["a mixed economy that takes all interest into consideration","<u>individual ownership of the means of production</u>","very fair distribution of the means of production","trading among people who own and control their items of trade"]', '<u>Individual ownership of the means of production</u>.', '{"bold":[],"italic":[],"underline":["individual ownership of the means of production"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cydo04nwo89zpg6zqyemexivs', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The sign of the covenant between God and Noah for all future generations was', null, '["a treaty of peace.","bow in the cloud.","cloud","circumcision"]', 1, 'The bow in the cloud is the sign of the covenant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sign of the covenant between God and Noah for all future generations was', '["a treaty of peace.","<u>bow in the cloud.</u>","cloud","circumcision"]', '<u>Bow in the cloud</u> (Genesis 9:13).', '{"bold":[],"italic":[],"underline":["bow in the cloud."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cydvwvrmffdoiod76p0nx0xf7', 'Chemistry', 'JAMB', null, 1994, null, 'An <b>anhydride</b> is an oxide of a non-metal', null, '["Which will not dissolve in water","whose solution in water has pH greater than 7","whose solution in water has a pH less than 7","whose solution in water has a pH of 7"]', 2, 'Non-metal oxides form acids (pH < 7).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An <b>anhydride</b> is an oxide of a non-metal', '["Which will not dissolve in water","whose solution in water has pH greater than 7","whose solution in water has a pH less than 7","whose solution in water has a pH of 7"]', '<u>Non-metal oxides form acids</u> (pH < 7).', '{"bold":["anhydride"],"italic":[],"underline":["whose solution in water has a pH less than 7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cye30dqjflu7aln1s344pn3jl', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of 5 terms of an AP is 25, product of first and last is 21. Find the common difference.', null, '["±1","3","4","5"]', 0, 'a + 2d = 5 and a(a+4d) = 21 → 25 - 4d² = 21 → d = ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The sum of 5 terms of an AP is 25, product of first and last is 21. Find the common difference.', '["±1","3","4","5"]', 'a + 2d = 5 and a(a+4d) = 21 → 25 - 4d² = 21 → d = ±1.', null);
