insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyegyywtghwq06sd3ivjzwwsa', 'Chemistry', 'JAMB', null, 1989, null, 'A hydrated salt of formula MSO4·xH2O contains 45.3% by mass of the water of crystallization. Calculate the value of x. [M=56, S=32, O=16, H=1]', null, '["3","5","7","10"]', 1, 'MSO4 = 152; water = 45.3% of total; 18x/(152+18x) = 0.453 → x ≈ 7. Key says 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A hydrated salt of formula MSO4·xH2O contains 45.3% by mass of the water of crystallization. Calculate the value of x. [M=56, S=32, O=16, H=1]', '["3","5","7","10"]', '18x/(152+18x) = 0.453 → <u>x ≈ 7</u> (key says 5).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyeh4iopgtwbwyjii7xh4guqb', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate 32₄ × 21₄ in base four.', null, '["1332₄","1322₄","1232₄","1222₄"]', 1, '32₄ = 14; 21₄ = 9; product = 126 = 1332₄. Key says 1322₄.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 32₄ × 21₄ in base four.', '["1332₄","1322₄","1232₄","1222₄"]', '32₄ × 21₄ = <u>1332₄</u> (key says 1322₄).', '{"bold":[],"italic":[],"underline":["1322₄"],"fillBlanks":[]}');
