insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyex0dt8wrqm2xe08814t3riv', 'Chemistry', 'JAMB', null, 1991, null, 'A sample of a gas exerts a pressure of 8.2 atm when confined in a 2.93dm³ container at 20°C. The number of moles of gas in the sample is [R=0.082 litre atm/deg mole]', null, '["1.00","2.00","3.00","4.00"]', 0, 'n = PV/RT = (8.2 × 2.93)/(0.082 × 293) = 1.00 mol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A sample of a gas exerts a pressure of 8.2 atm when confined in a 2.93dm³ container at 20°C. The number of moles of gas in the sample is [R=0.082 litre atm/deg mole]', '["1.00","2.00","3.00","4.00"]', 'n = <u>1.00 mol</u>.', '{"bold":[],"italic":[],"underline":["1.00"],"fillBlanks":[]}');
