insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyfg1dqrxvpzqtsxkq30l816w', 'English Language', 'JAMB', null, 2020, null, 'Yesterday in the hall, Ola said that _____ his watch.', null, '["he had forgot","he had mislaid","he has misplaced","he have lost"]', 1, 'Had mislaid = past perfect, correct form.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Yesterday in the hall, Ola said that _____ his watch.', '["he had forgot","he had mislaid","he has misplaced","he have lost"]', '<u>He had mislaid</u> his watch.', '{"bold":[],"italic":[],"underline":["he had mislaid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyfg7k70h4168ik0qseh634nb', 'Physics', 'JAMB', null, 2021, null, 'Calculate the internal resistance of a cell of 0.3A and 0.5A with resistance of 15 & 6 ohms', null, '["3 ohms","6 ohms","7.5 ohms","8.5 ohms"]', 2, 'E = I₁(R₁+r) = I₂(R₂+r). 0.3(15+r) = 0.5(6+r) → 4.5+0.3r = 3+0.5r → r = 7.5Ω.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Calculate the internal resistance of a cell of 0.3A and 0.5A with resistance of 15 & 6 ohms', '["3 ohms","6 ohms","<u>7.5 ohms</u>","8.5 ohms"]', '0.3(15+r) = 0.5(6+r) → <u>r = 7.5Ω</u>.', null);
