insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cygrasu1szkmfa6q4vtqapqpv', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the equation of the circle with a diameter from (1, 2) to (3, 4).', null, '["x² + y² - 4x - 6y + 11 = 0","x² + y² - 4x - 6y + 13 = 0","x² + y² - 4x - 6y + 9 = 0","x² + y² - 4x - 6y + 7 = 0"]', 0, 'Center (2, 3), r² = 2; equation: (x-2)² + (y-3)² = 2 → x² + y² - 4x - 6y + 11 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the circle with a diameter from (1, 2) to (3, 4).', '["x² + y² - 4x - 6y + 11 = 0","x² + y² - 4x - 6y + 13 = 0","x² + y² - 4x - 6y + 9 = 0","x² + y² - 4x - 6y + 7 = 0"]', 'Equation: <u>x² + y² - 4x - 6y + 11 = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyh4kvep7fvjn7fl7xwec5xz2', 'Chemistry', 'JAMB', null, 1994, null, 'The general formula of <b>alkanones</b> is', null, '["RCHO","RCO","RCOOH","RCOOR"]', 1, 'Alkanones have the general formula RCO (ketone).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The general formula of <b>alkanones</b> is', '["RCHO","RCO","RCOOH","RCOOR"]', '<u>RCO (ketone)</u>.', '{"bold":["alkanones"],"italic":[],"underline":["RCO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyh6n1tp0d7sgosm91eh8wl0q', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the locus of the midpoint of chords of x² + y² = 16 passing through (2, 0).', null, '["Circle","Ellipse","Hyperbola","Parabola"]', 0, 'Locus is a circle (with diameter between origin and point).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the locus of the midpoint of chords of x² + y² = 16 passing through (2, 0).', '["Circle","Ellipse","Hyperbola","Parabola"]', '<u>Circle</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyhe93xec9ivxp6uts6ap77sv', 'General Mathematics', 'WAEC', null, 2020, null, 'If a, b, c, d are in GP, then (a - d)² = ?', null, '["(b - c)² + (c - a)² + (d - b)²","(b - c)² + (c - a)² + (d - a)²","(b + c)² + (a - d)²","(a + b)² - (c + d)²"]', 0, 'Identity for GP: (a-d)² = (b-c)² + (c-a)² + (d-b)².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c, d are in GP, then (a - d)² = ?', '["(b - c)² + (c - a)² + (d - b)²","(b - c)² + (c - a)² + (d - a)²","(b + c)² + (a - d)²","(a + b)² - (c + d)²"]', 'Identity holds.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyhixpdigy3vgf5g30vz93ck7', 'Chemistry', 'JAMB', null, 1984, null, 'Some properties of chemical substances are mentioned below:<br>(i) sour taste<br>(ii) slippery to touch<br>(iii) yields alkaline gas with ammonium salts<br>(iv) has pH less than 7<br>(v) turns phenolphthalein pink<br>Which of the above are <b>NOT typical properties of alkalis</b>?', null, '["(i), (iv) and (v)","(iv) and (v)","(i) and (iv)","(ii) and (iii)","(i), (ii) and (iii)"]', 2, 'Sour taste and pH less than 7 are properties of acids, not alkalis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Some properties of chemical substances are mentioned below:<br>(i) sour taste<br>(ii) slippery to touch<br>(iii) yields alkaline gas with ammonium salts<br>(iv) has pH less than 7<br>(v) turns phenolphthalein pink<br>Which of the above are <b>NOT typical properties of alkalis</b>?', '["(i), (iv) and (v)","(iv) and (v)","(i) and (iv)","(ii) and (iii)","(i), (ii) and (iii)"]', '<u>Sour taste and pH less than 7</u> are acid properties.', '{"bold":["NOT typical properties of alkalis"],"italic":[],"underline":["(i) and (iv)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyhn8d37y4657w0yldyv7brpi', 'Chemistry', 'JAMB', null, 1985, null, 'The reaction Mg + H2O → MgO + H2 takes place only in the presence of', null, '["excess Mg ribbon","excess cold water","very hot water","steam"]', 3, 'Mg reacts with steam, not cold water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reaction Mg + H2O → MgO + H2 takes place only in the presence of', '["excess Mg ribbon","excess cold water","very hot water","steam"]', '<u>Mg reacts with steam</u>.', '{"bold":[],"italic":[],"underline":["steam"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyhqw345cpt096rtvq22r0p0t', 'General Mathematics', 'JAMB', null, 2020, null, 'The remainder when x³ + kx² + 3x - 2 divided by x - 1 equals the remainder when divided by x + 1 find k', null, '["3","no such value of k","1","0"]', 1, 'f(1) = k + 2 and f(-1) = k - 6 can never be equal, so no such k exists.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The remainder when x³ + kx² + 3x - 2 divided by x - 1 equals the remainder when divided by x + 1 find k', '["3","no such value of k","1","0"]', 'f(1) = k + 2 and f(-1) = k - 6 can never be equal, so no such k exists.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyi98ao2tzmtmg5lhihlnffg3', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫xe^(x²)dx.', null, '["½e^(x²) + C","e^(x²) + C","2e^(x²) + C","½xe^(x²) + C"]', 0, 'Let u = x²; du = 2x dx → ½∫eᵘdu = ½e^(x²) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫xe^(x²)dx.', '["½e^(x²) + C","e^(x²) + C","2e^(x²) + C","½xe^(x²) + C"]', '∫ = <u>½e^(x²) + C</u>.', '{"bold":[],"italic":[],"underline":["½e^(x²) + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyitvi4y65becelv4uyq7hobk', 'General Mathematics', 'WAEC', null, 2020, null, 'If the lines x + 2y = 5, 3x - y = 4, and kx + 5y = 8 are concurrent, find k.', null, '["5","1/13","7","8"]', 1, 'Lines 1 and 2 meet at (13/7, 11/7); k(13/7) + 5(11/7) = 8 → k = 1/13.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If the lines x + 2y = 5, 3x - y = 4, and kx + 5y = 8 are concurrent, find k.', '["5","1/13","7","8"]', 'Lines 1 and 2 meet at (13/7, 11/7); k(13/7) + 5(11/7) = 8 → k = 1/13.', null);
