insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cykyedzdhwncqtui0l6wxu9j7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Romans, justification is by faith through', null, '["works of righteousness","redemption in Christ","being filled with the Holy Spirit","obedience to the law."]', 1, 'Justification is through redemption in Christ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Romans, justification is by faith through', '["works of righteousness","<u>redemption in Christ</u>","being filled with the Holy Spirit","obedience to the law."]', '<u>Redemption in Christ</u> (Romans 3:24).', '{"bold":[],"italic":[],"underline":["redemption in Christ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyl03ycqmn7dlnkysb19vgmps', 'Biology', 'JAMB', null, 1983, null, 'Which sequence represents the correct order of organism in a food chain? 1. Toad, 2. Mucuna, 3. Grasshopper, 4. Snake, 5. Hawk', null, '["5-4-1-3-2","1-2-3-4-5","2-1-3-4-5","2-3-1-5-4","2-3-1-4-5"]', 4, 'Food chain: Mucuna (2) → Grasshopper (3) → Toad (1) → Snake (4) → Hawk (5) = 2-3-1-4-5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which sequence represents the correct order of organism in a food chain?<br>1. Toad<br>2. Mucuna<br>3. Grasshopper<br>4. Snake<br>5. Hawk', '["5-4-1-3-2","1-2-3-4-5","2-1-3-4-5","2-3-1-5-4","<u>2-3-1-4-5</u>"]', 'Food chain: Mucuna (2) → Grasshopper (3) → Toad (1) → Snake (4) → Hawk (5) = <u>2-3-1-4-5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyl5o9x0no5hopl27a2kqwg1j', 'Biology', 'JAMB', null, 2000, null, 'Use the diagram to answer questions 1 and 2. The part that will develop into an organ for feeling is labelled', null, '["IV","III","II","I"]', 3, 'Part I (antenna) develops into an organ for feeling.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 1 and 2. The part that will develop into an organ for feeling is labelled', '["IV","III","II","I"]', '<u>Part I (antenna)</u> develops into an organ for feeling.', '{"bold":[],"italic":[],"underline":["I"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyljn31o68wd4pigo9rwgxuth', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ dx/(x² - a²).', null, '["(1/2a)ln","(x - a)/(x + a)","+ C","(1/2a)ln","(x + a)/(x - a)","+ C","(1/a)ln","(x - a)/(x + a)","+ C","(1/a)ln","(x + a)/(x - a)","+ C"]', 0, 'Standard integral: (1/2a)ln|(x - a)/(x + a)| + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(x² - a²).', '["(1/2a)ln","(x - a)/(x + a)","+ C","(1/2a)ln","(x + a)/(x - a)","+ C","(1/a)ln","(x - a)/(x + a)","+ C","(1/a)ln","(x + a)/(x - a)","+ C"]', 'Integral = <u>(1/2a)ln|(x - a)/(x + a)| + C</u>.', '{"bold":[],"italic":[],"underline":["(1/2a)ln|(x - a)/(x + a)| + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cylszp3oask9i4weai29aioa0', 'Biology', 'JAMB', null, 1997, null, 'Annelids differ from nematodes in that they', null, '["exhibit bilateral symmetry","are triploblastic","are metamerically segmented","possess complete digestive system"]', 2, 'Annelids are segmented; nematodes are not.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Annelids differ from nematodes in that they', '["exhibit bilateral symmetry","are triploblastic","are metamerically segmented","possess complete digestive system"]', '<u>Annelids are metamerically segmented</u>.', '{"bold":[],"italic":[],"underline":["are metamerically segmented"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cymjih47ggplpi3bqd5z9pqia', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Josiah defiled Topheth which was in the valley of the sons of Hinnom during his reform in Israel so that', null, '["no one might sacrifice human beings again to Molech.","he might pull down Topheth and break Molech into pieces.","he might revive the worship of the sun god.","no one would worship Molech."]', 0, 'Josiah defiled Topheth so no one would sacrifice to Molech.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Josiah defiled Topheth which was in the valley of the sons of Hinnom during his reform in Israel so that', '["<u>no one might sacrifice human beings again to Molech.</u>","he might pull down Topheth and break Molech into pieces.","he might revive the worship of the sun god.","no one would worship Molech."]', '<u>No one might sacrifice human beings again to Molech</u> (2 Kings 23:10).', '{"bold":[],"italic":[],"underline":["no one might sacrifice human beings again to Molech."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cymmfllq06vbxoofdlyva8dpb', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...Why then have you not kept watch over your lord the king?... The question above by David was addressed to', null, '["Abishai","Abner","Amasa","Joab"]', 1, 'David addressed Abner.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...Why then have you not kept watch over your lord the king?... The question above by David was addressed to', '["Abishai","<u>Abner</u>","Amasa","Joab"]', '<u>Abner</u> (1 Samuel 26:15-16).', '{"bold":[],"italic":[],"underline":["Abner"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cymoswas1eotg1y676jjbe58w', 'Biology', 'JAMB', null, 2001, null, 'Use the diagram to answer questions 10 and 11. The structures labelled II and III respectively are', null, '["female organs and rhizoid","male organs and rhizoid","sporophyte and soil","annulus and stalk of sporangium"]', 1, 'II = male organs; III = rhizoid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 10 and 11. The structures labelled II and III respectively are', '["female organs and rhizoid","male organs and rhizoid","sporophyte and soil","annulus and stalk of sporangium"]', '<u>II = male organs; III = rhizoid</u>.', '{"bold":[],"italic":[],"underline":["male organs and rhizoid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cymoy4cstv7osp9hwohnvydfw', 'English Language', 'JAMB', null, 2020, null, 'The board has been having _____ series of meetings lately.', null, '["some","a","a lot","many"]', 1, 'Series is a singular count noun here: "a series of meetings".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The board has been having _____ series of meetings lately.', '["some","a","a lot","many"]', 'The singular count noun "series" takes <u>a</u>.', '{"bold":[],"italic":[],"underline":["a"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cymxqxl0hpgyqrleucng0uank', 'Chemistry', 'JAMB', null, 1996, null, '2H2S(g) + SO2(g) → 3S(s) + 2H2O(l). The above reaction is', null, '["a redox reaction in which H2S is the oxidant and SO2 is the reductant","a redox reaction in which SO2 is the oxidant and H2S is the reductant","Not a redox reaction because there is no oxidant in the reaction equation","Not a redox reaction because there is no reductant in the reaction equation"]', 1, 'SO2 is reduced (oxidant); H2S is oxidized (reductant).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2H2S(g) + SO2(g) → 3S(s) + 2H2O(l). The above reaction is', '["a redox reaction in which H2S is the oxidant and SO2 is the reductant","a redox reaction in which SO2 is the oxidant and H2S is the reductant","Not a redox reaction because there is no oxidant in the reaction equation","Not a redox reaction because there is no reductant in the reaction equation"]', '<u>SO2 oxidant, H2S reductant</u>.', '{"bold":[],"italic":[],"underline":["a redox reaction in which SO2 is the oxidant and H2S is the reductant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyn3245qavozzlqb2zyyy00rz', 'Biology', 'JAMB', null, 2003, null, 'Which of the following requires the use of carbon dating to prove that evolution has occurred?', null, '["biochemical similarities","molecular records","fossil records","comparative anatomy"]', 2, 'fossil records is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following requires the use of carbon dating to prove that evolution has occurred?', '["biochemical similarities","molecular records","<u>fossil records</u>","comparative anatomy"]', 'fossil records is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyn3gxqckb4uqwozcyrvyyzub', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the area of the triangle with vertices A(2, 3, 1), B(1, 0, 2), and C(-1, 2, 0).', null, '["√14","√74/2","√14/2","√74"]', 1, 'Area = ½|AB × AC| = ½√74.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area of the triangle with vertices A(2, 3, 1), B(1, 0, 2), and C(-1, 2, 0).', '["√14","√74/2","√14/2","√74"]', 'Area = <u>√74/2</u>.', '{"bold":[],"italic":[],"underline":["√74/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyn8skz0xvnzmykztjhfqpg81', 'Chemistry', 'JAMB', null, 1991, null, 'NO + CO ⇌ ½N2 + CO2, ΔH = -89.3kJ. What conditions would favour maximum conversion of nitrogen(II) oxide and carbon(II) oxide in the reaction above?', null, '["low temperature and high pressure","high temperature and low pressure","high temperature and high pressure","low temperature and low pressure"]', 0, 'Exothermic reaction favours low T; fewer gas moles on product side favours high P.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'NO + CO ⇌ ½N2 + CO2, ΔH = -89.3kJ. What conditions would favour maximum conversion of nitrogen(II) oxide and carbon(II) oxide in the reaction above?', '["low temperature and high pressure","high temperature and low pressure","high temperature and high pressure","low temperature and low pressure"]', '<u>Low temperature and high pressure</u> favour conversion.', '{"bold":[],"italic":[],"underline":["low temperature and high pressure"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cynahmq35018eilbtq76odwpc', 'Biology', 'JAMB', null, 1984, null, 'If a handful of soil is shaken with water and left to settle, the soil particles will settle from light to heavy particles as follows:', null, '["humus, clay, silt, sand, stones","humus, silt, clay, sand, stones","humus, clay, silt, stones, sand","humus, sand, silt, clay, stones","clay, humus, silt, sand, stones"]', 0, 'Soil particles settle in order: humus, clay, silt, sand, stones.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a handful of soil is shaken with water and left to settle, the soil particles will settle from light to heavy particles as follows:', '["<u>humus, clay, silt, sand, stones</u>","humus, silt, clay, sand, stones","humus, clay, silt, stones, sand","humus, sand, silt, clay, stones","clay, humus, silt, sand, stones"]', 'Soil particles settle in order: <u>humus, clay, silt, sand, stones</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cynntaliugrsnvmpiy4551b9b', 'Chemistry', 'JAMB', null, 1991, null, '1.1g of CaCl2 dissolved in 50cm³ of water caused a rise in temperature of 3.4°C. The heat of reaction, ΔH for CaCl2 in kJ per mole is [Ca=40, Cl=35.5, specific heat of water = 4.18 kJ]', null, '["-71.1","-4.18","+17.1","+111.0"]', 0, 'Heat = 50 × 4.18 × 3.4 = 710.6 J; moles = 1.1/111 = 0.0099; ΔH = -71.1 kJ/mol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '1.1g of CaCl2 dissolved in 50cm³ of water caused a rise in temperature of 3.4°C. The heat of reaction, ΔH for CaCl2 in kJ per mole is [Ca=40, Cl=35.5, specific heat of water = 4.18 kJ]', '["-71.1","-4.18","+17.1","+111.0"]', 'ΔH = <u>-71.1 kJ/mol</u>.', '{"bold":[],"italic":[],"underline":["-71.1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cynod7c8wvqde2u58zjllm8j8', 'Biology', 'JAMB', null, 2003, null, 'Organisms I, II, III and IV have surface/volume ratios of 1:2. 1:3, 1:4 and 1:5 respectively. The organism that is likely to have the most complex transport system is', null, '["III","IV","II","I Use the diagram below to answer questions 17 and 18"]', 3, 'I Use the diagram below to answer questions 17 and 18 is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Organisms I, II, III and IV have surface/volume ratios of 1:2. 1:3, 1:4 and 1:5 respectively. The organism that is likely to have the most complex transport system is', '["III","IV","II","<u>I Use the diagram below to answer questions 17 and 18</u>"]', 'I Use the diagram below to answer questions 17 and 18 is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cypgkb48e891e4lpdr5ti5h6f', 'Biology', 'JAMB', null, 2004, null, 'The function of the long-winged reproductives in a termite colony is to', null, '["protect the young","participate in swarming","feed the young","disperse the population"]', 1, 'participate in swarming is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The function of the long-winged reproductives in a termite colony is to', '["protect the young","<u>participate in swarming</u>","feed the young","disperse the population"]', 'participate in swarming is the best answer because it matches the biological principle tested by the question.', null);
