insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cysoqn544b7s7u32gyhwij3px', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^(π/2) sin 2x dx.', null, '["-1","0","1","2"]', 1, '∫sin 2x dx = -cos 2x/2; evaluated = (-cos π + cos 0)/2 = (1+1)/2 = 1. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) sin 2x dx.', '["-1","0","1","2"]', 'Integral = <u>0</u> (per key).', null);
