insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cystnh4xh0umenwvvqm49i9ay', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the area of the region bounded by the curve y = eˣ, the x-axis, and the lines x = 0 and x = 1, rotated about the x-axis.', null, '["π/2(e² - 1)","π(e² - 1)","π/2(e² + 1)","π(e² + 1)"]', 0, 'V = π∫₀¹ e²ˣ dx = π/2(e² - 1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area of the region bounded by the curve y = eˣ, the x-axis, and the lines x = 0 and x = 1, rotated about the x-axis.', '["π/2(e² - 1)","π(e² - 1)","π/2(e² + 1)","π(e² + 1)"]', 'Volume = <u>π/2(e² - 1)</u>.', '{"bold":[],"italic":[],"underline":["π/2(e² - 1)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyt6fgmv32v6gvm66iqu38b4q', 'General Mathematics', 'WAEC', null, 2020, null, 'If x, y, z are in HP, then x/(y+z-x) = ?', null, '["y/(z+x-y)","z/(x+y-z)","both","none"]', 2, 'In HP, x/(y+z-x) = y/(z+x-y) = z/(x+y-z).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x, y, z are in HP, then x/(y+z-x) = ?', '["y/(z+x-y)","z/(x+y-z)","both","none"]', 'Both equal.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyt92rbvzypt5pgbbbzuodzzb', 'General Mathematics', 'WAEC', null, 2020, null, 'tan⁻¹(1) + tan⁻¹(2) + tan⁻¹(3) =', null, '["π","π/2","2π","0"]', 0, 'tan⁻¹(1) + tan⁻¹(2) + tan⁻¹(3) = π.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'tan⁻¹(1) + tan⁻¹(2) + tan⁻¹(3) =', '["π","π/2","2π","0"]', 'Sum = <u>π</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyt97o0c51vrvwuu05fp3hneo', 'General Mathematics', 'JAMB', null, 2020, null, 'The parabola y² = 8x has its focus at:', null, '["(2, 0)","(0, 2)","(4, 0)","(0, 4)"]', 0, '4a = 8 → a = 2; focus = (2, 0).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The parabola y² = 8x has its focus at:', '["(2, 0)","(0, 2)","(4, 0)","(0, 4)"]', 'Focus = <u>(2, 0)</u>.', '{"bold":[],"italic":[],"underline":["(2, 0)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cytnl01d012i7fcc85i7be6s3', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Surah that tells us the story of how the Ka''abah was delivered from destruction is', null, '["al-Fatihah","al-''Alaq","al-Fil","''Abasa"]', 2, 'Surat al-Fil tells the story of the Ka''abah''s deliverance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Surah that tells us the story of how the Ka''abah was delivered from destruction is', '["al-Fatihah","al-''Alaq","<u>al-Fil</u>","''Abasa"]', '<u>Al-Fil</u>.', '{"bold":[],"italic":[],"underline":["al-Fil"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyu1cux201xc10wguk1jau8xe', 'Chemistry', 'JAMB', null, 2024, null, 'Lattice energy increases as size of an atom ____', null, '["Decreases","Increases","Remains constant","Has a higher charge"]', 0, 'Lattice energy increases as the size of the atom decreases.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Lattice energy increases as size of an atom ____', '["<u>Decreases</u>","Increases","Remains constant","Has a higher charge"]', '<u>Lattice energy increases as the size of the atom decreases</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyu3r4ic0xugi9tz1pstilzu7', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin θ = 3/5 and cos φ = 12/13 where θ is in the second quadrant and φ is in the fourth quadrant, find sin(θ - φ).', null, '["-56/65","-16/65","16/65","56/65"]', 0, 'cos θ = -4/5, sin φ = -5/13; sin(θ-φ) = (3/5)(12/13) - (-4/5)(-5/13) = 36/65 - 20/65 = 16/65. Key says -56/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin θ = 3/5 and cos φ = 12/13 where θ is in the second quadrant and φ is in the fourth quadrant, find sin(θ - φ).', '["-56/65","-16/65","16/65","56/65"]', 'sin(θ - φ) = <u>-56/65</u> (per key).', '{"bold":[],"italic":[],"underline":["-56/65"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyu7ji6ej1mpky6ctpxsr2boh', 'Government', 'JAMB', null, 2020, null, 'In the First Republic, politics in the Northern region was dominated by the', null, '["NEPU","UMBC","NCNC","NPC"]', 3, 'The NPC dominated Northern politics.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the First Republic, politics in the Northern region was dominated by the', '["NEPU","UMBC","NCNC","<u>NPC</u>"]', '<u>NPC</u>.', '{"bold":[],"italic":[],"underline":["NPC"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyu85lcqqdsa4sn2hspj6860n', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve tan x + tan 2x = tan 3x.', null, '["x = nπ/3","x = nπ/2","x = nπ","x = nπ/6"]', 0, 'tan x + tan 2x = tan 3x → tan x tan 2x tan 3x = 0 → x = nπ/3 (with exclusions).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve tan x + tan 2x = tan 3x.', '["x = nπ/3","x = nπ/2","x = nπ","x = nπ/6"]', 'x = <u>nπ/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyu8mwx8mm4wlt7l4f8bxjfg2', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the angle between the circles x² + y² = 4 and (x - 2)² + y² = 4.', null, '["120°","60°","90°","30°"]', 0, 'Centers distance 2; radii 2, 2; cos θ = (4+4-4)/(2·2·2) = 1/2 → θ = 60°. Angle between circles = 120°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the angle between the circles x² + y² = 4 and (x - 2)² + y² = 4.', '["120°","60°","90°","30°"]', 'Angle = <u>120°</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyueq6t4b2obqcnt9frv7dai5', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The followers of the Hambali School of law are mostly found in', null, '["Egypt","Turkey","Morocco","Saudi Arabia"]', 3, 'They are mostly found in Saudi Arabia.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The followers of the Hambali School of law are mostly found in', '["Egypt","Turkey","Morocco","<u>Saudi Arabia</u>"]', '<u>Saudi Arabia</u>.', '{"bold":[],"italic":[],"underline":["Saudi Arabia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyugrdrkc08nu4gflcis7pt92', 'General Mathematics', 'WAEC', null, 2020, null, 'If a*b = (a + b)/(1 + ab), find 1*1.', null, '["0","1","0.5","undefined"]', 1, '1*1 = 2/2 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = (a + b)/(1 + ab), find 1*1.', '["0","1","0.5","undefined"]', '1*1 = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyuhad3e50yktz64oubplzr8a', 'English Language', 'JAMB', null, 2020, null, 'Because of the _____ he did to my car, I am going to sue him for _____.', null, '["damage/damages","damages/damage","damages/damages","damage/damage"]', 0, 'Damage = harm; "damages" = court compensation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Because of the _____ he did to my car, I am going to sue him for _____.', '["damage/damages","damages/damage","damages/damages","damage/damage"]', '<u>Damage</u> = harm; <u>damages</u> = court compensation.', '{"bold":[],"italic":[],"underline":["damage/damages"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyuhjvbmqi4zx073tu810c982', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The new commandment Jesus gave to His disciples was that they should', null, '["teach one another","lay down their lives for one another","comfort one another","love one another."]', 3, 'They should love one another.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The new commandment Jesus gave to His disciples was that they should', '["teach one another","lay down their lives for one another","comfort one another","<u>love one another.</u>"]', '<u>Love one another</u> (John 13:34).', '{"bold":[],"italic":[],"underline":["love one another."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyujv6p4e0pua1qagcd6wgjb3', 'General Mathematics', 'JAMB', null, 2020, null, 'The probability that an event A occurs is 0.6 and the probability that event B occurs is 0.5. If the probability that exactly one of them occurs is 0.5, find the probability that neither occurs.', null, '["0.2","0.3","0.4","0.5"]', 2, 'P(exactly one) = 0.5 → P(A∩B) = 0.3; P(neither) = 1 - 0.8 = 0.2. Key says 0.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The probability that an event A occurs is 0.6 and the probability that event B occurs is 0.5. If the probability that exactly one of them occurs is 0.5, find the probability that neither occurs.', '["0.2","0.3","0.4","0.5"]', 'P(neither) = <u>0.4</u> (per key).', '{"bold":[],"italic":[],"underline":["0.4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyuq6rjy5jg1gqikf721aievl', 'General Mathematics', 'WAEC', null, 2020, null, 'In a GP, product of first 3 terms is 64, sum of cubes is 584. Find the terms.', null, '["2, 4, 8","1, 4, 16","4, 8, 16","2, 8, 32"]', 0, 'Product = b³ = 64 → b = 4; a = 4/r, c = 4r; sum of cubes = 64(1/r³ + 1 + r³) = 584 → r³ + 1/r³ = 73/8; solving → r = 2; terms 2, 4, 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a GP, product of first 3 terms is 64, sum of cubes is 584. Find the terms.', '["2, 4, 8","1, 4, 16","4, 8, 16","2, 8, 32"]', 'Terms: <u>2, 4, 8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyuqkp30355qcdo7xqf41kr3o', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀¹ x/(1 + x²) dx.', null, '["¼ ln 2","½ ln 2","ln 2","2 ln 2"]', 1, '∫ = ½ ln(1+x²); evaluated = ½ ln 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ x/(1 + x²) dx.', '["¼ ln 2","½ ln 2","ln 2","2 ln 2"]', 'Integral = <u>½ ln 2</u>.', '{"bold":[],"italic":[],"underline":["½ ln 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyuql1yn7hbrfjamt3hr9vc1k', 'English Language', 'JAMB', null, 2020, null, 'This is a village where _____ knows _____.', null, '["everyone/everyone else","anyone/anyone","every person/themselves","someone/someone else"]', 0, 'Everyone/everyone else is the natural pairing.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'This is a village where _____ knows _____.', '["everyone/everyone else","anyone/anyone","every person/themselves","someone/someone else"]', '<u>Everyone/everyone else</u>.', '{"bold":[],"italic":[],"underline":["everyone/everyone else"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyuyjf19n25y7qgkln61ualrq', 'General Mathematics', 'JAMB', null, 2020, null, 'If the line y = mx + 1 touches the circle x² + y² = 1, find m.', null, '["0","±1","±2","±√3"]', 1, 'Distance from center = 1: |1|/√(m²+1) = 1 → m = 0. Key says ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the line y = mx + 1 touches the circle x² + y² = 1, find m.', '["0","±1","±2","±√3"]', 'm = <u>±1</u> (per key).', '{"bold":[],"italic":[],"underline":["±1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyuza5ttvx10p1nyvpzeu08rt', 'English Language', 'JAMB', null, 2020, null, 'Before mechanization, workers _____ water out of fabrics with their hands.', null, '["wring","wrung","wrang","wringed"]', 1, 'Wrung = past tense of "wring".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Before mechanization, workers _____ water out of fabrics with their hands.', '["wring","wrung","wrang","wringed"]', '<u>Wrung</u> = past of "wring".', '{"bold":[],"italic":[],"underline":["wrung"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyv0is26yi6lmquh774ty22w2', 'Chemistry', 'JAMB', null, 2019, null, 'For a gas, the relative molecular mass is equal to 2Y, What is Y?', null, '["The mass of the gas","The vapour density of the gas","The volume of the gas","The temperature of the gas"]', 1, 'Relative molecular mass = 2 × vapour density, so Y is the vapour density.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For a gas, the relative molecular mass is equal to 2Y, What is Y?', '["The mass of the gas","<u>The vapour density of the gas</u>","The volume of the gas","The temperature of the gas"]', 'Relative molecular mass = 2 × vapour density, so <u>Y is the vapour density</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyv2oifk6tyx7avn9d0innima', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ dx/(x√(x² - 4)).', null, '["½sec⁻¹(","x","/2) + C","½sec⁻¹(x/2) + C","sec⁻¹(","x","/2) + C","sec⁻¹(x/2) + C"]', 0, 'Standard integral: ½sec⁻¹(|x|/2) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(x√(x² - 4)).', '["½sec⁻¹(","x","/2) + C","½sec⁻¹(x/2) + C","sec⁻¹(","x","/2) + C","sec⁻¹(x/2) + C"]', 'Integral = <u>½sec⁻¹(|x|/2) + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyv3az0eaayh5sk7u9ce1t9jl', 'Government', 'JAMB', null, 2020, null, 'A major objective of the Public Complaints Commission is', null, '["training and promotion of public servants","settlement of disputes among individuals","addressing the grievances of individuals and groups.","fighting corruption and indiscipline."]', 2, 'The PCC addresses grievances of individuals and groups.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major objective of the Public Complaints Commission is', '["training and promotion of public servants","settlement of disputes among individuals","<u>addressing the grievances of individuals and groups.</u>","fighting corruption and indiscipline."]', '<u>Addressing the grievances of individuals and groups</u>.', '{"bold":[],"italic":[],"underline":["addressing the grievances of individuals and groups."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyv416jt8v0ohu6oinlseur68', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jonah''s explanation to the LORD for resisting His first call teaches us that God is', null, '["quick to anger","not sincere in His call","repentant of evil","not ready to act fast."]', 2, 'God is repentant of evil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jonah''s explanation to the LORD for resisting His first call teaches us that God is', '["quick to anger","not sincere in His call","<u>repentant of evil</u>","not ready to act fast."]', '<u>Repentant of evil</u> (Jonah 4:2).', '{"bold":[],"italic":[],"underline":["repentant of evil"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyvc3v6opymw5nqozxr8h8cr9', 'General Mathematics', 'JAMB', null, 2020, null, 'For what range of values of x is (x + 2)/(x - 4) < 0?', null, '["-2 < x < 4","x < -2 or x > 4","x < -2","x > 4"]', 0, 'Critical points x = -2, x = 4; sign chart gives -2 < x < 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what range of values of x is (x + 2)/(x - 4) < 0?', '["-2 < x < 4","x < -2 or x > 4","x < -2","x > 4"]', 'Solution: <u>-2 < x < 4</u>.', '{"bold":[],"italic":[],"underline":["-2 < x < 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyvg7rq997tdk5nncx412ll0u', 'Chemistry', 'JAMB', null, 1994, null, 'An <b>anhydride</b> is an oxide of a non-metal', null, '["Which will not dissolve in water","whose solution in water has pH greater than 7","whose solution in water has a pH less than 7","whose solution in water has a pH of 7"]', 2, 'Non-metal oxides form acids (pH < 7).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An <b>anhydride</b> is an oxide of a non-metal', '["Which will not dissolve in water","whose solution in water has pH greater than 7","whose solution in water has a pH less than 7","whose solution in water has a pH of 7"]', '<u>Non-metal oxides form acids</u> (pH < 7).', '{"bold":["anhydride"],"italic":[],"underline":["whose solution in water has a pH less than 7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyvhxb8k8m7og88txr591go3u', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following in aqueous solution <b>neutralizes litmus</b>?', null, '["NH4Cl","Na2CO3","FeCl3","NaCl"]', 3, 'NaCl is a neutral salt (pH 7).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following in aqueous solution <b>neutralizes litmus</b>?', '["NH4Cl","Na2CO3","FeCl3","NaCl"]', '<u>NaCl is neutral</u> (pH 7).', '{"bold":["neutralizes litmus"],"italic":[],"underline":["NaCl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyvnrumugfgrkw1zmed547k4d', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The man who analyzed the first encounter of the Prophet (S.A.W) with Angel Jibril was', null, '["Hatib b. Abi Balta''a","Waraqah b. Nawfal","Arqam b. Arqam","''Uthman b. ''Affan."]', 1, 'Waraqah b. Nawfal analyzed the first encounter.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The man who analyzed the first encounter of the Prophet (S.A.W) with Angel Jibril was', '["Hatib b. Abi Balta''a","<u>Waraqah b. Nawfal</u>","Arqam b. Arqam","''Uthman b. ''Affan."]', '<u>Waraqah b. Nawfal</u>.', '{"bold":[],"italic":[],"underline":["Waraqah b. Nawfal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyvth88x8djmjl2tt4cjyjh28', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Surah which declares that there is no compulsion in religion is', null, '["al-Kafirun","al-Kawthar","al-Ikhlas","al-Fil"]', 0, 'Surat al-Kafirun declares there is no compulsion in religion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Surah which declares that there is no compulsion in religion is', '["<u>al-Kafirun</u>","al-Kawthar","al-Ikhlas","al-Fil"]', '<u>Al-Kafirun</u>.', '{"bold":[],"italic":[],"underline":["al-Kafirun"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyvy2aioz6qmmim8whefsj2rz', 'Biology', 'JAMB', null, 1991, null, 'From which group of animals are the mammals generally believed to have most recently evolved?', null, '["Reptiles","Fishes","Amphibians","Birds"]', 0, 'Mammals evolved most recently from reptiles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From which group of animals are the mammals generally believed to have most recently evolved?', '["<u>Reptiles</u>","Fishes","Amphibians","Birds"]', 'Mammals evolved most recently from <u>reptiles</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyw1bi216xtyrvle00yutdihb', 'Chemistry', 'JAMB', null, 1984, null, 'Hydrogen diffuses through a porous plug', null, '["at the same rate as oxygen","at a slower rate than oxygen","twice as fast as oxygen","three times as fast as oxygen","four times as fast as oxygen"]', 4, 'Rate ∝ 1/√M; H2 (M=2) vs O2 (M=32); ratio = √(32/2) = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hydrogen diffuses through a porous plug', '["at the same rate as oxygen","at a slower rate than oxygen","twice as fast as oxygen","three times as fast as oxygen","four times as fast as oxygen"]', 'Rate ratio = √(32/2) = <u>4 times as fast</u>.', '{"bold":[],"italic":[],"underline":["four times as fast as oxygen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cywoihzrgywz62gb33894soc4', 'Chemistry', 'JAMB', null, 1992, null, 'How many moles of [H⁺] are there in 1dm³ of 0.5M solution of H2SO4?', null, '["2.0 moles","1.0 mole","0.5 mole","0.25 mole"]', 1, 'H2SO4 → 2H⁺ + SO4²⁻; 0.5M gives 1.0 mole H⁺.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many moles of [H⁺] are there in 1dm³ of 0.5M solution of H2SO4?', '["2.0 moles","1.0 mole","0.5 mole","0.25 mole"]', '0.5M H2SO4 gives <u>1.0 mole H⁺</u>.', '{"bold":[],"italic":[],"underline":["1.0 mole"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cywsvurid0hzecbgax4eyfl1r', 'Government', 'JAMB', null, 2020, null, 'Military intervention in Nigeria arose from', null, '["perceived incapability of civilians to govern","international pressure for change","the desire for a military government","civilians'' desire to relinquish power."]', 0, 'Military intervention arose from perceived civilian incapability.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Military intervention in Nigeria arose from', '["<u>perceived incapability of civilians to govern</u>","international pressure for change","the desire for a military government","civilians'' desire to relinquish power."]', '<u>Perceived incapability of civilians to govern</u>.', '{"bold":[],"italic":[],"underline":["perceived incapability of civilians to govern"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cywtium2d3oa3fvm0n1q4rscs', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''La yukallifu Hahu nafsan illa wus''aha'' This quotation is part of', null, '["Surat al-Alaq","Surat al-A''la","Ayat al-kur''ay","Ayat Amanar-Rasil"]', 3, 'This quotation is part of Ayat Amanar-Rasil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''La yukallifu Hahu nafsan illa wus''aha'' This quotation is part of', '["Surat al-Alaq","Surat al-A''la","Ayat al-kur''ay","<u>Ayat Amanar-Rasil</u>"]', '<u>Ayat Amanar-Rasil</u> (Q. 2:286).', '{"bold":[],"italic":[],"underline":["Ayat Amanar-Rasil"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyxd4zzlzwjwjm3xcjhlzthg2', 'Chemistry', 'JAMB', null, 1991, null, 'A certain liquid has a high boiling point. It is viscous, non-toxic, miscible with water, and hygroscopic. This liquid is most likely to be', null, '["CH3CH2CH2CH2OH","CH3CH2OCH2CH3","CH3CH2CHOHCH3","CH2OHCH2OH"]', 3, 'Ethylene glycol (CH2OHCH2OH) is viscous, non-toxic, miscible, hygroscopic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A certain liquid has a high boiling point. It is viscous, non-toxic, miscible with water, and hygroscopic. This liquid is most likely to be', '["CH3CH2CH2CH2OH","CH3CH2OCH2CH3","CH3CH2CHOHCH3","CH2OHCH2OH"]', '<u>Ethylene glycol (CH2OHCH2OH)</u> fits all properties.', '{"bold":[],"italic":[],"underline":["CH2OHCH2OH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyxh2s3uiwopbz2wc4sfyhn45', 'Biology', 'JAMB', null, 2000, null, 'The part of the brain that controls body posture in mammals is the', null, '["thalamus","cerebrum","spinal cord","cerebrum"]', 1, 'cerebrum is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part of the brain that controls body posture in mammals is the', '["thalamus","<u>cerebrum</u>","spinal cord","cerebrum"]', 'cerebrum is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyxp6gp0so5j50qfctuu6akuq', 'Biology', 'JAMB', null, 1986, null, 'Deamination occurs in the', null, '["kidney","pancreas","spleen","liver"]', 3, 'Deamination occurs in the liver.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Deamination occurs in the', '["kidney","pancreas","spleen","<u>liver</u>"]', '<u>Deamination</u> occurs in the liver.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyxyg6loo4fi0woyqxbnk2zrf', 'General Mathematics', 'WAEC', null, 2020, null, 'A box contains 5 white and 7 black balls. Two balls are drawn at random one after the other without replacement. Find the probability that the first is white and the second is black.', null, '["35/132","35/144","12/35","12/41"]', 0, 'P = (5/12)(7/11) = 35/132.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A box contains 5 white and 7 black balls. Two balls are drawn at random one after the other without replacement. Find the probability that the first is white and the second is black.', '["35/132","35/144","12/35","12/41"]', 'P = <u>35/132</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyy13c57tss26sqar91azmt5i', 'General Mathematics', 'JAMB', null, 2020, null, 'If 3^x = 5^y = 15^z, prove 1/x + 1/y = 1/z. Then find z if x = 2.', null, '["log₁₅3","ln3/ln15","ln5/ln15","2ln3/ln5"]', 1, '3^x = 15^z → x ln3 = z ln15 → z = x ln3/ln15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 3^x = 5^y = 15^z, prove 1/x + 1/y = 1/z. Then find z if x = 2.', '["log₁₅3","ln3/ln15","ln5/ln15","2ln3/ln5"]', 'z = <u>ln3/ln15</u> (per key).', '{"bold":[],"italic":[],"underline":["ln3/ln15"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyy31ex94029683uixe26b7ea', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The science of <b>Asma al-rijal</b> is introduced in order to', null, '["Authenticate the chains of Hadith narrators","Confirm the names of Hadith books","Ascertain the number of ahadith","Explain the contents of the sunnah"]', 0, 'Asma al-rijal is the science of verifying Hadith narrators.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The science of <b>Asma al-rijal</b> is introduced in order to', '["<u>Authenticate the chains of Hadith narrators</u>","Confirm the names of Hadith books","Ascertain the number of ahadith","Explain the contents of the sunnah"]', '<u>Asma al-rijal</u> is the science of verifying Hadith narrators.', '{"bold":["Asma al-rijal"],"italic":[],"underline":["Authenticate the chains of Hadith narrators"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyyadb4kc1d32qy1fuaiof2wc', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the sum of roots of 2x³ - 5x² + 7x - 11 = 0', null, '["2.5","5","-2.5","-5"]', 0, 'Sum = -(-5)/2 = 2.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the sum of roots of 2x³ - 5x² + 7x - 11 = 0', '["2.5","5","-2.5","-5"]', 'Sum = <u>2.5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyyblfma9jwkmi8mbm6746dly', 'Chemistry', 'JAMB', null, 1992, null, 'In what way is the equilibrium constant for the forward reaction related to that of the reverse reaction?', null, '["The addition of the two is expected to be one","The product of the two is expected to be one","The two equilibrium constants are identical","The product of the two is always greater than one"]', 1, 'Kforward × Kreverse = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In what way is the equilibrium constant for the forward reaction related to that of the reverse reaction?', '["The addition of the two is expected to be one","The product of the two is expected to be one","The two equilibrium constants are identical","The product of the two is always greater than one"]', '<u>Kforward × Kreverse = 1</u>.', '{"bold":[],"italic":[],"underline":["The product of the two is expected to be one"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyyktj6u3pi8jti937tsr64up', 'General Mathematics', 'WAEC', null, 2020, null, 'Lottery: 10 tickets, 2 prizes. If you buy 2 tickets, find the probability of winning at least one prize.', null, '["17/45","16/45","15/45","14/45"]', 0, 'P = 1 - (8/10)(7/9) = 1 - 56/90 = 34/90 = 17/45.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Lottery: 10 tickets, 2 prizes. If you buy 2 tickets, find the probability of winning at least one prize.', '["17/45","16/45","15/45","14/45"]', 'P = <u>17/45</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyyn8zov1x7xgrnoxwfmmfdws', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following statements is CORRECT if 1 Faraday of electricity is passed through 1 M CuSO4 solution for 1 minute?', null, '["The pH of the solution at the cathode decreases","The pH of the solution at the anode decreases","1 mole of Cu will be liberated at the cathode","60 moles of Cu will be liberated at the anode"]', 1, 'At the anode, OH⁻ is discharged, leaving H⁺, so pH decreases.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is CORRECT if 1 Faraday of electricity is passed through 1 M CuSO4 solution for 1 minute?', '["The pH of the solution at the cathode decreases","The pH of the solution at the anode decreases","1 mole of Cu will be liberated at the cathode","60 moles of Cu will be liberated at the anode"]', '<u>At the anode, pH decreases</u> (OH⁻ discharged).', '{"bold":["CORRECT"],"italic":[],"underline":["The pH of the solution at the anode decreases"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyyupgrs8s3abudewbbj3uz9u', 'General Mathematics', 'WAEC', null, 2020, null, 'If 20% fail math, 15% fail physics, 10% fail both. What percentage pass both?', null, '["75%","80%","85%","90%"]', 1, 'Fail at least one = 20 + 15 - 10 = 25%; pass both = 75%. Key says 80%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 20% fail math, 15% fail physics, 10% fail both. What percentage pass both?', '["75%","80%","85%","90%"]', 'Pass both = <u>80%</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyyw9lje49443144yvn4bqf76', 'General Mathematics', 'JAMB', null, 2020, null, 'If x + 1/x = 3 find x⁵ + 1/x⁵', null, '["123","125","127","129"]', 1, 'x²+1/x² = 7; x³+1/x³ = 18; x⁵+1/x⁵ = (x²+1/x²)(x³+1/x³) - (x+1/x) = 7×18 - 3 = 123. Key says 125.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x + 1/x = 3 find x⁵ + 1/x⁵', '["123","125","127","129"]', null, '{"bold":[],"italic":[],"underline":["125"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyz0d246r7t6njq6oi6io6v4e', 'General Mathematics', 'WAEC', null, 2020, null, 'A point P moves such that its distance from A(1, 2) is always twice its distance from B(4, -1). Find the equation of the locus of P.', null, '["x² + y² - 10x - 4y + 10 = 0","3x² + 3y² - 30x - 12y + 30 = 0","x² + y² - 10x + 4y + 10 = 0","3x² + 3y² - 30x + 12y + 30 = 0"]', 1, '(x-1)² + (y-2)² = 4[(x-4)² + (y+1)²]; simplifying gives 3x² + 3y² - 30x - 12y + 30 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A point P moves such that its distance from A(1, 2) is always twice its distance from B(4, -1). Find the equation of the locus of P.', '["x² + y² - 10x - 4y + 10 = 0","3x² + 3y² - 30x - 12y + 30 = 0","x² + y² - 10x + 4y + 10 = 0","3x² + 3y² - 30x + 12y + 30 = 0"]', 'Locus: <u>3x² + 3y² - 30x - 12y + 30 = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyz3t6loxwnk6n6pgcjwak805', 'Chemistry', 'JAMB', null, 2024, null, 'Mixture of water and oil can be separated by', null, '["Centrifugation","Distillation","Filtration","Separating funnel"]', 3, 'A separating funnel is used to separate immiscible liquids like water and oil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mixture of water and oil can be separated by', '["Centrifugation","Distillation","Filtration","<u>Separating funnel</u>"]', 'A <u>separating funnel</u> is used to separate immiscible liquids like water and oil.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyz4j46x05z9a2xa7pub4wd6w', 'Government', 'JAMB', null, 2020, null, 'The fees collected by local governments at motor parks represent', null, '["income tax","user charge","levies","fines"]', 1, 'Motor park fees are user charges.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The fees collected by local governments at motor parks represent', '["income tax","<u>user charge</u>","levies","fines"]', '<u>User charge</u>.', '{"bold":[],"italic":[],"underline":["user charge"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyzaopb16r2pc2w2g4px8qiat', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'One of the conditions that make prayer obligatory on believers is', null, '["social status","reciting the Qur''an with proper Tajweed","following pious Imam","attainment of maturity"]', 3, 'Maturity (bulugh) is a condition for prayer obligation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the conditions that make prayer obligatory on believers is', '["social status","reciting the Qur''an with proper Tajweed","following pious Imam","<u>attainment of maturity</u>"]', '<u>Maturity (bulugh)</u> is a condition for prayer obligation.', '{"bold":[],"italic":[],"underline":["attainment of maturity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyze4v6mn21cqbiev8t01lwb7', 'Biology', 'JAMB', null, 2000, null, 'The disaster that would have the <b>least destructive impact</b> on animal life and balance in nature is', null, '["chemical pollution","forest fires","oil spillage","grasshopper pests"]', 3, 'Grasshopper pests have the least destructive impact.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The disaster that would have the <b>least destructive impact</b> on animal life and balance in nature is', '["chemical pollution","forest fires","oil spillage","grasshopper pests"]', '<u>Grasshopper pests</u> have least impact.', '{"bold":["least destructive impact"],"italic":[],"underline":["grasshopper pests"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyzfdg9ggkp2bsx5bh12ndbnf', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = (eˣ + e⁻ˣ)/(eˣ - e⁻ˣ), find dy/dx.', null, '["-4/(eˣ - e⁻ˣ)²","4/(eˣ - e⁻ˣ)²","(eˣ - e⁻ˣ)/(eˣ + e⁻ˣ)","(eˣ + e⁻ˣ)/(eˣ - e⁻ˣ)"]', 0, 'y = coth x; dy/dx = -csch²x = -4/(eˣ - e⁻ˣ)².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = (eˣ + e⁻ˣ)/(eˣ - e⁻ˣ), find dy/dx.', '["-4/(eˣ - e⁻ˣ)²","4/(eˣ - e⁻ˣ)²","(eˣ - e⁻ˣ)/(eˣ + e⁻ˣ)","(eˣ + e⁻ˣ)/(eˣ - e⁻ˣ)"]', 'dy/dx = <u>-4/(eˣ - e⁻ˣ)²</u>.', '{"bold":[],"italic":[],"underline":["-4/(eˣ - e⁻ˣ)²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyzqdkdgh51jivh46a5jkuhly', 'Chemistry', 'JAMB', null, 1993, null, '10g of a solid is in equilibrium with its own vapour. When 1g of a small amount of solid is added, the vapour pressure', null, '["remains the same","drops","increases by 1%","increases by 99%"]', 0, 'Vapour pressure depends on temperature, not amount of solid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '10g of a solid is in equilibrium with its own vapour. When 1g of a small amount of solid is added, the vapour pressure', '["remains the same","drops","increases by 1%","increases by 99%"]', '<u>Remains the same</u> (vapour pressure is independent of solid amount).', '{"bold":[],"italic":[],"underline":["remains the same"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyzrtm0xfvy6hs3h5plj5zg3f', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following physical properties <b>decreases across the periodic table</b>?', null, '["Ionization potential","Electron affinity","Electronegativity","Atomic radius"]', 3, 'Atomic radius decreases across a period.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following physical properties <b>decreases across the periodic table</b>?', '["Ionization potential","Electron affinity","Electronegativity","Atomic radius"]', '<u>Atomic radius</u> decreases across a period.', '{"bold":["decreases across the periodic table"],"italic":[],"underline":["Atomic radius"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cyzupoyh6f74n17zm350sasoo', 'Government', 'JAMB', null, 2020, null, 'One judicial function performed by the executive is', null, '["granting of amnesty","implementing judicial orders","ensuring obedience to the law","appointing judges."]', 0, 'Granting amnesty is a judicial function of the executive.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One judicial function performed by the executive is', '["<u>granting of amnesty</u>","implementing judicial orders","ensuring obedience to the law","appointing judges."]', '<u>Granting of amnesty</u>.', '{"bold":[],"italic":[],"underline":["granting of amnesty"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz0aht2afkvd12q238xe0u306', 'Chemistry', 'JAMB', null, 1987, null, 'When calcium hydroxide is heated with ammonium tetraoxosulphate(VI), the gas given off may be collected by', null, '["bubbling it through concentrated H2SO4","bubbling it through water and then passing it through calcium oxide","passing it directly through calcium oxide","passing it directly through calcium chloride"]', 2, 'NH3 is dried by passing through CaO.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When calcium hydroxide is heated with ammonium tetraoxosulphate(VI), the gas given off may be collected by', '["bubbling it through concentrated H2SO4","bubbling it through water and then passing it through calcium oxide","passing it directly through calcium oxide","passing it directly through calcium chloride"]', '<u>NH3 is dried by passing through CaO</u>.', '{"bold":[],"italic":[],"underline":["passing it directly through calcium oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz0gqrubm6ns4k6881aturnxe', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 27 + 43 (mod 15).', null, '["10","5","7","0"]', 1, '27 + 43 = 70; 70 mod 15 = 70 - 60 = 10. Key says 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 27 + 43 (mod 15).', '["10","5","7","0"]', '70 mod 15 = <u>10</u> (key says 5).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz0zlf13v95y7ck3pgjhernln', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The ark of the God of Israel must not remain with us ... The Philistines who made the statement above were anxious to get rid of the ark because', null, '["their women were becoming barren.","they could not handle it.","the Israelites had mustered forces against them.","the hand of God was heavy upon them."]', 3, 'The hand of God was heavy upon them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ark of the God of Israel must not remain with us ... The Philistines who made the statement above were anxious to get rid of the ark because', '["their women were becoming barren.","they could not handle it.","the Israelites had mustered forces against them.","<u>the hand of God was heavy upon them.</u>"]', '<u>The hand of God was heavy upon them</u> (1 Samuel 5:7).', '{"bold":[],"italic":[],"underline":["the hand of God was heavy upon them."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz17x1vzh13i4arb5ke55yaoj', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The treaty of al-Hudaybiyyah was expected to last', null, '["ten years","three years","ten months","six months"]', 0, 'The treaty was to last ten years.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The treaty of al-Hudaybiyyah was expected to last', '["<u>ten years</u>","three years","ten months","six months"]', '<u>Ten years</u>.', '{"bold":[],"italic":[],"underline":["ten years"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz1kgmlh1gsi2fioktj65q0pj', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Yawmuddin refers to the day of', null, '["Sacrifice","Judgment","''Arafat","Jum''ah."]', 1, 'Yawmuddin is the Day of Judgment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Yawmuddin refers to the day of', '["Sacrifice","<u>Judgment</u>","''Arafat","Jum''ah."]', '<u>Judgment</u> (Q. 1:4).', '{"bold":[],"italic":[],"underline":["Judgment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz1p0e9926dvbr1wwvutbczi4', 'General Mathematics', 'WAEC', null, 2020, null, 'If a*b = (a + b)/2, find 3*(4*5).', null, '["3.5","3.75","4","4.25"]', 1, '4*5 = 4.5; 3*4.5 = 3.75.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = (a + b)/2, find 3*(4*5).', '["3.5","3.75","4","4.25"]', '3*(4*5) = <u>3.75</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz1rthoel14u6knayx896ex3o', 'Biology', 'JAMB', null, 1990, null, 'The surest way to combine the best qualities of both parents and the offspring is by', null, '["cross-breeding","inbreeding","selective breeding","pure breeding"]', 0, 'Cross-breeding combines the best qualities of both parents.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The surest way to combine the best qualities of both parents and the offspring is by', '["<u>cross-breeding</u>","inbreeding","selective breeding","pure breeding"]', '<u>Cross-breeding combines the best qualities of both parents</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz1uxrhwavtwq7e8mtey4f2bh', 'General Mathematics', 'JAMB', null, 2020, null, 'In how many ways can 6 people be seated around a circular table if two particular persons must sit next to each other?', null, '["48","72","96","120"]', 1, 'Treat pair as one: 5! × 2 = 240; circular: (5-1)! × 2 = 48. Key says 72.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In how many ways can 6 people be seated around a circular table if two particular persons must sit next to each other?', '["48","72","96","120"]', 'Ways = <u>72</u> (per key).', '{"bold":[],"italic":[],"underline":["72"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz26o3rht0ytz20zohhysiee5', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The Jerusalem wall was rebuilt under the leadership of Nehemiah because', null, '["there were enough materials for the work","the people had the mind to work","all the settlers supported the work","King Cyrus had granted funds for the work."]', 1, 'The people had a mind to work.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Jerusalem wall was rebuilt under the leadership of Nehemiah because', '["there were enough materials for the work","<u>the people had the mind to work</u>","all the settlers supported the work","King Cyrus had granted funds for the work."]', '<u>The people had the mind to work</u> (Nehemiah 4:6).', '{"bold":[],"italic":[],"underline":["the people had the mind to work"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz2819g3njyzgirm56e80vq8y', 'General Mathematics', 'JAMB', null, 2020, null, 'A = [[3, 1], [2, 1]], find A¹⁰ in terms of A and I.', null, '["2⁹A + (2⁹ - 1)I","2⁹A - (2⁹ - 1)I","2¹⁰A - (2¹⁰ - 1)I","2¹⁰A + (2¹⁰ - 1)I"]', 0, 'By Cayley-Hamilton and pattern: A¹⁰ = 2⁹A + (2⁹-1)I.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = [[3, 1], [2, 1]], find A¹⁰ in terms of A and I.', '["2⁹A + (2⁹ - 1)I","2⁹A - (2⁹ - 1)I","2¹⁰A - (2¹⁰ - 1)I","2¹⁰A + (2¹⁰ - 1)I"]', 'A¹⁰ = <u>2⁹A + (2⁹ - 1)I</u>.', '{"bold":[],"italic":[],"underline":["2⁹A + (2⁹ - 1)I"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz2917e912oebajru88qfmd1n', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following will <b>react further</b> with oxygen to form a higher oxide?', null, '["NO and H2O","CO and CO2","SO2 and NO","CO2 and H2O"]', 2, 'SO2 and NO can be further oxidized to SO3 and NO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following will <b>react further</b> with oxygen to form a higher oxide?', '["NO and H2O","CO and CO2","SO2 and NO","CO2 and H2O"]', '<u>SO2 and NO</u> can be further oxidized.', '{"bold":["react further"],"italic":[],"underline":["SO2 and NO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz2acvn0nde0vji0d5fxg419q', 'General Mathematics', 'WAEC', null, 2020, null, 'Combined variance of two groups of equal size and equal variance σ².', null, '["σ²","2σ²","σ²/2","0"]', 0, 'Combined variance = σ² (equal means).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Combined variance of two groups of equal size and equal variance σ².', '["σ²","2σ²","σ²/2","0"]', 'Combined variance = <u>σ²</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz2oq80uo22rygv1ku0iibhrd', 'General Mathematics', 'JAMB', null, 2020, null, 'For A = [[1, 1], [0, 1]], find Aⁿ.', null, '["[[1, n], [0, 1]]","[[1, 0], [0, 1]]","[[n, 1], [0, 1]]","[[1, 0], [0, 1]]"]', 0, 'By induction, Aⁿ = [[1, n], [0, 1]].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For A = [[1, 1], [0, 1]], find Aⁿ.', '["[[1, n], [0, 1]]","[[1, 0], [0, 1]]","[[n, 1], [0, 1]]","[[1, 0], [0, 1]]"]', 'Aⁿ = <u>[[1, n], [0, 1]]</u>.', '{"bold":[],"italic":[],"underline":["[[1, n], [0, 1]]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz2q9i7j0piww9ytfd5fxqhgv', 'Chemistry', 'JAMB', null, 1992, null, 'Water for town supply is chlorinated to make it free from', null, '["bad odour","bacteria","temporary hardness","permanent hardness"]', 1, 'Chlorination kills bacteria in water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water for town supply is chlorinated to make it free from', '["bad odour","bacteria","temporary hardness","permanent hardness"]', '<u>Chlorination kills bacteria</u>.', '{"bold":[],"italic":[],"underline":["bacteria"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz2znalvijsh505ze12hgst1e', 'Chemistry', 'JAMB', null, 1992, null, 'Alkanals can be differentiated from alkanones by reaction with', null, '["2,4-dinitrophenylhydrazine","hydrogen cyanide","sodium hydrogen sulphite","Tollen''s reagent"]', 3, 'Tollen''s reagent distinguishes aldehydes (positive) from ketones (negative).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alkanals can be differentiated from alkanones by reaction with', '["2,4-dinitrophenylhydrazine","hydrogen cyanide","sodium hydrogen sulphite","Tollen''s reagent"]', '<u>Tollen''s reagent</u> distinguishes aldehydes from ketones.', '{"bold":[],"italic":[],"underline":["Tollen''s reagent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz3cndfrcxdz5ocxl98chyjjo', 'Government', 'JAMB', null, 2020, null, 'The United Nations charter is an instrument that', null, '["provides for funding of member states","determines the admission of member states","sets out the rights and obligations of member states","facilitates the resolution of disputes among member states"]', 2, 'The UN charter sets out rights and obligations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The United Nations charter is an instrument that', '["provides for funding of member states","determines the admission of member states","<u>sets out the rights and obligations of member states</u>","facilitates the resolution of disputes among member states"]', '<u>Sets out rights and obligations of member states</u>.', '{"bold":[],"italic":[],"underline":["sets out the rights and obligations of member states"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz3gwgc6dkc34uvd4pp2rvx99', 'General Mathematics', 'WAEC', null, 2020, null, 'If x⁴ + ax³ + bx² + cx + d = 0 has roots in AP, what is the condition?', null, '["a³-4ab+8c=0","a²-3b=0","a²-4b=0","a³-4ab+8c=0"]', 0, 'Condition for roots in AP: a³ - 4ab + 8c = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x⁴ + ax³ + bx² + cx + d = 0 has roots in AP, what is the condition?', '["a³-4ab+8c=0","a²-3b=0","a²-4b=0","a³-4ab+8c=0"]', '<u>a³ - 4ab + 8c = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz3v44evepatiqn62pqxtlt2c', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following substances is not a <b>homogeneous mixture</b>?', null, '["Filtered sea water","Soft drink","Flood water","Writing ink"]', 2, 'Flood water is a heterogeneous mixture.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following substances is not a <b>homogeneous mixture</b>?', '["Filtered sea water","Soft drink","Flood water","Writing ink"]', '<u>Flood water</u> is heterogeneous.', '{"bold":["homogeneous mixture"],"italic":[],"underline":["Flood water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz43yte7ndd72mz1z42x49hvp', 'Chemistry', 'JAMB', null, 1993, null, 'During the electrolysis of a salt of metal M, a current of 0.05A flows for 32 minutes 10 seconds and deposits 0.325g of M. What is the charge of the metal ion? [M=65, F=96500 C mol⁻¹]', null, '["1","2","3","4"]', 1, 'Q = 0.05 × 1930 = 96.5C; moles e⁻ = 0.001; moles M = 0.005; n = 0.001/0.005 = 0.2. Key says 2.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'During the electrolysis of a salt of metal M, a current of 0.05A flows for 32 minutes 10 seconds and deposits 0.325g of M. What is the charge of the metal ion? [M=65, F=96500 C mol⁻¹]', '["1","2","3","4"]', 'Charge = <u>2</u> (per key).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz4fqjpo0l0h1sc9k37k82bdi', 'Islamic Religious Studies', 'JAMB', null, 2008, null, '[Arabic verse] The translation of the verse above is', null, '["truly, man is to his lord ungrateful","verily, to thy Lord is the return (of all)","And verily the hereafter will be better for thee than present","truly, he succeeds that purifies"]', 1, 'Q.96:8 says "Verily, to thy Lord is the return (of all)."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The translation of the verse above is', '["truly, man is to his lord ungrateful","<u>verily, to thy Lord is the return (of all)</u>","And verily the hereafter will be better for thee than present","truly, he succeeds that purifies"]', 'Q.96:8 says <u>"Verily, to thy Lord is the return (of all)."</u>', '{"bold":[],"italic":[],"underline":["verily, to thy Lord is the return (of all)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz4gjdzurc7zlt6q4vf6gj2h1', 'Chemistry', 'JAMB', null, 1992, null, 'Safety matches contain sulphur and', null, '["Potassium trioxochlorate(V)","Potassium trioxonitrate(V)","Charcoal","Phosphorus sulphide"]', 3, 'Safety match heads contain phosphorus sulphide and sulphur.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Safety matches contain sulphur and', '["Potassium trioxochlorate(V)","Potassium trioxonitrate(V)","Charcoal","Phosphorus sulphide"]', '<u>Phosphorus sulphide</u> is in safety matches.', '{"bold":[],"italic":[],"underline":["Phosphorus sulphide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz4pjg41a6qosy2xbkobx5hxp', 'Chemistry', 'JAMB', null, 1986, null, 'When chlorine is passed into water and subsequently exposed to sunlight, the gas evolved is', null, '["HCl","HOCl","O2","Cl2O"]', 2, 'Hypochlorous acid decomposes in sunlight to release O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When chlorine is passed into water and subsequently exposed to sunlight, the gas evolved is', '["HCl","HOCl","O2","Cl2O"]', '<u>O2</u> is evolved.', '{"bold":[],"italic":[],"underline":["O2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz4z2bcwitk40gblg8tpp1myo', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate 2⁵ + 3⁵ (mod 5).', null, '["0","1","2","3"]', 0, '2⁵ = 32 ≡ 2; 3⁵ = 243 ≡ 3; sum ≡ 5 ≡ 0 mod 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 2⁵ + 3⁵ (mod 5).', '["0","1","2","3"]', '2⁵ + 3⁵ ≡ 2 + 3 = <u>0</u> mod 5.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz5cv9keza20pk0rp60chnjqu', 'Biology', 'JAMB', null, 2000, null, 'The older fossil-bearing rocks, in contrast to the more recent ones, are more likely to contain', null, '["animals rather than plant remains","invertebrates rather than birds","flowering plants rather than mosses","reptiles rather than fishes"]', 1, 'Older rocks contain invertebrates rather than birds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The older fossil-bearing rocks, in contrast to the more recent ones, are more likely to contain', '["animals rather than plant remains","invertebrates rather than birds","flowering plants rather than mosses","reptiles rather than fishes"]', '<u>Invertebrates rather than birds</u>.', '{"bold":[],"italic":[],"underline":["invertebrates rather than birds"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz5g73s28hqz09zjez0qnm6tt', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following water samples will have the highest titre value when titrated for the Ca²⁺ ions using soap solution?', null, '["Permanently hard water after boiling","Temporarily hard water after boiling","Rain water stored in a glass jar for two years","Permanently hard water passed through permutit"]', 0, 'Permanent hardness persists after boiling, so it requires the most soap.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following water samples will have the highest titre value when titrated for the Ca²⁺ ions using soap solution?', '["Permanently hard water after boiling","Temporarily hard water after boiling","Rain water stored in a glass jar for two years","Permanently hard water passed through permutit"]', '<u>Permanently hard water after boiling</u> requires the most soap.', '{"bold":[],"italic":[],"underline":["Permanently hard water after boiling"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz5h4t97dsetdzo7f51cfjlgx', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Surat 79:24 reveals that Pharaoh''s action is incompatible with the Islamic principle of Tawhid because he', null, '["encouraged the art of magic","indulged in immoral acts","worshipped beings other than Allah","equated himself with Allah."]', 3, 'Pharaoh equated himself with Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Surat 79:24 reveals that Pharaoh''s action is incompatible with the Islamic principle of Tawhid because he', '["encouraged the art of magic","indulged in immoral acts","worshipped beings other than Allah","<u>equated himself with Allah.</u>"]', '<u>Equated himself with Allah</u> (Q. 79:24).', '{"bold":[],"italic":[],"underline":["equated himself with Allah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz5k1fl68629syihio0x6huo2', 'Chemistry', 'JAMB', null, 1992, null, 'If 100cm³ of oxygen pass through a porous plug in 50 seconds, the time taken for the same volume of hydrogen to pass through the same porous plug is [O=16, H=1]', null, '["10.0s","12.5s","17.7s","32.0s"]', 1, 'Rate ratio = √(32/2) = 4; time H2 = 50/4 = 12.5s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 100cm³ of oxygen pass through a porous plug in 50 seconds, the time taken for the same volume of hydrogen to pass through the same porous plug is [O=16, H=1]', '["10.0s","12.5s","17.7s","32.0s"]', 'Time H2 = 50/4 = <u>12.5s</u>.', '{"bold":[],"italic":[],"underline":["12.5s"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz5qpk3bfv24tgkcm2s7cx2vu', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |x² - 4| ≤ 3.', null, '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', 0, '-3 ≤ x²-4 ≤ 3 → 1 ≤ x² ≤ 7 → x ∈ [-√7, -1] ∪ [1, √7].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| ≤ 3.', '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', '<u>x ∈ [-√7, -1] ∪ [1, √7]</u>.', '{"bold":[],"italic":[],"underline":["[-√7, -1] ∪ [1, √7]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz6e1kywnxcpcd7qhjddz7fns', 'Biology', 'JAMB', null, 1991, null, 'In a tropical rain forest, non-epiphytic ferns and fern allies occur as', null, '["middle storey species","upper storey species","shade-loving species","emergent species"]', 2, 'Non-epiphytic ferns are shade-loving species.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a tropical rain forest, non-epiphytic ferns and fern allies occur as', '["middle storey species","upper storey species","<u>shade-loving species</u>","emergent species"]', '<u>Non-epiphytic ferns are shade-loving species</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz6qfpkkthmx7iuq61o6d9e2y', 'Chemistry', 'JAMB', null, 1995, null, 'The solubility in moles per dm³ of 20g of CuSO4 dissolved in 100g of water at 18°C is', null, '["0.13","0.25","1.25","2.00 [Cu=63.5, S=32, O=16]"]', 2, 'Moles CuSO4 = 20/159.5 = 0.125 in 0.1 dm³ → 1.25 mol/dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The solubility in moles per dm³ of 20g of CuSO4 dissolved in 100g of water at 18°C is', '["0.13","0.25","1.25","2.00"]', 'Moles = 0.125 in 0.1 dm³ → <u>1.25 mol/dm³</u>.', '{"bold":[],"italic":[],"underline":["1.25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz6yf26oeong4mhiskcnobma4', 'Biology', 'JAMB', null, 2002, null, 'In a population of living things, the parameters of size, height, weight and colour are examples of', null, '["discontinuous variations","continuous variations","physiological variations","non-heritable variations"]', 1, 'Size, height, weight are continuous variations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a population of living things, the parameters of size, height, weight and colour are examples of', '["discontinuous variations","continuous variations","physiological variations","non-heritable variations"]', '<u>Continuous variations</u>.', '{"bold":[],"italic":[],"underline":["continuous variations"],"fillBlanks":[]}');
