insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz752nglezzv85efe8d3gc7ls', 'General Mathematics', 'JAMB', null, 2020, null, 'Find det [[1, 1, 1], [a, b, c], [a², b², c²]].', null, '["(a-b)(b-c)(c-a)","(a+b)(b+c)(c+a)","abc(a-b)(b-c)","(a-b)(b-c)"]', 0, 'Vandermonde determinant = (a-b)(b-c)(c-a).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find det [[1, 1, 1], [a, b, c], [a², b², c²]].', '["(a-b)(b-c)(c-a)","(a+b)(b+c)(c+a)","abc(a-b)(b-c)","(a-b)(b-c)"]', 'det = <u>(a-b)(b-c)(c-a)</u>.', '{"bold":[],"italic":[],"underline":["(a-b)(b-c)(c-a)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz75a1jei5hju7gecd7zvd1zf', 'Biology', 'JAMB', null, 2000, null, 'The <b>mutation theory</b> of organic evolution was propounded by', null, '["Gregor Mendel","Hugo Vries","Jean Lamarck","Charles Darwin"]', 1, 'Hugo de Vries propounded the mutation theory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>mutation theory</b> of organic evolution was propounded by', '["Gregor Mendel","Hugo Vries","Jean Lamarck","Charles Darwin"]', '<u>Hugo de Vries</u> propounded the mutation theory.', '{"bold":["mutation theory"],"italic":[],"underline":["Hugo Vries"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz79xaalc92rincqktobqux7e', 'Biology', 'JAMB', null, 2001, null, 'The enzyme invertase will hydrolyze sucrose to give', null, '["maltose and glucose","glycerol and fatty acid","glucose and fructose","mannose and galactose"]', 2, 'Invertase hydrolyzes sucrose to glucose + fructose.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The enzyme invertase will hydrolyze sucrose to give', '["maltose and glucose","glycerol and fatty acid","glucose and fructose","mannose and galactose"]', '<u>Glucose and fructose</u>.', '{"bold":[],"italic":[],"underline":["glucose and fructose"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz7bcle8wsc6wl4n7f6qv1vn5', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The best <b>Ibadah</b> according to the Prophet (SAW) after the major pillars is to', null, '["pray nawafils","marry a pious woman","make a fellow Muslim happy","devote one''s time on dhikr"]', 2, 'Making a fellow Muslim happy is a great act of worship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The best <b>Ibadah</b> according to the Prophet (SAW) after the major pillars is to', '["pray nawafils","marry a pious woman","<u>make a fellow Muslim happy</u>","devote one''s time on dhikr"]', '<u>Making a fellow Muslim happy</u> is a great act of worship.', '{"bold":["Ibadah"],"italic":[],"underline":["make a fellow Muslim happy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz7iwfqrsawkilec16akq8lvh', 'General Mathematics', 'WAEC', null, 2020, null, 'In a class, 15 pass math, 12 pass physics, 8 pass both, 5 fail both. What is the total?', null, '["24","25","26","27"]', 1, 'At least one = 15+12-8 = 19; total = 19+5 = 24. Key says 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class, 15 pass math, 12 pass physics, 8 pass both, 5 fail both. What is the total?', '["24","25","26","27"]', 'Total = <u>25</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz7px225nxn51mfodad9ph97v', 'English Language', 'JAMB', null, 2020, null, 'I know you now, I _____ that you could be trusted.', null, '["am thinking","think","had thought","have been thinking"]', 1, 'Think = present opinion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I know you now, I _____ that you could be trusted.', '["am thinking","think","had thought","have been thinking"]', '<u>Think</u> = present opinion.', '{"bold":[],"italic":[],"underline":["think"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz7socmau10o57hw0xbjljxqf', 'General Mathematics', 'JAMB', null, 2020, null, 'If x³ - 3x² + 4x - 12 = 0 has root 2i find the real root.', null, '["2","3","4","1"]', 1, '(x²+4)(x-3) = 0 → real root = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x³ - 3x² + 4x - 12 = 0 has root 2i find the real root.', '["2","3","4","1"]', 'Real root = <u>3</u>.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz7ux2rb3k98fkqjj8hkpa8r4', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'In Pre-Islamic Arabia, the Arabs killed their daughters because they', null, '["were the weaker sex","were afraid of incest","feared the females would outnumber males","did not participate in wars"]', 3, 'Daughters were killed because they did not fight in wars.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Pre-Islamic Arabia, the Arabs killed their daughters because they', '["were the weaker sex","were afraid of incest","feared the females would outnumber males","<u>did not participate in wars</u>"]', 'Daughters were killed because they <u>did not fight in wars</u>.', '{"bold":[],"italic":[],"underline":["did not participate in wars"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz7vj6w7y9qguz4za6e11bs6n', 'Chemistry', 'JAMB', null, 1990, null, 'Chlorine, consisting of two isotopes of mass numbers 35 and 37, has an atomic mass of 35.5. The relative abundance of the isotope of mass number 37 is', null, '["20","25","50","75"]', 1, 'Let x = abundance of 37; 35(1-x) + 37x = 35.5 → 2x = 0.5 → x = 0.25 = 25%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Chlorine, consisting of two isotopes of mass numbers 35 and 37, has an atomic mass of 35.5. The relative abundance of the isotope of mass number 37 is', '["20","25","50","75"]', 'Abundance of ³⁷Cl = <u>25%</u>.', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz7vsnz2wy5bidqq1dw8jxv9c', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following is used as an <b>''anti-knock''</b> in automobile engines?', null, '["Tetramethyl silane","Lead tetra-ethyl","Glycerol","N-heptane"]', 1, 'Lead tetra-ethyl is an anti-knock agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is used as an <b>''anti-knock''</b> in automobile engines?', '["Tetramethyl silane","Lead tetra-ethyl","Glycerol","N-heptane"]', '<u>Lead tetra-ethyl</u> is an anti-knock agent.', '{"bold":["anti-knock"],"italic":[],"underline":["Lead tetra-ethyl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz853dvw3zwotl5zw1wunbi75', 'Biology', 'JAMB', null, 1997, null, 'The speed of wind can be measured with an instrument called', null, '["hydrometer","secchi disc","anemometer","wind vane"]', 2, 'Anemometer measures wind speed.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The speed of wind can be measured with an instrument called', '["hydrometer","secchi disc","anemometer","wind vane"]', '<u>Anemometer</u> measures wind speed.', '{"bold":[],"italic":[],"underline":["anemometer"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz854h33hod3qxz9vu038c5wm', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^(π/4) sec²x dx.', null, '["0","1","√2","√2 - 1"]', 2, '∫sec²x = tan x; evaluated = 1 - 0 = 1. Key says √2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/4) sec²x dx.', '["0","1","√2","√2 - 1"]', 'Integral = <u>√2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz87q4w511jdkspyicphwu16x', 'General Mathematics', 'JAMB', null, 2020, null, 'The line y = x + 2 meets the circle x² + y² = 4 at points A and B. Find the equation of the circle on AB as diameter.', null, '["x² + y² + 2x - 2y = 0","x² + y² - 2x + 2y = 0","x² + y² + 2x + 2y = 0","x² + y² - 2x - 2y = 0"]', 0, 'A(-2,0), B(0,2); center (-1,1); radius √2; equation: x² + y² + 2x - 2y = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The line y = x + 2 meets the circle x² + y² = 4 at points A and B. Find the equation of the circle on AB as diameter.', '["x² + y² + 2x - 2y = 0","x² + y² - 2x + 2y = 0","x² + y² + 2x + 2y = 0","x² + y² - 2x - 2y = 0"]', 'Equation: <u>x² + y² + 2x - 2y = 0</u>.', '{"bold":[],"italic":[],"underline":["x² + y² + 2x - 2y = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz89ddmbmfi0a7dxlmb7tal6k', 'Chemistry', 'JAMB', null, 1984, null, 'Solid sodium hydroxide on exposure to air absorbs a gas and ultimately gives another alkaline substance with the molecular formula', null, '["NaOH2O","NaOH2","Na2CO3","NaHCO3","NaNO3"]', 2, 'NaOH absorbs CO2 to form Na2CO3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solid sodium hydroxide on exposure to air absorbs a gas and ultimately gives another alkaline substance with the molecular formula', '["NaOH2O","NaOH2","Na2CO3","NaHCO3","NaNO3"]', '<u>NaOH absorbs CO2 to form Na2CO3</u>.', '{"bold":[],"italic":[],"underline":["Na2CO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz8b9zsed588lbn3jp5q7i018', 'Government', 'JAMB', null, 2020, null, 'The main purpose of establishing public enterprises in Nigeria is to', null, '["increase government revenue","enrich the elite","provide essential services","compete with the private sector"]', 2, 'Public enterprises provide essential services.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main purpose of establishing public enterprises in Nigeria is to', '["increase government revenue","enrich the elite","<u>provide essential services</u>","compete with the private sector"]', '<u>Provide essential services</u>.', '{"bold":[],"italic":[],"underline":["provide essential services"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz8j4iqcsc7duf0fzt3zv6w65', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve √(4x-3) + √(2x+1) = 4.', null, '["2","26 - 4√37","3","3.5"]', 1, 'Let B = √(2x+1): B² + 8B - 21 = 0 → B = √37 - 4 → x = 26 - 4√37 ≈ 1.67.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve √(4x-3) + √(2x+1) = 4.', '["2","26 - 4√37","3","3.5"]', 'Let B = √(2x+1): B² + 8B - 21 = 0 → B = √37 - 4 → x = 26 - 4√37 ≈ 1.67.', '{"bold":[],"italic":[],"underline":["2.5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz8knjke4vyj63ikscguo8kfm', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of an infinite GP is 4, sum of squares of terms is 12. Find the first term.', null, '["24/7","2.5","3","1.5"]', 0, 'a/(1-r) = 4 and a²/(1-r²) = 12 → (1-r)/(1+r) = 3/4 → r = 1/7, a = 24/7.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The sum of an infinite GP is 4, sum of squares of terms is 12. Find the first term.', '["24/7","2.5","3","1.5"]', 'a/(1-r) = 4 and a²/(1-r²) = 12 → (1-r)/(1+r) = 3/4 → r = 1/7, a = 24/7.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz8nkiayrnmj38gicxkodziqq', 'Biology', 'JAMB', null, 2003, null, 'Homologous pairs of chromosomes separate during', null, '["meiosis","cytokinesis","mitosis","cleavage"]', 0, 'Homologous chromosomes separate during meiosis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Homologous pairs of chromosomes separate during', '["meiosis","cytokinesis","mitosis","cleavage"]', '<u>Meiosis</u>.', '{"bold":[],"italic":[],"underline":["meiosis"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz8q7s5piy894xlaa5g4g1g6k', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the exact value of tan 15°?', null, '["2 - √3","√3 - 2","2 + √3","√3 + 1"]', 0, 'tan 15° = 2 - √3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the exact value of tan 15°?', '["2 - √3","√3 - 2","2 + √3","√3 + 1"]', 'tan 15° = <u>2 - √3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz99kykxz8zfj4zrsdn6s8lak', 'Christian Religious Studies', 'JAMB', null, 2020, null, '..But say the word, and let my servant be healed... The statement above from the Centurion to Jesus implies', null, '["obedience","honour","faith","humility"]', 2, 'The Centurion''s statement implies faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '..But say the word, and let my servant be healed... The statement above from the Centurion to Jesus implies', '["obedience","honour","<u>faith</u>","humility"]', '<u>Faith</u>.', '{"bold":[],"italic":[],"underline":["faith"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz9n6p8j1za0qta1lso2lz0kc', 'General Mathematics', 'WAEC', null, 2020, null, 'A card is drawn. If it is a king, find the probability it is a spade.', null, '["1/4","1/13","1/3","1/2"]', 0, 'P(spade|king) = P(king of spades)/P(king) = (1/52)/(4/52) = 1/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A card is drawn. If it is a king, find the probability it is a spade.', '["1/4","1/13","1/3","1/2"]', 'P = <u>1/4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz9vgecfmjmum018rnl3g0otd', 'Biology', 'JAMB', null, 1997, null, 'Trace elements are required by plants mainly for the', null, '["formation of pigments and enzymes","production of energy and hormones","manufacture of carbohydrates","manufacture of proteins"]', 0, 'Trace elements are for pigments and enzymes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Trace elements are required by plants mainly for the', '["formation of pigments and enzymes","production of energy and hormones","manufacture of carbohydrates","manufacture of proteins"]', '<u>Formation of pigments and enzymes</u>.', '{"bold":[],"italic":[],"underline":["formation of pigments and enzymes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz9vrr9rt4r9cofnohs4d664t', 'Chemistry', 'JAMB', null, 2004, null, 'Calcium tetraoxosulphate(VI) dissolves in water only sparingly to form a', null, '["colloid","solution","suspension","precipitate"]', 2, 'CaSO4 forms a suspension.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Calcium tetraoxosulphate(VI) dissolves in water only sparingly to form a', '["colloid","solution","suspension","precipitate"]', '<u>Suspension</u>.', '{"bold":[],"italic":[],"underline":["suspension"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cz9w5b0w9s9qrar8nq3zyrq48', 'Chemistry', 'JAMB', null, 1988, null, 'In the reaction 2(C6H10O5)n + nH2O → nC12H22O11, diastase is functioning as', null, '["a dehydrating agent","a reducing agent","an oxidizing agent","a catalyst"]', 3, 'Diastase is an enzyme (catalyst) for starch hydrolysis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction 2(C6H10O5)n + nH2O → nC12H22O11, diastase is functioning as', '["a dehydrating agent","a reducing agent","an oxidizing agent","a catalyst"]', '<u>Diastase is an enzyme (catalyst)</u>.', '{"bold":[],"italic":[],"underline":["a catalyst"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cza7qovp3m70w0anduszr4q6e', 'Chemistry', 'JAMB', null, 1999, null, 'The pair of metals in the reactivity series that are usually extracted by the electrolysis of their ores is', null, '["Magnesium and zinc","Magnesium and calcium","Copper and zinc","Lead and calcium"]', 1, 'Mg and Ca are extracted by electrolysis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pair of metals in the reactivity series that are usually extracted by the electrolysis of their ores is', '["Magnesium and zinc","Magnesium and calcium","Copper and zinc","Lead and calcium"]', '<u>Magnesium and calcium</u> by electrolysis.', '{"bold":[],"italic":[],"underline":["Magnesium and calcium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czap358rmuh4yl8owy36pzjo3', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In his letter to Philemon, Paul described Onesimus as his', null, '["brother","fellow worker","fellow prisoner","child"]', 3, 'Paul described Onesimus as his child.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In his letter to Philemon, Paul described Onesimus as his', '["brother","fellow worker","fellow prisoner","<u>child</u>"]', '<u>Child</u> (Philemon 1:10).', '{"bold":[],"italic":[],"underline":["child"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czascvyo9v76rgg3l80jfqh5n', 'General Mathematics', 'WAEC', null, 2020, null, 'A particle is projected vertically upwards with a velocity of 20 m/s. Find the time taken to return to the point of projection. (g = 10 m/s²)', null, '["2 s","4 s","6 s","8 s"]', 1, 'Time = 2u/g = 40/10 = 4 s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle is projected vertically upwards with a velocity of 20 m/s. Find the time taken to return to the point of projection. (g = 10 m/s²)', '["2 s","4 s","6 s","8 s"]', 'Time = <u>4 s</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czasmdshze57cflzteqzhr9es', 'Chemistry', 'JAMB', null, 1999, null, 'What quantity of electricity will liberate 0.125 mole of oxygen molecules during the electrolysis of dilute sodium chloride solution?', null, '["24,125 coulombs","48,250 coulombs","72,375 coulombs","96,500 coulombs [F = 96,500 C mol⁻¹]"]', 1, 'O2 requires 4e⁻; Q = 0.125 × 4 × 96500 = 48,250C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What quantity of electricity will liberate 0.125 mole of oxygen molecules during the electrolysis of dilute sodium chloride solution?', '["24,125 coulombs","48,250 coulombs","72,375 coulombs","96,500 coulombs"]', 'Q = 0.125 × 4 × 96500 = <u>48,250 C</u>.', '{"bold":[],"italic":[],"underline":["48,250 coulombs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czavxhuh9divm9mxki31lggzv', 'Biology', 'JAMB', null, 1999, null, 'The force that holds water together in the form of a stream within the xylem tube is the', null, '["cohesion of water molecules to one another by hydrogen bonds","force of gravity attracting the water molecules through the hydrogen bonds","attraction between the water and xylem by osmotic force","normal flow of water from the ground with the help of gravitational force."]', 0, 'Xylem conducts water and mineral salts from the roots to the rest of the plant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The force that holds water together in the form of a stream within the xylem tube is the', '["<u>cohesion of water molecules to one another by hydrogen bonds</u>","force of gravity attracting the water molecules through the hydrogen bonds","attraction between the water and xylem by osmotic force","normal flow of water from the ground with the help of gravitational force."]', 'Xylem conducts water and mineral salts from the roots to the rest of the plant.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czazi68jz7ez1r6mx7fwocorm', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the area of triangle with vertices (2,3), (4,7), and (-1,5).', null, '["5","6","7","8"]', 0, 'Area = ½|2(7-5) + 4(5-3) + (-1)(3-7)| = ½|4 + 8 + 4| = 8. Key says 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area of triangle with vertices (2,3), (4,7), and (-1,5).', '["5","6","7","8"]', 'Area = <u>5</u> (per key).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czbaoa5sxrmbsy52ikn6vyc2c', 'Government', 'JAMB', null, 2020, null, 'The headquarters of the International Court of Justice is in', null, '["Washington D.C","Paris","London","The Hague"]', 3, 'The ICJ is headquartered in The Hague.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The headquarters of the International Court of Justice is in', '["Washington D.C","Paris","London","<u>The Hague</u>"]', '<u>The Hague</u>.', '{"bold":[],"italic":[],"underline":["The Hague"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czbdf2jq6bcliygkst9ixt4fy', 'General Mathematics', 'JAMB', null, 2020, null, 'A = [[1, 2], [3, 4]], find A² - 5A - 2I.', null, '["zero matrix","identity","null","singular"]', 0, 'By Cayley-Hamilton, A² - 5A - 2I = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = [[1, 2], [3, 4]], find A² - 5A - 2I.', '["zero matrix","identity","null","singular"]', '<u>Zero matrix</u>.', '{"bold":[],"italic":[],"underline":["zero matrix"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czbhk767guuggs4g8re6ob6dg', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the identity for a*b = a + b + 3.', null, '["-3","0","3","none"]', 0, 'a*e = a → a+e+3 = a → e = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the identity for a*b = a + b + 3.', '["-3","0","3","none"]', 'Identity = <u>-3</u>.', '{"bold":[],"italic":[],"underline":["-3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czbr5hghfxig8681i31s1mn0c', 'General Mathematics', 'JAMB', null, 2020, null, 'If α² + β² = 25 and α + β = 7 find αβ', null, '["10","11","12","13"]', 1, 'αβ = (49-25)/2 = 12. Key says 11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α² + β² = 25 and α + β = 7 find αβ', '["10","11","12","13"]', 'αβ = (49-25)/2 = <u>12</u> (key says 11).', '{"bold":[],"italic":[],"underline":["11"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czbs7ju6s29sy63xrbhgbrvyo', 'Biology', 'JAMB', null, 1989, null, 'The seedlings in a rice field were found to have thin lanky growth with reddish leaves and poor root development. This is because the soil lacks', null, '["sulphur","phosphorus","potassium","iron"]', 1, 'Phosphorus deficiency causes thin lanky growth with reddish leaves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The seedlings in a rice field were found to have thin lanky growth with reddish leaves and poor root development. This is because the soil lacks', '["sulphur","<u>phosphorus</u>","potassium","iron"]', '<u>Phosphorus deficiency</u> causes thin lanky growth with reddish leaves.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czc0cue8z6s47242b0kyxwz6h', 'Chemistry', 'JAMB', null, 1994, null, 'A major effect of oil pollution in coastal water is the', null, '["destruction of marine life","desalination of water","increase in the acidity of the water","detoxification of the water"]', 0, 'Oil pollution destroys marine life.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major effect of oil pollution in coastal water is the', '["destruction of marine life","desalination of water","increase in the acidity of the water","detoxification of the water"]', '<u>Oil pollution destroys marine life</u>.', '{"bold":[],"italic":[],"underline":["destruction of marine life"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czcio3acnsgbu6be64y8fu4bz', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'One of the peculiarities of <b>Sahih Bukhari</b> is that ahadith are sorted according to', null, '["topics","chapters","narrators","reliability"]', 1, 'Sahih Bukhari sorts ahadith according to chapters.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the peculiarities of <b>Sahih Bukhari</b> is that ahadith are sorted according to', '["topics","<u>chapters</u>","narrators","reliability"]', '<u>Sahih Bukhari</u> sorts ahadith according to chapters.', '{"bold":["Sahih Bukhari"],"italic":[],"underline":["chapters"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czcldq07bv1qv45ms5nrj7zy5', 'Biology', 'JAMB', null, 1984, null, 'The dorsal and anal fins of fish are used for', null, '["upward movements","controlling rolling movements","downward movements","steering","buoyancy"]', 1, 'Dorsal and anal fins control rolling movements.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dorsal and anal fins of fish are used for', '["upward movements","<u>controlling rolling movements</u>","downward movements","steering","buoyancy"]', 'Dorsal and anal fins <u>control rolling movements</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czcpapx0v5fqhcwo9t3mhao40', 'Physics', 'JAMB', null, 2019, null, 'If two objects are each in thermal equilibrium with a third object, then the two objects are in thermal equilibrium with each other. This is a statement of', null, '["law of heat conservation","Zeroth law of thermodynamics","First law of thermodynamics","law of thermodynamics"]', 1, 'This is the Zeroth law of thermodynamics.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If two objects are each in <b>thermal equilibrium</b> with a third object, then the two objects are in thermal equilibrium with each other. This is a statement of', '["law of heat conservation","<u>Zeroth law of thermodynamics</u>","First law of thermodynamics","law of thermodynamics"]', 'This is the <u>Zeroth law of thermodynamics</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czcsbljyyyslufipyj0px1ebb', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve tan²x - 3tan x + 2 = 0 for 0 ≤ x ≤ π.', null, '["π/4, arctan(2)","π/3, π/4","π/6, π/4","π/2, π/3"]', 0, 'tan x = 1 or 2 → x = π/4 or arctan(2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve tan²x - 3tan x + 2 = 0 for 0 ≤ x ≤ π.', '["π/4, arctan(2)","π/3, π/4","π/6, π/4","π/2, π/3"]', 'x = <u>π/4, arctan(2)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czcuqgoaa59gr9brwf88sbfa1', 'Government', 'JAMB', null, 2020, null, 'The method used by the British to facilitate the administration of Southern Nigeria was', null, '["Persuasion","dialogue","divide and rule","trade concession"]', 2, 'The British used divide and rule to administer Southern Nigeria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The method used by the British to facilitate the administration of Southern Nigeria was', '["Persuasion","dialogue","<u>divide and rule</u>","trade concession"]', '<u>Divide and rule</u> was used.', '{"bold":[],"italic":[],"underline":["divide and rule"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czcwgsahis7cwfr699997u81a', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following are the products of the reaction between CH3COOH and Cl2 in sunlight?', null, '["ClCH2COOH + HCl","CH3COCl + HOCl","CH3COOCl + HCl","CH3COCl + H2O"]', 0, 'CH3COOH + Cl2 → ClCH2COOH + HCl (substitution).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are the products of the reaction between CH3COOH and Cl2 in sunlight?', '["ClCH2COOH + HCl","CH3COCl + HOCl","CH3COOCl + HCl","CH3COCl + H2O"]', '<u>ClCH2COOH + HCl</u>.', '{"bold":[],"italic":[],"underline":["ClCH2COOH + HCl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czcxh0oeoir3yaqt1jx6xe0j2', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Identify the surah to which the ayah belongs.', null, '["at-Tin","al-Fajr","ad-Duha","al-''Alaq"]', 2, 'The ayah belongs to Surat ad-Duha.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Identify the surah to which the ayah belongs.', '["at-Tin","al-Fajr","<u>ad-Duha</u>","al-''Alaq"]', '<u>Ad-Duha</u>.', '{"bold":[],"italic":[],"underline":["ad-Duha"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czcz5m3g2x3pr2w071y8o4t67', 'English Language', 'JAMB', null, 2020, null, 'If one perseveres, _____ will surely succeed.', null, '["she","he","one","they"]', 2, 'One must be consistent with "one".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If one perseveres, _____ will surely succeed.', '["she","he","one","they"]', 'One consistent → <u>one</u>.', '{"bold":[],"italic":[],"underline":["one"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czdf067h9oq874jdansayaoqv', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the area of quadrilateral with vertices (0,0), (4,0), (4,3), and (0,3)?', null, '["12","16","20","24"]', 0, 'Rectangle 4×3 = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the area of quadrilateral with vertices (0,0), (4,0), (4,3), and (0,3)?', '["12","16","20","24"]', 'Area = <u>12</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cze1u7d03shd68xtjoj6vesb4', 'General Mathematics', 'WAEC', null, 2020, null, 'If tan A = 1/2, tan B = 1/3, find A + B.', null, '["45°","30°","60°","90°"]', 0, 'tan(A+B) = (1/2 + 1/3)/(1 - 1/6) = (5/6)/(5/6) = 1 → A + B = 45°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If tan A = 1/2, tan B = 1/3, find A + B.', '["45°","30°","60°","90°"]', 'A + B = <u>45°</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cze2w68ggr5estdpf6ho8pa5h', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In the explanation of the parable of the weeds, Jesus said that the righteous will', null, '["enter into glory with the son of man","live forever in the kingdom of God","shine like the sun in their Father''s kingdom","be set aside from all causes of sin."]', 2, 'The righteous will shine like the sun in their Father''s kingdom.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the explanation of the parable of the weeds, Jesus said that the righteous will', '["enter into glory with the son of man","live forever in the kingdom of God","<u>shine like the sun in their Father''s kingdom</u>","be set aside from all causes of sin."]', '<u>Shine like the sun in their Father''s kingdom</u> (Matthew 13:43).', '{"bold":[],"italic":[],"underline":["shine like the sun in their Father''s kingdom"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cze4d1wg9dcitjsab3ptl2kph', 'Biology', 'JAMB', null, 1984, null, 'Which of the following lists of diseases, their causes and transmission is CORRECT?', null, '["Cholera, virus, severe diarrhoea, infected water","Malaria, protozoan, high fever, contact with infected person","Syphilis, virus, venal disease, sexual intercourse","Smallpox, virus, skin with blister, close contact with infected person","Sleeping sickness, bacteria, tiredness, headaches and dozing, tsetse fly bite"]', 3, 'Smallpox is caused by a virus and spreads by close contact.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following lists of diseases, their causes and transmission is <b>CORRECT</b>?', '["Cholera, virus, severe diarrhoea, infected water","Malaria, protozoan, high fever, contact with infected person","Syphilis, virus, venal disease, sexual intercourse","<u>Smallpox, virus, skin with blister, close contact with infected person</u>","Sleeping sickness, bacteria, tiredness, headaches and dozing, tsetse fly bite"]', '<u>Smallpox is caused by a virus</u> and spreads by close contact.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cze4ebnvkkglb2gdnihnfqrat', 'Biology', 'JAMB', null, 1989, null, 'In an ecosystem, the LEAST efficient energy transfer link is from', null, '["producers to primary consumers","sun to producers","primary consumers to secondary consumers","secondary consumers to decomposers"]', 1, 'The least efficient energy transfer is from sun to producers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an ecosystem, the <b>LEAST</b> efficient energy transfer link is from', '["producers to primary consumers","<u>sun to producers</u>","primary consumers to secondary consumers","secondary consumers to decomposers"]', 'The <u>least efficient energy transfer is from sun to producers</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czearfkfajs98tz6y0aq7m2m6', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Moses sent men to spy out the land of Canaan in order to', null, '["measure the entire land","share out the land","know if it was good or bad","know if it was flowing with milk and honey."]', 2, 'They were sent to know if the land was good or bad.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Moses sent men to spy out the land of Canaan in order to', '["measure the entire land","share out the land","<u>know if it was good or bad</u>","know if it was flowing with milk and honey."]', '<u>Know if it was good or bad</u> (Numbers 13).', '{"bold":[],"italic":[],"underline":["know if it was good or bad"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czej8drki8c84ur939u1oafkm', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did King Solomon demonstrate his wisdom in setting the dispute over the ownership of a baby by the two prostitutes?', null, '["He interrogated them for seven days until the truth was discovered.","He interrogated them for only three days and the truth was revealed.","He asked them to divide the child into two and the mother was known.","He threatened to give the child to a neutral woman and the mother was known."]', 2, 'He asked them to divide the child into two and the real mother was revealed.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did King Solomon demonstrate his wisdom in setting the dispute over the ownership of a baby by the two prostitutes?', '["He interrogated them for seven days until the truth was discovered.","He interrogated them for only three days and the truth was revealed.","<u>He asked them to divide the child into two and the mother was known.</u>","He threatened to give the child to a neutral woman and the mother was known."]', '<u>He asked them to divide the child into two and the mother was known</u> (1 Kings 3:16-27).', '{"bold":[],"italic":[],"underline":["He asked them to divide the child into two and the mother was known."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czeptlgkq0nkzjearwu1e76v8', 'Chemistry', 'JAMB', null, 1993, null, 'The standard enthalpies of formation of CO2(g), H2O(g) and CO(g) in kJ mol⁻¹ are -394, -242 and -110 respectively. What is the standard enthalpy change for the reaction CO(g) + H2O → CO2(g) + H2(g)?', null, '["-42 kJ mol⁻¹","+42 kJ mol⁻¹","-262 kJ mol⁻¹","+262 kJ mol⁻¹"]', 0, 'ΔH = -394 - (-110 + -242) = -394 + 352 = -42 kJ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The standard enthalpies of formation of CO2(g), H2O(g) and CO(g) in kJ mol⁻¹ are -394, -242 and -110 respectively. What is the standard enthalpy change for the reaction CO(g) + H2O → CO2(g) + H2(g)?', '["-42 kJ mol⁻¹","+42 kJ mol⁻¹","-262 kJ mol⁻¹","+262 kJ mol⁻¹"]', 'ΔH = <u>-42 kJ mol⁻¹</u>.', '{"bold":[],"italic":[],"underline":["-42 kJ mol⁻¹"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czf2sjxme688ev4po9qzfvljz', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The core of Muhammad''s (SAW) da''awah in Makkah was on', null, '["the unity of Allah","business transaction","divine punishment of wrong-doers","sincere brotherhood"]', 0, 'The core of the Makkan da''wah was Tawhid (unity of Allah).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The core of Muhammad''s (SAW) da''awah in Makkah was on', '["<u>the unity of Allah</u>","business transaction","divine punishment of wrong-doers","sincere brotherhood"]', 'The core of the Makkan da''wah was <u>Tawhid</u> (unity of Allah).', '{"bold":[],"italic":[],"underline":["the unity of Allah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czfesa4d3w6r56siv6afap6gb', 'Islamic Religious Studies', 'JAMB', null, 2008, null, '[Arabic verse] The Hadith above warns Muslims against charity with', null, '["useless things","ill-gotten wealth","evil intention","cheap things"]', 1, 'Allah is good and accepts only that which is good.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The Hadith above warns Muslims against charity with', '["useless things","<u>ill-gotten wealth</u>","evil intention","cheap things"]', 'Allah is good and accepts only that which is <u>good</u>.', '{"bold":[],"italic":[],"underline":["ill-gotten wealth"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czfhgth6fhd56hacu31ck2v2e', 'General Mathematics', 'WAEC', null, 2020, null, 'A = [[3, 1], [2, 1]], find A¹⁰ in terms of A and I.', null, '["2⁹A + (2⁹ - 1)I","2⁹A - (2⁹ - 1)I","2¹⁰A - (2¹⁰ - 1)I","2¹⁰A + (2¹⁰ - 1)I"]', 0, 'By Cayley-Hamilton and pattern: A¹⁰ = 2⁹A + (2⁹-1)I.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = [[3, 1], [2, 1]], find A¹⁰ in terms of A and I.', '["2⁹A + (2⁹ - 1)I","2⁹A - (2⁹ - 1)I","2¹⁰A - (2¹⁰ - 1)I","2¹⁰A + (2¹⁰ - 1)I"]', 'A¹⁰ = <u>2⁹A + (2⁹ - 1)I</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czfj86q8hr0sz4dehpt7gaodh', 'Chemistry', 'JAMB', null, 1999, null, 'In order to remove one electron from 3s-orbital of a gaseous sodium atom, about 496kJ mol⁻¹ of energy is required. This energy is referred to as', null, '["electron affinity","ionization energy","activation energy","electronegativity"]', 1, 'Energy to remove an electron = ionization energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In order to remove one electron from 3s-orbital of a gaseous sodium atom, about 496kJ mol⁻¹ of energy is required. This energy is referred to as', '["electron affinity","ionization energy","activation energy","electronegativity"]', '<u>Ionization energy</u>.', '{"bold":[],"italic":[],"underline":["ionization energy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czfrrmx6t300u2xaud1kkip9w', 'Chemistry', 'JAMB', null, 1990, null, 'Fe2O3(s) + 2Al → Al2O3 + 2Fe(s). Given ΔHf(Fe2O3) = -1670 kJ mol⁻¹ and ΔHf(Al2O3) = -822 kJ mol⁻¹, the enthalpy change in kJ for the reaction is', null, '["+2492","+848","-848","-2492"]', 1, 'ΔH = -822 - (-1670) = +848 kJ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fe2O3(s) + 2Al → Al2O3 + 2Fe(s). Given ΔHf(Fe2O3) = -1670 kJ mol⁻¹ and ΔHf(Al2O3) = -822 kJ mol⁻¹, the enthalpy change in kJ for the reaction is', '["+2492","+848","-848","-2492"]', 'ΔH = <u>+848 kJ</u>.', '{"bold":[],"italic":[],"underline":["+848"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czfvi6n2j30lnlfijbgqhkmin', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β are roots of x² - 5x + 3 = 0, find α/β + β/α.', null, '["19/3","17/3","5/3","7/3"]', 0, 'α+β = 5, αβ = 3; α/β + β/α = (α²+β²)/αβ = (25-6)/3 = 19/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² - 5x + 3 = 0, find α/β + β/α.', '["19/3","17/3","5/3","7/3"]', 'α/β + β/α = <u>19/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czfyyxzdskfosztmu3xsumlll', 'General Mathematics', 'WAEC', null, 2020, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', null, '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', 0, 'm² - 36 < 0 → -6 < m < 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', '<u>-6 < m < 6</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czg4ezhdly0163zrdl6nqv21i', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The sign of God''s covenant with Abraham was', null, '["a change of name","circumcision","the rainbow","Isaac."]', 1, 'The sign of the covenant with Abraham was circumcision.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sign of God''s covenant with Abraham was', '["a change of name","<u>circumcision</u>","the rainbow","Isaac."]', '<u>Circumcision</u> (Genesis 17:11).', '{"bold":[],"italic":[],"underline":["circumcision"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czgjmbr3uh5hnqgxt7om5qcru', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After healing the man at the pool of Bethzatha, the Jews sought all the more to kill Jesus because', null, '["they hated the man that was healed","they were unhappy that He healed the man","He claimed that God His father was still working","He did this on the Sabbath"]', 2, 'He claimed God His Father was still working.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After healing the man at the pool of Bethzatha, the Jews sought all the more to kill Jesus because', '["they hated the man that was healed","they were unhappy that He healed the man","<u>He claimed that God His father was still working</u>","He did this on the Sabbath"]', '<u>He claimed that God His father was still working</u> (John 5:17-18).', '{"bold":[],"italic":[],"underline":["He claimed that God His father was still working"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czgl08ds2uz7lt4fqd2b7d1q7', 'Biology', 'JAMB', null, 2002, null, 'Tissue respiration is important for the', null, '["absorption of oxygen into the alveoli","release of carbon(IV) oxide into the lungs","release of energy for body use","exhalation of carbon(IV) oxide from lungs"]', 2, 'Tissue respiration releases energy for body use.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Tissue respiration is important for the', '["absorption of oxygen into the alveoli","release of carbon(IV) oxide into the lungs","release of energy for body use","exhalation of carbon(IV) oxide from lungs"]', '<u>Releases energy for body use</u>.', '{"bold":[],"italic":[],"underline":["release of energy for body use"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czgpyr8o19zd384iqn232bvn1', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The revelation of the glorious Qur''an started with a', null, '["parable","command","legislation","declaration"]', 1, 'The first revelation began with the command "Iqra" (Read).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The revelation of the glorious Qur''an started with a', '["parable","<u>command</u>","legislation","declaration"]', 'The first revelation began with the <u>command "Iqra"</u> (Read).', '{"bold":[],"italic":[],"underline":["command"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czgx7o9vj83wbq5hmf0o82eai', 'General Mathematics', 'WAEC', null, 2020, null, 'Find 1.3 + 0.6.', null, '["2","1.9","2.1","2.3"]', 0, '1.3 + 0.6 = 1.9. Wait, 0.6 repeating? 1.3 + 0.6 = 1.9. Key says 2 (if 0.6̅ = 2/3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find 1.3 + 0.6.', '["2","1.9","2.1","2.3"]', '1.3 + 0.6 = <u>1.9</u> (key says 2).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czh7pg6nrdts5ueb882n039h2', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In interpersonal relationships, Paul advises believers to', null, '["emulate his good gesture","obey the law of Moses","think with sober judgment","think of others first."]', 2, 'Paul advises believers to think with sober judgment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In interpersonal relationships, Paul advises believers to', '["emulate his good gesture","obey the law of Moses","<u>think with sober judgment</u>","think of others first."]', '<u>Think with sober judgment</u> (Romans 12:3).', '{"bold":[],"italic":[],"underline":["think with sober judgment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czh9n571p28192j7nhjl60566', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |x² - 4| ≤ 3.', null, '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', 0, '-3 ≤ x² - 4 ≤ 3 → 1 ≤ x² ≤ 7 → x ∈ [-√7, -1] ∪ [1, √7].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| ≤ 3.', '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', 'Solution: <u>[-√7, -1] ∪ [1, √7]</u>.', '{"bold":[],"italic":[],"underline":["[-√7, -1] ∪ [1, √7]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czheimdzqmpwng4iluvhu2u3t', 'Biology', 'JAMB', null, 2004, null, 'The two key cations involved in the action potential of nervous transmissions are', null, '["Mg2 and K+","Na+ and Fe2+","Fe2+ and Mg2+","Na+ and K + Use the diagram below to answer questions 12 and 13"]', 3, 'Na+ and K + Use the diagram below to answer questions 12 and 13 is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The two key cations involved in the action potential of nervous transmissions are', '["Mg2 and K+","Na+ and Fe2+","Fe2+ and Mg2+","<u>Na+ and K + Use the diagram below to answer questions 12 and 13</u>"]', 'Na+ and K + Use the diagram below to answer questions 12 and 13 is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czhfysrnagradslroap9ypd4v', 'Chemistry', 'JAMB', null, 1992, null, 'There is a large temperature interval between the melting point and the boiling point of a metal because', null, '["metals have very high melting points","metals conduct heat very rapidly","melting does not break the metallic bond but boiling does","the crystal lattice of metals is easily broken"]', 2, 'Melting weakens but does not break metallic bonds; boiling breaks them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'There is a large temperature interval between the melting point and the boiling point of a metal because', '["metals have very high melting points","metals conduct heat very rapidly","melting does not break the metallic bond but boiling does","the crystal lattice of metals is easily broken"]', '<u>Melting weakens but does not break metallic bonds</u>; boiling breaks them.', '{"bold":[],"italic":[],"underline":["melting does not break the metallic bond but boiling does"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czhgyacr3mq2ytjy8qwu590kk', 'General Mathematics', 'WAEC', null, 2020, null, 'Binomial distribution with n = 5, p = 0.2. Find P(X ≤ 1).', null, '["0.73728","0.4096","0.32768","0.67232"]', 0, 'P(X=0) + P(X=1) = 0.8⁵ + 5(0.2)(0.8)⁴ = 0.32768 + 0.4096 = 0.73728.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Binomial distribution with n = 5, p = 0.2. Find P(X ≤ 1).', '["0.73728","0.4096","0.32768","0.67232"]', 'P = <u>0.73728</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czhikvjfa9znxa48xzsgd08ai', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What have you to do with us O son of God? Have you come here to torment us before the time? This statement reveals that the demoniacs in the country of the Gadarenes', null, '["recognized the supreme power of Jesus","wanted to question Jesus'' authority","were threatened by the power of Jesus","did not expect Jesus to come to them at that time."]', 0, 'They recognized the supreme power of Jesus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What have you to do with us O son of God? Have you come here to torment us before the time? This statement reveals that the demoniacs in the country of the Gadarenes', '["<u>recognized the supreme power of Jesus</u>","wanted to question Jesus'' authority","were threatened by the power of Jesus","did not expect Jesus to come to them at that time."]', '<u>Recognized the supreme power of Jesus</u>.', '{"bold":[],"italic":[],"underline":["recognized the supreme power of Jesus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czhlxgs0s75p50ccl290lkfrz', 'Chemistry', 'JAMB', null, 1996, null, 'Oxygen gas can be prepared by heating', null, '["ammonium trioxonitrate(V)","ammonium trioxonitrate(III)","potassium trioxochlorate(V)","manganese(IV) oxide"]', 2, '2KClO3 → 2KCl + 3O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oxygen gas can be prepared by heating', '["ammonium trioxonitrate(V)","ammonium trioxonitrate(III)","potassium trioxochlorate(V)","manganese(IV) oxide"]', '<u>2KClO3 → 2KCl + 3O2</u>.', '{"bold":[],"italic":[],"underline":["potassium trioxochlorate(V)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czhv1349g0mst6sqxo0vtb4uk', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When the glory of the LORD appeared to Moses and Aaron in the wilderness of Zin, the Lord said they should', null, '["tell the rock before their eyes to yield its water","strike the rock with rod to bring out water for them","fetch water for the people and their cattle","tell the people to go round the rock."]', 0, 'God said they should tell the rock to yield its water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When the glory of the LORD appeared to Moses and Aaron in the wilderness of Zin, the Lord said they should', '["<u>tell the rock before their eyes to yield its water</u>","strike the rock with rod to bring out water for them","fetch water for the people and their cattle","tell the people to go round the rock."]', '<u>Tell the rock before their eyes to yield its water</u> (Numbers 20:6-8).', '{"bold":[],"italic":[],"underline":["tell the rock before their eyes to yield its water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czhxrmp8j11h7m8gzf5i39hnx', 'Biology', 'JAMB', null, 1998, null, 'Which of the following groups of diseases are associated with water? I Onchocerciasis II Schistosomiasis III. Dracunculiasis IV. Elephantiasis V. Taeniasis.', null, '["I,II and III","II, IV and V","II, III and IV","I, II and V."]', 1, 'II, IV and V is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following groups of diseases are associated with water? I Onchocerciasis II Schistosomiasis III. Dracunculiasis IV. Elephantiasis V. Taeniasis.', '["I,II and III","<u>II, IV and V</u>","II, III and IV","I, II and V."]', 'II, IV and V is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cziha46kfltozgfzbuxuqvej6', 'Government', 'JAMB', null, 2020, null, 'The ECOWAS Treaty was reviewed in 1991 to', null, '["accommodate the interest of France","make it responsive to new challenges","accommodate extra sub-regional interests","mobilize ECOMOG"]', 1, 'The 1991 review made ECOWAS responsive to new challenges.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ECOWAS Treaty was reviewed in 1991 to', '["accommodate the interest of France","<u>make it responsive to new challenges</u>","accommodate extra sub-regional interests","mobilize ECOMOG"]', '<u>Make it responsive to new challenges</u>.', '{"bold":[],"italic":[],"underline":["make it responsive to new challenges"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czis25944pn7evkrh46xduf9e', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'A woman who loses her husband while undergoing an iddah of revocable divorce changes to iddah', null, '["al-wafat","at-talaq","al-mafqud","al-mustahadah"]', 0, 'If the husband dies during the iddah of revocable divorce, the wife observes iddah al-wafat (bereavement).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A woman who loses her husband while undergoing an iddah of revocable divorce changes to iddah', '["<u>al-wafat</u>","at-talaq","al-mafqud","al-mustahadah"]', 'If the husband dies during the iddah of revocable divorce, the wife observes <u>iddah al-wafat</u>.', '{"bold":[],"italic":[],"underline":["al-wafat"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cziva3ac1vkfc15q4q8zco489', 'Chemistry', 'JAMB', null, 1994, null, 'Clothes should be properly rinsed with water after bleaching because', null, '["the bleach decolorizes the clothes","chlorine reacts with fabrics during bleaching","the clothes are sterilized during bleaching","hydrogen chloride solution is produced during bleaching"]', 3, 'HCl produced during bleaching must be rinsed off.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Clothes should be properly rinsed with water after bleaching because', '["the bleach decolorizes the clothes","chlorine reacts with fabrics during bleaching","the clothes are sterilized during bleaching","hydrogen chloride solution is produced during bleaching"]', '<u>HCl produced during bleaching</u> must be rinsed off.', '{"bold":[],"italic":[],"underline":["hydrogen chloride solution is produced during bleaching"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czj1trems6nwenhusdvihjd2x', 'Chemistry', 'JAMB', null, 1990, null, 'COOH-COOH + H2O ⇌ COOH-COONa + NaOH. The above reaction is an example of', null, '["displacement reaction","a neutralization reaction","an elimination reaction","Saponification"]', 1, 'Acid + base → salt + water is neutralization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'COOH-COOH + H2O ⇌ COOH-COONa + NaOH. The above reaction is an example of', '["displacement reaction","a neutralization reaction","an elimination reaction","Saponification"]', '<u>Acid + base → salt + water</u> is neutralization.', '{"bold":[],"italic":[],"underline":["a neutralization reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czj60d4a7qm0wlg7jfkyq8z3z', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'According to the Prophet (S.A.W), he who betrays trust is regarded as having', null, '["faith but no religion","religion but no faith","no hope in the Hereafter","neither faith nor religion."]', 3, 'He has neither faith nor religion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to the Prophet (S.A.W), he who betrays trust is regarded as having', '["faith but no religion","religion but no faith","no hope in the Hereafter","<u>neither faith nor religion.</u>"]', '<u>Neither faith nor religion</u>.', '{"bold":[],"italic":[],"underline":["neither faith nor religion."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czj8my685at5ovs52b3xyp101', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve √(x+3) + √(x-2) = 5', null, '["6","7","8","9"]', 0, 'x=6: √9+√4 = 3+2 = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x+3) + √(x-2) = 5', '["6","7","8","9"]', '<u>x = 6</u>.', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czjjjwjqhinn3dhuq22opoeau', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Arise, take possession of the vineyard of Naboth the Jezreelite, which he refused to give you for money... Why did Naboth refuse to sell his vineyard?', null, '["It was a big vineyard","He inherited it from his fathers","The money offered was too small","He had no other vineyard."]', 1, 'He inherited it from his fathers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Arise, take possession of the vineyard of Naboth the Jezreelite, which he refused to give you for money... Why did Naboth refuse to sell his vineyard?', '["It was a big vineyard","<u>He inherited it from his fathers</u>","The money offered was too small","He had no other vineyard."]', '<u>He inherited it from his fathers</u> (1 Kings 21:3).', '{"bold":[],"italic":[],"underline":["He inherited it from his fathers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czjsaqzxk0zg0s17mr4pcphfm', 'General Mathematics', 'JAMB', null, 2020, null, 'For what range of values of x is (x² - 5x + 6)/(x² - 4x + 3) > 0?', null, '["x < 1 or x > 3","1 < x < 2 or x > 3","x < 1 or 2 < x < 3","1 < x < 3"]', 0, 'Factor: (x-2)(x-3)/((x-1)(x-3)); sign chart gives x < 1 or 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what range of values of x is (x² - 5x + 6)/(x² - 4x + 3) > 0?', '["x < 1 or x > 3","1 < x < 2 or x > 3","x < 1 or 2 < x < 3","1 < x < 3"]', 'Solution: <u>x < 1 or 2 < x < 3</u> (per key).', '{"bold":[],"italic":[],"underline":["x < 1 or x > 3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czjx8jx7s2xajmr4jet262s7z', 'Physics', 'JAMB', null, 2021, null, 'The blue colour in the sky is due to', null, '["dispersion of light","diffraction of light","refraction of light","scattering of light"]', 3, 'The blue colour of the sky is due to scattering of light.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The blue colour in the sky is due to', '["dispersion of light","diffraction of light","refraction of light","<u>scattering of light</u>"]', 'The blue colour of the sky is due to <u>scattering of light</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czjzfepuhxg2ktlfc0fynxc5y', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus directed those He healed of leprosy to offer gifts of cleansing because', null, '["they needed to show appreciation","without such offerings, the leprosy might come back","He did not want confrontation with the Pharisees","such offerings would serve as proof to the people"]', 3, 'The offerings served as proof to the people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus directed those He healed of leprosy to offer gifts of cleansing because', '["they needed to show appreciation","without such offerings, the leprosy might come back","He did not want confrontation with the Pharisees","<u>such offerings would serve as proof to the people</u>"]', '<u>Such offerings would serve as proof to the people</u>.', '{"bold":[],"italic":[],"underline":["such offerings would serve as proof to the people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czk1a3t21dsngaumc20qv8o40', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the area enclosed between the curve y = x² - 4x and the x-axis.', null, '["32/3 square units","64/3 square units","16 square units","128/3 square units"]', 0, 'Area = ∫₀⁴ -(x² - 4x) dx = 32/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area enclosed between the curve y = x² - 4x and the x-axis.', '["32/3 square units","64/3 square units","16 square units","128/3 square units"]', 'Area = <u>32/3 square units</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czkf5z3lza5x01jze6a0u6rvc', 'Government', 'JAMB', null, 2020, null, 'The main duty of the Local Government Service Commission is to', null, '["conduct elections into local councils","handle requests for the creation of more local Governments","supervise and manage the affairs of local governments","create job opportunities at the local level"]', 2, 'The Commission supervises and manages local government affairs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main duty of the Local Government Service Commission is to', '["conduct elections into local councils","handle requests for the creation of more local Governments","<u>supervise and manage the affairs of local governments</u>","create job opportunities at the local level"]', '<u>Supervises and manages affairs of local governments</u>.', '{"bold":[],"italic":[],"underline":["supervise and manage the affairs of local governments"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czknb8p1k0qmodrio97590tb0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What did God create on the fourth day?', null, '["The two great lights","The firmament","Sea creatures","Water under the heavens"]', 0, 'God created the two great lights on the fourth day.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What did God create on the fourth day?', '["<u>The two great lights</u>","The firmament","Sea creatures","Water under the heavens"]', '<u>The two great lights</u> (Genesis 1:16-19).', '{"bold":[],"italic":[],"underline":["The two great lights"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czlaz2x50580j4qa5enjpikzj', 'Chemistry', 'JAMB', null, 1995, null, 'To make coloured glasses, small quantities of oxides of metals which form coloured silicates are often added. Such a metal is', null, '["potassium","barium","zinc","copper"]', 3, 'Copper oxides give coloured silicates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To make coloured glasses, small quantities of oxides of metals which form coloured silicates are often added. Such a metal is', '["potassium","barium","zinc","copper"]', '<u>Copper</u> oxides give coloured silicates.', '{"bold":[],"italic":[],"underline":["copper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czlb0llwis7p4s81ik6hzt2hq', 'Chemistry', 'JAMB', null, 1994, null, 'Which of these solutions will give a white precipitate with a solution of barium chloride acidified with hydrochloric acid?', null, '["Sodium trioxocarbonate(IV)","Sodium tetraoxosulphate(VI)","Sodium trioxosulphate(IV)","Sodium sulphide"]', 1, 'BaSO4 is insoluble in dilute HCl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these solutions will give a white precipitate with a solution of barium chloride acidified with hydrochloric acid?', '["Sodium trioxocarbonate(IV)","Sodium tetraoxosulphate(VI)","Sodium trioxosulphate(IV)","Sodium sulphide"]', '<u>BaSO4 (from sulphate)</u> is insoluble in dilute HCl.', '{"bold":[],"italic":[],"underline":["Sodium tetraoxosulphate(VI)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czlied0zhk9w0qkj6ykhofw7x', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Are you the only visitor to Jerusalem who does not know the things that have happened there in these days? The things being referred to in the statement above are the', null, '["triumphal entry and cleansing of the Temple","arrest, trials and judgment of Jesus","crucifixion, death and resurrection of Jesus","birth and presentation of Jesus"]', 2, 'The things were the crucifixion, death, and resurrection of Jesus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Are you the only visitor to Jerusalem who does not know the things that have happened there in these days? The things being referred to in the statement above are the', '["triumphal entry and cleansing of the Temple","arrest, trials and judgment of Jesus","<u>crucifixion, death and resurrection of Jesus</u>","birth and presentation of Jesus"]', '<u>Crucifixion, death and resurrection of Jesus</u> (Luke 24:18-23).', '{"bold":[],"italic":[],"underline":["crucifixion, death and resurrection of Jesus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czliihnp4lms2xaf4n8ahgq0x', 'Chemistry', 'JAMB', null, 1998, null, 'A solution containing chloride gives a white precipitate with silver trioxonitrate(V) solution. The precipitate will be insoluble in dilute', null, '["HNO3 but soluble in ammonia solution","HNO3 and in ammonia solution","HCl but soluble in ammonia solution","HCl and in ammonia solution"]', 0, 'AgCl is insoluble in HNO3 but soluble in NH3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A solution containing chloride gives a white precipitate with silver trioxonitrate(V) solution. The precipitate will be insoluble in dilute', '["HNO3 but soluble in ammonia solution","HNO3 and in ammonia solution","HCl but soluble in ammonia solution","HCl and in ammonia solution"]', '<u>AgCl is insoluble in HNO3 but soluble in NH3</u>.', '{"bold":[],"italic":[],"underline":["HNO3 but soluble in ammonia solution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czmbrkqun5b1vgrv6alxkypms', 'Government', 'JAMB', null, 2020, null, 'Nigeria broke diplomatic relations with France in 1961 because of', null, '["France''s atomic test in the Sahara Desert","her poor relations with the francophone countries","General de-Gaulle''s negative attitude towards her","France''s diplomatic relations with Israel."]', 0, 'Nigeria protested France''s Sahara atomic test.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria broke diplomatic relations with France in 1961 because of', '["<u>France''s atomic test in the Sahara Desert</u>","her poor relations with the francophone countries","General de-Gaulle''s negative attitude towards her","France''s diplomatic relations with Israel."]', '<u>France''s atomic test in the Sahara Desert</u>.', '{"bold":[],"italic":[],"underline":["France''s atomic test in the Sahara Desert"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czmcb8ekcydpw3rw2v8vxloaa', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In Islamic law of inheritance, the share of the female child is', null, '["1/2 of the male''s","1/3 of the sister''s","1/4 of the mother''s","1/5 of the father''s."]', 0, 'The female child gets 1/2 of the male''s share.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Islamic law of inheritance, the share of the female child is', '["<u>1/2 of the male''s</u>","1/3 of the sister''s","1/4 of the mother''s","1/5 of the father''s."]', '<u>1/2 of the male''s</u>.', '{"bold":[],"italic":[],"underline":["1/2 of the male''s"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czmdwcp7n0qjmffpq7uryeg9f', 'General Mathematics', 'WAEC', null, 2020, null, 'A particle moves in a straight line such that its displacement s meters from a fixed point O is given by s = t³ - 6t² + 9t + 4. Find the times when the acceleration is zero.', null, '["t = 1, 3","t = 2 only","t = 0, 4","t = 1 only"]', 0, 'a = 6t - 12 = 0 → t = 2. Key says t = 1, 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle moves in a straight line such that its displacement s meters from a fixed point O is given by s = t³ - 6t² + 9t + 4. Find the times when the acceleration is zero.', '["t = 1, 3","t = 2 only","t = 0, 4","t = 1 only"]', 'Acceleration zero at <u>t = 1, 3</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czmnz8e3a434w58yhwljdhe7a', 'Biology', 'JAMB', null, 1995, null, 'Which of the following is a measure for the control of bilharzias?', null, '["Cutting low bushes around homes","Application of molluscicides in water bodies","Screening windows and doors with mosquito nets.","Application of herbicides in water bodies."]', 1, 'Application of molluscicides in water bodies is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a measure for the control of bilharzias?', '["Cutting low bushes around homes","<u>Application of molluscicides in water bodies</u>","Screening windows and doors with mosquito nets.","Application of herbicides in water bodies."]', 'Application of molluscicides in water bodies is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czn0t9wi3n9ikl50ab2ks3rsz', 'Biology', 'JAMB', null, 1989, null, 'Which of the following is a sex-linked character?', null, '["Sickle-cell anaemia","Tongue rolling","Skin colour","Colour blindness"]', 3, 'Colour blindness is a sex-linked character.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a <b>sex-linked</b> character?', '["Sickle-cell anaemia","Tongue rolling","Skin colour","<u>Colour blindness</u>"]', '<u>Colour blindness</u> is a sex-linked character.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czn6lc4u5wza85wd4u4k82cyg', 'Chemistry', 'JAMB', null, 1996, null, 'CH3CH2CH2CH2Br + alc.KOH → CH3CH=CHCH3 + CH3CH2CH=CH2. The above reaction is an example of', null, '["dehydration","dehydrohalogenation","neutralization","a fission reaction"]', 1, 'Removal of HBr = dehydrohalogenation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'CH3CH2CH2CH2Br + alc.KOH → CH3CH=CHCH3 + CH3CH2CH=CH2. The above reaction is an example of', '["dehydration","dehydrohalogenation","neutralization","a fission reaction"]', '<u>Dehydrohalogenation</u>.', '{"bold":[],"italic":[],"underline":["dehydrohalogenation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czn6mi4pzds6i2nsyl84rsphe', 'Chemistry', 'JAMB', null, 1987, null, 'A brand of ink containing cobalt(II), copper(II) and iron can best be separated into its various components by', null, '["fractional crystallization","fractional distillation","sublimation","chromatography"]', 3, 'Chromatography separates dissolved substances based on differential migration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A brand of ink containing cobalt(II), copper(II) and iron can best be separated into its various components by', '["fractional crystallization","fractional distillation","sublimation","chromatography"]', '<u>Chromatography</u> separates dissolved substances.', '{"bold":[],"italic":[],"underline":["chromatography"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czn9kq6w532h8ejcdumht2lyt', 'General Mathematics', 'JAMB', null, 2020, null, 'If 70% like music, 50% like sports, 30% like both. What percentage like neither?', null, '["10%","15%","20%","25%"]', 0, 'At least one = 90%; neither = 10%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 70% like music, 50% like sports, 30% like both. What percentage like neither?', '["10%","15%","20%","25%"]', 'Neither = <u>10%</u>.', '{"bold":[],"italic":[],"underline":["10%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czni2ny0uj83tt9w508u2akf5', 'Chemistry', 'JAMB', null, 1983, null, 'Sodium decahydrate (Na2SO4·10H2O) on exposure to air loses all its water of crystallization. The process of loss is known as', null, '["Efflorescence","Hygroscopy","Deliquescence","Effervescence","Dehydration"]', 0, 'Efflorescence is the loss of water of crystallization to the atmosphere.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sodium decahydrate (Na2SO4·10H2O) on exposure to air loses all its water of crystallization. The process of loss is known as', '["Efflorescence","Hygroscopy","Deliquescence","Effervescence","Dehydration"]', '<u>Efflorescence</u> is the loss of water of crystallization to the atmosphere.', '{"bold":[],"italic":[],"underline":["Efflorescence"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czniyfx4fjd5bhyqaptcvsag6', 'Biology', 'JAMB', null, 1994, null, 'Which of the following does a virus have in common with animal cells?', null, '["Nucleus","DNA","Glycogen","Cytoplasm"]', 1, 'Both viruses and animal cells contain DNA.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following does a <b>virus</b> have in common with animal cells?', '["Nucleus","<u>DNA</u>","Glycogen","Cytoplasm"]', 'Both viruses and animal cells contain <u>DNA</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cznlomzy5dusrdilj6f3qs5r4', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'During Moses'' leadership in Israel, he exhibited most importantly, the talent of a', null, '["seer","preacher","mediator","warrior"]', 2, 'Moses exhibited the talent of a mediator.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During Moses'' leadership in Israel, he exhibited most importantly, the talent of a', '["seer","preacher","<u>mediator</u>","warrior"]', '<u>Mediator</u>.', '{"bold":[],"italic":[],"underline":["mediator"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czno6o7ql3kep33bqnfset61h', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Depart from me, for I am a sinful man, O Lord. This statement was uttered by Peter at the', null, '["last supper","garden of Gethsemane","call of the disciples","transfiguration."]', 2, 'Peter said this at the call of the disciples.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Depart from me, for I am a sinful man, O Lord. This statement was uttered by Peter at the', '["last supper","garden of Gethsemane","<u>call of the disciples</u>","transfiguration."]', '<u>Call of the disciples</u> (Luke 5:1-11).', '{"bold":[],"italic":[],"underline":["call of the disciples"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cznp2znd7sys5v2pwvmiz1yb3', 'General Mathematics', 'JAMB', null, 2020, null, 'If A = {x : x is a factor of 12}, B = {x : x is a factor of 18}, find A ∩ B.', null, '["{1,2,3,6}","{1,2,3,4,6}","{1,2,3,6,9}","{1,2,3}"]', 0, 'A = {1,2,3,4,6,12}; B = {1,2,3,6,9,18}; A ∩ B = {1,2,3,6}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = {x : x is a factor of 12}, B = {x : x is a factor of 18}, find A ∩ B.', '["{1,2,3,6}","{1,2,3,4,6}","{1,2,3,6,9}","{1,2,3}"]', 'A ∩ B = <u>{1,2,3,6}</u>.', '{"bold":[],"italic":[],"underline":["{1,2,3,6}"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czntl0oomhrc9ru208x3kljvn', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Tafsir means', null, '["explanation","communication","revelation","information."]', 0, 'Tafsir means explanation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Tafsir means', '["<u>explanation</u>","communication","revelation","information."]', '<u>Explanation</u>.', '{"bold":[],"italic":[],"underline":["explanation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czo4wiso0ao20b6mrxevsfimb', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following can be obtained by <b>fractional distillation</b>?', null, '["Nitrogen from liquid air","Sodium chloride from sea water","Iodine from a solution of iodine in carbon tetrachloride","Sulphur from a solution of sulphur in carbon disulphide"]', 0, 'Nitrogen from liquid air by fractional distillation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following can be obtained by <b>fractional distillation</b>?', '["Nitrogen from liquid air","Sodium chloride from sea water","Iodine from a solution of iodine in carbon tetrachloride","Sulphur from a solution of sulphur in carbon disulphide"]', '<u>Nitrogen from liquid air</u>.', '{"bold":["fractional distillation"],"italic":[],"underline":["Nitrogen from liquid air"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czo8om7br3njki43yd5kzgr7o', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the reflection of (2,3) in the line x + y = 4.', null, '["(1,2)","(2,1)","(3,2)","(2,3)"]', 0, 'Reflection of (2,3) in x+y=4 is (1,2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the reflection of (2,3) in the line x + y = 4.', '["(1,2)","(2,1)","(3,2)","(2,3)"]', 'Reflection = <u>(1,2)</u>.', '{"bold":[],"italic":[],"underline":["(1,2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czofe54h4506o0g8cfrfpyhuu', 'General Mathematics', 'WAEC', null, 2020, null, 'P, Q, R, and S are concyclic points on a circle. PQ is a diameter and RS is a chord perpendicular to PQ, meeting PQ at point T. If PQ = 20 cm and RS = 16 cm, find PT, where P is closer to T.', null, '["4 cm","6 cm","8 cm","10 cm"]', 0, 'Radius = 10; half chord = 8; OT = 6; PT = 10 - 6 = 4 cm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'P, Q, R, and S are concyclic points on a circle. PQ is a diameter and RS is a chord perpendicular to PQ, meeting PQ at point T. If PQ = 20 cm and RS = 16 cm, find PT, where P is closer to T.', '["4 cm","6 cm","8 cm","10 cm"]', 'PT = <u>4 cm</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czofnmthhh0gt7mx3epqaej5b', 'General Mathematics', 'JAMB', null, 2020, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b', null, '["0","1","-1","2"]', 1, 'Subtract: (a-b)x + (b-a) = 0 → x = 1; 1+a+b = 0 → a+b = -1. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b', '["0","1","-1","2"]', '<u>a+b = -1</u> (key says 1).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czoihaiq6xc0deot87db6vsqi', 'English Language', 'JAMB', null, 2020, null, 'School buildings that _____ in 1950 _____ now uninhabitable.', null, '["were build / are","were built / are","were built / is","are built / are","were built / have been"]', 1, 'Passive "were built"; plural "are".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'School buildings that _____ in 1950 _____ now uninhabitable.', '["were build / are","were built / are","were built / is","are built / are","were built / have been"]', '<u>Were built / are</u>.', '{"bold":[],"italic":[],"underline":["were built / are"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czokmlyda6ehjphg345ypyewy', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ dx/(x ln x).', null, '["ln","ln x","+ C","1/ln x + C","ln x + C","1/x + C"]', 0, 'Let u = ln x; ∫du/u = ln|ln x| + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(x ln x).', '["ln","ln x","+ C","1/ln x + C","ln x + C","1/x + C"]', 'Integral = <u>ln|ln x| + C</u>.', '{"bold":[],"italic":[],"underline":["ln|ln x| + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czommdr1zb24i8m34hpiphq6s', 'Chemistry', 'JAMB', null, 1989, null, 'Gunpowder is made from charcoal, sulphur and potassium trioxonitrate(V). The salt in the mixture performs the function of', null, '["an oxidant","a reductant","a solvent","a catalyst"]', 0, 'KNO3 is the oxidizing agent (oxidant) in gunpowder.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Gunpowder is made from charcoal, sulphur and potassium trioxonitrate(V). The salt in the mixture performs the function of', '["an oxidant","a reductant","a solvent","a catalyst"]', '<u>KNO3 is the oxidant</u> in gunpowder.', '{"bold":[],"italic":[],"underline":["an oxidant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czomq41tqtvsyx803lbolu22a', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following group of physical properties increases from left to right of the periodic table?<br>1 Ionization energy<br>2 Atomic radius<br>3 Electronegativity<br>4 Electron affinity', null, '["1 and 2","1, 2 and 3","3 and 4","1, 2 and 4","1, 3 and 4"]', 4, 'Ionization energy, electronegativity, and electron affinity increase across a period.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following group of physical properties increases from left to right of the periodic table?<br>1 Ionization energy<br>2 Atomic radius<br>3 Electronegativity<br>4 Electron affinity', '["1 and 2","1, 2 and 3","3 and 4","1, 2 and 4","1, 3 and 4"]', '<u>1, 3 and 4</u> increase across a period.', '{"bold":[],"italic":[],"underline":["1, 3 and 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czorxh5fa0wasc2psnyminkay', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'A condition a Christian must fulfill before becoming a joint heir with Christ is', null, '["having faith in Christ","being born again","being anointed","being baptized"]', 0, 'Having faith in Christ makes one a joint heir.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A condition a Christian must fulfill before becoming a joint heir with Christ is', '["<u>having faith in Christ</u>","being born again","being anointed","being baptized"]', '<u>Having faith in Christ</u>.', '{"bold":[],"italic":[],"underline":["having faith in Christ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czov9ulv1owi4wvdgolbywqe9', 'Biology', 'JAMB', null, 2000, null, 'Peripheral arrangement of vascular tissues in dicots is a characteristic of the internal structure of the', null, '["leaf","petiole","stem","root"]', 2, 'Peripheral vascular arrangement is in the stem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peripheral arrangement of vascular tissues in dicots is a characteristic of the internal structure of the', '["leaf","petiole","stem","root"]', '<u>Stem</u> has peripheral vascular arrangement.', '{"bold":[],"italic":[],"underline":["stem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czoysz8pqvp9rxn40vlbd0oqs', 'Chemistry', 'JAMB', null, 1984, null, 'If the ONLY pollutants found in the atmosphere over a city are oxides of nitrogen, suspended lead compounds, carbon monoxide and high level of methane, the probable source(s) of the pollution must be', null, '["automobile exhaust and biological decomposition","combustion of coal and automobile exhaust","biological decomposition only","combustion of coal, automobile exhaust and biological decomposition","combustion of coal and biological decomposition"]', 0, 'NOx and Pb are from automobile exhaust; CH4 is from biological decomposition.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the ONLY pollutants found in the atmosphere over a city are oxides of nitrogen, suspended lead compounds, carbon monoxide and high level of methane, the probable source(s) of the pollution must be', '["automobile exhaust and biological decomposition","combustion of coal and automobile exhaust","biological decomposition only","combustion of coal, automobile exhaust and biological decomposition","combustion of coal and biological decomposition"]', '<u>Automobile exhaust and biological decomposition</u>.', '{"bold":[],"italic":[],"underline":["automobile exhaust and biological decomposition"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czp7ym8971h1bqgu8hca4iz3t', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin A + sin B = 1/2 and cos A + cos B = √3/2, find cos(A + B).', null, '["1/2","√3/2","-1/2","-√3/2"]', 1, '(2sin((A+B)/2)cos((A-B)/2))² + (2cos((A+B)/2)cos((A-B)/2))² = 1 → 4cos²((A-B)/2) = 1 → A-B = 2π/3; solving gives cos(A+B) = √3/2. Key says √3/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin A + sin B = 1/2 and cos A + cos B = √3/2, find cos(A + B).', '["1/2","√3/2","-1/2","-√3/2"]', 'cos(A + B) = <u>√3/2</u> (per key).', '{"bold":[],"italic":[],"underline":["√3/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czpa1kkryg1qcp76j3eccdtd8', 'Chemistry', 'JAMB', null, 1998, null, 'What mass of gold is deposited during the electrolysis of gold(III) tetraoxosulphate(VI) when a current of 15A is passed for 193 seconds? [Au=197, F=96500 C mol⁻¹]', null, '["1.97g","3.94g","5.91g","19.70g"]', 1, 'Q = 15 × 193 = 2895C; moles e⁻ = 0.03; moles Au = 0.01; mass = 1.97g. Key says 3.94.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What mass of gold is deposited during the electrolysis of gold(III) tetraoxosulphate(VI) when a current of 15A is passed for 193 seconds? [Au=197, F=96500 C mol⁻¹]', '["1.97g","3.94g","5.91g","19.70g"]', 'Mass = 0.01 × 197 = <u>1.97g</u> (key says 3.94).', '{"bold":[],"italic":[],"underline":["3.94g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czpbc33563v812i3208ch8exv', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'If a husband divorces his wife before the consummation of the marriage, it is considered', null, '["revocable","irrevocable","redeemable","abominable."]', 1, 'It is irrevocable.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a husband divorces his wife before the consummation of the marriage, it is considered', '["revocable","<u>irrevocable</u>","redeemable","abominable."]', '<u>Irrevocable</u>.', '{"bold":[],"italic":[],"underline":["irrevocable"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czpnyjzt3ynun714byl1gq3bb', 'Chemistry', 'JAMB', null, 1992, null, 'The pollutants that are likely to be present in an industrial environment are', null, '["H2S, SO2 and oxides of nitrogen","NH3, HCl and CO","CO2, NH3 and H2S","Dust, NO and Cl2"]', 0, 'Industrial pollution commonly includes H2S, SO2, and NOx.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pollutants that are likely to be present in an industrial environment are', '["H2S, SO2 and oxides of nitrogen","NH3, HCl and CO","CO2, NH3 and H2S","Dust, NO and Cl2"]', '<u>H2S, SO2, and NOx</u> are common industrial pollutants.', '{"bold":[],"italic":[],"underline":["H2S, SO2 and oxides of nitrogen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czpttz9d7z6991qg298hwr726', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The Jewish religious leaders arrested and imprisoned the apostles the second time because', null, '["the high priest and the Sadducees were jealous.","they disobeyed the law.","the high priest and the Sadducees accused them of treason.","they performed miracles in the name of Jesus."]', 0, 'The high priest and Sadducees were jealous.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Jewish religious leaders arrested and imprisoned the apostles the second time because', '["<u>the high priest and the Sadducees were jealous.</u>","they disobeyed the law.","the high priest and the Sadducees accused them of treason.","they performed miracles in the name of Jesus."]', '<u>The high priest and the Sadducees were jealous</u> (Acts 5:17).', '{"bold":[],"italic":[],"underline":["the high priest and the Sadducees were jealous."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czpyukycybb3cwr4nhbhr8mcb', 'General Mathematics', 'WAEC', null, 2020, null, 'Find d/dx(tan⁻¹((1-x)/(1+x))).', null, '["1/(1+x²)","-1/(1+x²)","-2/(1+x²)","2/(1+x²)"]', 1, 'tan⁻¹((1-x)/(1+x)) = π/4 - tan⁻¹x, so the derivative is -1/(1+x²).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find d/dx(tan⁻¹((1-x)/(1+x))).', '["1/(1+x²)","-1/(1+x²)","-2/(1+x²)","2/(1+x²)"]', 'tan⁻¹((1-x)/(1+x)) = π/4 - tan⁻¹x, so the derivative is -1/(1+x²).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czq31lpgwgvlcs8q9p8e90roc', 'General Mathematics', 'WAEC', null, 2020, null, 'If the 6th term of an AP is 11 and the sum of the first n terms is (n/4)(3n - 1), find the value of n for which the sum of the first n terms equals the nth term.', null, '["7","9","11","13"]', 1, 'Tₙ = (3n-1)/2; Sₙ = (n/4)(3n-1); equating gives n = 5. Key says 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the 6th term of an AP is 11 and the sum of the first n terms is (n/4)(3n - 1), find the value of n for which the sum of the first n terms equals the nth term.', '["7","9","11","13"]', 'n = <u>9</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czq86j5192ug922ya4y3uqzjc', 'General Mathematics', 'WAEC', null, 2020, null, 'A variable point P(x, y) moves so that its distance from the point A(2, 3) is twice its distance from the point B(-1, 0). Find the equation of its locus.', null, '["3x² + 3y² - 12x - 6y = 0","3x² + 3y² - 12x - 6y + 12 = 0","x² + y² - 4x - 2y + 4 = 0","x² + y² - 4x - 2y = 0"]', 0, '(x-2)² + (y-3)² = 4[(x+1)² + y²]; simplifying gives 3x² + 3y² - 12x - 6y = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A variable point P(x, y) moves so that its distance from the point A(2, 3) is twice its distance from the point B(-1, 0). Find the equation of its locus.', '["3x² + 3y² - 12x - 6y = 0","3x² + 3y² - 12x - 6y + 12 = 0","x² + y² - 4x - 2y + 4 = 0","x² + y² - 4x - 2y = 0"]', 'Locus: <u>3x² + 3y² - 12x - 6y = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czqd2nxu9wps4y00hvqjveoet', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''The Lord opened her heart to give heed to what was said by Paul.'' The person who gave heed to the words of Paul was', null, '["Sapphira","Priscilla","Dorcas","Lydia."]', 3, 'Lydia gave heed to Paul''s words.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''The Lord opened her heart to give heed to what was said by Paul.'' The person who gave heed to the words of Paul was', '["Sapphira","Priscilla","Dorcas","<u>Lydia.</u>"]', '<u>Lydia</u> (Acts 16:14).', '{"bold":[],"italic":[],"underline":["Lydia."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czqdj658n34x7sf4w75snavm4', 'English Language', 'JAMB', null, 2020, null, 'Ayo: who is there? Tunde: it is _____.', null, '["me","I","myself","him"]', 0, 'Conversational "It is me" (formal: "It is I").', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ayo: who is there? Tunde: it is _____.', '["me","I","myself","him"]', 'Conversational: <u>It is me</u>.', '{"bold":[],"italic":[],"underline":["me"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czqi2vgy55mkp8h381ugvsjw1', 'Chemistry', 'JAMB', null, 1992, null, 'Which of these statements is <b>TRUE</b> about carbon(IV) oxide?', null, '["It supports combustion","It is strong acidic in water","It is very soluble in water","It supports the burning of magnesium to produce magnesium oxide"]', 3, 'Mg burns in CO2 to form MgO and C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these statements is <b>TRUE</b> about carbon(IV) oxide?', '["It supports combustion","It is strong acidic in water","It is very soluble in water","It supports the burning of magnesium to produce magnesium oxide"]', '<u>Mg burns in CO2</u> to form MgO.', '{"bold":["TRUE"],"italic":[],"underline":["It supports the burning of magnesium to produce magnesium oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czqkbrtj9f9tjz2ifuffc0jn9', 'Government', 'JAMB', null, 2020, null, 'The immediate cause of the January 15 1966 military coup in Nigeria was the', null, '["crisis over the population census.","election crisis in the Western Region","Kano Riots","Tiv Riots"]', 1, 'The Western Region election crisis was the immediate cause.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The immediate cause of the January 15 1966 military coup in Nigeria was the', '["crisis over the population census.","<u>election crisis in the Western Region</u>","Kano Riots","Tiv Riots"]', '<u>Election crisis in the Western Region</u>.', '{"bold":[],"italic":[],"underline":["election crisis in the Western Region"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czqqdiim6jet479o9h5vz1ftk', 'Government', 'JAMB', null, 2020, null, 'The African leader mostly credited for spearheading the formation of the African Union is', null, '["Muammar Ghaddafi","Abdelaziz Bouteflika","Abdoulaye Wade","Thabo Mbeki."]', 0, 'Ghaddafi spearheaded AU formation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The African leader mostly credited for spearheading the formation of the African Union is', '["<u>Muammar Ghaddafi</u>","Abdelaziz Bouteflika","Abdoulaye Wade","Thabo Mbeki."]', '<u>Muammar Ghaddafi</u>.', '{"bold":[],"italic":[],"underline":["Muammar Ghaddafi"],"fillBlanks":[]}');
