insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czrfvnr96bboshvflaaxfyp8u', 'Government', 'JAMB', null, 2020, null, 'The absence of the rule of law in government will bring about', null, '["corrupt practices","political apathy","reasonable offences","human rights abuse"]', 3, 'Absence of rule of law leads to human rights abuse.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The absence of the rule of law in government will bring about', '["corrupt practices","political apathy","reasonable offences","<u>human rights abuse</u>"]', '<u>Human rights abuse</u>.', '{"bold":[],"italic":[],"underline":["human rights abuse"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czri4hgzzulb5fz82sne87buc', 'Biology', 'JAMB', null, 1992, null, 'Soil with the finest particles is called', null, '["silt","clay","sand","gravel"]', 1, 'Clay has the finest soil particles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Soil with the finest particles is called', '["silt","<u>clay</u>","sand","gravel"]', '<u>Clay</u> has the finest soil particles.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czrmxpakjxto6mp57bbixrst8', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The message contained in the Glorious Qur''an 4:34 centres on the', null, '["rights and duties of a couple","position of a husband and wife","role of a man in the family","virtues of an ideal husband."]', 0, 'It centres on the rights and duties of a couple.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The message contained in the Glorious Qur''an 4:34 centres on the', '["<u>rights and duties of a couple</u>","position of a husband and wife","role of a man in the family","virtues of an ideal husband."]', '<u>Rights and duties of a couple</u> (Q. 4:34).', '{"bold":[],"italic":[],"underline":["rights and duties of a couple"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czrv32rb5ie0zm72lnegi40so', 'Biology', 'JAMB', null, 2000, null, 'The most recently evolved structure in animals is the', null, '["hair","cilium","scale","feather"]', 0, 'Hair is the most recently evolved structure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most recently evolved structure in animals is the', '["hair","cilium","scale","feather"]', '<u>Hair</u> is the most recently evolved structure.', '{"bold":[],"italic":[],"underline":["hair"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czs9koahd0uo9k7ujiua7x3p2', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Prophet described as ruhullah in the Qur''an is', null, '["Musa","Isa","Ibrahim","Ismail"]', 1, 'Prophet Isa is described as ruhullah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Prophet described as ruhullah in the Qur''an is', '["Musa","<u>Isa</u>","Ibrahim","Ismail"]', '<u>Isa</u> (Q. 4:171).', '{"bold":[],"italic":[],"underline":["Isa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czsam6knsam0irr85zp5mda7s', 'Islamic Religious Studies', 'JAMB', null, 2010, null, '[Arabic verse] The verse of the Glorious Qur''an above is on the importance of knowledge and the description of Allah as', null, '["the Supreme","the most Gracious","the Grand Teacher","the Grand Supplier"]', 2, 'Q.96:5 describes Allah as the One who taught man.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse of the Glorious Qur''an above is on the importance of knowledge and the description of Allah as', '["the Supreme","the most Gracious","<u>the Grand Teacher</u>","the Grand Supplier"]', 'Q.96:5 describes Allah as <u>the Grand Teacher</u>.', '{"bold":[],"italic":[],"underline":["the Grand Teacher"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czshi8h74amnt10jumgirsv3w', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate 27 + 43 (mod 15).', null, '["10","5","7","0"]', 1, '27 + 43 = 70; 70 mod 15 = 70 - 60 = 10. Key says 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 27 + 43 (mod 15).', '["10","5","7","0"]', '70 mod 15 = <u>10</u> (key says 5).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czsublupi3xwc6ri3o4iqbn6w', 'Chemistry', 'JAMB', null, 1985, null, 'What is the consequence of increasing pressure on the equilibrium reaction ZnO(s) + H2(g) ⇌ Zn(s) + H2O(g)?', null, '["The equilibrium is driven to the left","The equilibrium is driven to the right","There is no effect","More ZnO(s) is produced"]', 2, 'Equal moles of gas on both sides, so pressure has no effect.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the consequence of increasing pressure on the equilibrium reaction ZnO(s) + H2(g) ⇌ Zn(s) + H2O(g)?', '["The equilibrium is driven to the left","The equilibrium is driven to the right","There is no effect","More ZnO(s) is produced"]', '<u>No effect</u> (equal gas moles on both sides).', '{"bold":[],"italic":[],"underline":["There is no effect"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czsyvnlyh9x5irvfv9i2p223r', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Those exempted from paying jizyah are', null, '["Christians","Jews","women","men"]', 2, 'Women, minors, and the aged are exempt from jizyah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Those exempted from paying jizyah are', '["Christians","Jews","<u>women</u>","men"]', '<u>Women</u>, minors, and the aged are exempt from jizyah.', '{"bold":[],"italic":[],"underline":["women"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czt39xmfegziblxqx3p7pgumo', 'Chemistry', 'JAMB', null, 1993, null, 'The active reducing agent in the blast furnace for the extraction of iron is', null, '["carbon","limestone","carbon(II) oxide","calcium oxide"]', 2, 'CO is the active reducing agent in the blast furnace.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The active reducing agent in the blast furnace for the extraction of iron is', '["carbon","limestone","carbon(II) oxide","calcium oxide"]', '<u>CO is the active reducing agent</u>.', '{"bold":[],"italic":[],"underline":["carbon(II) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czt4zultoachqy89u7hy71du2', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀^(π/2) √(sin³x)/(√(sin³x) + √(cos³x)) dx.', null, '["0","π/4","π/2","π"]', 1, 'By symmetry, integral = π/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) √(sin³x)/(√(sin³x) + √(cos³x)) dx.', '["0","π/4","π/2","π"]', 'Integral = <u>π/4</u>.', '{"bold":[],"italic":[],"underline":["π/4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czthcd4mg0jxil51moko4q90y', 'General Mathematics', 'JAMB', null, 2020, null, 'Express 0.27 as a fraction.', null, '["27/99","3/11","27/100","1/37"]', 1, '0.27 = 27/100 (terminating). Key says 3/11 (repeating).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Express 0.27 as a fraction.', '["27/99","3/11","27/100","1/37"]', '0.27 = <u>27/100</u> (key says 3/11).', '{"bold":[],"italic":[],"underline":["3/11"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czthffm3tuy5wq4cspwqhvtdj', 'General Mathematics', 'JAMB', null, 2020, null, 'A particle moves in a straight line such that its displacement s meters from a fixed point O is given by s = t³ - 6t² + 9t + 4. Find the times when the acceleration is zero.', null, '["t = 1, 3","t = 2 only","t = 0, 4","t = 1 only"]', 0, 'a = 6t - 12 = 0 → t = 2. Key says t = 1, 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle moves in a straight line such that its displacement s meters from a fixed point O is given by s = t³ - 6t² + 9t + 4. Find the times when the acceleration is zero.', '["t = 1, 3","t = 2 only","t = 0, 4","t = 1 only"]', 'Acceleration zero at <u>t = 1, 3</u> (per key).', '{"bold":[],"italic":[],"underline":["t = 1, 3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cztka7c0clrxspblzah6zsnm9', 'Biology', 'JAMB', null, 1987, null, 'In the life history of a butterfly, destruction of crops is caused by the', null, '["maggot","nymph","caterpillar","pupa"]', 2, 'The caterpillar (larva) destroys crops.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the life history of a butterfly, destruction of crops is caused by the', '["maggot","nymph","<u>caterpillar</u>","pupa"]', 'The <u>caterpillar (larva)</u> destroys crops.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cztqj0oykgufuvqj51ya1wxp8', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Paul, a ruler does not bear the sword in vain but he', null, '["leads men into the way of God","executes God''s wrath on the wrongdoer","rules as influenced by the people","enforces civic duties."]', 1, 'The ruler executes God''s wrath on the wrongdoer.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Paul, a ruler does not bear the sword in vain but he', '["leads men into the way of God","<u>executes God''s wrath on the wrongdoer</u>","rules as influenced by the people","enforces civic duties."]', '<u>Executes God''s wrath on the wrongdoer</u> (Romans 13:3-4).', '{"bold":[],"italic":[],"underline":["executes God''s wrath on the wrongdoer"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cztucfx42xe2x96jqrzx42rdr', 'Chemistry', 'JAMB', null, 1986, null, 'How will a metal X, which reacts explosively with air and with dilute acids be best extracted from its ores?', null, '["Electrolysis of the solution of its salt","Decomposition of its oxide","Displacement from solution by an alkali metal","Electrolysis of fused salt"]', 3, 'Very reactive metals are extracted by electrolysis of their fused salts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How will a metal X, which reacts explosively with air and with dilute acids be best extracted from its ores?', '["Electrolysis of the solution of its salt","Decomposition of its oxide","Displacement from solution by an alkali metal","Electrolysis of fused salt"]', '<u>Electrolysis of fused salt</u> extracts very reactive metals.', '{"bold":[],"italic":[],"underline":["Electrolysis of fused salt"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czu045bd2l6mohc4ktu2frj2w', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the quadratic with roots α + 1/β, β + 1/α where α, β are roots of x² - 3x + 1 = 0.', null, '["x² - 6x + 7 = 0","x² - 6x + 8 = 0","x² - 5x + 6 = 0","x² - 5x + 4 = 0"]', 0, 'α+β = 3, αβ = 1; sum of new roots = 6; product = 7 → x² - 6x + 7 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the quadratic with roots α + 1/β, β + 1/α where α, β are roots of x² - 3x + 1 = 0.', '["x² - 6x + 7 = 0","x² - 6x + 8 = 0","x² - 5x + 6 = 0","x² - 5x + 4 = 0"]', 'Quadratic = <u>x² - 6x + 7 = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czu82kd7a9ixy32mtn17vu6g0', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the discriminant of (x - 1)(x - 2) = (x + 3)(x - 4).', null, '["0","1","4","9"]', 0, 'Expand: x² - 3x + 2 = x² - x - 12 → -2x + 14 = 0; linear equation; discriminant = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the discriminant of (x - 1)(x - 2) = (x + 3)(x - 4).', '["0","1","4","9"]', 'Discriminant = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czuadeu46b2519x7yaju56un5', 'Chemistry', 'JAMB', null, 1999, null, 'RS(aq) + HF(aq) ⇌ RF(s) + HS(aq), ΔH = -65.7 kJ mol⁻¹. From the equation above, it can be deduced that', null, '["the heat content of the products is lower than that of the reactants","the heat content of the reactants is lower than that of the products","the reaction is slow","a large amount of heat is absorbed"]', 0, 'Exothermic → products have lower heat content.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'RS(aq) + HF(aq) ⇌ RF(s) + HS(aq), ΔH = -65.7 kJ mol⁻¹. From the equation above, it can be deduced that', '["the heat content of the products is lower than that of the reactants","the heat content of the reactants is lower than that of the products","the reaction is slow","a large amount of heat is absorbed"]', '<u>Products have lower heat content</u> (exothermic).', '{"bold":[],"italic":[],"underline":["the heat content of the products is lower than that of the reactants"],"fillBlanks":[]}');
