insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czue42kumetq92ol0h7lyg7mn', 'Biology', 'JAMB', null, 1990, null, 'A certain savanna grasshopper changes colour from green during the rainy season to brown during the dry season bush fires. The reason for these colour changes is that the', null, '["grasshopper is getting older","environment temperature is changing","grasshopper is avoiding predation","grasshopper is frequently moulting"]', 2, 'Colour change helps the grasshopper avoid predation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A certain savanna grasshopper changes colour from green during the rainy season to brown during the dry season bush fires. The reason for these colour changes is that the', '["grasshopper is getting older","environment temperature is changing","<u>grasshopper is avoiding predation</u>","grasshopper is frequently moulting"]', '<u>Colour change helps the grasshopper avoid predation</u>.', null);
