insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czz0c1o7p7wigs9nk7mw6yth4', 'Biology', 'JAMB', null, 2002, null, 'A feature of the caste systems of bees and termites is that', null, '["the workers are sterile","the kings are bigger than the queens","only the workers perform duties","nuptial flight is performed by all members"]', 0, 'Workers are sterile in bee and termite colonies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A feature of the caste systems of bees and termites is that', '["the workers are sterile","the kings are bigger than the queens","only the workers perform duties","nuptial flight is performed by all members"]', '<u>Workers are sterile</u>.', '{"bold":[],"italic":[],"underline":["the workers are sterile"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czz76kcud3ldpixilpqe4lvtw', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify (0.3 × 0.03) / 0.003.', null, '["3","0.3","30","300"]', 0, '(0.3 × 0.03) / 0.003 = 0.009/0.003 = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify (0.3 × 0.03) / 0.003.', '["3","0.3","30","300"]', '(0.3 × 0.03) / 0.003 = <u>3</u>.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('czzbif1n52cdnoodclxwwiil1', 'Chemistry', 'JAMB', null, 1994, null, 'SO3 is NOT directly dissolved in water in the preparation of H2SO4 by the contact process because', null, '["the reaction between SO3 and water is violently exothermic","acid is usually added to water and never water to acid","SO3 is an acid not dissolve in water readily","SO3 is an acid gas"]', 0, 'SO3 + H2O is violently exothermic, forming mist.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'SO3 is NOT directly dissolved in water in the preparation of H2SO4 by the contact process because', '["the reaction between SO3 and water is violently exothermic","acid is usually added to water and never water to acid","SO3 is an acid not dissolve in water readily","SO3 is an acid gas"]', '<u>The reaction is violently exothermic</u>.', '{"bold":[],"italic":[],"underline":["the reaction between SO3 and water is violently exothermic"],"fillBlanks":[]}');
