insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d2c0978b-c83a-40fb-8840-694f6559c0ac', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The chairman was accused for <u>implemented</u> policies that favored the elite.', null, '["oppressed","executed","jobless","citizen"]', 0, 'Implemented = executed; opposite = oppressed (garbled).', true, '2026-10-24 07:21:27.664', '2026-10-24 07:21:27.664', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The chairman was accused for <u>implemented</u> policies that favored the elite.', '["oppressed","executed","jobless","citizen"]', 'Implemented = executed; opposite = oppressed (garbled).', '{}');
