insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d2de57c5-0e5a-41bb-b73d-c8ab5f72f6db', 'Physics', 'JAMB', null, 1999, null, 'When the temperature of a liquid is increased, its surface tension', null, '["Decreases","Increases","Remains constant","Increases then decreases."]', 0, 'Surface tension decreases as the temperature rises, because the cohesive forces between molecules weaken.', true, '2026-10-12 19:15:47.554', '2026-10-12 19:15:47.554', null, null, null, 'When the temperature of a liquid is increased, its surface tension', '["Decreases","Increases","Remains constant","Increases then decreases."]', 'Surface tension decreases as the temperature rises, because the cohesive forces between molecules weaken.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d2e335b9-f137-4801-8eb9-d2ced81803ae', 'Literature in English', 'JAMB', null, 2026, null, 'In the poem, the sea mainly serves as', null, '["a place of entertainment","a witness to human history and suffering","a symbol of wealth","a source of political power"]', 1, 'The sea serves as a witness to human history and suffering.', true, '2026-09-12 11:12:17.765', '2026-09-12 11:12:17.765', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d2e372d9-9053-4a05-8e9d-e62e5d66089e', 'General Mathematics', 'JAMB', null, 2026, null, 'Simplify: (1½ ÷ ¾) × ¾', null, '["1","1/3","2","3/4"]', 2, '(3/2 ÷ 3/4) × 3/4 = (3/2 × 4/3) × 3/4 = 2 × 3/4 = 3/2 = 1.5. Not in options.', true, '2026-09-12 11:44:11.175', '2026-09-12 11:44:11.175', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d2ee11d0-d008-4b92-9080-543c5abb0c41', 'Chemistry', 'JAMB', null, 2026, null, 'In which of the following will the reaction be fastest (I) concentrated acid (II) dilute acid (III) marble chip (IV) powdered marble', null, '["I, III","I, IV","II, III","II, IV"]', 1, 'Concentrated acid and powdered marble give the fastest reaction.', true, '2026-09-12 11:36:07.796', '2026-09-12 11:36:07.796', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d2f63023-695a-4272-867d-86d5abb29d64', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to James, effective prayer is that which is offered', null, '["loudly","silently","in faith","with emotion"]', 2, 'The prayer of faith will save the sick (James 5:15).', true, '2026-09-12 10:41:22.717', '2026-09-12 10:41:22.717', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d2f9f2b0-8af1-465b-8b1e-f53420f4f0e6', 'English Language', 'JAMB', null, 2024, null, 'Employees demand higher _3_, better overtime pay so as to improve the standard of living.', null, '["money","cash","wages","incentives"]', 2, 'Employees demand higher wages (pay for work done).', true, '2026-09-18 09:23:08.087', '2026-09-18 09:23:08.087', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d3019ca9-b79f-41e5-8201-3c1fbcf5e55d', 'General Mathematics', 'JAMB', null, 2026, null, 'If it is given that 5^(x+1) + 5^x = 150, then the value of x is equal to', null, '["3","4","1","2","1/2"]', 3, '5^(x+1) + 5^x = 5·5^x + 5^x = 6·5^x = 150. So 5^x = 25 = 5². Therefore x = 2.', true, '2026-09-10 10:48:18.65', '2026-09-10 10:48:18.65', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d301e16d-0993-49ef-bdac-9d3c1f8c5cd6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Everyone was talking about the <u>camaraderie</u> in the club.', null, '["companionship","quarrelsome","commissioning","disunity"]', 0, 'Camaraderie = companionship.', true, '2026-10-24 01:01:56.335', '2026-10-24 01:01:56.335', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Everyone was talking about the <u>camaraderie</u> in the club.', '["<u>companionship</u>","quarrelsome","commissioning","disunity"]', '<b>Camaraderie</b> = <b>companionship</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d3126cac-65cf-4711-a54b-74dca04493f7', 'Biology', 'JAMB', null, 2026, null, 'Soil with the finest particles is called', null, '["silt","gravel","sand","clay"]', 3, 'Clay has the finest particles among soil types. Soil particle sizes in descending order: gravel (largest) > sand > silt > clay (smallest). Clay particles are less than 0.002 mm in diameter and have a large surface area relative to their volume, giving them unique properties including high water-holding capacity, high cation exchange capacity, and plasticity when wet. Silt particles are intermediate between sand and clay. The small size of clay particles results in a dense, sticky soil that can hold nutrients well but may have poor drainage.', true, '2026-09-09 03:18:43.088', '2026-09-09 03:18:43.088', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d31e80ad-1c42-4d3d-b62c-e73532864abe', 'Literature in English', 'JAMB', null, 2026, null, 'The title So the Path Does Not Die primarily suggests', null, '["the inevitability of death","the preservation of tradition and legacy","the struggle for political power","the importance of education"]', 1, 'The title suggests the preservation of tradition and legacy.', true, '2026-09-12 11:04:22.199', '2026-09-12 11:04:22.199', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d32758ab-bf7c-4bb2-96d8-17071312b501', 'Government', 'JAMB', null, 2026, null, 'Which constitution established the Public Service Commission?', null, '["The 1963 constitution","The 1979 constitution","The 1999 constitution","The 1989 constitution"]', 1, 'The 1979 constitution established the Public Service Commission.', true, '2026-09-12 11:24:29.334', '2026-09-12 11:24:29.334', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d32eb243-b5c1-497b-830b-910b5e168c91', 'Financial Accounting', 'UTME', null, 2003, null, 'Receipt and payment account is the summary of', null, '["income and expenditure","cash book","balance sheet","supplementary warrant"]', 1, 'Receipt and payment account is the summary of the cash book.', true, '2026-10-12 22:00:01.016', '2026-10-12 22:00:01.016', null, null, null, 'Receipt and payment account is the summary of', '["income and expenditure","<b>cash book</b>","balance sheet","supplementary warrant"]', 'Receipt and payment account is the summary of the <b>cash book</b>.', '{"bold":["cash book"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d33262e3-5cbb-47ed-872a-eaa4e5a08e8e', 'Chemistry', 'JAMB', null, 2026, null, 'The element, fluorine differs from the other halogens due to? I) small size ii) very high electronegativity iii) nonavailability of d-orbitals iv) large size', null, '["I, ii and iv only","ii, iii and iv only","I, ii and iii only","ii only"]', 2, 'Fluorine differs due to small size, high electronegativity, and no d-orbitals.', true, '2026-09-12 11:36:16.233', '2026-09-12 11:36:16.233', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d334bc75-0207-4d27-ae8f-966fd3cceaad', 'Physics', 'JAMB', null, 2026, null, 'A stone and a feather are dropped from the same height above the earth surface. Ignoring air resistance, which of the following is correct?', null, '["the feather will be blown away by the wind while stone will drop steadily","the stone and the feather will both reach the ground at the same time","the feather will reach the ground first","the stone will reach the ground first"]', 1, 'Ignoring air resistance, both the stone and the feather will reach the ground at the same time. In a vacuum, all objects fall with the same acceleration due to gravity (g), regardless of their mass.', true, '2026-09-10 10:56:49.215', '2026-09-10 10:56:49.215', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d33dff5a-6688-4e52-8f9b-8728bb0afbef', 'Literature in English', 'JAMB', null, 2026, null, 'The dominant tone of the poem is', null, '["nostalgic and reflective","angry and violent","humorous and playful","satirical and mocking"]', 0, 'The dominant tone is nostalgic and reflective.', true, '2026-09-12 11:10:14.257', '2026-09-12 11:10:14.257', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d3415ae0-b7b4-4a4f-af53-08fdb3f8c456', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Any student found guilty of examination malpractice should be allowed to <u>stew in his own juice</u>.', null, '["taste a repeat of the examination","suffer the consequences of his action","bear the brunt of the disgrace","forfeit the opportunity of further education"]', 1, '''Stew in his own juice'' = suffer consequences of actions.', true, '2026-10-24 01:04:21.85', '2026-10-24 01:04:21.85', null, null, null, '(Choose the most appropriate interpretation). Any student found guilty of examination malpractice should be allowed to <u>stew in his own juice</u>.', '["taste a repeat of the examination","<u>suffer the consequences of his action</u>","bear the brunt of the disgrace","forfeit the opportunity of further education"]', '''<b>Stew in his own juice</b>'' = <b>suffer consequences of actions</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d35c82e6-cbb2-4645-9110-b6b78d83f8cd', 'English Language', 'JAMB', null, 2007, null, 'We are <u>__________</u> to receive your letter and to know that you are <u>__________</u>', null, '["happy/in good health","grateful/sound","pleased/all well","appreciative/swimming in good health"]', 2, 'Correct forms: pleased/all well.', true, '2026-10-24 07:21:43.263', '2026-10-24 07:21:43.263', null, null, null, 'We are <u>__________</u> to receive your letter and to know that you are <u>__________</u>', '["happy/in good health","grateful/sound","pleased/all well","appreciative/swimming in good health"]', 'Correct forms: pleased/all well.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d3641a48-1477-47d4-8c49-ae2e033bb38e', 'Biology', 'JAMB', null, 2004, null, 'The surface of an alveolus in a mammal is well supplied with tiny blood vessels known as', null, '["arterioles","venules","arteries","capillaries"]', 3, 'Alveoli are surrounded by capillaries.', true, '2026-10-12 20:59:34.913', '2026-10-12 20:59:34.913', null, null, null, 'The surface of an alveolus in a mammal is well supplied with tiny blood vessels known as', '["arterioles","venules","arteries","capillaries"]', 'Alveoli are surrounded by capillaries.', '{"bold":["capillaries"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d366e1e6-7812-4e37-b57a-e4b5a6ee5aaa', 'Biology', 'JAMB', null, 2026, null, 'A surprising fact about sickle cell is that', null, '["affects only black people","kills the patient","is hereditary","affects blood cells","weakens the patient"]', 3, 'A surprising fact about sickle cell is that it affects blood cells (red blood cells). Sickle cell disease causes red blood cells to become sickle-shaped, affecting their ability to carry oxygen and their lifespan. While sickle cell primarily affects people of African descent, it is not restricted to black people. The trait is hereditary. The disease can be fatal, but not all patients die from it. It weakens the patient, but the most surprising aspect is the effect on red blood cell shape.', true, '2026-09-09 03:19:14.984', '2026-09-09 03:19:14.984', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d36d4a61-33ad-45a4-83c0-3840ba6c66d2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The government is making <u>concerted</u> efforts at providing essential social facilities in the rural areas.', null, '["dissipated","unconcerned","unsuccessful","uncontrolled"]', 0, 'Concerted = combined; opposite = dissipated.', true, '2026-10-24 07:21:12.904', '2026-10-24 07:21:12.904', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The government is making <u>concerted</u> efforts at providing essential social facilities in the rural areas.', '["dissipated","unconcerned","unsuccessful","uncontrolled"]', 'Concerted = combined; opposite = dissipated.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d36f19ba-d09a-4525-8b3b-75e91d6e298f', 'English Language', 'JAMB', null, 2007, null, 'Adamu is one of the<u>______</u> who always <u>_____</u>hard.', null, '["men/works","men/work","man/works","man/work"]', 1, '''Who'' â†’ men (plural) â†’ work.', true, '2026-10-24 01:02:16.851', '2026-10-24 01:02:16.851', null, null, null, 'Adamu is one of the<u>______</u> who always <u>_____</u>hard.', '["men/works","<u>men/work</u>","man/works","man/work"]', '''<b>Who</b>'' â†’ <b>men</b> (plural) â†’ <b>work</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d373cfa4-9ca6-4bf6-89cf-4ebeb9b4c49e', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Before announcing his retirement, Ochima resolved to <u>settle on account</u> with the bank.', null, '["pay back all he owes","close his account with","retire his loans from","get back at"]', 0, '''Settle on account'' = pay back all owed.', true, '2026-10-24 01:02:09.03', '2026-10-24 01:02:09.03', null, null, null, '(Choose the most appropriate interpretation). Before announcing his retirement, Ochima resolved to <u>settle on account</u> with the bank.', '["<u>pay back all he owes</u>","close his account with","retire his loans from","get back at"]', '''<b>Settle on account</b>'' = <b>pay back all owed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d3764946-88fc-4ddd-a8fb-9a9d71ce5a86', 'Biology', 'JAMB', null, 2012, null, 'A function of hydrochloric acid produced in the human stomach during digestion is to', null, '["neutralize the effect of bile","coagulate milk protein and emulsify fats","stop the action of ptyalin","break up food into smaller particles."]', 2, 'Hydrochloric acid stops the action of ptyalin.', true, '2026-10-12 20:59:44.741', '2026-10-12 20:59:44.741', null, null, null, 'A function of hydrochloric acid produced in the human stomach during digestion is to', '["neutralize the effect of bile","coagulate milk protein and emulsify fats","stop the action of ptyalin","break up food into smaller particles."]', 'Hydrochloric acid stops the action of ptyalin.', '{"bold":["stops the action of ptyalin"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d37900f2-d677-40e9-b850-9900f6561ad9', 'Physics', 'JAMB', null, 1991, null, 'In a ray diagram for a thin converging lens, a ray that is not parallel to the optic axis but passes through the optic centre will', null, '["Pass through undeviated","Pass through the centre of curvature after refraction","Emerge parallel to the principal axis","Pass through the principal focus after refraction."]', 0, 'A ray through the optical centre of a thin lens passes through without deviation.', true, '2026-10-12 19:15:33.676', '2026-10-12 19:15:33.676', null, null, null, 'In a ray diagram for a thin converging lens, a ray that is not parallel to the optic axis but passes through the optic centre will', '["Pass through undeviated","Pass through the centre of curvature after refraction","Emerge parallel to the principal axis","Pass through the principal focus after refraction."]', 'A ray through the optical centre of a thin lens passes through without deviation.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d37e25db-c473-4a87-a498-2a37f0872100', 'Physics', 'JAMB', null, 2004, null, 'A moving-coil galvanometer has a full-scale deflection of 3 A equivalent to 30° deflection. The sensitivity of the instrument is', null, '["10.0","33.0","90.0","0.1"]', 0, 'Sensitivity = deflection per unit current = 30/3 = 10.0 degrees per ampere.', true, '2026-10-12 19:15:59.034', '2026-10-12 19:15:59.034', null, null, null, 'A moving-coil galvanometer has a full-scale deflection of 3 A equivalent to 30° deflection. The sensitivity of the instrument is', '["10.0","33.0","90.0","0.1"]', 'Sensitivity = deflection per unit current = 30/3 = 10.0 degrees per ampere.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d3835426-353a-415d-a236-cf456754ad4b', 'Chemistry', 'JAMB', null, 2026, null, 'Which factor would not affect the rate of a homogeneous reaction in solution?', null, '["Temperature","Concentration","Catalyst","Colour of the solution"]', 3, 'The colour of the solution does not affect the rate of a homogeneous reaction in solution. Temperature, concentration, and catalyst all significantly affect reaction rates. Colour is a physical property that does not influence reaction kinetics.', true, '2026-09-12 09:38:14.737', '2026-09-12 09:38:14.737', null, null, null, null, null, null, null);
