insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d38abc35-5a1d-4a7f-8955-7ea726d908c7', 'Government', 'JAMB', null, 2026, null, 'The West African Student''s Union (WASU) was formed in', null, '["1925","1924","1922","1923"]', 0, 'The West African Student''s Union (WASU) was formed in 1925. WASU was founded in London by West African students studying in Britain. It became a platform for nationalist agitation and Pan-Africanism. The organization campaigned against colonial rule, racial discrimination, and for the independence of West African countries. It provided training and inspiration for many future nationalist leaders.', true, '2026-09-10 10:44:18.507', '2026-09-10 10:44:18.507', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d38e1b52-e5a5-4016-a83b-21e6839c911c', 'Economics', 'JAMB', null, 2026, null, 'A ______ in the price of the domestic currency in terms of a foreign currency is referred to as ______', null, '["Increase, depreciation","Decrease, appreciation","Increase, devaluation","Decrease, depreciation"]', 3, 'A decrease in the price of domestic currency in terms of foreign currency is depreciation.', true, '2026-09-12 11:02:04.87', '2026-09-12 11:02:04.87', null, null, null, null, null, null, null);
