insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d3a92089-b2fb-44b3-af33-0ac222d4ecf8', 'Financial Accounting', 'UTME', null, 2001, null, 'Department F transferred some goods to department G at a selling price. The goods were not sold at the end of the accounting period. Which account is affected at the time of preparing a combined balance sheet?', null, '["Creditors","Debtors","Stock","Suspense."]', 2, 'Stock is affected at the time of preparing a combined balance sheet.', true, '2026-10-12 22:00:07.707', '2026-10-12 22:00:07.707', null, null, null, 'Department F transferred some goods to department G at a selling price. The goods were not sold at the end of the accounting period. Which account is affected at the time of preparing a combined balance sheet?', '["Creditors","Debtors","<b>Stock</b>","Suspense."]', '<b>Stock</b> is affected at the time of preparing a combined balance sheet.', '{"bold":["Stock"],"italic":[],"underline":[],"fillBlanks":[]}');
