insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d3c31e75-c848-474d-a84a-134f52283d10', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following changes will decrease the solubility of potassium nitrate in water?', null, '["Increasing temperature","Decreasing temperature","Stirring","Increasing pressure"]', 1, 'Dissolution of potassium nitrate is endothermic; lowering the temperature reduces its solubility in water.', true, '2026-09-09 17:12:49.519', '2026-09-09 17:12:49.519', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d3d60445-0957-49b3-b8b6-49821c1f4ec5', 'Physics', 'JAMB', null, 1993, null, 'Radio waves emitted from an antenna are picked up by a radar after reflection from an aircraft in 4 x 10⁻³ s. How far is the aircraft from the antenna? [c = 3 x 10⁸ m s⁻¹]', null, '["6.0 x 10² km","1.2 x 10³ km","3.0 x 10³ km","6.0 x 10⁵ km"]', 0, 'The waves travel to the aircraft and back, so d = ct/2 = (3 x 10⁸ x 4 x 10⁻³)/2 = 6 x 10⁵ m = 6.0 x 10² km.', true, '2026-10-12 19:15:37.756', '2026-10-12 19:15:37.756', null, null, null, 'Radio waves emitted from an antenna are picked up by a radar after reflection from an aircraft in 4 x 10<sup>-3</sup> s. How far is the aircraft from the antenna? [c = 3 x 10<sup>8</sup> m s<sup>-1</sup>]', '["6.0 x 10<sup>2</sup> km","1.2 x 10<sup>3</sup> km","3.0 x 10<sup>3</sup> km","6.0 x 10<sup>5</sup> km"]', 'The waves travel to the aircraft and back, so d = ct/2 = (3 x 10<sup>8</sup> x 4 x 10<sup>-3</sup>)/2 = 6 x 10<sup>5</sup> m = 6.0 x 10<sup>2</sup> km.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
