insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d3f663ac-e62f-420f-9617-d025c0e0b08f', 'Literature in English', 'JAMB', null, 2026, null, 'The ''path'' in the title functions symbolically as', null, '["a literal road connecting villages","a spiritual journey with no cultural ties","continuity of cultural ties","a political movement for independence"]', 2, 'The path symbolizes the continuity of cultural ties.', true, '2026-09-12 11:04:24.534', '2026-09-12 11:04:24.534', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4236a46-01ab-4a28-9d0d-aa5cac80756c', 'Literature in English', 'JAMB', null, 2026, null, 'The dominant theme of the poem ''Hearty Garlands'' is', null, '["birthday celebration","generational conflict","loneliness in old age","political struggle"]', 0, 'The dominant theme of the poem ''Hearty Garlands'' is birthday celebration. The poem celebrates the life and achievements of an individual, likely on their birthday or a similar milestone occasion. It expresses joy and appreciation. Generational conflict, loneliness, and political struggle are not the central themes of this celebratory poem.', true, '2026-09-10 10:47:54.266', '2026-09-10 10:47:54.266', null, null, null, null, null, null, null);
