insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4388d46-2d64-4b4a-8e7a-4929f898483c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. They have tried to <u>circumvent</u> the restriction on the importation of the commodities.', null, '["bypass","confront","oppose","challenge"]', 0, 'Circumvent = bypass.', true, '2026-10-24 01:04:01.406', '2026-10-24 01:04:01.406', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. They have tried to <u>circumvent</u> the restriction on the importation of the commodities.', '["<u>bypass</u>","confront","oppose","challenge"]', '<b>Circumvent</b> = <b>bypass</b>.', '{}');
