insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d445ed09-74af-4901-8819-506403f1d300', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The Sons of Eli were worthless because they...', null, '["Stole offering from the Lord’s house","Treated the Lord’s offering with Contempt","Seized the Lord’s offering from the temple","Took bribes and perverted justice"]', 1, 'In 1 Samuel 2:12-17, Hophni and Phinehas are described as worthless men because they treated the offering of the Lord with contempt by taking meat before it was offered properly.', true, '2026-09-09 17:18:23.725', '2026-09-09 17:18:23.725', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d44641e4-d851-4e15-a804-d6e5cdbebe02', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man outran his wife when they heard the <u>eerie</u> sound.', null, '["hissing","harsh","scary","loud"]', 2, 'Eerie = scary.', true, '2026-10-24 01:01:51.664', '2026-10-24 01:01:51.664', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man outran his wife when they heard the <u>eerie</u> sound.', '["hissing","harsh","<u>scary</u>","loud"]', '<b>Eerie</b> = <b>scary</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d447517a-ea9b-4963-b684-68d6b22259a0', 'Financial Accounting', 'UTME', null, 2003, null, 'The company consumed raw materials worth', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841364/questions/nosxrvm114y656byywjh.jpg', '["N54 600","N56 000","N57 400","N59 500"]', 0, 'Opening stock of raw material 3500 + Purchases 56000 = 59,500. Less Closing Stock of R.M. 4,900 = 54,600.', true, '2026-10-12 22:00:00.569', '2026-10-12 22:00:00.569', null, null, null, 'The company consumed raw materials worth', '["<b>N54 600</b>","N56 000","N57 400","N59 500"]', 'Opening stock of raw material 3500 + Purchases 56000 = 59,500. Less Closing Stock of R.M. 4,900 = <b>54,600</b>.', '{"bold":["54,600"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d45adc74-4473-467c-a87a-03660021b399', 'Financial Accounting', 'UTME', null, 2003, null, 'Four broad classifications of overheads are', null, '["production selling and material","production, selling, distribution and administration","selling, distribution, production and wages","selling, distribution, administration and material"]', 1, 'The four broad classifications of overheads are production, selling, distribution and administration.', true, '2026-10-12 22:00:00.421', '2026-10-12 22:00:00.421', null, null, null, 'Four broad classifications of overheads are', '["production selling and material","<b>production, selling, distribution and administration</b>","selling, distribution, production and wages","selling, distribution, administration and material"]', 'The four broad classifications of overheads are <b>production, selling, distribution and administration</b>.', '{"bold":["production, selling, distribution and administration"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d45bca55-738c-4e46-9e61-1eb7f997dff8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tade became <u>timorous</u> when she was asked to give the valedictory speech.', null, '["excited","aggressive","nervous","happy"]', 2, 'Timorous = nervous/fearful.', true, '2026-10-24 01:04:02.656', '2026-10-24 01:04:02.656', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tade became <u>timorous</u> when she was asked to give the valedictory speech.', '["excited","aggressive","<u>nervous</u>","happy"]', '<b>Timorous</b> = <b>nervous</b>/fearful.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d45deee2-387f-4514-8013-7255b0a45a47', 'Biology', 'JAMB', null, 2026, null, 'The two halves of the pelvic girdle are joined together at the', null, '["ileum","pubis","obturator foramen","pubic symphysis"]', 3, 'The two halves of the pelvic girdle are joined together at the pubic symphysis, a cartilaginous joint that allows slight movement and provides support during weight-bearing activities. The pubis is one of the three bones of each pelvic half (ilium, ischium, pubis). The ileum is part of the small intestine. The obturator foramen is a large hole in each pelvic bone. The pubic symphysis is strengthened by ligaments and is particularly important during pregnancy and childbirth, where it allows the pelvis to expand.', true, '2026-09-09 03:18:53.027', '2026-09-09 03:18:53.027', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d460324f-eaae-4248-923b-0ef2c8ef0cdb', 'English Language', 'JAMB', null, 2007, null, 'Defects like <u>--------------</u> in government''s development plans <u>--------</u> for extra vigilance.', null, '["this/calls","these/calls","this/call","these/call"]', 3, 'Plural ''defects'' â†’ these/call.', true, '2026-10-24 01:02:13.911', '2026-10-24 01:02:13.911', null, null, null, 'Defects like <u>--------------</u> in government''s development plans <u>--------</u> for extra vigilance.', '["this/calls","these/calls","this/call","<u>these/call</u>"]', 'Plural ''<b>defects</b>'' â†’ <b>these/call</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4641f9d-c387-4c37-a92c-35c8b97c27f3', 'Biology', 'JAMB', null, 2026, null, 'During blood transfusion, agglutination may occur when', null, '["contrasting antigens reacts with contrasting antibodies","similar antigens react with similar antibody","two different antigens react with each other","two different antibodies react with each other"]', 0, 'Agglutination occurs when contrasting antigens react with contrasting antibodies (antigen-antibody reaction). For example, if a person with blood group A (who has A antigens and anti-B antibodies) receives blood from a person with blood group B (who has B antigens), the anti-B antibodies in the recipient will bind to the B antigens, causing clumping. This is why blood type matching is critical for safe transfusions.', true, '2026-09-09 03:19:19.066', '2026-09-09 03:19:19.066', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d467d00d-584e-4a4e-8a56-e62a96ed76e4', 'Yoruba', 'JAMB', null, 2002, null, 'Atûnkò fûn Adé na Olù nípa lílo òrõ-aròpò-orúkò dípò Olù ní', null, '["Adé nà á","Adé nà án","Adé nà-án","Adé nà-á."]', 1, 'Atûnkò fûn Adé na Olù ni Adé nà án.', true, '2026-10-13 13:22:38.797', '2026-10-13 13:22:38.797', null, null, null, 'Atûnkò fûn Adé na Olù nípa lílo òrõ-aròpò-orúkò dípò Olù ní', '["Adé nà á","Adé nà án","Adé nà-án","Adé nà-á."]', 'Atûnkò fûn Adé na Olù ni Adé nà án.', '{"bold":["Adé nà án"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d46c77ae-2c3d-4f6c-a878-4e739eff9837', 'Economics', 'JAMB', null, 2026, null, 'Which of the following best describes a tabular arrangement of various prices of a commodity and the corresponding quantities purchased at a given time?', null, '["Demand curve","Demand schedule","Demand line","Market demand","Law of demand"]', 1, 'A demand schedule is a tabular arrangement showing various prices of a commodity and the corresponding quantities purchased at a given time. It is a table that lists the quantity demanded at each price. When this data is plotted on a graph, it forms the demand curve. The law of demand states that quantity demanded varies inversely with price.', true, '2026-09-10 10:41:20.937', '2026-09-10 10:41:20.937', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d47e445f-ed3b-412c-825b-3a89933b4091', 'Yoruba', 'JAMB', null, 2002, null, 'Didi òbç ìfarì mó òkù lòwò sínù sàrèè tòka sí òkù', null, '["ìjàngbòn","awò","ríró","òrìyà"]', 2, 'Didi òbç ìfarì mó òkù lòwò sínù sàrèè tòka sí òkù ríró.', true, '2026-10-13 13:22:40.382', '2026-10-13 13:22:40.382', null, null, null, 'Didi òbç ìfarì mó òkù lòwò sínù sàrèè tòka sí òkù', '["ìjàngbòn","awò","ríró","òrìyà"]', 'Didi òbç ìfarì mó òkù lòwò sínù sàrèè tòka sí òkù ríró.', '{"bold":["ríró"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d489ac21-3a44-497c-949a-eff740e11d1e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Because our representative is immature and biased, he takes a <u>jaundiced</u> view of our problems.', null, '["hazy","unclear","prejudiced","bleak"]', 2, 'Jaundiced = prejudiced.', true, '2026-10-24 01:01:46.108', '2026-10-24 01:01:46.108', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Because our representative is immature and biased, he takes a <u>jaundiced</u> view of our problems.', '["hazy","unclear","<u>prejudiced</u>","bleak"]', '<b>Jaundiced</b> = <b>prejudiced</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d48d2867-a0ed-4b6f-a35b-56f4c2723d5d', 'Chemistry', 'JAMB', null, 2026, null, '0.79g of gas at stp occupied a volume of 250cm3. What is the relative molecular mass of the gas? (GMV=22.4dm3)', null, '["17","32","64","71"]', 3, '250 cm3 = 0.25 dm3. Moles = 0.25 / 22.4 = 0.01116 mol. Molar mass = mass / moles = 0.79 / 0.01116 ≈ 70.8 g/mol (approx 71).', true, '2026-09-09 17:12:46.344', '2026-09-09 17:12:46.344', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4a59263-9fb6-4a83-b6f2-7b1fac8d569f', 'Government', 'JAMB', null, 2026, null, 'The African Union is unable to perform its role on the global political scene very well due to the', null, '["inadequate system of education","low level of wages in the member countries","Outbreak of Pandemic on the African Continent","divided loyalty among member states"]', 3, 'Divided loyalty among member states hinders the AU''s global role.', true, '2026-09-12 11:24:17.023', '2026-09-12 11:24:17.023', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4a69fba-2e85-452f-8152-1ff9e14a3b4b', 'Financial Accounting', 'UTME', null, 2002, null, 'What is the closing cash balance?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791840936/questions/tiktz9oouf6ppnsmxzib.jpg', '["N 11500","N 12000","N 13000","N 13500"]', 0, 'The closing cash balance is N11500.', true, '2026-10-12 21:59:57.858', '2026-10-12 21:59:57.858', null, null, null, 'What is the closing cash balance?', '["<b>N 11500</b>","N 12000","N 13000","N 13500"]', 'The closing cash balance is <b>N11500</b>.', '{"bold":["N11500"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4bcb460-5355-4bdc-83a2-5ee15a6d59aa', 'English Language', 'JAMB', null, 2007, null, 'The sergeant spoke to me in a <u>__________</u> manner.', null, '["coarse","casual","coerce","course"]', 0, 'Correct spelling: coarse.', true, '2026-10-24 07:21:35.718', '2026-10-24 07:21:35.718', null, null, null, 'The sergeant spoke to me in a <u>__________</u> manner.', '["coarse","casual","coerce","course"]', 'Correct spelling: coarse.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4cc1148-9007-4af0-b7b7-33659e83b7f3', 'Government', 'JAMB', null, 2026, null, 'The Organization of Petroleum Exporting Countries came into existence at a conference held in', null, '["Tripoli","Caracas","Riyadh","Baghdad"]', 3, 'OPEC was founded at a conference in Baghdad.', true, '2026-09-12 11:24:47.662', '2026-09-12 11:24:47.662', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4d2627b-ec35-477c-b311-e7ecf517f1ed', 'English Language', 'JAMB', null, 2007, null, 'No teacher of honour would subject his student to any form of <u>__________</u>', null, '["harassement","harasment","harrasment","harassment"]', 3, 'Correct spelling: harassment.', true, '2026-10-24 07:21:35.969', '2026-10-24 07:21:35.969', null, null, null, 'No teacher of honour would subject his student to any form of <u>__________</u>', '["harassement","harasment","harrasment","harassment"]', 'Correct spelling: harassment.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4d5558d-6d9b-4022-ad8e-e5496e78012e', 'Government', 'JAMB', null, 2026, null, 'A tactic employed by pressure groups to achieve their objectives is', null, '["memorandum","electioneering campaign","propaganda","lobbying"]', 3, 'A tactic employed by pressure groups to achieve their objectives is lobbying. Lobbying involves attempting to influence legislators and government officials to make decisions favorable to the group''s interests. Pressure groups use various tactics including lobbying, strikes, demonstrations, petitions, and publicity campaigns. Electioneering campaigns are used by political parties, not pressure groups. Propaganda can be used but lobbying is the most direct and common tactic.', true, '2026-09-10 10:44:17.6', '2026-09-10 10:44:17.6', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4d57d92-cf6b-4db9-bbb2-af2c785c8ea1', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The family discussed the crisis and resolved to <u>nail the lie to the counter</u>.', null, '["expose it publicly","bury it...","defer action on it","seek more advice"]', 0, '''Nail a lie to the counter'' = expose publicly.', true, '2026-10-24 01:04:22.598', '2026-10-24 01:04:22.598', null, null, null, '(Choose the most appropriate interpretation). The family discussed the crisis and resolved to <u>nail the lie to the counter</u>.', '["<u>expose it publicly</u>","bury it...","defer action on it","seek more advice"]', '''<b>Nail a lie to the counter</b>'' = <b>expose publicly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4d980fa-7150-4c51-937d-a77753c1b2f3', 'Economics', 'JAMB', null, 2026, null, 'A feature of money that says it must not be perishable is', null, '["Durability","General acceptability","Divisibility","Stability"]', 0, 'Durability means money must not be perishable.', true, '2026-09-12 11:01:10.603', '2026-09-12 11:01:10.603', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4dba5af-041c-4687-b749-d8d4f71b9e32', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The last <u>criticism</u> at the rally was made in ignorance.', null, '["unimpeachable","objection","impeccable","uniformed"]', 3, 'Garbled source; closest = uniformed (uninformed).', true, '2026-10-24 01:01:56.86', '2026-10-24 01:01:56.86', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The last <u>criticism</u> at the rally was made in ignorance.', '["unimpeachable","objection","impeccable","<u>uniformed</u>"]', '<b>Garbled source</b>; closest = <b>uniformed</b> (uninformed).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4ea4994-8f24-4645-8a85-fdb6cbcddcfb', 'Biology', 'JAMB', null, 2026, null, 'The activity of ptyalin is likely to decrease with an increase in the concentration of', null, '["oxygen","starch","protein","acid"]', 3, 'Ptyalin (salivary amylase) activity decreases with an increase in acid concentration (lower pH). Ptyalin works optimally at a neutral to slightly alkaline pH (around pH 6.8-7.0). In the acidic environment of the stomach (pH 1.5-3.5), ptyalin is denatured and becomes inactive. Oxygen does not directly affect ptyalin activity. Starch is the substrate, not an inhibitor. Protein is not directly involved with amylase activity. The inactivation of ptyalin in the stomach is important because carbohydrate digestion is completed by pancreatic amylase in the alkaline environment of the duodenum.', true, '2026-09-09 03:18:41.537', '2026-09-09 03:18:41.537', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4ece721-1c19-4361-b514-4baa0c57ff39', 'General Mathematics', 'JAMB', null, 2026, null, 'The solution of the simultaneous equations 3x + 5y = 4 and 4x + 3y = 5 is', null, '["-13/11, 1/11","13/11, 1/11","13/11, -1/11","11/13, 1/11","13, 11"]', 1, '3x+5y=4 ...(1). 4x+3y=5 ...(2). Multiply (1) by 3: 9x+15y=12. Multiply (2) by 5: 20x+15y=25. Subtract: 11x=13, x=13/11. Substitute into (1): 3(13/11)+5y=4. 39/11+5y=4. 5y = 4 - 39/11 = (44-39)/11 = 5/11. y = 1/11.', true, '2026-09-10 10:48:19.736', '2026-09-10 10:48:19.736', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4ed2111-6161-4b3e-b3fd-f4672a187043', 'Literature in English', 'JAMB', null, 2026, null, '''The aroma of roasted corn filled the evening air'' appeals to', null, '["Gustatory imagery","Olfactory imagery","Tactile imagery","Visual imagery"]', 1, 'It appeals to olfactory imagery.', true, '2026-09-12 11:14:17.929', '2026-09-12 11:14:17.929', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4f26c17-d748-4b7b-912f-fd96d04e7d9a', 'Yoruba', 'JAMB', null, 2007, null, 'Dídá àásó çwà sí wòpõ láàrin àwòn', null, '["Òdòkùnrin","Òdòbiýrin","àgbà òkùnrin","àgbà obiýrin"]', 0, 'Dídá àásó çwà sí wòpõ láàrin àwòn Òdòkùnrin.', true, '2026-10-13 13:23:32.612', '2026-10-13 13:23:32.612', null, null, null, 'Dídá àásó çwà sí wòpõ láàrin àwòn', '["Òdòkùnrin","Òdòbiýrin","àgbà òkùnrin","àgbà obiýrin"]', 'Dídá àásó çwà sí wòpõ láàrin àwòn Òdòkùnrin.', '{"bold":["Òdòkùnrin"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4f3bed9-5ffa-4043-abdc-863a59ab8aed', 'Physics', 'JAMB', null, 2003, null, 'Thermal equilibrium between two objects exists when', null, '["The heat capacities of both objects are the same","One object loses heat continuously to the other","The temperatures of both objects are equal","The quantity of heat in both objects is the same."]', 2, 'Two objects are in thermal equilibrium when there is no net heat flow between them, which happens when their temperatures are equal.', true, '2026-10-12 19:15:55.793', '2026-10-12 19:15:55.793', null, null, null, 'Thermal equilibrium between two objects exists when', '["The heat capacities of both objects are the same","One object loses heat continuously to the other","The temperatures of both objects are equal","The quantity of heat in both objects is the same."]', 'Two objects are in thermal equilibrium when there is no net heat flow between them, which happens when their temperatures are equal.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d4fc8148-cbf1-42a1-918d-cda3d0f08033', 'Biology', 'JAMB', null, 2003, null, 'The type of reproduction that lead to variation in animal and plant population is', null, '["budding","sexual","vegetative","asexual"]', 1, 'Sexual reproduction leads to variation.', true, '2026-10-12 20:59:33.897', '2026-10-12 20:59:33.897', null, null, null, 'The type of reproduction that lead to variation in animal and plant population is', '["budding","sexual","vegetative","asexual"]', 'Sexual reproduction leads to variation.', '{"bold":["Sexual reproduction"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d501c349-970d-4a78-b036-a8114f923b48', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The town looked deserted but we moved in with some <u>trepidation</u>.', null, '["confidence","surprise","hesitation","fear"]', 3, 'Trepidation = fear.', true, '2026-10-24 01:03:59.478', '2026-10-24 01:03:59.478', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The town looked deserted but we moved in with some <u>trepidation</u>.', '["confidence","surprise","hesitation","<u>fear</u>"]', '<b>Trepidation</b> = <b>fear</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d50237e8-2a26-45f3-b0fd-1750d650fb6b', 'Biology', 'JAMB', null, 2026, null, 'Fruit enlargement can be induced by spraying yellow ovary with', null, '["Cytokinin, abscisic acid and ethylene","Gibberellin, ethylene and abscisic acid","Auxin, abscisic acid and ethylene","Auxin, Cytokinin and Gibberellin"]', 3, 'Fruit enlargement is induced by the plant hormones auxin, cytokinin, and gibberellin. These are growth-promoting hormones that stimulate cell division, cell elongation, and fruit development. Auxin promotes fruit set and growth, cytokinin promotes cell division, and gibberellin promotes cell elongation and fruit enlargement. Abscisic acid inhibits growth and promotes dormancy, while ethylene promotes fruit ripening rather than enlargement. This combination of growth hormones is used in commercial agriculture to produce seedless fruits and increase fruit size.', true, '2026-09-09 03:18:22.115', '2026-09-09 03:18:22.115', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d502df9d-4b7b-40de-b671-14457b245656', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The promise of God with Abraham was that', null, '["he will live long","he would make nations out of him","he would make him return to his father''s house","he would give him flocks"]', 1, 'God promised to make Abraham a great nation.', true, '2026-09-12 10:41:10.213', '2026-09-12 10:41:10.213', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d50698c3-9238-4178-80e7-2aec258211f3', 'Government', 'JAMB', null, 2026, null, 'The first properly so-called political party in Nigeria is', null, '["NNDP","NCNC","NYM","AG"]', 0, 'The first properly so-called political party in Nigeria was the Nigerian National Democratic Party (NNDP), founded in 1923 by Herbert Macaulay. It was the first political party in Nigeria and contested the 1923 elections under the Clifford Constitution. The NCNC was formed in 1944, the NYM in 1934, and the AG in 1951.', true, '2026-09-10 10:45:05.182', '2026-09-10 10:45:05.182', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d513b989-1f76-4305-a423-a3040ddadfad', 'Physics', 'JAMB', null, 2003, null, 'At what position will an object be placed in front of a concave mirror in order to obtain an image at infinity?', null, '["At centre of curvature","Between the principal focus and the centre of curvature","At the pole of the mirror","At the principal focus"]', 3, 'Rays from an object at the principal focus are reflected parallel, so the image forms at infinity.', true, '2026-10-12 19:15:56.296', '2026-10-12 19:15:56.296', null, null, null, 'At what position will an object be placed in front of a concave mirror in order to obtain an image at infinity?', '["At centre of curvature","Between the principal focus and the centre of curvature","At the pole of the mirror","At the principal focus"]', 'Rays from an object at the principal focus are reflected parallel, so the image forms at infinity.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d521e1d7-ab3e-40ca-8ba9-06199ef27d0d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Most of his observations were <u>wide off the mark</u>.', null, '["comprehensible","irrelevant","pertinent","unacceptable"]', 1, '''Wide off the mark'' = irrelevant.', true, '2026-10-24 01:04:18.733', '2026-10-24 01:04:18.733', null, null, null, '(Choose the most appropriate interpretation). Most of his observations were <u>wide off the mark</u>.', '["comprehensible","<u>irrelevant</u>","pertinent","unacceptable"]', '''<b>Wide off the mark</b>'' = <b>irrelevant</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d537f689-4e16-4386-ae5b-5ff1a570cd8c', 'Hausa', 'JAMB', null, 2011, null, 'Labarin kura da akuya da harawa yana cikin nau''in labari na', null, '["tatsuniya","kacici-kacici","ƙissa","almara"]', 3, 'Labarin kura da akuya da harawa yana cikin nau''in labari na almara.', true, '2026-10-13 10:37:21.992', '2026-10-13 10:37:21.992', null, null, null, 'Labarin kura da akuya da harawa yana cikin nau''in labari na', '["tatsuniya","kacici-kacici","ƙissa","almara"]', 'Labarin kura da akuya da harawa yana cikin nau''in labari na almara.', '{"bold":["almara"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d53848ba-649e-4e88-bf0b-3a0208b132ef', 'Economics', 'JAMB', null, 2026, null, 'The basic aim of Economic Community of West African States is the', null, '["discouragement of trade among member states","encouragement of revolts against former colonial masters","establishment of its headquarters in each members state","liberalization of trade among member states"]', 3, 'ECOWAS aims to liberalize trade among member states.', true, '2026-09-12 11:01:00.488', '2026-09-12 11:01:00.488', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d543dd92-d09d-4f91-bba2-71431ad744fd', 'Physics', 'JAMB', null, 1998, null, 'In photoelectric effect, electrons will leave the metal surface when illuminated by light of appropriate frequency if the photon energy is', null, '["Greater than the work function.","Less than the work function","Equal to the work function","Equal to the maximum kinetic energy of the electrons."]', 0, 'Electrons are emitted with some kinetic energy when the photon energy exceeds the work function. At equality the electrons are only just freed.', true, '2026-10-12 19:15:46.912', '2026-10-12 19:15:46.912', null, null, null, 'In photoelectric effect, electrons will leave the metal surface when illuminated by light of appropriate frequency if the photon energy is', '["Greater than the work function.","Less than the work function","Equal to the work function","Equal to the maximum kinetic energy of the electrons."]', 'Electrons are emitted with some kinetic energy when the photon energy exceeds the work function. At equality the electrons are only just freed.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d54cd71c-0765-4b06-872b-7056c185ebe4', 'English Language', 'JAMB', null, 2007, null, 'Attention has shifted to the teaching of science nowadays <u>__________</u> the usefulness of the Arts.', null, '["in spite of","not minding","oblivious to","forgetting"]', 0, 'Correct form: in spite of.', true, '2026-10-24 07:21:42.307', '2026-10-24 07:21:42.307', null, null, null, 'Attention has shifted to the teaching of science nowadays <u>__________</u> the usefulness of the Arts.', '["in spite of","not minding","oblivious to","forgetting"]', 'Correct form: in spite of.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d54e7319-cb66-4a60-820d-26d3a39c2015', 'Financial Accounting', 'UTME', null, 2004, null, 'The journal entries for the purchase of stock on credit are to debit', null, '["stock account and credit cash account","stock account and credit liability account","purchase account and credit liability account","suspense account and cash account"]', 2, 'The journal entries for the purchase of stock on credit are to debit purchase account and credit liability account.', true, '2026-10-12 22:00:01.705', '2026-10-12 22:00:01.705', null, null, null, 'The journal entries for the purchase of stock on credit are to debit', '["stock account and credit cash account","stock account and credit liability account","<b>purchase account and credit liability account</b>","suspense account and cash account"]', 'The journal entries for the purchase of stock on credit are to debit <b>purchase account and credit liability account</b>.', '{"bold":["purchase account and credit liability account"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d556a903-f16a-42ea-bc24-0318db61299f', 'Literature in English', 'JAMB', null, 2026, null, 'Sludge in the extract means', null, '["Water","Fire","Snow","Mud"]', 3, 'Sludge means mud.', true, '2026-09-12 11:07:28.477', '2026-09-12 11:07:28.477', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d55b0464-3465-459b-803a-5369eb7aef37', 'General Mathematics', 'JAMB', null, 2026, null, 'In how many different ways can the letters of the word football be arranged such that all vowels are always together?', null, '["3360 ways","1080 ways","2800 ways","560 ways"]', 1, 'FOOTBALL has 8 letters: F,O,O,T,B,A,L,L. Vowels: O,O,A (3). Treat as one unit: 6 units. Arrangements = 6!/(2!) × 3!/(2!) = 360 × 3 = 1080.', true, '2026-09-12 11:43:57.472', '2026-09-12 11:43:57.472', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d55e2919-1e1c-46a1-9a33-9d3ca67bda36', 'Government', 'JAMB', null, 2026, null, 'The pre-colonial political system regarded as fragmented was', null, '["Yoruba","Hausa/Fulani","Tiv","Igbo"]', 3, 'The pre-colonial Igbo political system is regarded as fragmented. The Igbo people were organized into autonomous village communities and village groups with no centralized political authority. Decisions were made through councils of elders and assemblies. This is in contrast to the centralized systems of the Hausa/Fulani (emirates) and Yoruba (kingdoms). The Tiv also had a decentralized system, but the Igbo are the classic example of a fragmented political system.', true, '2026-09-10 10:45:06.143', '2026-09-10 10:45:06.143', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d56afd94-391e-49e3-8930-1592792b4147', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is true of the children of a haemophilic man who marries a woman that is not haemophilic and does not carry the trait?', null, '["all their daughters will be haemophilic","all their daughters will be carriers","all their sons will be haemophilic","all their sons will be carriers"]', 1, 'Haemophilia is an X-linked recessive disorder. The father has the genotype X^h Y (affected). The mother is normal and not a carrier, so she has the genotype X^H X^H. Daughters inherit their father''s X chromosome (X^h) and one X chromosome from their mother (X^H), resulting in X^H X^h - they are carriers. Sons inherit the Y chromosome from their father and an X chromosome from their mother (X^H), resulting in X^H Y - they are normal, not carriers. None of the children will be haemophilic.', true, '2026-09-09 03:18:17.612', '2026-09-09 03:18:17.612', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d56c48d0-0c8b-4cb3-bf2c-4f0dc4688a28', 'Literature in English', 'JAMB', null, 2026, null, 'Where does this conversation take place?', null, '["Rome, Egypt","Alexandria, Egypt","Athens, Rome","on the high sea"]', 1, 'The conversation takes place in Alexandria, Egypt.', true, '2026-09-12 11:14:07.793', '2026-09-12 11:14:07.793', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5721802-23f7-4dfc-b394-87473c4dbe75', 'Government', 'JAMB', null, 2026, null, 'Sheu Shagari won the 1979 Presidential Election under', null, '["UPN","NPN","NPP","GNPP"]', 1, 'Shehu Shagari won the 1979 election under NPN.', true, '2026-09-12 11:24:13.714', '2026-09-12 11:24:13.714', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d57232fd-6163-4981-9255-4813f3bae05c', 'English Language', 'JAMB', null, 2007, null, 'Either Ekaete or you <u>---</u> to go.', null, '["was","are","has","is"]', 1, '''Eitherâ€¦or'' agrees with nearer ''you'' â†’ are.', true, '2026-10-24 01:04:27.727', '2026-10-24 01:04:27.727', null, null, null, 'Either Ekaete or you <u>---</u> to go.', '["was","<u>are</u>","has","is"]', '''<b>Eitherâ€¦or</b>'' agrees with nearer ''<b>you</b>'' â†’ <b>are</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d57507b2-5b34-40f9-8136-dee3724706ae', 'Biology', 'JAMB', null, 2005, null, 'An evidence of a common ancestry for fishes, amphibians, reptiles, birds and mammals is the', null, '["possession of wings by birds and bats","cold-bloodedness of fishes amphibians and reptiles","presence of gill clefts in vertebrate embryos","possession of scales by fishes and reptiles"]', 2, 'Gill clefts in vertebrate embryos provide evidence of common ancestry.', true, '2026-10-12 20:59:38.489', '2026-10-12 20:59:38.489', null, null, null, 'An evidence of a common ancestry for fishes, amphibians, reptiles, birds and mammals is the', '["possession of wings by birds and bats","cold-bloodedness of fishes amphibians and reptiles","presence of gill clefts in vertebrate embryos","possession of scales by fishes and reptiles"]', 'Gill clefts in vertebrate embryos provide evidence of common ancestry.', '{"bold":["Gill clefts in vertebrate embryos"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5783ac1-ec3e-4575-acfc-0854d66008a9', 'Government', 'JAMB', null, 2026, null, 'The 1976 Local Government reforms in Nigeria gave birth to a', null, '["Five-tier local government system","Four-tier local government system","One-tier local government system","Two-tier local government system"]', 2, 'The 1976 reforms gave birth to a one-tier local government system.', true, '2026-09-12 11:24:27.46', '2026-09-12 11:24:27.46', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d58c43cf-3156-4568-bed5-2040138e54c6', 'Physics', 'JAMB', null, 2004, null, 'In a tuned radio receiver R, L, C series circuit at resonance, the inductive and capacitive reactances XL and XC respectively are related as', null, '["XL = 1/XC","XL = 1/(XC²)","XL = XC","XL = 2XC"]', 2, 'At resonance the inductive and capacitive reactances are equal, XL = XC, so they cancel and the impedance is just R.', true, '2026-10-12 19:15:59.088', '2026-10-12 19:15:59.088', null, null, null, 'In a tuned radio receiver R, L, C series circuit at resonance, the inductive and capacitive reactances X<sub>L</sub> and X<sub>C</sub> respectively are related as', '["X<sub>L</sub> = 1/X<sub>C</sub>","X<sub>L</sub> = 1/(X<sub>C</sub><sup>2</sup>)","X<sub>L</sub> = X<sub>C</sub>","X<sub>L</sub> = 2X<sub>C</sub>"]', 'At resonance the inductive and capacitive reactances are equal, X<sub>L</sub> = X<sub>C</sub>, so they cancel and the impedance is just R.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d59711d6-5672-47f9-bce8-b51b57edae36', 'Biology', 'JAMB', null, 2026, null, 'The DNA molecule is a chain of repeating', null, '["nucleoside","nitrogenous base","sugar phosphate","nucleotide"]', 3, 'The DNA molecule is a chain of repeating nucleotides. Each nucleotide consists of three components: a deoxyribose sugar, a phosphate group, and a nitrogenous base (A, T, C, or G). Nucleosides are sugar + base without phosphate. Nitrogenous bases and sugar-phosphate backbones are components of nucleotides. DNA is a polymer of nucleotides linked by phosphodiester bonds between the sugar and phosphate groups.', true, '2026-09-09 03:19:19.286', '2026-09-09 03:19:19.286', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d59e78ab-c632-4929-97b3-e08fe13eade3', 'Literature in English', 'JAMB', null, 2026, null, 'The role of the Storyteller in the play primarily serves to', null, '["Represent colonial authority and control","Provide comic relief without influencing the plot","Bridge the gap between the audience and the dramatic action through commentary and direction","Act as a silent observer of events"]', 2, 'The Storyteller bridges the gap between the audience and the dramatic action.', true, '2026-09-12 11:09:50.137', '2026-09-12 11:09:50.137', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5a5678d-243a-4dcd-b644-95a47bbc4b2a', 'Economics', 'JAMB', null, 2026, null, 'Microeconomics is the study of how individuals and firms behave and how individual markets and industries are organized. True or false', null, '["True","False","Maybe","Uncertain"]', 0, 'True. Microeconomics studies individual economic units and markets.', true, '2026-09-12 11:00:52.298', '2026-09-12 11:00:52.298', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5aa23e9-28e6-454d-92c9-af90215c0142', 'Christian Religious Studies', 'JAMB', null, 2026, null, '“Hear this word, you cows of Bashan... who oppress the poor, who crush the needy...” ''Cows of Bashan'' in this statement refers to the...', null, '["Wicked kings","False prophets","Women of Samaria","Judges in Israel"]', 2, 'Amos 4:1 uses ''cows of Bashan'' to address the wealthy, oppressive women of Samaria who demanded luxury at the expense of the poor.', true, '2026-09-09 17:18:27.821', '2026-09-09 17:18:27.821', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5ab41dd-7057-4b8c-b3b4-aabb962c5428', 'Physics', 'JAMB', null, 1992, null, '²⁷₁₃Al + ¹₀n → ²⁴₁₁Na + X. In the nuclear reaction above, the product denoted by X is', null, '["A proton","A gamma ray","A helium particle","An alpha particle."]', 3, 'Conserving mass number (27 + 1 = 28, so X has 4) and charge (13 + 0 = 11 + 2), X is ⁴₂He, an alpha particle.', true, '2026-10-12 19:15:36.841', '2026-10-12 19:15:36.841', null, null, null, '<sup>27</sup><sub>13</sub>Al + <sup>1</sup><sub>0</sub>n → <sup>24</sup><sub>11</sub>Na + X. In the nuclear reaction above, the product denoted by X is', '["A proton","A gamma ray","A helium particle","An alpha particle."]', 'Conserving mass number (27 + 1 = 28, so X has 4) and charge (13 + 0 = 11 + 2), X is <sup>4</sup><sub>2</sub>He, an alpha particle.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5b08f68-d153-4fad-82f4-f0090877bb02', 'English Language', 'JAMB', null, 2007, null, 'Ours <u>-----------------</u> based venture', null, '["are a resource","is a resource","are resources","is a resourced"]', 1, '''Ours'' singular â†’ is a resource.', true, '2026-10-24 01:04:28.029', '2026-10-24 01:04:28.029', null, null, null, 'Ours <u>-----------------</u> based venture', '["are a resource","<u>is a resource</u>","are resources","is a resourced"]', '''<b>Ours</b>'' singular â†’ <b>is a resource</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5b9935f-b32c-44f2-84d6-b058ec946e12', 'Biology', 'JAMB', null, 2005, null, 'The blackfly is a vector of', null, '["malaria","trypanosomiasis","onchocerciasis","yellow fever"]', 2, 'Blackflies transmit the parasitic worm that causes onchocerciasis (river blindness).', true, '2026-10-12 20:05:11.959', '2026-10-12 20:05:11.959', null, null, null, 'The blackfly is a vector of', '["malaria","trypanosomiasis","onchocerciasis","yellow fever"]', 'Blackflies transmit the parasitic worm that causes onchocerciasis (river blindness).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5b993b4-1942-4dc5-9c1a-957c1e7611ea', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is a major cause of variation among organisms?', null, '["inbreeding","backcrossing","sexual reproduction","gene dominance"]', 2, 'Sexual reproduction is a major cause of variation among organisms. During sexual reproduction, genetic material from two parents is combined, producing offspring with unique combinations of genes. This includes independent assortment, crossing-over during meiosis, and fertilization. Inbreeding and backcrossing reduce genetic variation. Gene dominance determines how traits are expressed but is not a cause of variation.', true, '2026-09-09 03:19:25.427', '2026-09-09 03:19:25.427', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5c739df-3312-496f-9822-633dbde72f8a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Mr. Adeyemo is quite <u>a conceited</u> young man.', null, '["a practical","an unassuming","an experience","a resourceful"]', 1, 'Conceited = proud; opposite = unassuming.', true, '2026-10-24 07:21:28.464', '2026-10-24 07:21:28.464', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Mr. Adeyemo is quite <u>a conceited</u> young man.', '["a practical","an unassuming","an experience","a resourceful"]', 'Conceited = proud; opposite = unassuming.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5d647b5-f931-4527-9f37-790147e45dd6', 'Biology', 'JAMB', null, 2026, null, 'Chewing the cud is an adaptation peculiar to', null, '["Herbivores","Omnivores","Rodents","Ruminants"]', 3, 'Chewing the cud (rumination) is an adaptation peculiar to ruminants, a specific group of herbivores. Ruminants (such as cattle, sheep, goats, deer, giraffes) have a four-chambered stomach that allows them to regurgitate, re-chew, and re-swallow food for more efficient digestion of cellulose. While all ruminants are herbivores, not all herbivores are ruminants. Omnivores do not ruminate. Rodents have a simple stomach and do not chew the cud. Rumination is a specialized adaptation for plant material digestion.', true, '2026-09-09 03:19:05.546', '2026-09-09 03:19:05.546', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5e1c96e-f139-4a93-aab2-048507a1673a', 'Economics', 'JAMB', null, 2026, null, 'The problem of what to produce is determined by', null, '["Consumption pattern","distribution pattern","production pattern","level of technology"]', 0, 'The problem of what to produce is determined by the consumption pattern. In a market economy, consumer sovereignty determines what is produced—producers respond to consumer demand. In a planned economy, the government decides what to produce based on national priorities. The consumption pattern reflects what consumers want and are willing to pay for, guiding producers in their production decisions.', true, '2026-09-10 10:41:59.43', '2026-09-10 10:41:59.43', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5e4acb8-9709-4f2f-b90f-e9aa3a3d0fcd', 'Biology', 'JAMB', null, 2026, null, 'Which of these excretory structures is not found in amphibians?', null, '["lungs","flame cells","gills","skin"]', 1, 'Flame cells (protonephridia) are excretory structures found in flatworms (phylum Platyhelminthes), not in amphibians. Amphibians possess lungs, gills, and skin as respiratory and excretory organs. In amphibians, the kidneys are the primary excretory organs, while the skin is important for both respiration and excretion (cutaneous respiration). Lungs are present in adult amphibians, and gills are present in larvae and some aquatic amphibians. Flame cells have cilia that beat to draw fluid into tubules, a system absent in amphibians.', true, '2026-09-09 03:18:18.774', '2026-09-09 03:18:18.774', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5ef5cf4-0088-43ae-a1a4-7e19a522e048', 'English Language', 'JAMB', null, 2024, null, 'Choose the option that best explains the information conveyed in the sentence: The lecture is Uye''s road to Damascus', null, '["the lecture talks exclusively about Damascus","the lecture is an experience that changes the way she thinks","the lecture is an opportunity to travel to Damascus","the lecture is an experience that cannot be changed"]', 1, '"Road to Damascus" refers to a life-changing experience.', true, '2026-09-18 09:43:02.916', '2026-09-18 09:43:02.916', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5f5a8f1-c284-448d-92c4-056f8a3e0b9a', 'Government', 'JAMB', null, 2026, null, 'The Chairman of the 1976 constitution drafting committee was', null, '["Udo Udoma","Ademola Adetokunbo","Rotimi Williams","Nikki Tobi"]', 2, 'The Chairman of the 1976 constitution drafting committee was Rotimi Williams. Chief Rotimi Williams, a renowned Nigerian lawyer, chaired the Constitution Drafting Committee that drafted the 1979 Constitution. The committee was set up by the military government of General Olusegun Obasanjo to prepare a new constitution for the return to civilian rule. The draft was later debated by a Constituent Assembly.', true, '2026-09-10 10:44:18.88', '2026-09-10 10:44:18.88', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5fe9b00-c81b-4ab0-8edf-fe56d265a29a', 'Biology', 'JAMB', null, 2002, null, 'To select and retain the desirable trait of large body size which a farmer has observed in his herd, the farmer needs to', null, '["feed the animals in the herd with more food","cross-breed his animals with a different herd","inbreed the animals in his herd","prevent diseases in his herd"]', 2, 'Inbreeding helps retain desirable traits in a herd.', true, '2026-10-12 20:59:31.679', '2026-10-12 20:59:31.679', null, null, null, 'To select and retain the desirable trait of large body size which a farmer has observed in his herd, the farmer needs to', '["feed the animals in the herd with more food","cross-breed his animals with a different herd","inbreed the animals in his herd","prevent diseases in his herd"]', 'Inbreeding helps retain desirable traits in a herd.', '{"bold":["Inbreeding"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d5ffc4b6-f6bd-454b-9c8c-70bef09d1619', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What sign did God give Gideon to confirm His call?', null, '["a wet fleece and dry ground","an earthquake","a speaking donkey","fire from a rock"]', 0, 'Gideon asked for a fleece wet with dew while the ground was dry.', true, '2026-09-12 10:40:58.496', '2026-09-12 10:40:58.496', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d60308d8-2a63-4b07-9e6c-cc0c1d5602cf', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''I am the LORD, and there is no other, beside me there is no God.'' God''s statement through Isaiah depicts', null, '["Israel''s acceptance of His Supremacy","assurance to Isaiah of His existence","His sovereignty","His divine nature"]', 2, 'God declares His sovereignty—He alone is God.', true, '2026-09-12 10:41:44.588', '2026-09-12 10:41:44.588', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6104a6e-48a4-4fe8-8eb0-808cb40e360b', 'Biology', 'JAMB', null, 2003, null, 'A feature associated with the Y-chromosome in humans is', null, '["long eyelashes","prominent fingernails","facial hairs","enlarged breast"]', 2, 'Facial hairs are associated with the Y-chromosome.', true, '2026-10-12 20:59:33.846', '2026-10-12 20:59:33.846', null, null, null, 'A feature associated with the Y-chromosome in humans is', '["long eyelashes","prominent fingernails","facial hairs","enlarged breast"]', 'Facial hairs are associated with the Y-chromosome.', '{"bold":["Facial hairs"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d61a4822-df07-4675-ab46-b28a8eb312f5', 'Physics', 'JAMB', null, 1990, null, 'An object which is 3 cm high is placed vertically 10 cm in front of a concave mirror. If this object produces an image 40 cm from the mirror, the height of the image is', null, '["0.75 cm","4.00 cm","8.00 cm","12.00 cm"]', 3, 'Magnification = v/u = 40/10 = 4, so image height = 4 x 3 = 12.00 cm.', true, '2026-10-12 19:15:31.25', '2026-10-12 19:15:31.25', null, null, null, 'An object which is 3 cm high is placed vertically 10 cm in front of a concave mirror. If this object produces an image 40 cm from the mirror, the height of the image is', '["0.75 cm","4.00 cm","8.00 cm","12.00 cm"]', 'Magnification = v/u = 40/10 = 4, so image height = 4 x 3 = 12.00 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d61be93e-63b4-4319-be02-144a1a49a894', 'English Language', 'JAMB', null, 2007, null, 'The development is to be carried to the <u>--------------------</u> level.', null, '["grass root","grass roots","grassroots","grass-root"]', 1, 'Correct form: grass roots.', true, '2026-10-24 07:21:34.808', '2026-10-24 07:21:34.808', null, null, null, 'The development is to be carried to the <u>--------------------</u> level.', '["grass root","grass roots","grassroots","grass-root"]', 'Correct form: grass roots.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d61d57ed-da17-44d5-9cbf-01485dbeeb04', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. They show no <u>finesse</u> in dealing with strangers.', null, '["boldness","kindness","tact","love"]', 2, 'Finesse = tact.', true, '2026-10-24 01:01:47.483', '2026-10-24 01:01:47.483', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. They show no <u>finesse</u> in dealing with strangers.', '["boldness","kindness","<u>tact</u>","love"]', '<b>Finesse</b> = <b>tact</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d623e829-d433-434b-973a-9d3036b52853', 'Physics', 'JAMB', null, 1991, null, 'A thermometer with an arbitrary scale, S, of equal divisions registers -30 °S at the ice point and +90 °S at the steam point. Calculate the Celsius temperature corresponding to 60 °S.', null, '["25.0 °C","50.0 °C","66.7 °C","75.0 °C"]', 3, 'θ = (60 - (-30))/(90 - (-30)) x 100 = 90/120 x 100 = 75.0 °C.', true, '2026-10-12 19:15:33.028', '2026-10-12 19:15:33.028', null, null, null, 'A thermometer with an arbitrary scale, S, of equal divisions registers -30 °S at the ice point and +90 °S at the steam point. Calculate the Celsius temperature corresponding to 60 °S.', '["25.0 °C","50.0 °C","66.7 °C","75.0 °C"]', 'θ = (60 - (-30))/(90 - (-30)) x 100 = 90/120 x 100 = 75.0 °C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6280781-b341-4c5f-8023-5acd703c6baa', 'Biology', 'JAMB', null, 2026, null, 'Fungi are heterotrophic because they', null, '["are filamentous","lack roots","lack chlorophyll","have no leaves"]', 2, 'Fungi are heterotrophic because they lack chlorophyll and cannot photosynthesize their own food. Instead, they obtain nutrients by absorbing organic matter from their environment. Being filamentous, lacking roots, and lacking leaves are all characteristics of fungi but do not explain why they are heterotrophic. The absence of chlorophyll means they cannot produce food from sunlight, water, and CO₂, so they must obtain organic compounds from other sources. Fungi are absorptive heterotrophs, secreting digestive enzymes and absorbing the resulting nutrients.', true, '2026-09-09 03:18:41.979', '2026-09-09 03:18:41.979', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d62c9d16-a640-4807-8f99-79bb72b23eda', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Kunana is <u>like a bear with a sore head</u>', null, '["He is a bully","He is grumpy","He is ugly","He is quiet"]', 1, '''A bear with a sore head'' = grumpy.', true, '2026-10-24 01:02:11.162', '2026-10-24 01:02:11.162', null, null, null, '(Choose the most appropriate interpretation). Kunana is <u>like a bear with a sore head</u>', '["He is a bully","<u>He is grumpy</u>","He is ugly","He is quiet"]', '''A <b>bear with a sore head</b>'' = <b>grumpy</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d633d269-b33f-4409-b8e3-89024189db88', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Saul lost his kingship mainly because he', null, '["disobeyed divine instruction","was rejected by the people","lost battles","was too young"]', 0, 'Saul disobeyed God by not destroying the Amalekites completely.', true, '2026-09-12 10:40:54.261', '2026-09-12 10:40:54.261', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d63b39fe-7f3c-4d0b-875c-31dbbd8dcb4c', 'General Mathematics', 'JAMB', null, 2026, null, 'The angles of a triangle are in the ratio 2:3:5. Find the largest angle.', null, '["72°","90°","100°","108°"]', 1, '2x+3x+5x = 180. x = 18. Largest = 5(18) = 90°.', true, '2026-09-12 11:44:12.266', '2026-09-12 11:44:12.266', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d63ee6c5-34c2-4861-abe5-d0966d313259', 'Government', 'JAMB', null, 2026, null, 'Which of the following African country participated in the signing of the United Nation organization charter 1945?', null, '["Ghana","Zimbabwe","Indian","South Africa"]', 3, 'South Africa participated in the signing of the UN Charter in 1945.', true, '2026-09-12 11:24:38.191', '2026-09-12 11:24:38.191', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d64c7db9-d0fe-4aa4-b8b9-85d7715aa9d1', 'Literature in English', 'JAMB', null, 2026, null, 'In The Marriage of Anansewa, the dramatic technique of Anansegoro is best described as', null, '["A tragic form characterised by the downfall of a noble hero","A traditional storytelling mode blending narration, music, and audience participation","A realist technique focusing strictly on dialogue and stage action","A symbolic method relying solely on abstract characters"]', 1, 'Anansegoro is a traditional storytelling mode blending narration, music, and audience participation.', true, '2026-09-12 11:11:59.59', '2026-09-12 11:11:59.59', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d65249ff-9ead-43bd-b0b7-24eadc2c8da9', 'Physics', 'JAMB', null, 2026, null, 'Which of the following is false about Reaction force?', null, '["a reaction force is the force exerted on an object in response to a force applied to it by another object","it is usually equivalent to the weight(mg) of a body depending on the system and its orientation","It is the resultant force of a body''s weight acting on the ground","usually acts opposite to the direction of the force of action"]', 2, 'The statement that reaction force is the resultant force of a body''s weight acting on the ground is false. Reaction force is a force exerted in response to an action force (Newton''s third law). It is not simply the resultant of weight.', true, '2026-09-10 10:56:45.36', '2026-09-10 10:56:45.36', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d653002b-d511-40e8-ba25-97c4ac7db5fb', 'English Language', 'JAMB', null, 2024, null, 'Identify the option that is nearest in meaning to the underlined word: The doctor told the patient about all the things that could impair his health', null, '["attack","terminate","damage","reduce"]', 2, '"Impair" means to damage or weaken.', true, '2026-09-18 09:43:02.52', '2026-09-18 09:43:02.52', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d653b331-5d5a-4b90-a37b-ad5f1a89b555', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Peter, Christians living among non-Christians should', null, '["maintain good conduct","live like them","be suspicious of them","avoid them"]', 0, 'According to 1 Peter 2:12, Christians should maintain good conduct among non-Christians, so that though they speak against them as wrongdoers, they may see their good deeds and glorify God.', true, '2026-09-12 09:46:04.576', '2026-09-12 09:46:04.576', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6583a8e-2027-465c-acac-6ded78568c07', 'Physics', 'JAMB', null, 1998, null, 'A parachute attains a terminal velocity when', null, '["Its density is equal to the density of air","The viscous force of the air and the upthrust completely counteract its weight.","It expands as a result of reduced external pressure","The viscous force of the air is equal to the sum of the weight and upthrust."]', 1, 'At terminal velocity the net force is zero, so the upward viscous drag plus upthrust balance the weight.', true, '2026-10-12 19:15:45.085', '2026-10-12 19:15:45.085', null, null, null, 'A parachute attains a terminal velocity when', '["Its density is equal to the density of air","The viscous force of the air and the upthrust completely counteract its weight.","It expands as a result of reduced external pressure","The viscous force of the air is equal to the sum of the weight and upthrust."]', 'At terminal velocity the net force is zero, so the upward viscous drag plus upthrust balance the weight.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d67a3de4-79bc-4093-bc06-dbf843be78b6', 'English Language', 'JAMB', null, 2007, null, 'The quality of the goods on display <u>______</u> our attention.', null, '["attract","attracts","are attracting","have attracted"]', 1, 'Singular ''quality'' â†’ attracts.', true, '2026-10-24 01:02:15.979', '2026-10-24 01:02:15.979', null, null, null, 'The quality of the goods on display <u>______</u> our attention.', '["attract","<u>attracts</u>","are attracting","have attracted"]', 'Singular ''<b>quality</b>'' â†’ <b>attracts</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d68117c6-7709-41fc-abe8-03a6433946c4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The awareness of <u>mortality</u> has always imposed some restraint on man''s excesses.', null, '["celestiality","eternity","continuity","inexistence"]', 1, 'Mortality = death; opposite = eternity.', true, '2026-10-24 07:21:15.295', '2026-10-24 07:21:15.295', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The awareness of <u>mortality</u> has always imposed some restraint on man''s excesses.', '["celestiality","eternity","continuity","inexistence"]', 'Mortality = death; opposite = eternity.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6863eac-d6af-47a0-ae83-e048e4cc1b6e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Nkechi was a <u>novice</u> when she was first employed.', null, '["manager","clerk","supervisor","professional"]', 3, 'Novice = beginner; opposite = professional.', true, '2026-10-24 07:21:29.521', '2026-10-24 07:21:29.521', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Nkechi was a <u>novice</u> when she was first employed.', '["manager","clerk","supervisor","professional"]', 'Novice = beginner; opposite = professional.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d68762a4-ca27-4c60-a32b-cc1dae6202d8', 'Physics', 'JAMB', null, 1983, null, 'A machine has a velocity ratio of 5. It requires a 50 kg weight to overcome a 200 kg weight. The efficiency is', null, '["4%","5%","40%","50%","80%"]', 4, 'Mechanical advantage = load/effort = 200/50 = 4. Efficiency = (MA/VR) x 100% = (4/5) x 100% = 80%.', true, '2026-10-12 19:15:17.429', '2026-10-12 19:15:17.429', null, null, null, 'A machine has a velocity ratio of 5. It requires a 50 kg weight to overcome a 200 kg weight. The efficiency is', '["4%","5%","40%","50%","80%"]', 'Mechanical advantage = load/effort = 200/50 = 4. Efficiency = (MA/VR) x 100% = (4/5) x 100% = 80%.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d690ac7c-6e0b-4d4b-996d-46e293f88635', 'Government', 'JAMB', null, 2026, null, 'The process of depriving persons of the right of voting is', null, '["enfranchisement","disqualification","disenfranchisement","prohibition"]', 2, 'Disenfranchisement is depriving persons of the right to vote.', true, '2026-09-12 11:24:15.048', '2026-09-12 11:24:15.048', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6a93d90-e746-4eba-8479-fa212af82fef', 'Biology', 'JAMB', null, 2026, null, 'A sex linked character cannot be passed on directly from', null, '["father to son","mother to daughter","mother to son","father to daughter"]', 0, 'A sex-linked character cannot be passed on directly from father to son. Fathers pass their Y chromosome to their sons, while sex-linked traits on the X chromosome are passed from father to daughters. A father with an X-linked trait will pass the affected X chromosome to all of his daughters (who become carriers or affected), but none of his sons. Sons inherit their X chromosome from their mother, not their father.', true, '2026-09-09 03:19:20.986', '2026-09-09 03:19:20.986', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6b1d708-5fdd-475f-a4b7-854f398fbd2c', 'Literature in English', 'JAMB', null, 2026, null, 'What theme is best illustrated by the tale?', null, '["romantic love","the power of prophecy","the danger of pride and flattery","heroism in battle"]', 2, 'The theme best illustrated by ''The Nun''s Priest Tale'' is the danger of pride and flattery. Chanticleer''s pride in his voice and his susceptibility to the fox''s flattery lead to his near-death. The tale warns against vanity and the dangers of listening to flatterers. Romantic love, prophecy, and heroism are not the central themes.', true, '2026-09-10 10:47:54.757', '2026-09-10 10:47:54.757', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6b59256-4770-4a62-ab66-463b24ff5f30', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lamb is a <u>feeble</u> little animal.', null, '["quite","loving","weak","fat"]', 2, 'Feeble = weak.', true, '2026-10-24 01:04:10.848', '2026-10-24 01:04:10.848', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lamb is a <u>feeble</u> little animal.', '["quite","loving","<u>weak</u>","fat"]', '<b>Feeble</b> = <b>weak</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6b76a8d-2597-4cc2-ba82-da0db28eec27', 'Chemistry', 'JAMB', null, 2026, null, 'Which Best defines Hardness? I. The durability of a material/substance II. The tendency to resist rust and decay III. A measure of a materials resistance to scratches and abrasions IV. this is the molecular strength of a material V. the boiling/melting point ratio', null, '["I&IV","all but V","III only","IV only","i,ii,IV only"]', 2, 'Hardness is best defined as resistance to scratches and abrasions.', true, '2026-09-12 11:36:11.347', '2026-09-12 11:36:11.347', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6bab579-dc7d-4338-95f9-a366872f47d9', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The man who scared the girl was a bit <u>deranged</u>.', null, '["crazy","amorous","dangerous","sane"]', 3, 'Deranged = insane; opposite = sane.', true, '2026-10-24 07:21:25.231', '2026-10-24 07:21:25.231', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The man who scared the girl was a bit <u>deranged</u>.', '["crazy","amorous","dangerous","sane"]', 'Deranged = insane; opposite = sane.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6bccab0-b09d-44fb-b1ed-b6b53d81b42e', 'Financial Accounting', 'UTME', null, 2003, null, 'The recording phase of accounting is known as', null, '["book keeping","trial balancing","ledger accounting","final accounting"]', 0, 'Source documents are recorded at the recording phase; this is known as book-keeping.', true, '2026-10-12 21:59:59.683', '2026-10-12 21:59:59.683', null, null, null, 'The recording phase of accounting is known as', '["<b>book keeping</b>","trial balancing","ledger accounting","final accounting"]', 'Source documents are recorded at the recording phase; this is known as <b>book-keeping</b>.', '{"bold":["book-keeping"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6c007c2-991f-4525-b02c-d5e180746998', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Do this job while I am away, but <u>take your time</u>.', null, '["be careful","be thorough","be fast","don''t be in a hurry"]', 3, '''Take your time'' = don''t be in a hurry.', true, '2026-10-24 01:02:07.117', '2026-10-24 01:02:07.117', null, null, null, '(Choose the most appropriate interpretation). Do this job while I am away, but <u>take your time</u>.', '["be careful","be thorough","be fast","<u>don''t be in a hurry</u>"]', '''<b>Take your time</b>'' = <b>don''t be in a hurry</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6c8ed28-6826-454e-aa7f-2fbfa06203fe', 'English Language', 'JAMB', null, 2007, null, 'Some scientists are trying to <u>__________</u> human beings in their laboratories', null, '["imitate","replicate","implicate","fabricate"]', 1, 'Correct spelling: replicate.', true, '2026-10-24 07:21:38.135', '2026-10-24 07:21:38.135', null, null, null, 'Some scientists are trying to <u>__________</u> human beings in their laboratories', '["imitate","replicate","implicate","fabricate"]', 'Correct spelling: replicate.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6cb2e00-5c69-4825-b179-e87a020567a2', 'Physics', 'JAMB', null, 1992, null, 'In alternating current theory, the units of impedance, r.m.s. voltage and resonance frequency are respectively equal to', null, '["Volt, ampere and hertz","Ohm, volt and hertz","Watt, ohm and radian","Ohm, hertz and joule."]', 1, 'Impedance is measured in ohms, r.m.s. voltage in volts and resonance frequency in hertz.', true, '2026-10-12 19:15:36.681', '2026-10-12 19:15:36.681', null, null, null, 'In alternating current theory, the units of impedance, r.m.s. voltage and resonance frequency are respectively equal to', '["Volt, ampere and hertz","Ohm, volt and hertz","Watt, ohm and radian","Ohm, hertz and joule."]', 'Impedance is measured in ohms, r.m.s. voltage in volts and resonance frequency in hertz.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6d9f089-acc9-483a-8ba8-74fadf16f4bd', 'English Language', 'JAMB', null, 2024, null, 'Choose the option that has the same CONSONANT sound as the one represented by the letter(s) underlined: healthy', null, '["father","path","they","smooth"]', 1, 'The "th" in "healthy" sounds like /θ/, same as in "path."', true, '2026-09-18 09:24:04.864', '2026-09-18 09:24:04.864', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6dae730-ff78-4822-9f14-7f8cfc8b3b49', 'English Language', 'JAMB', null, 2007, null, 'I will pay my debt <u>__________</u>', null, '["instalmentally","by instalmentally","in instalments","in instalmentally"]', 2, 'Correct form: in instalments.', true, '2026-10-24 07:21:39.973', '2026-10-24 07:21:39.973', null, null, null, 'I will pay my debt <u>__________</u>', '["instalmentally","by instalmentally","in instalments","in instalmentally"]', 'Correct form: in instalments.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6dbb730-5a02-4221-8ef0-929cc7653753', 'General Mathematics', 'JAMB', null, 2026, null, 'The cost of dinner for a group of students is partly constant and partly varies directly as the number of students. If the cost is $74.00 when the number of students is 20, and $96.00 when the number is 30, find the cost when there are 15 students', null, '["66","36","33","63"]', 3, 'C = a + bn. 74 = a + 20b. 96 = a + 30b. 22 = 10b. b = 2.2. a = 74 - 44 = 30. C = 30 + 2.2(15) = 30 + 33 = 63.', true, '2026-09-12 11:43:47.146', '2026-09-12 11:43:47.146', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6dfdb2e-dd75-491d-b654-c69df197b801', 'English Language', 'JAMB', null, 2024, null, 'Choose the option nearest in meaning to the word or phrase in italics: Garuba''s performance in the competition was horrid', null, '["commendable","encouraging","terrible","terrific"]', 2, '"Horrid" means terrible or unpleasant.', true, '2026-09-18 09:43:02.897', '2026-09-18 09:43:02.897', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d6ec1884-aa82-448d-aa12-d7b803b82379', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). He suddenly <u>found himself in the thick of the situation.</u>', null, '["He did not agree with the situation","He used his experience to settle the situation","He saved himself out of the situation","He found himself deeply involved in the situation"]', 3, '''In the thick of'' = deeply involved.', true, '2026-10-24 01:02:10.205', '2026-10-24 01:02:10.205', null, null, null, '(Choose the most appropriate interpretation). He suddenly <u>found himself in the thick of the situation.</u>', '["He did not agree with the situation","He used his experience to settle the situation","He saved himself out of the situation","<u>He found himself deeply involved in the situation</u>"]', '''<b>In the thick of</b>'' = <b>deeply involved</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d7027d69-9f12-495d-8646-0a916999b895', 'Physics', 'JAMB', null, 1997, null, 'The distance x m travelled by a particle in time t seconds is described by the equation x = 10 + 12t². Find the average speed of the particle between the time interval t = 2 s and t = 5 s.', null, '["60 m s⁻¹","72 m s⁻¹","84 m s⁻¹","108 m s⁻¹"]', 2, 'At t = 2 s: x = 58 m. At t = 5 s: x = 310 m. Average speed = (310 - 58)/3 = 84 m s⁻¹.', true, '2026-10-12 19:15:42.594', '2026-10-12 19:15:42.594', null, null, null, 'The distance x m travelled by a particle in time t seconds is described by the equation x = 10 + 12t<sup>2</sup>. Find the average speed of the particle between the time interval t = 2 s and t = 5 s.', '["60 m s<sup>-1</sup>","72 m s<sup>-1</sup>","84 m s<sup>-1</sup>","108 m s<sup>-1</sup>"]', 'At t = 2 s: x = 58 m. At t = 5 s: x = 310 m. Average speed = (310 - 58)/3 = 84 m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d70ffd36-36fb-4536-b72e-00442229976d', 'English Language', 'JAMB', null, 2024, null, 'Identify the option that contains the sound /p/', null, '["lorry","expect","country","tailor"]', 1, '"Expect" contains the /p/ sound.', true, '2026-09-18 09:43:02.648', '2026-09-18 09:43:02.648', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d7237f7a-87e1-4f1e-8708-7eff185bc0c2', 'English Language', 'JAMB', null, 2007, null, 'Three quarters of the hostel <u>------------</u> been painted and three quarters of the students <u>------------</u> moved in.', null, '["has/has","have/has","have/have","has/have"]', 3, 'Hostel singular (has); students plural (have).', true, '2026-10-24 01:02:11.741', '2026-10-24 01:02:11.741', null, null, null, 'Three quarters of the hostel <u>------------</u> been painted and three quarters of the students <u>------------</u> moved in.', '["has/has","have/has","have/have","<u>has/have</u>"]', '<b>Hostel</b> singular (<b>has</b>); <b>students</b> plural (<b>have</b>).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d72cf290-8bd2-4104-b94e-93885e15c55a', 'Physics', 'JAMB', null, 2002, null, 'When connected to a mains of 250 V, the fuse rating in the plug of an electric device of 1 kW is', null, '["5 A","4 A","3 A","2 A"]', 0, 'I = P/V = 1000/250 = 4 A. The fuse must be rated just above this, so 5 A is used.', true, '2026-10-12 19:15:54.191', '2026-10-12 19:15:54.191', null, null, null, 'When connected to a mains of 250 V, the fuse rating in the plug of an electric device of 1 kW is', '["5 A","4 A","3 A","2 A"]', 'I = P/V = 1000/250 = 4 A. The fuse must be rated just above this, so 5 A is used.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d73c8fba-fff0-4f74-b2a1-d096c13b0653', 'Biology', 'JAMB', null, 2026, null, 'The blood vessel which carries blood from the alimentary canal to the liver is the', null, '["hepatic artery","hepatic portal vein","mesenteric artery","hepatic vein"]', 1, 'The hepatic portal vein carries nutrient-rich blood from the alimentary canal (intestines, stomach) to the liver. This blood contains absorbed nutrients that the liver processes, stores, or sends to the rest of the body. The hepatic artery supplies oxygenated blood to the liver itself. The mesenteric arteries supply oxygenated blood to the intestines. The hepatic vein carries blood from the liver to the inferior vena cava. The hepatic portal system allows the liver to regulate nutrient levels, detoxify harmful substances, and store glucose as glycogen before blood reaches the general circulation.', true, '2026-09-09 03:18:42.446', '2026-09-09 03:18:42.446', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d74488e0-8f21-4456-80d4-d7f6070f250b', 'General Mathematics', 'JAMB', null, 2026, null, 'Evaluate: (27)^(2/3)', null, '["3","6","9","18"]', 2, '(27)^(2/3) = (3³)^(2/3) = 3² = 9.', true, '2026-09-12 11:44:15.847', '2026-09-12 11:44:15.847', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d7578ef8-0b75-485b-953d-2a43453d3e41', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You do not need to <u>stutter</u> in order to show your excitement.', null, '["jump about","shout","sob","stammer"]', 3, 'Stutter = stammer.', true, '2026-10-24 01:01:44.368', '2026-10-24 01:01:44.368', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You do not need to <u>stutter</u> in order to show your excitement.', '["jump about","shout","sob","<u>stammer</u>"]', '<b>Stutter</b> = <b>stammer</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d75ebd70-1e79-46b2-9a69-4aef184c4b1f', 'English Language', 'JAMB', null, 2007, null, 'He went to the restaurant to enjoy the special <u>__________</u>', null, '["suite","cuisine","a la carte","chef"]', 1, 'Correct spelling: cuisine.', true, '2026-10-24 07:21:37.476', '2026-10-24 07:21:37.476', null, null, null, 'He went to the restaurant to enjoy the special <u>__________</u>', '["suite","cuisine","a la carte","chef"]', 'Correct spelling: cuisine.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d767912c-a346-4c6e-b022-1c3641c7f1c5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. His intention was not actually to punish the villagers, and in any case he is now making moves to <u>pacify</u> them.', null, '["placate","ridicule","appease","annoy"]', 3, 'Pacify = appease; opposite = annoy.', true, '2026-10-24 07:21:17.549', '2026-10-24 07:21:17.549', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. His intention was not actually to punish the villagers, and in any case he is now making moves to <u>pacify</u> them.', '["placate","ridicule","appease","annoy"]', 'Pacify = appease; opposite = annoy.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d769633a-d40a-46f8-9043-0cff73036188', 'Financial Accounting', 'UTME', null, 2004, null, 'The company''s net current assets amount to', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841842/questions/pmpfydhvak8qfc2gh0zh.jpg', '["N5 780","N5870","N6 580","N7 930"]', 0, 'The company''s net current assets amount to N5,780.', true, '2026-10-12 22:00:02.837', '2026-10-12 22:00:02.837', null, null, null, 'The company''s net current assets amount to', '["<b>N5 780</b>","N5870","N6 580","N7 930"]', 'The company''s net current assets amount to <b>N5,780</b>.', '{"bold":["N5,780"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d7726dfb-5982-4b19-89ad-eca40d3a1587', 'English Language', 'JAMB', null, 2024, null, 'Neither the captain nor I ______ wrong', null, '["am","is","are","were"]', 0, 'With "neither...nor," the verb agrees with the nearest subject, which is "I," so "am" is correct.', true, '2026-09-18 09:43:02.792', '2026-09-18 09:43:02.792', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d772940c-05b5-4455-a531-587ada37abf6', 'Physics', 'JAMB', null, 1994, null, 'Which of the following is TRUE of a particle moving in a horizontal circle with constant angular velocity?', null, '["The energy is constant but the linear momentum varies","The linear momentum is constant but the energy varies.","Both energy and linear momentum are constant.","The speed and the linear velocity are both constant."]', 0, 'The speed is constant, so the kinetic energy is constant. The direction of motion keeps changing, so the velocity and the linear momentum vary.', true, '2026-10-12 19:15:38.943', '2026-10-12 19:15:38.943', null, null, null, 'Which of the following is <b>TRUE</b> of a particle moving in a horizontal circle with constant angular velocity?', '["The energy is constant but the linear momentum varies","The linear momentum is constant but the energy varies.","Both energy and linear momentum are constant.","The speed and the linear velocity are both constant."]', 'The speed is constant, so the kinetic energy is constant. The direction of motion keeps changing, so the velocity and the linear momentum vary.', '{"bold":["TRUE"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d77bb88d-4c59-4a8b-97d1-2c07de7ff6e5', 'Literature in English', 'JAMB', null, 2026, null, 'In The Breasts of the Sea, the sea is most appropriately interpreted as a', null, '["Literal geographic feature only","Symbol of nurturing, mystery, and vast emotional depth","Representation of political boundaries","Device for comic imagery"]', 1, 'The sea symbolizes nurturing, mystery, and vast emotional depth.', true, '2026-09-12 11:12:07.008', '2026-09-12 11:12:07.008', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d7814481-d779-461a-ac89-f9fce646763a', 'Economics', 'JAMB', null, 2026, null, 'A vehicle purchased for engaging transport service is', null, '["Consumer good","Capital good","All of the above","None of the above"]', 1, 'A vehicle used for business (transport service) is a capital good.', true, '2026-09-12 11:00:08.248', '2026-09-12 11:00:08.248', null, null, null, null, null, null, null);
