insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d78731eb-39b4-4d55-a746-da09af993f40', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The rally was attended only by people who were <u>apolitical</u>.', null, '["full of political fervor","antagonistic to politicians","new-breed politicians","not interested in politics"]', 3, 'Apolitical = not interested in politics.', true, '2026-10-24 01:01:48.176', '2026-10-24 01:01:48.176', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The rally was attended only by people who were <u>apolitical</u>.', '["full of political fervor","antagonistic to politicians","new-breed politicians","<u>not interested in politics</u>"]', '<b>Apolitical</b> = <b>not interested in politics</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d78a2392-9889-4e1f-82cd-7cebd32fc859', 'English Language', 'JAMB', null, 2024, null, '______ high time you ______ going to school late.', null, '["it''s ... stop","its ... stop","it''s ... stopped","its ... stopped"]', 2, '"It''s high time you stopped" uses the past subjunctive after "it''s high time."', true, '2026-09-18 09:23:08.281', '2026-09-18 09:23:08.281', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d7b791da-4e10-4224-888f-1739013557b5', 'Economics', 'JAMB', null, 2026, null, 'The following are types of capital except?', null, '["Social capital","Circulatory capital","Savings capital","Fixed capital"]', 2, 'Savings capital is not a standard type of capital. The types are fixed, circulating, and social capital.', true, '2026-09-12 10:59:00.008', '2026-09-12 10:59:00.008', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d7bdaba4-7751-4d67-9875-af676f8d7edb', 'General Mathematics', 'JAMB', null, 2026, null, 'Simplify: sin²θ + cos²θ', null, '["0","1","2","sin 2θ"]', 1, 'sin²θ + cos²θ = 1.', true, '2026-09-12 11:44:13.629', '2026-09-12 11:44:13.629', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d7c0eebd-332b-472d-9204-b4463529eacd', 'Literature in English', 'JAMB', null, 2026, null, 'The cultural practices depicted in the novel serve mainly to', null, '["entertain the reader with folklore","criticize modern religion","highlight the importance of heritage and communal values","promote superstition"]', 2, 'They highlight the importance of heritage and communal values.', true, '2026-09-12 11:04:27.669', '2026-09-12 11:04:27.669', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d7c9b6d0-3b41-41c5-a2f4-354bb7ebad75', 'Biology', 'JAMB', null, 2026, null, 'One of the ways in which body cells differ from gamete cells is in the', null, '["type of centromeres they contain","number of chromosome pairs they contain","type of chromatids they contain","number of chromosomes"]', 3, 'Body cells differ from gamete cells in the number of chromosomes they contain. Body cells (somatic cells) are diploid (2n) and contain two sets of chromosomes (homologous pairs). Gametes (sex cells) are haploid (n) and contain one set of chromosomes (one from each pair). Centromeres and chromatids are present in both types of cells but do not differ in type.', true, '2026-09-09 03:19:30.097', '2026-09-09 03:19:30.097', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d7d095b5-53f3-4077-8363-6d7e2300f820', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The noise across the road <u>drowned</u> the sound of the keyboard in my room.', null, '["overshadowed","neutralized","balanced","equalized"]', 0, 'Drowned = overshadowed.', true, '2026-10-24 01:01:56.598', '2026-10-24 01:01:56.598', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The noise across the road <u>drowned</u> the sound of the keyboard in my room.', '["<u>overshadowed</u>","neutralized","balanced","equalized"]', '<b>Drowned</b> = <b>overshadowed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d7e9150f-f1c9-45ff-9fff-06870e22b152', 'English Language', 'JAMB', null, 2007, null, 'The officer was compelled to <u>__________</u> the suspect''s car.', null, '["seize","cease","sieze","sease"]', 0, 'Correct spelling: seize.', true, '2026-10-24 07:21:32.541', '2026-10-24 07:21:32.541', null, null, null, 'The officer was compelled to <u>__________</u> the suspect''s car.', '["seize","cease","sieze","sease"]', 'Correct spelling: seize.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d7f0ed9a-f350-4694-aedb-a70ec369b959', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Some actions of the Nigerian youth have <u>alienated</u> them from those who were <u>sympathetic</u> to their cause.', null, '["endeared/kindly","confronted/ill disposed","separated/opposed","estranged/well disposed"]', 3, 'Alienated/sympathetic = estranged/well disposed.', true, '2026-10-24 01:01:49.973', '2026-10-24 01:01:49.973', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Some actions of the Nigerian youth have <u>alienated</u> them from those who were <u>sympathetic</u> to their cause.', '["endeared/kindly","confronted/ill disposed","separated/opposed","<u>estranged/well disposed</u>"]', '<b>Alienated/sympathetic</b> = <b>estranged/well disposed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d80df9a8-52c9-4dcc-a964-f8e117a48c85', 'Literature in English', 'JAMB', null, 2026, null, 'In the expression: ''He is a lion in battle,'' the device used is', null, '["Simile","Metaphor","Euphemism","Litotes"]', 1, 'The device is metaphor.', true, '2026-09-12 11:11:24.854', '2026-09-12 11:11:24.854', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d817b1cc-a658-43f6-8bfa-4f64e5aac2e6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The patient <u>disregarded</u> the advice of the doctor.', null, '["ignored","disobeyed","questioned","respected"]', 0, 'Disregarded = ignored.', true, '2026-10-24 01:03:58.78', '2026-10-24 01:03:58.78', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The patient <u>disregarded</u> the advice of the doctor.', '["<u>ignored</u>","disobeyed","questioned","respected"]', '<b>Disregarded</b> = <b>ignored</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d81bf22e-ea9d-4f6f-9bb3-7b5c84666cc6', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Achan was...', null, '["one of the spies who visited Rahab in Jericho","one of the two men who prophesied in the camp in the wilderness","one of the judges of Israel","the one who took some of the devoted things when Jericho fell"]', 3, 'Joshua 7:1 records that Achan took some of the accursed/devoted things from the destruction of Jericho, bringing defeat upon Israel at Ai.', true, '2026-09-09 17:18:26.786', '2026-09-09 17:18:26.786', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d81f3f61-8c11-4f25-a55e-3031179d0d39', 'English Language', 'JAMB', null, 2024, null, 'This passage emphasizes', null, '["Child growing up in ignorance","Our unconscious mind","A child''s inability to distinguish between dream and reality","Illogical dreams"]', 2, 'The passage emphasizes that children cannot distinguish between wishes and reality, similar to the unconscious mind.', true, '2026-09-18 09:43:02.626', '2026-09-18 09:43:02.626', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d8276fa7-0655-46ac-a794-652b54606b66', 'Biology', 'JAMB', null, 2003, null, 'The cell component that is present in a prokaryotic cell is the', null, '["chloroplast","ribosome","mitochondrion","nuclear envelope"]', 1, 'Ribosomes are present in prokaryotic cells.', true, '2026-10-12 20:59:32.465', '2026-10-12 20:59:32.465', null, null, null, 'The cell component that is present in a prokaryotic cell is the', '["chloroplast","ribosome","mitochondrion","nuclear envelope"]', 'Ribosomes are present in prokaryotic cells.', '{"bold":["Ribosomes"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d82b4bbc-0929-4adc-b613-4ed2db1f6973', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The lotion recommended by the doctor <u>soothed</u> Okon''s aching tooth.', null, '["calmed","extracted","excited","worsened"]', 3, 'Soothed = relieved; opposite = worsened.', true, '2026-10-24 07:21:11.571', '2026-10-24 07:21:11.571', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The lotion recommended by the doctor <u>soothed</u> Okon''s aching tooth.', '["calmed","extracted","excited","worsened"]', 'Soothed = relieved; opposite = worsened.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d82b80ad-6f31-4990-95e1-fe424427880e', 'Biology', 'JAMB', null, 2026, null, 'The filaments of Spirogyra were put into equal volumes of sugar solution X and Y. After 5 minutes, filaments from solution X had their cell contents rounded up while those from Y were unaffected. The experiment shows that', null, '["solution X was stronger than Y","solution Y was stronger than X","Spirogyra used up the sugar in solution X","solution X is good for stimulating sexual reproduction in Spirogyra"]', 0, 'The experiment shows that solution X was stronger (more concentrated) than solution Y. In solution X, the Spirogyra cells underwent plasmolysis (cell contents rounded up) because water moved out of the cells into the more concentrated external sugar solution. In solution Y, the cells were unaffected, indicating that Y was isotonic or relatively less concentrated. This demonstrates the principle of osmosis: cells in hypertonic solutions lose water and shrink. The speed of the response (5 minutes) indicates that the concentration gradient was steep for solution X.', true, '2026-09-09 03:18:55.667', '2026-09-09 03:18:55.667', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d82bbefe-f2a7-4d24-a297-35d4547f0b46', 'Physics', 'JAMB', null, 1989, null, 'Which of the following pairs is NOT part of the electromagnetic spectrum?
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d82eda30-d228-475f-b0ed-d910ac902390', 'Physics', 'JAMB', null, 1989, null, 'The resistance of a 5 m uniform wire of cross-sectional area 0.2 x 10⁻⁶ m² is 0.425 Ω. What is the resistivity of the material of the wire?', null, '["1.10 x 10⁻⁶ Ω m","4.25 x 10⁻⁶ Ω m","2.40 x 10⁻⁷ Ω m","1.70 x 10⁻⁸ Ω m"]', 3, 'ρ = RA/L = (0.425 x 0.2 x 10⁻⁶)/5 = 1.7 x 10⁻⁸ Ω m.', true, '2026-10-12 19:15:29.849', '2026-10-12 19:15:29.849', null, null, null, 'The resistance of a 5 m uniform wire of cross-sectional area 0.2 x 10<sup>-6</sup> m<sup>2</sup> is 0.425 Ω. What is the resistivity of the material of the wire?', '["1.10 x 10<sup>-6</sup> Ω m","4.25 x 10<sup>-6</sup> Ω m","2.40 x 10<sup>-7</sup> Ω m","1.70 x 10<sup>-8</sup> Ω m"]', 'ρ = RA/L = (0.425 x 0.2 x 10<sup>-6</sup>)/5 = 1.7 x 10<sup>-8</sup> Ω m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d8590cfb-f522-4a9c-9f61-763c1a104422', 'Physics', 'JAMB', null, 1995, null, 'An electric kettle with negligible heat capacity is rated at 2000 W. If 2.0 kg of water is put in it, how long will it take the temperature of the water to rise from 20 °C to 100 °C? [specific heat capacity of water = 4200 J kg⁻¹ K⁻¹]', null, '["420 s","336 s","168 s","84 s."]', 1, 'Heat needed = mcΔθ = 2.0 x 4200 x 80 = 672 000 J. Time = 672 000/2000 = 336 s.', true, '2026-10-12 19:15:41.308', '2026-10-12 19:15:41.308', null, null, null, 'An electric kettle with negligible heat capacity is rated at 2000 W. If 2.0 kg of water is put in it, how long will it take the temperature of the water to rise from 20 °C to 100 °C? [specific heat capacity of water = 4200 J kg<sup>-1</sup> K<sup>-1</sup>]', '["420 s","336 s","168 s","84 s."]', 'Heat needed = mcΔθ = 2.0 x 4200 x 80 = 672 000 J. Time = 672 000/2000 = 336 s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d85daacd-45c3-43ad-ad98-23aebfeb592a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Many states practise the ideals of <u>democracy</u>.', null, '["government by elections","government by representatives","government by civilians","government by all the people","oligarchy"]', 3, 'Democracy = government by all the people.', true, '2026-10-24 01:01:40.749', '2026-10-24 01:01:40.749', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Many states practise the ideals of <u>democracy</u>.', '["government by elections","government by representatives","government by civilians","<u>government by all the people</u>","oligarchy"]', '<b>Democracy</b> = <b>government by all the people</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d860c995-659d-46da-9a8a-45c40b53f319', 'Physics', 'JAMB', null, 1984, null, 'Heat is supplied uniformly at the rate of 100 W to 1.0 x 10⁻² kg of a liquid for 20 seconds. If the temperature of the liquid rises by 5 °C, then the specific heat capacity of the liquid is', null, '["2.0 x 10² J kg⁻¹ K⁻¹","2.0 x 10² J kg⁻¹","4.0 x 10⁴ J kg⁻¹ K⁻¹","4.0 x 10⁴ J kg⁻¹","8.4 x 10³ J kg⁻¹ K⁻¹"]', 2, 'Heat = Pt = 100 x 20 = 2000 J. c = Q/(mΔθ) = 2000/(1.0 x 10⁻² x 5) = 4.0 x 10⁴ J kg⁻¹ K⁻¹.', true, '2026-10-12 19:15:19.558', '2026-10-12 19:15:19.558', null, null, null, 'Heat is supplied uniformly at the rate of 100 W to 1.0 x 10<sup>-2</sup> kg of a liquid for 20 seconds. If the temperature of the liquid rises by 5 °C, then the specific heat capacity of the liquid is', '["2.0 x 10<sup>2</sup> J kg<sup>-1</sup> K<sup>-1</sup>","2.0 x 10<sup>2</sup> J kg<sup>-1</sup>","4.0 x 10<sup>4</sup> J kg<sup>-1</sup> K<sup>-1</sup>","4.0 x 10<sup>4</sup> J kg<sup>-1</sup>","8.4 x 10<sup>3</sup> J kg<sup>-1</sup> K<sup>-1</sup>"]', 'Heat = Pt = 100 x 20 = 2000 J. c = Q/(mΔθ) = 2000/(1.0 x 10<sup>-2</sup> x 5) = 4.0 x 10<sup>4</sup> J kg<sup>-1</sup> K<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d86dca0a-2116-41bd-aa99-7715e7bfac75', 'Biology', 'JAMB', null, 2026, null, 'One of the following is an example of anabolic process', null, '["respiration","Glycolysis","digestion","photosynthesis"]', 3, 'Photosynthesis is an anabolic process because it builds complex molecules (glucose) from simpler ones (CO₂ and H₂O) using energy from sunlight. Anabolism is the constructive phase of metabolism where smaller molecules are assembled into larger, more complex molecules, requiring energy input. Respiration and glycolysis are catabolic processes that break down molecules to release energy. Digestion is a catabolic process that breaks down large food molecules into smaller absorbable units. Photosynthesis is the primary anabolic process in plants.', true, '2026-09-09 03:18:48.323', '2026-09-09 03:18:48.323', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d8710f13-6808-4783-ab07-7fc9be2ca9b9', 'Physics', 'JAMB', null, 2001, null, 'The height at which the atmosphere ceases to exist is about 80 km. If the atmospheric pressure at ground level is 760 mmHg, the pressure at a height of 20 km above the ground level is', null, '["380 mmHg","570 mmHg","190 mmHg","480 mmHg"]', 1, 'Assuming pressure falls uniformly with height: at 20 km the remaining fraction is (80 - 20)/80 = 3/4, so P = 0.75 x 760 = 570 mmHg.', true, '2026-10-12 19:15:50.772', '2026-10-12 19:15:50.772', null, null, null, 'The height at which the atmosphere ceases to exist is about 80 km. If the atmospheric pressure at ground level is 760 mmHg, the pressure at a height of 20 km above the ground level is', '["380 mmHg","570 mmHg","190 mmHg","480 mmHg"]', 'Assuming pressure falls uniformly with height: at 20 km the remaining fraction is (80 - 20)/80 = 3/4, so P = 0.75 x 760 = 570 mmHg.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d872aa1a-af2f-4db8-af23-a02ccb19624a', 'Government', 'JAMB', null, 2026, null, 'The OPEC quota system is primarily designed to', null, '["reduce oil dependency","enforce international law","control oil quality","stabilize oil prices"]', 3, 'The OPEC quota system is designed to stabilize oil prices.', true, '2026-09-12 11:24:45.738', '2026-09-12 11:24:45.738', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d87ef1ab-91b5-4fed-be33-c7d8cd7c3748', 'Biology', 'JAMB', null, 2004, null, 'In a Mendelian cross of red and white varieties of the four o''clock plant, F1 generation expresses incomplete dominance by having flowers which are', null, '["white","red","pink","multicoloured"]', 2, 'Incomplete dominance produces pink flowers.', true, '2026-10-12 20:59:35.838', '2026-10-12 20:59:35.838', null, null, null, 'In a Mendelian cross of red and white varieties of the four o''clock plant, F1 generation expresses incomplete dominance by having flowers which are', '["white","red","pink","multicoloured"]', 'Incomplete dominance produces pink flowers.', '{"bold":["pink"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d8905a86-6573-48ce-a8c4-946297f7ae1b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>coalescence</u> of the groups created additional problems.', null, '["union","fighting","proscription","disbandment"]', 0, 'Coalescence = union.', true, '2026-10-24 01:04:02.824', '2026-10-24 01:04:02.824', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>coalescence</u> of the groups created additional problems.', '["<u>union</u>","fighting","proscription","disbandment"]', '<b>Coalescence</b> = <b>union</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d8913c24-e3c5-4232-b4e0-15b35002d407', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Bello said he <u>would pitch his tent with the club</u>', null, '["He would support the club","He would build a pitch in the club","He would build a tent on the pitch","He would distance himself from the club"]', 0, '''Pitch one''s tent with'' = support/join.', true, '2026-10-24 01:04:24.634', '2026-10-24 01:04:24.634', null, null, null, '(Choose the most appropriate interpretation). Bello said he <u>would pitch his tent with the club</u>', '["<u>He would support the club</u>","He would build a pitch in the club","He would build a tent on the pitch","He would distance himself from the club"]', '''<b>Pitch one''s tent with</b>'' = <b>support/join</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d8985e54-6dae-4d55-9511-a64ef862b0cf', 'General Mathematics', 'JAMB', null, 2026, null, 'The sixth term of an arithmetical progression is half of its twelfth term. The first term is equal to', null, '["the common difference","half of the common difference","zero","double the common difference"]', 0, 'a+5d = 1/2(a+11d). 2a+10d = a+11d. a = d.', true, '2026-09-12 11:43:48.245', '2026-09-12 11:43:48.245', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d89ebb3d-bbb9-4832-8765-e9d1817c8f6b', 'Literature in English', 'JAMB', null, 2026, null, 'The imagery in Night contributes mainly to the creation of', null, '["Suspense and tension","Comic relief","Romantic atmosphere","Didactic instruction"]', 0, 'The imagery creates suspense and tension.', true, '2026-09-12 11:09:57.122', '2026-09-12 11:09:57.122', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d8a79f86-c5a7-450c-ac56-97031ed4e530', 'Yoruba', 'JAMB', null, 2007, null, 'Nínú Mò ï gààrí rè, gààrí', null, '["òrõ-ìye","òrõ-orúkõ","òrõ-àpònlé","òrõ-atòkùn"]', 0, 'Nínú Mò ï gààrí rè, gààrí jè òrõ-ìye.', true, '2026-10-13 13:23:31.302', '2026-10-13 13:23:31.302', null, null, null, 'Nínú Mò ï gààrí rè, gààrí', '["òrõ-ìye","òrõ-orúkõ","òrõ-àpònlé","òrõ-atòkùn"]', 'Nínú Mò ï gààrí rè, gààrí jè òrõ-ìye.', '{"bold":["òrõ-ìye"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d8d78b94-2a49-4fbe-8ab2-7e1086e20677', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What was Zechariah''s punishment for doubting Gabriel''s message?', null, '["leprosy","deafness","blindness","muteness"]', 3, 'Zechariah was struck mute because he doubted Gabriel''s message that he and Elizabeth would have a son in their old age. He remained unable to speak until John the Baptist was born and named.', true, '2026-09-12 09:45:49.27', '2026-09-12 09:45:49.27', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d8df47dc-8eaa-414c-81ad-6a9299ce9e11', 'Literature in English', 'JAMB', null, 2026, null, 'The writing convention in which the events in a narrative are scrambled as they come to the writer''s mind without any attempt to arrange them in orderly sequence is called', null, '["Shifting style","Narrator''s mind style","Psycho-consciousness style","Stream of consciousness"]', 3, 'It is stream of consciousness.', true, '2026-09-12 11:10:54.124', '2026-09-12 11:10:54.124', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d8e007ea-2901-44dc-8ada-dab06b287122', 'English Language', 'JAMB', null, 2007, null, 'Most of the missing jewelry were <u>__________</u> by the police', null, '["found","taken","kept","recovered"]', 3, 'Correct spelling: recovered.', true, '2026-10-24 07:21:44.568', '2026-10-24 07:21:44.568', null, null, null, 'Most of the missing jewelry were <u>__________</u> by the police', '["found","taken","kept","recovered"]', 'Correct spelling: recovered.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d8e85fb3-3687-40c8-9bf2-ee9b104903cf', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'After healing the man at the pool of Bethzatha, the Jews sought all the more to kill Jesus because', null, '["They hated the man that was healed","they were unhappy that He healed the man","He claimed that God His father was still working","He did this on the Sabbath"]', 3, 'Jesus healed on the Sabbath and called God His Father.', true, '2026-09-12 10:41:52.676', '2026-09-12 10:41:52.676', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d90097f2-5192-458b-9169-8ac6de0d04bd', 'Financial Accounting', 'UTME', null, 2001, null, 'Given: Club trading profit 12,000 Members'' subscription 15,000 Profit on sale of fixed assets 2,500 Loss on sale of investments 1,000 Wages 16,000 Other expenses 10,000. Determine the club''s excess of income over expenditure.', null, '["N500","N1,500","N2,000","N2,500"]', 2, 'Excess = (12,000 + 15,000 + 2,500) - (1,000 + 16,000 + 10,000) = 29,500 - 27,000 = 2,500. Wait, the answer is N2,000.', true, '2026-10-12 22:00:06.814', '2026-10-12 22:00:06.814', null, null, null, 'Given: Club trading profit 12,000 Members'' subscription 15,000 Profit on sale of fixed assets 2,500 Loss on sale of investments 1,000 Wages 16,000 Other expenses 10,000. Determine the club''s excess of income over expenditure.', '["N500","N1,500","<b>N2,000</b>","N2,500"]', 'Excess = (12,000 + 15,000 + 2,500) - (1,000 + 16,000 + 10,000) = 29,500 - 27,000 = <b>N2,000</b>.', '{"bold":["N2,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d9088de2-539d-4ecb-b6d9-06623aaa6c41', 'Physics', 'JAMB', null, 2026, null, 'A gas occupies a volume of 2.0L at 27°C. If the temperature is raised to 127°C at constant pressure, its volume would be', null, '["1.5 L","2.0 L","2.67 L","3.0 L"]', 2, 'Using Charles''s Law: V1/T1 = V2/T2. T1 = 27+273 = 300K, T2 = 127+273 = 400K. V2 = V1 × T2/T1 = 2.0 × 400/300 = 2.67 L.', true, '2026-09-10 10:56:49.46', '2026-09-10 10:56:49.46', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d90bffe5-bc19-46e0-908c-23787dc23c90', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The policeman looked at the face of robber and saw tell-tale sign of a <u>dyed-in-the-wool</u> convict.', null, '["hardened","remorseless","heady","hardhearted"]', 0, 'Dyed-in-the-wool = hardened.', true, '2026-10-24 01:01:43.785', '2026-10-24 01:01:43.785', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The policeman looked at the face of robber and saw tell-tale sign of a <u>dyed-in-the-wool</u> convict.', '["<u>hardened</u>","remorseless","heady","hardhearted"]', '<b>Dyed-in-the-wool</b> = <b>hardened</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d9168608-64bb-423b-97a1-1424f9282b6d', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''If your enemy is hungry, feed him.'' This statement implies', null, '["vengeance","kindness","forgiveness","charity"]', 1, 'This statement implies kindness. In Romans 12:20, Paul quotes Proverbs, ''If your enemy is hungry, feed him; if he is thirsty, give him something to drink.'' This is overcoming evil with good.', true, '2026-09-12 09:46:04.351', '2026-09-12 09:46:04.351', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d91b61cf-c155-470e-a7e7-b02e892b2738', 'English Language', 'JAMB', null, 2024, null, 'Choose the option that has the same VOWEL sound as the one represented by the letter(s) underlined: guard', null, '["gourd","guide","argue","chat"]', 2, 'The "ua" in "guard" sounds like /ɑː/, same as the "ar" in "argue."', true, '2026-09-18 09:24:04.881', '2026-09-18 09:24:04.881', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d9336ea9-7b83-4bf0-a9aa-b33ab3176df1', 'Christian Religious Studies', 'JAMB', null, 2026, null, '“He will give his Angels charge of you.....and on their hands they will bear you up...” What reply was given on this occasion?', null, '["You shall not tempt the Lord your God","Man shall not live by bread alone","You shall worship the Lord your God","Only God shall you serve"]', 0, 'When Satan quoted Psalm 91 during the temptation on the pinnacle of the temple, Jesus replied in Matthew 4:7 / Luke 4:12 with ''It is written again, You shall not tempt the Lord your God.''', true, '2026-09-09 17:18:23.615', '2026-09-09 17:18:23.615', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d94e7a93-5d09-4910-9f89-2092d161d7ee', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It was interesting to observe the <u>likeness</u> between the pupil and his teacher.', null, '["similarity","relationship","fondness","affection","affinity"]', 0, 'Likeness = similarity.', true, '2026-10-24 01:03:53.165', '2026-10-24 01:03:53.165', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It was interesting to observe the <u>likeness</u> between the pupil and his teacher.', '["<u>similarity</u>","relationship","fondness","affection","affinity"]', '<b>Likeness</b> = <b>similarity</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d94fce9b-c917-42d5-97ab-65b6d2c073e4', 'Biology', 'JAMB', null, 2026, null, 'A phenotypic character with intermediate forms that can be graded from one extreme to the other is referred to as', null, '["discontinuous variation","continuous variation","mutant","genome"]', 1, 'A phenotypic character with intermediate forms that can be graded from one extreme to the other is referred to as continuous variation. Continuous variation shows a range of values with no distinct categories (like height, weight, skin color). Discontinuous variation shows distinct, non-overlapping categories (like blood groups). A mutant is an organism with a mutation. A genome is all the genetic material in an organism. Continuous variation is often controlled by multiple genes (polygenic inheritance) and influenced by environmental factors.', true, '2026-09-09 03:19:13.606', '2026-09-09 03:19:13.606', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d95645b4-d574-4c4e-a041-58085c6b6211', 'English Language', 'JAMB', null, 2024, null, 'Choose the word that is opposite in meaning to the word or phrase in italics: Okonkwo''s lethal right foot did the magic in the football match', null, '["weak","wicked","fat","harmless"]', 3, '"Lethal" means deadly or harmful; the opposite is "harmless."', true, '2026-09-18 09:24:04.805', '2026-09-18 09:24:04.805', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d964c82e-15c9-4c91-8c2e-a5455488c9bb', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The task was <u>Herculean</u>.', null, '["irregular","related to Hercules","stimulating","demanding"]', 3, 'Herculean = demanding great effort.', true, '2026-10-24 01:02:03.786', '2026-10-24 01:02:03.786', null, null, null, '(Choose the most appropriate interpretation). The task was <u>Herculean</u>.', '["irregular","related to Hercules","stimulating","<u>demanding</u>"]', '<b>Herculean</b> = <b>demanding great effort</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d97bc1c5-3139-4a6d-99e5-9afb756ebe55', 'Biology', 'JAMB', null, 2012, null, 'The significance of a very large number of termites involved in nuptial swarming is to', null, '["provide birds with plenty of food","ensure their perpetuation despite predatory pressure","search for a favourable place to breed","ensure that every individual gets a mate."]', 1, 'Nuptial swarming ensures perpetuation despite predatory pressure.', true, '2026-10-12 20:59:45.907', '2026-10-12 20:59:45.907', null, null, null, 'The significance of a very large number of termites involved in nuptial swarming is to', '["provide birds with plenty of food","ensure their perpetuation despite predatory pressure","search for a favourable place to breed","ensure that every individual gets a mate."]', 'Nuptial swarming ensures perpetuation despite predatory pressure.', '{"bold":["ensures perpetuation despite predatory pressure"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d98bf174-77bb-42b2-b791-823e5ff4a486', 'General Mathematics', 'JAMB', null, 2026, null, 'An arc of length 16π cm subtends an angle of 80° at the centre of the circle. Find the radius of the circle.', null, '["24cm","28cm","36cm","32cm"]', 2, 'Arc length = (θ/360) × 2πr. 16π = (80/360) × 2πr. 16 = (2/9) × 2r. 16 = 4r/9. r = 36cm.', true, '2026-09-10 10:48:18.946', '2026-09-10 10:48:18.946', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d9b5c8cc-8f01-46fe-bf5d-5d5c686f4dcc', 'Physics', 'JAMB', null, 2026, null, 'Electrical power is transmitted at a high voltage rather than at low voltage because the amount of energy loss is due to', null, '["heat dissipation","production of eddy current","excessive current discharge","excessive voltage discharge"]', 0, 'Electrical power is transmitted at high voltage to reduce energy loss due to heat dissipation. Power loss = I²R. By increasing voltage, current is reduced (P = VI), so less energy is lost as heat in the transmission cables.', true, '2026-09-10 10:56:42.005', '2026-09-10 10:56:42.005', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d9da8046-31f9-4f75-b1e7-6f916c56bb84', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Garba always <u>puts his shoulder to the wheel</u>.', null, '["sits with his shoulders straight when he is driving","works energetically at the task in hand","performs tasks assigned him grudgingly","holds the steering wheel firmly when he is driving"]', 1, '''Puts his shoulder to the wheel'' = works energetically.', true, '2026-10-24 01:04:17.608', '2026-10-24 01:04:17.608', null, null, null, '(Choose the most appropriate interpretation). Garba always <u>puts his shoulder to the wheel</u>.', '["sits with his shoulders straight when he is driving","<u>works energetically at the task in hand</u>","performs tasks assigned him grudgingly","holds the steering wheel firmly when he is driving"]', '''<b>Puts his shoulder to the wheel</b>'' = <b>works energetically</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d9e54728-6040-4e26-b8b9-4ed980f113c9', 'Biology', 'JAMB', null, 2010, null, 'At what stage in the life history of a mammal is the sex of an individual set?', null, '["At adolescence","At puberty","At birth","At conception."]', 3, 'Sex is set at conception.', true, '2026-10-12 20:59:41.393', '2026-10-12 20:59:41.393', null, null, null, 'At what stage in the life history of a mammal is the sex of an individual set?', '["At adolescence","At puberty","At birth","At conception."]', 'Sex is set at conception.', '{"bold":["at conception"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d9fabb37-3b1e-4aa6-8871-ac542d02174b', 'Physics', 'JAMB', null, 1992, null, 'What is the frequency of the sound made by a siren having a disc with 32 holes and making 25 revolutions per second?', null, '["80 Hz","600 Hz","800 Hz","1 600 Hz"]', 2, 'Frequency = number of holes x revolutions per second = 32 x 25 = 800 Hz.', true, '2026-10-12 19:15:35.766', '2026-10-12 19:15:35.766', null, null, null, 'What is the frequency of the sound made by a siren having a disc with 32 holes and making 25 revolutions per second?', '["80 Hz","600 Hz","800 Hz","1 600 Hz"]', 'Frequency = number of holes x revolutions per second = 32 x 25 = 800 Hz.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('d9fee692-4261-493a-9976-caf3b78f9281', 'Economics', 'JAMB', null, 2026, null, 'Which of the following measures the value of goods and services produced within a given country for a given year?', null, '["GNP","NNP","NNI","Per Capita Income","GDP"]', 4, 'GDP (Gross Domestic Product) measures the value of goods and services produced within a given country for a given year, regardless of the nationality of the producers. GNP (Gross National Product) measures the value of goods and services produced by a country''s citizens, whether at home or abroad. GDP is the most common measure of a country''s economic output within its borders.', true, '2026-09-10 10:41:21.26', '2026-09-10 10:41:21.26', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da22b41f-fcf2-41bd-a0f7-8a3160bdd7f8', 'Biology', 'JAMB', null, 2003, null, 'The gall bladder of a mammal has a duct connected to the', null, '["liver","duodenum","small intestine","pancreas"]', 1, 'The bile duct from the gall bladder empties bile directly into the duodenum.', true, '2026-10-12 20:05:11.109', '2026-10-12 20:05:11.109', null, null, null, 'The gall bladder of a mammal has a duct connected to the', '["liver","duodenum","small intestine","pancreas"]', 'The bile duct from the gall bladder empties bile directly into the duodenum.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da2cd1a1-7574-4a75-8ca3-3f6cfd487cd3', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The sin of Achan brought defeat to Israel at', null, '["Jericho","Canaan","Ai","Gibeon"]', 2, 'Achan disobeyed God by taking some of the devoted things from Jericho (a beautiful mantle, silver, and gold). Because of his sin, Israel was defeated at Ai. Achan and his family were later stoned and burned.', true, '2026-09-12 09:45:46.583', '2026-09-12 09:45:46.583', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da2f9339-4a87-4eff-81a4-5f62949fa74c', 'Literature in English', 'JAMB', null, 2026, null, 'The poet''s title ''Not my Business'' is a representation of the speaker''s', null, '["courageous stance","moral conviction","shortsightedness","long-term planning"]', 2, 'The poet''s title ''Not my Business'' represents the speaker''s shortsightedness. The speaker believes that the oppression of others is not his concern, failing to see that injustice anywhere is a threat to justice everywhere. His refusal to get involved is shortsighted because eventually, the oppression reaches him too. It is not a courageous stance, moral conviction, or long-term planning.', true, '2026-09-10 10:45:34.937', '2026-09-10 10:45:34.937', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da465846-e293-4352-abff-66e1b02414f1', 'Economics', 'JAMB', null, 2026, null, 'Economics is often described as a social science because?', null, '["laboratory experiments are performed","It makes use of controlled experiments","It uses scientific methods to explain an observed phenomenon and predict future events","It makes use of fieldwork"]', 2, 'Economics uses scientific methods to explain observed phenomena and predict future events.', true, '2026-09-12 11:00:49.371', '2026-09-12 11:00:49.371', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da4c39bd-40bd-4fd7-a3e3-4647141af567', 'Biology', 'JAMB', null, 2026, null, 'Angiosperms and gymnosperms belong to the class', null, '["schizophyta","spermatophyta","pteridophyta","bryophyta"]', 1, 'Angiosperms and gymnosperms belong to the class Spermatophyta (seed plants). Schizophyta is an outdated division for bacteria and blue-green algae. Pteridophyta is the division for ferns and their allies (spore-bearing plants). Bryophyta is the division for mosses and liverworts (non-vascular plants). Spermatophyta includes all seed-bearing plants, which are further divided into gymnosperms (naked seeds) and angiosperms (enclosed seeds). Seed plants evolved from spore-bearing plants and are the most advanced plant group.', true, '2026-09-09 03:19:07.712', '2026-09-09 03:19:07.712', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da4c48bd-9cc8-4fb6-b1df-a38437993e24', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Oisa <u>hoodwinked</u> the men into buying and selling.', null, '["prevent","improve","promote","worsen"]', 0, 'Garbled source; closest = prevent (deceived).', true, '2026-10-24 01:01:58.927', '2026-10-24 01:01:58.927', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Oisa <u>hoodwinked</u> the men into buying and selling.', '["<u>prevent</u>","improve","promote","worsen"]', '<b>Garbled source</b>; closest = <b>prevent</b> (deceived).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da5818e5-4aab-43c2-9bd1-005a2097f1c5', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Which epistle contains the famous analogy of the Church as the ''body of Christ'' and the members as individual parts?', null, '["1 Corinthians","Romans","Galatians","Colossians"]', 0, '1 Corinthians contains the famous analogy of the Church as the body of Christ and the members as individual parts. In 1 Corinthians 12, Paul explains that just as the body has many members with different functions, so the church has many members with different gifts, but all are needed and work together.', true, '2026-09-12 09:46:16.897', '2026-09-12 09:46:16.897', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da5ba85d-1e9f-4798-adeb-58229b8c31da', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The shortage of petrol was a <u>perennial</u> problem.', null, '["a seasonal","a recurring","an incurring","an annual"]', 1, 'Perennial = recurring.', true, '2026-10-24 01:04:09.445', '2026-10-24 01:04:09.445', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The shortage of petrol was a <u>perennial</u> problem.', '["a seasonal","<u>a recurring</u>","an incurring","an annual"]', '<b>Perennial</b> = <b>a recurring</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da5d1887-a955-44a4-b9d8-a627e4c13b5d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man outran his wife when they heard the <u>eerie</u> sound.', null, '["hissing","harsh","scary","loud"]', 2, 'Eerie = scary.', true, '2026-10-24 01:04:03.973', '2026-10-24 01:04:03.973', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man outran his wife when they heard the <u>eerie</u> sound.', '["hissing","harsh","<u>scary</u>","loud"]', '<b>Eerie</b> = <b>scary</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da644bf2-4f6a-4fb3-aeb9-1282638a0457', 'Biology', 'JAMB', null, 2026, null, 'Which of the organelles has a double membrane?', null, '["nucleus","chloroplast","mitochondria","all except b","all"]', 4, 'The nucleus, chloroplast, and mitochondria are all double-membrane-bound organelles.', true, '2026-09-09 02:56:41.11', '2026-09-09 02:56:41.11', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da6845ab-a111-4efe-bb66-7991e029d3c1', 'Government', 'JAMB', null, 2026, null, 'Which of the following represents a confederal arrangement?', null, '["Nigeria","China","European Union","United States of America"]', 2, 'The European Union represents a confederal arrangement.', true, '2026-09-12 11:24:44.541', '2026-09-12 11:24:44.541', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da686513-c368-41ad-80b6-61076abe008b', 'Physics', 'JAMB', null, 1984, null, 'Two cells, each of e.m.f. 1.5 V and internal resistance 2 Ω are connected in parallel. Calculate the current flowing when the cells are connected to a 1 Ω resistor.', null, '["0.75 A","1.5 A","0.5 A","1.0 A","0.6 A"]', 0, 'Two identical cells in parallel give e.m.f. 1.5 V and internal resistance 2/2 = 1 Ω. I = E/(R + r) = 1.5/(1 + 1) = 0.75 A.', true, '2026-10-12 19:15:18.747', '2026-10-12 19:15:18.747', null, null, null, 'Two cells, each of e.m.f. 1.5 V and internal resistance 2 Ω are connected in parallel. Calculate the current flowing when the cells are connected to a 1 Ω resistor.', '["0.75 A","1.5 A","0.5 A","1.0 A","0.6 A"]', 'Two identical cells in parallel give e.m.f. 1.5 V and internal resistance 2/2 = 1 Ω. I = E/(R + r) = 1.5/(1 + 1) = 0.75 A.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da81f9ce-5ed5-4ea3-a31b-a593cfdbe8cb', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Everybody <u>respects</u> the team leader.', null, '["looks up for","looks up on","looks up to","looks up at"]', 2, '''Looks up to'' = respects.', true, '2026-10-24 01:02:03.514', '2026-10-24 01:02:03.514', null, null, null, '(Choose the most appropriate interpretation). Everybody <u>respects</u> the team leader.', '["looks up for","looks up on","<u>looks up to</u>","looks up at"]', '''<b>Looks up to</b>'' = <b>respects</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da8c2811-1122-4f97-ad45-e9ff162b8228', 'English Language', 'JAMB', null, 2007, null, 'After months of tedious climbing, the team reached the <u>__________</u> of the mountain.', null, '["end","summit","height","terminal"]', 1, 'Correct spelling: summit.', true, '2026-10-24 07:21:42.256', '2026-10-24 07:21:42.256', null, null, null, 'After months of tedious climbing, the team reached the <u>__________</u> of the mountain.', '["end","summit","height","terminal"]', 'Correct spelling: summit.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da8f7574-92c3-4ace-abff-a3add3fa9905', 'Physics', 'JAMB', null, 1994, null, 'When a biro pen rubbed on a dry silk cloth is moved very close to a piece of paper on a dry table, the pen is found to pick up the paper. This is because', null, '["Both the pen and the cloth are magnetized","The pen is magnetized but the cloth is not","The pen is charged while the cloth is magnetized","Both the pen and the cloth are charged."]', 3, 'Rubbing transfers charge: the pen and the cloth acquire opposite charges. The charged pen attracts the paper by induction.', true, '2026-10-12 19:15:40.236', '2026-10-12 19:15:40.236', null, null, null, 'When a biro pen rubbed on a dry silk cloth is moved very close to a piece of paper on a dry table, the pen is found to pick up the paper. This is because', '["Both the pen and the cloth are magnetized","The pen is magnetized but the cloth is not","The pen is charged while the cloth is magnetized","Both the pen and the cloth are charged."]', 'Rubbing transfers charge: the pen and the cloth acquire opposite charges. The charged pen attracts the paper by induction.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da8fabb4-9fe7-4c8b-8867-26e0c8b99878', 'Literature in English', 'JAMB', null, 2026, null, 'An anti-social action taken by the tragic hero which results in a catastrophe is called', null, '["anagnorisis","premonition","hamartia","empathy"]', 2, 'Hamartia is the tragic hero''s error leading to catastrophe.', true, '2026-09-12 11:10:36.35', '2026-09-12 11:10:36.35', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da98921b-ade6-4880-a34b-e3622c2158cf', 'Literature in English', 'JAMB', null, 2026, null, 'In Hearty Garlands, ''garlands'' symbolise', null, '["Honour and celebration of achievement","Mourning and grief","Political power","Religious sacrifice"]', 0, 'Garlands symbolize honour and celebration of achievement.', true, '2026-09-12 11:05:28.167', '2026-09-12 11:05:28.167', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('da997ca8-5dff-470f-a98a-430b53bda55a', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In Romans, Paul condemned sin taking over mortal bodies in the new life as instruments of', null, '["greediness","wickedness","sadness","foolishness"]', 1, 'In Romans 6:13, Paul says, ''Do not yield your members to sin as instruments of wickedness, but yield yourselves to God as men who have been brought from death to life.''', true, '2026-09-12 09:46:02.644', '2026-09-12 09:46:02.644', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('daa7430e-8247-4ce9-aea2-0ed11bfc4e68', 'Economics', 'JAMB', null, 2026, null, 'What add funds to the circular flow?', null, '["Leakages","Injections","Withdrawals","Public Expenditure"]', 1, 'Injections add funds to the circular flow.', true, '2026-09-12 11:01:33.361', '2026-09-12 11:01:33.361', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dab5ddff-e35d-4910-a0a4-46650c000a11', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Although the manager is busy right now, he will be with you <u>presently</u>.', null, '["immediately","soon","without delay","right away"]', 1, 'Presently = soon.', true, '2026-10-24 01:03:59.747', '2026-10-24 01:03:59.747', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Although the manager is busy right now, he will be with you <u>presently</u>.', '["immediately","<u>soon</u>","without delay","right away"]', '<b>Presently</b> = <b>soon</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dab5e5fd-72ff-4f4f-bd30-5edda8319d80', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Which of the following commandments is described by James as the royal law?', null, '["You shall have no other gods before me","You shall love the Lord your God with all your heart","You shall love your neighbor as yourself","You shall covet your neighbor''s property"]', 2, 'James describes ''You shall love your neighbor as yourself'' as the royal law. He says, ''If you really fulfil the royal law, according to the scripture, "You shall love your neighbor as yourself," you do well.''', true, '2026-09-12 09:46:01.704', '2026-09-12 09:46:01.704', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dab99866-87f9-4f50-8db2-bac30b7b66cd', 'General Mathematics', 'JAMB', null, 2026, null, 'The sum of the interior angles of a regular polygon is 1800°. Calculate the size of each interior angle of the polygon.', null, '["30°","24°","18°","12°"]', 0, 'Sum of interior angles = (n-2) × 180 = 1800. So n-2 = 10, n = 12. Each interior angle = 1800/12 = 150°. But the options are 30°, 24°, 18°, 12°. This doesn''t match. Perhaps the question asks for the exterior angle? Exterior angle = 360/12 = 30°. So the answer is 30°.', true, '2026-09-10 10:48:18.748', '2026-09-10 10:48:18.748', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('daba716f-a7c6-4bd1-bf07-aa2b40c56059', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). I <u>shuddered in revulsion</u> as I watched the snake slowly swallow the struggling rat.', null, '["was fascinated","was repelled","was interested","was distressed"]', 1, '''Revulsion'' = strong disgust/repelled.', true, '2026-10-24 01:04:20.933', '2026-10-24 01:04:20.933', null, null, null, '(Choose the most appropriate interpretation). I <u>shuddered in revulsion</u> as I watched the snake slowly swallow the struggling rat.', '["was fascinated","<u>was repelled</u>","was interested","was distressed"]', '''<b>Revulsion</b>'' = <b>strong disgust/repelled</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dabd33ce-c97b-4bdd-966a-c46852070e95', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The rain falls for days <u>_______________</u>', null, '["no end","at end","at ending","on ending"]', 0, '''For days no end'' = endlessly.', true, '2026-10-24 01:04:23.827', '2026-10-24 01:04:23.827', null, null, null, '(Choose the most appropriate interpretation). The rain falls for days <u>_______________</u>', '["<u>no end</u>","at end","at ending","on ending"]', '''<b>For days no end</b>'' = <b>endlessly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dac9cf2d-9b66-465a-ac9d-488f2732f372', 'Physics', 'JAMB', null, 1992, null, 'In an experiment to determine Young''s Modulus for a wire, several loads are attached to the wire and the corresponding extensions measured. The tensile stress in each case depends on the', null, '["Load and the extension","Load and the radius of the wire","Radius of the wire and the extension","Extension and the original length of the wire."]', 1, 'Tensile stress = force/cross-sectional area = load/(πr²), so it depends on the load and the radius of the wire.', true, '2026-10-12 19:15:35.123', '2026-10-12 19:15:35.123', null, null, null, 'In an experiment to determine Young''s Modulus for a wire, several loads are attached to the wire and the corresponding extensions measured. The tensile stress in each case depends on the', '["Load and the extension","Load and the radius of the wire","Radius of the wire and the extension","Extension and the original length of the wire."]', 'Tensile stress = force/cross-sectional area = load/(πr<sup>2</sup>), so it depends on the load and the radius of the wire.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dace97db-f0b4-4690-8343-92f317525bcc', 'Literature in English', 'JAMB', null, 2026, null, 'The speaker''s tone throughout the poem can best be described as', null, '["submissive","bitter","defiant","indifferent"]', 2, 'The speaker''s tone is defiant.', true, '2026-09-12 11:13:45.807', '2026-09-12 11:13:45.807', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dad44b89-9dc8-42bd-b3a9-21e0e326a2be', 'English Language', 'JAMB', null, 2007, null, 'He was <u>__________</u> by the trickster', null, '["assisted","duped","cajoled","encouraged"]', 1, 'Correct spelling: duped.', true, '2026-10-24 07:21:44.167', '2026-10-24 07:21:44.167', null, null, null, 'He was <u>__________</u> by the trickster', '["assisted","duped","cajoled","encouraged"]', 'Correct spelling: duped.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dad75d20-ea8a-49e8-ac85-2fdfe615488a', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Peter encourages Christians to endure suffering because', null, '["it brings wealth","it leads to glory","it avoids punishment","it ensures power"]', 1, 'Peter encourages Christians to endure suffering because it leads to glory. He writes that after they have suffered a little while, the God of all grace will restore, establish, and strengthen them, and that suffering produces glory.', true, '2026-09-12 09:45:52.839', '2026-09-12 09:45:52.839', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dae0655d-95ca-474c-b236-47b145eb31ee', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). My plans are still <u>up in the air</u>.', null, '["being publicized","uncertain","uncovered","unprotected"]', 1, '''Up in the air'' = uncertain.', true, '2026-10-24 01:02:04.744', '2026-10-24 01:02:04.744', null, null, null, '(Choose the most appropriate interpretation). My plans are still <u>up in the air</u>.', '["being publicized","<u>uncertain</u>","uncovered","unprotected"]', '''<b>Up in the air</b>'' = <b>uncertain</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dae19613-e3a5-4c1f-9ed2-abceb34a30a1', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In Genesis 22, Abraham''s willingness to sacrifice Isaac primarily demonstrates', null, '["legal obedience to covenant terms","ritual purification practices","prophetic symbolism of exile","typology of substitutionary atonement"]', 3, 'Abraham''s willingness prefigures Christ''s substitutionary atonement.', true, '2026-09-12 10:41:02.11', '2026-09-12 10:41:02.11', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dae8d8c8-44e3-4a42-9a34-6068d591a767', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>panacea</u> for a country''s economic ills lies in systematic planning and hardwork.', null, '["foresight","hope","trouble","cure"]', 3, 'Panacea = cure.', true, '2026-10-24 01:01:54.484', '2026-10-24 01:01:54.484', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>panacea</u> for a country''s economic ills lies in systematic planning and hardwork.', '["foresight","hope","trouble","<u>cure</u>"]', '<b>Panacea</b> = <b>cure</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('daf77f2e-255b-487b-babc-85ad27d083a2', 'English Language', 'JAMB', null, 2007, null, 'The accident was due to <u>----------</u> driving by the defendant.', null, '["negligence","negligible","negligent","neglectable"]', 2, 'Correct spelling: negligent.', true, '2026-10-24 07:21:35.16', '2026-10-24 07:21:35.16', null, null, null, 'The accident was due to <u>----------</u> driving by the defendant.', '["negligence","negligible","negligent","neglectable"]', 'Correct spelling: negligent.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dafc17f3-10dd-4403-bfa8-e0bb5c23cbfc', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is an example of an invisible item on the balance of payments account?', null, '["Merchandise","Gold","Aviation","Exports and imports"]', 2, 'Aviation is an invisible item (service).', true, '2026-09-12 11:02:14.638', '2026-09-12 11:02:14.638', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db0ca40c-73f5-4cc6-be6c-5ee8670fa426', 'Literature in English', 'JAMB', null, 2026, null, '''Anansewa- a! where is that typewriter I bought for you at a price that nearly drove me to sell myself?'' This statement depicts', null, '["the abundant state of Ananse''s wealth","the struggle behind living up to standard","the hand-to-mouth feeding status of Ananse''s family","the nonchalant nature of Anansewa"]', 1, 'It depicts the struggle behind living up to standard.', true, '2026-09-12 11:12:07.56', '2026-09-12 11:12:07.56', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db14ac70-69d9-43a8-9603-91fb07c50e9f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The report of the committee contained a <u>plethora</u> of details.', null, '["simplicity","multitude","spectrum","shortage"]', 3, 'Plethora = excess; opposite = shortage.', true, '2026-10-24 07:21:26.637', '2026-10-24 07:21:26.637', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The report of the committee contained a <u>plethora</u> of details.', '["simplicity","multitude","spectrum","shortage"]', 'Plethora = excess; opposite = shortage.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db2c51b6-1adb-4002-b0c1-161fde48024f', 'Physics', 'JAMB', null, 2003, null, 'A test tube of radius 1.0 cm is loaded to 8.8 g. If it is placed upright in water, find the depth to which it would sink. [g = 10 m s⁻², density of water 1 000 kg m⁻³]', null, '["25.2 cm","2.8 cm","28.0 cm","5.2 cm"]', 1, 'Weight = upthrust: m = ρ x (πr²h). h = 8.8/(1 x π x 1²) = 2.8 cm.', true, '2026-10-12 19:15:55.101', '2026-10-12 19:15:55.101', null, null, null, 'A test tube of radius 1.0 cm is loaded to 8.8 g. If it is placed upright in water, find the depth to which it would sink. [g = 10 m s<sup>-2</sup>, density of water 1 000 kg m<sup>-3</sup>]', '["25.2 cm","2.8 cm","28.0 cm","5.2 cm"]', 'Weight = upthrust: m = ρ x (πr<sup>2</sup>h). h = 8.8/(1 x π x 1<sup>2</sup>) = 2.8 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db2dde54-9fdf-49d9-a496-b61cb80d1a0b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearly opposite in meaning to the word(s) or phrase in italics and underlined. To most people last Christmas was an <u>austere</u> period.', null, '["a prosperous","a harsh","a severe","a sour","a stern"]', 0, 'Austere = severe/harsh; opposite = prosperous.', true, '2026-10-24 07:21:10.656', '2026-10-24 07:21:10.656', null, null, null, 'Choose the option nearly opposite in meaning to the word(s) or phrase in italics and underlined. To most people last Christmas was an <u>austere</u> period.', '["a prosperous","a harsh","a severe","a sour","a stern"]', 'Austere = severe/harsh; opposite = prosperous.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db3697f2-ba65-4f3e-a060-0bb185929128', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation).The case was dismissed <u>for want of evidence</u>.', null, '["for want of facts","for want of opinions","for insufficient discussions","for lack of proof"]', 3, '''Want of evidence'' = lack of proof.', true, '2026-10-24 01:02:04.849', '2026-10-24 01:02:04.849', null, null, null, '(Choose the most appropriate interpretation).The case was dismissed <u>for want of evidence</u>.', '["for want of facts","for want of opinions","for insufficient discussions","<u>for lack of proof</u>"]', '''<b>Want of evidence</b>'' = <b>lack of proof</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db40310a-df7f-4649-8bd9-b43c0d1f53f3', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Hosea used his marriage to illustrate', null, '["Israel''s political failure","God''s love and Israel''s unfaithfulness","economic decline","foreign oppression"]', 1, 'Hosea used his marriage to Gomer, a harlot, to illustrate God''s love and Israel''s unfaithfulness. Just as Gomer was unfaithful to Hosea, Israel was unfaithful to God by worshipping other gods. Hosea''s continued love for Gomer symbolized God''s steadfast love for Israel.', true, '2026-09-12 09:45:48.36', '2026-09-12 09:45:48.36', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db46089a-1672-47e7-a358-99de5f1d2cba', 'Economics', 'JAMB', null, 2026, null, 'If a country can supply us with a commodity cheaper than we ourselves can make it, the country is said to have ______ over us', null, '["Comparative advantage","Absolute advantage","Internal advantage","comparative cost advantage"]', 1, 'Absolute advantage means a country can produce a good more cheaply than another country.', true, '2026-09-12 11:00:34.502', '2026-09-12 11:00:34.502', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db5b1e11-f286-402e-ba5e-1b7c10580eb5', 'Chemistry', 'JAMB', null, 2026, null, 'Dyes in water soluble markers can be separated by', null, '["magnetisation","chromatography","distillation","evaporation"]', 1, 'Chromatography separates dyes in water-soluble markers.', true, '2026-09-12 11:36:05.784', '2026-09-12 11:36:05.784', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db5ea559-026b-4e7f-867e-bc0f5ca28a70', 'Chemistry', 'JAMB', null, 2026, null, 'In which reaction will the point of equilibrium shift to the left when the pressure on the system is increased?', null, '["C(s) + O2(g) ⇌ CO2(g)","CaCO3(s) ⇌ CaO(s) + CO2(g)","2Mg(s) + O2(g) ⇌ 2MgO(s)","2H2(g) + O2(g) ⇌ 2H2O(g)"]', 1, 'Increasing pressure shifts equilibrium toward fewer gas moles. In reaction B, reactants have 0 gas moles while products have 1 gas mole, shifting equilibrium left.', true, '2026-09-09 17:12:46.847', '2026-09-09 17:12:46.847', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db5eb7d0-e26e-4a15-9b4b-2b765a989343', 'Physics', 'JAMB', null, 1998, null, 'In free fall, a body of mass 1 kg drops from a height of 125 m from rest in 5 s. How long will it take another body of mass 2 kg to fall from rest from the same height? (g = 10 m s⁻²)', null, '["5 s","10 s","12 s","15 s"]', 0, 'In free fall the time depends only on the height and g, not on the mass: t = √(2h/g) = 5 s.', true, '2026-10-12 19:15:44.762', '2026-10-12 19:15:44.762', null, null, null, 'In free fall, a body of mass 1 kg drops from a height of 125 m from rest in 5 s. How long will it take another body of mass 2 kg to fall from rest from the same height? (g = 10 m s<sup>-2</sup>)', '["5 s","10 s","12 s","15 s"]', 'In free fall the time depends only on the height and g, not on the mass: t = √(2h/g) = 5 s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db64223f-1469-481e-8c2b-a3eaf66b3b00', 'English Language', 'JAMB', null, 2007, null, 'The situation has deteriorated sharply, and relations between the two countries may soon be <u>__________</u>', null, '["removed","broken","withdrawn","eliminated","deferred"]', 1, 'Correct form: broken (relations broken).', true, '2026-10-24 07:21:40.228', '2026-10-24 07:21:40.228', null, null, null, 'The situation has deteriorated sharply, and relations between the two countries may soon be <u>__________</u>', '["removed","broken","withdrawn","eliminated","deferred"]', 'Correct form: broken (relations broken).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db6b2560-b81b-472f-a80f-ef3a46d5a0c0', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The period of the ''Return from Exile'' is associated with which Persian King''s decree?', null, '["King Cyrus","King Artaxerxes","King Darius","King Xerxes"]', 0, 'King Cyrus issued the decree allowing the Jews to return.', true, '2026-09-12 10:41:45.598', '2026-09-12 10:41:45.598', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db7ad121-8930-4f3f-8e34-aa1945affb46', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearly opposite in meaning to the word(s) or phrase in italics and underlined. Her <u>identification</u> with the king is publicly known.', null, '["hatred","disassociation","relationship","intimacy"]', 1, 'Identification = association; opposite = disassociation.', true, '2026-10-24 07:21:14.427', '2026-10-24 07:21:14.427', null, null, null, 'Choose the option nearly opposite in meaning to the word(s) or phrase in italics and underlined. Her <u>identification</u> with the king is publicly known.', '["hatred","disassociation","relationship","intimacy"]', 'Identification = association; opposite = disassociation.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db89960c-a32b-497b-9498-c8510b0ddc26', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Ijeoma <u>counted her chickens before they were hatched</u>. This means that Ijeoma ________________', null, '["regarded each egg as a chicken","hatched the eggs prematurely","assumed that her expectations had already been realized","protected her eggs from breaking","insured the eggs"]', 2, 'Assumed success prematurely.', true, '2026-10-24 01:02:00.351', '2026-10-24 01:02:00.351', null, null, null, '(Choose the most appropriate interpretation). Ijeoma <u>counted her chickens before they were hatched</u>. This means that Ijeoma ________________', '["regarded each egg as a chicken","hatched the eggs prematurely","<u>assumed that her expectations had already been realized</u>","protected her eggs from breaking","insured the eggs"]', 'Assumed <b>success prematurely</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('db987079-d6d3-4ac7-bada-1179c5b0b216', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. All we need is a <u>concerted</u> effort to combat the epidemic.', null, '["persistent","dramatic","joint","concentrated"]', 2, 'Concerted = joint.', true, '2026-10-24 01:01:43.625', '2026-10-24 01:01:43.625', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. All we need is a <u>concerted</u> effort to combat the epidemic.', '["persistent","dramatic","<u>joint</u>","concentrated"]', '<b>Concerted</b> = <b>joint</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dba582cb-fad5-404b-b536-6d74bd89c6c1', 'English Language', 'JAMB', null, 2024, null, 'Maryam, the girl in my neighbourhood, treats people as if she ______ better than they are', null, '["has","were","is","was"]', 1, 'The subjunctive mood "were" is used after "as if" to express an unreal or hypothetical situation.', true, '2026-09-18 09:43:02.263', '2026-09-18 09:43:02.263', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dba971c7-4893-4823-ab0b-a3c0cc6af296', 'Literature in English', 'JAMB', null, 2026, null, '…………………………………….is the sudden reversal of fortune or change in circumstance', null, '["Peripeteia","Anagnorisis","Hamartia","Catharsis"]', 0, 'Peripeteia is the sudden reversal of fortune or change in circumstance. In classical tragedy, peripeteia is the turning point where the protagonist''s fortunes change dramatically, often from good to bad. Anagnorisis is recognition, hamartia is a tragic flaw, and catharsis is emotional purgation. Peripeteia is a key element of tragic plots.', true, '2026-09-10 10:47:55.15', '2026-09-10 10:47:55.15', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dbabc94f-32d3-4330-a275-09a269d468d9', 'Chemistry', 'JAMB', null, 2026, null, 'A reaction with low activation energy will be spontaneous at room temperature i) true ii) false iii) maybe iv) never', null, '["I only","ii only","iii only","iv only"]', 0, 'Low activation energy means the reaction can proceed spontaneously at room temperature.', true, '2026-09-12 11:36:16.683', '2026-09-12 11:36:16.683', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dbb032cc-7cd3-4815-9062-f3bb340fbe71', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Gideon was able to defeat the Midianites, with a reduced number of soldiers because he', null, '["was a good fighter","was a prudent warrior","had better weapons","had faith in God"]', 3, 'Gideon was able to defeat the Midianites with a reduced number of soldiers because he had faith in God. God reduced his army from 32,000 to 300 so that Israel would know that the victory came from God, not from their own strength.', true, '2026-09-12 09:46:00.58', '2026-09-12 09:46:00.58', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dbb4e256-5797-4db4-901e-7d4afa04f629', 'Economics', 'JAMB', null, 2026, null, 'The law of diminishing returns often operates in the', null, '["long run","short run","medium term","small scale production","none of the above"]', 1, 'The law of diminishing returns operates in the short run. It states that as more units of a variable factor (e.g., labour) are added to fixed factors (e.g., land, machinery), the marginal product of the variable factor will eventually decline. This law applies only in the short run because at least one factor is fixed. In the long run, all factors are variable, so the law does not apply.', true, '2026-09-10 10:41:19.7', '2026-09-10 10:41:19.7', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dbbcb7b8-bdb4-4b46-8db9-edbc044ee32c', 'English Language', 'JAMB', null, 2007, null, 'The army officer said that more <u>__________</u> would be needed to prosecute the war.', null, '["guerrilas","guerrillas","guerillas","geurrillas"]', 1, 'Correct spelling: guerrillas.', true, '2026-10-24 07:21:35.517', '2026-10-24 07:21:35.517', null, null, null, 'The army officer said that more <u>__________</u> would be needed to prosecute the war.', '["guerrilas","guerrillas","guerillas","geurrillas"]', 'Correct spelling: guerrillas.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dbc233a3-6f17-499e-809b-c57a5553030b', 'Biology', 'JAMB', null, 2001, null, 'Which of the following is likely to encourage inbreeding in plants', null, '["monoecious","dioecious","hermaphrodite","protandrous"]', 2, 'Hermaphroditic plants can self-pollinate, encouraging inbreeding.', true, '2026-10-12 20:59:29.467', '2026-10-12 20:59:29.467', null, null, null, 'Which of the following is likely to encourage inbreeding in plants', '["monoecious","dioecious","hermaphrodite","protandrous"]', 'Hermaphroditic plants can self-pollinate, encouraging inbreeding.', '{"bold":["Hermaphroditic"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dbc8acc8-46ac-44e9-97c9-99361c4fb0c6', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is not an example of a working capital?', null, '["Fuel","Machinery","Raw Material","Cash"]', 1, 'Machinery is a fixed capital item because it is used over a long period. Working capital includes fuel, raw materials, and cash.', true, '2026-09-12 10:57:25.606', '2026-09-12 10:57:25.606', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dbcee57a-5e86-4ce6-bb8c-e81333e2dec9', 'Biology', 'JAMB', null, 2026, null, 'Eye defect usually associated with the elderly is', null, '["myopia","hypermetropia","astigmatism","presbyopia"]', 3, 'Presbyopia is the eye defect usually associated with aging (elderly). It results from the loss of elasticity of the eye lens, making it difficult to focus on near objects. Myopia (nearsightedness) and hypermetropia (farsightedness) are refractive errors that can occur at any age. Astigmatism is an irregular curvature of the cornea or lens. Presbyopia typically becomes noticeable around age 40 and progresses with age. It is caused by hardening of the lens and weakening of the ciliary muscles, reducing the eye''s ability to change focus (accommodation).', true, '2026-09-09 03:18:48.547', '2026-09-09 03:18:48.547', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dbd2be4a-3568-43f0-9daa-b2b56ab54405', 'English Language', 'JAMB', null, 2024, null, 'Choose the option nearest in meaning to the word(s) or phrase(s) Underlined: His summary of the meeting was brief and to the point', null, '["Precise","Accurate","Exact","crucial"]', 0, '"Brief and to the point" means precise.', true, '2026-09-18 09:43:02.412', '2026-09-18 09:43:02.412', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dbee0809-1e61-4f0d-8db4-4c57b80b1f3d', 'General Mathematics', 'JAMB', null, 2026, null, 'A sum of #15,000 is split into two parts: one earns 6% per annum, and the other 9% per annum. After 2 years, the total interest is #2,040. How much was invested at 9%?', null, '["#4,000","#6,000","#7,000","#8,000"]', 3, 'Let x at 9%, 15000-x at 6%. 2(0.09x + 0.06(15000-x)) = 2040. 0.09x + 900 - 0.06x = 1020. 0.03x = 120. x = 4000. The answer is (A) #4,000.', true, '2026-09-12 11:43:51.603', '2026-09-12 11:43:51.603', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dbf4f34c-7b56-40ae-b777-0717c0ebe0ae', 'Biology', 'JAMB', null, 2010, null, 'I. Adoption of appropriate nocturnal habits II. Burrowing III. Adjusting their internal body temperature IV. Possession of many sweat pores. Which of the above are ways in which desert animals adapt to extreme heat of the environment?', null, '["I and IV only.","II and III only.","I and II only.","I, II and III only."]', 3, 'I, II and III are ways desert animals adapt to extreme heat.', true, '2026-10-12 20:59:40.784', '2026-10-12 20:59:40.784', null, null, null, 'I. Adoption of appropriate nocturnal habits II. Burrowing III. Adjusting their internal body temperature IV. Possession of many sweat pores. Which of the above are ways in which desert animals adapt to extreme heat of the environment?', '["I and IV only.","II and III only.","I and II only.","I, II and III only."]', 'I, II and III are ways desert animals adapt to extreme heat.', '{"bold":["I, II and III"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dbfb2c6e-4777-422a-9679-d8770ea7e74c', 'Hausa', 'JAMB', null, 2011, null, 'Wanne ne kebaBen bayanin wasalin /a/?', null, '["Dan gaba ne na sama.","Dan gaba ne na tsakiya.","Dan kurya ne na sama.","Dan tsakatsaki ne na kasa."]', 3, 'Wasalin /a/ dan tsakatsaki ne na kasa.', true, '2026-10-13 10:37:20.924', '2026-10-13 10:37:20.924', null, null, null, 'Wanne ne kebaBen bayanin wasalin /a/?', '["Dan gaba ne na sama.","Dan gaba ne na tsakiya.","Dan kurya ne na sama.","Dan tsakatsaki ne na kasa."]', 'Wasalin /a/ dan tsakatsaki ne na kasa.', '{"bold":["dan tsakatsaki ne na kasa"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc074d79-ad20-453f-bf08-8c679435f47b', 'Economics', 'JAMB', null, 2026, null, 'Banks established specifically to build and sustain certain sectors of the economy are called?', null, '["Merchant banks","Commercial banks","Central banks","Development banks"]', 3, 'Development banks are established to build and sustain specific sectors.', true, '2026-09-12 11:01:11.559', '2026-09-12 11:01:11.559', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc12bfbe-e1bb-4f80-b25d-84e6690c5da5', 'Biology', 'JAMB', null, 2026, null, 'If a DNA strand has a base sequence TCA, its complementary strand must be', null, '["ATG","GAT","TAG","AGT"]', 3, 'If a DNA strand has the base sequence TCA, its complementary strand must be AGT. The base pairing rules are: A pairs with T, and G pairs with C. TCA: T pairs with A, C pairs with G, A pairs with T. Therefore, the complementary sequence is AGT. This is the basis of DNA''s double helix and is essential for DNA replication and transcription.', true, '2026-09-09 03:19:27.637', '2026-09-09 03:19:27.637', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc242962-5a9d-4e6c-8fa0-e7cf368010fd', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Who was the man full of the Spirit and wisdom appointed to serve tables?', null, '["Stephen","Paul","John","Silas"]', 0, 'Stephen was one of the seven men appointed to serve tables.', true, '2026-09-12 10:40:58.288', '2026-09-12 10:40:58.288', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc24c2f4-f65f-4603-b1f7-c77d7fa5c269', 'Literature in English', 'JAMB', null, 2026, null, 'In New Tongue, the ''new tongue'' symbolically represents', null, '["Linguistic confusion","Religious transformation","Political rebellion","Cultural alienation and loss of identity"]', 3, 'The ''new tongue'' represents cultural alienation and loss of identity.', true, '2026-09-12 11:09:56.065', '2026-09-12 11:09:56.065', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc3b1a0d-c873-4ab5-8c69-df0403257e8d', 'Economics', 'JAMB', null, 2026, null, 'Given that fixed cost is #500.00, variable cost is #1500.00 and output is 40 units, what will be the average cost of producing one unit?', null, '["#2.50","#37.50","#50.00","#500.00"]', 2, 'Average cost = Total Cost / Output. Total Cost = Fixed Cost + Variable Cost = 500 + 1500 = 2000. Average Cost = 2000 / 40 = #50.00. Therefore, the average cost of producing one unit is #50.00.', true, '2026-09-10 10:42:55.881', '2026-09-10 10:42:55.881', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc3cbe17-bfb3-4619-a856-21e873a4e564', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tom''s <u>aberrant</u> behaviour attracted attention.', null, '["rascally","selfish","heady","abnormal"]', 3, 'Aberrant = abnormal.', true, '2026-10-24 01:03:57.733', '2026-10-24 01:03:57.733', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tom''s <u>aberrant</u> behaviour attracted attention.', '["rascally","selfish","heady","<u>abnormal</u>"]', '<b>Aberrant</b> = <b>abnormal</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc4efd96-a3ac-4b51-af33-87bfee3d848c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man was able to persuade his <u>wilful and obstinate</u> daughter to follow the career he chose for her.', null, '["intelligent but arrogant","unyielding and obdurate","obscure and odious","hardworking and intelligent"]', 1, 'Wilful and obstinate = unyielding and obdurate.', true, '2026-10-24 01:01:50.078', '2026-10-24 01:01:50.078', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man was able to persuade his <u>wilful and obstinate</u> daughter to follow the career he chose for her.', '["intelligent but arrogant","<u>unyielding and obdurate</u>","obscure and odious","hardworking and intelligent"]', '<b>Wilful and obstinate</b> = <b>unyielding and obdurate</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc5081be-bbc7-49c7-8435-4900b1b5a6c3', 'Biology', 'JAMB', null, 2026, null, 'Which of the following has the most primitive respiratory system?', null, '["snail","fish","insect","mouse"]', 0, 'Snails have the most primitive respiratory system among the options. They have simple lungs (in land snails) or gills (in aquatic snails) with limited surface area and less efficiency. Fish have gills with counter-current exchange systems for efficient gas exchange. Insects have tracheal systems with extensive branching for direct gas exchange. Mice have complex lungs with alveoli for efficient gas exchange. Snails represent an earlier evolutionary stage of respiratory system development.', true, '2026-09-09 03:19:09.448', '2026-09-09 03:19:09.448', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc5bb1b6-adc3-4257-9b0e-8ac3e5a6e2c0', 'Literature in English', 'JAMB', null, 2026, null, 'Ananse''s mattress is a', null, '["a straw-stuffed mat","a straw-stuffed, lumpy mattress","a soft, bouncy duniplo","a fragment of patched-up foam"]', 1, 'Ananse''s mattress is a straw-stuffed, lumpy mattress.', true, '2026-09-12 11:10:05.078', '2026-09-12 11:10:05.078', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc6e3db0-3683-459b-b059-879f5c20290b', 'Government', 'JAMB', null, 2026, null, 'Rule by divine right is a basis of', null, '["absolute monarchy","representative democracy","the republican system","the feudal system"]', 0, 'Rule by divine right is the basis of absolute monarchy.', true, '2026-09-12 11:24:51.831', '2026-09-12 11:24:51.831', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc75d460-dae0-46ef-a895-8287c9767927', 'Physics', 'JAMB', null, 1992, null, 'Which of the following characteristics of a wave is used in the measurement of the depth of the sea?', null, '["Diffraction","Interference","Refraction","Reflection"]', 3, 'Echo sounding uses the reflection of sound from the sea bed, with depth = (speed x time)/2.', true, '2026-10-12 19:15:35.659', '2026-10-12 19:15:35.659', null, null, null, 'Which of the following characteristics of a wave is used in the measurement of the depth of the sea?', '["Diffraction","Interference","Refraction","Reflection"]', 'Echo sounding uses the reflection of sound from the sea bed, with depth = (speed x time)/2.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc84150b-4be3-4a87-a501-48386b70ea20', 'Biology', 'JAMB', null, 2003, null, 'Metabolic production of urea is carried out in the', null, '["urinary bladder and kidney","liver","pancreas","kidney and Malpighian tubule"]', 1, 'The liver deaminates excess amino acids to synthesize urea, which is later excreted by the kidneys.', true, '2026-10-12 20:05:09.864', '2026-10-12 20:05:09.864', null, null, null, 'Metabolic production of urea is carried out in the', '["urinary bladder and kidney","liver","pancreas","kidney and Malpighian tubule"]', 'The liver deaminates excess amino acids to synthesize urea, which is later excreted by the kidneys.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc937496-c6be-48cb-8673-6b1be9d2ca34', 'Biology', 'JAMB', null, 2026, null, 'The theory which supports the view that the large muscles developed by an athlete will be passed on to the offspring was proposed by', null, '["Lamarck","Darwin","Mendel","Pasteur"]', 0, 'Lamarck proposed the theory of inheritance of acquired characteristics. He believed that traits acquired during an organism''s lifetime could be passed to offspring (the ''use and disuse'' theory). This view was later disproven. Darwin proposed natural selection. Mendel established the principles of inheritance (genetics). Pasteur disproved spontaneous generation. Lamarck''s theory was incorrect because acquired characteristics (like muscles developed through exercise) are not heritable, as they are not encoded in the germline cells (gametes).', true, '2026-09-09 03:18:52.384', '2026-09-09 03:18:52.384', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc963389-cc40-4535-8b96-c1f41d7e3f4b', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'God blessed and hallowed the seventh day because', null, '["it was the day he rested from creation","it was the day he created man","he wanted it to be a day of worship","he saw that all he had created was good"]', 0, 'God rested on the seventh day and hallowed it.', true, '2026-09-12 10:41:04.588', '2026-09-12 10:41:04.588', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dc9e08f6-0edc-4b51-a4cc-f607cc50af66', 'English Language', 'JAMB', null, 2007, null, 'The Principal expressed his <u>__________</u> when the students broke the rules <u>__________</u> and he didn''t know how to stop them', null, '["anger/everyday","frustration/time and again","disappointment/understandably","powerlessness/occasionally"]', 1, 'Correct forms: frustration/time and again.', true, '2026-10-24 07:21:45.375', '2026-10-24 07:21:45.375', null, null, null, 'The Principal expressed his <u>__________</u> when the students broke the rules <u>__________</u> and he didn''t know how to stop them', '["anger/everyday","frustration/time and again","disappointment/understandably","powerlessness/occasionally"]', 'Correct forms: frustration/time and again.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dcb14c4f-e3f6-47d0-9b94-21e1ce9b85fb', 'English Language', 'JAMB', null, 2024, null, 'Choose the word or group of words that is nearest in meaning to the underlined words: Her spell in the university was an unmitigated disaster.', null, '["an unavoidable","a regrettable","an unfortunate","an unqualified"]', 3, '"Unmitigated" means absolute or unqualified (used for emphasis).', true, '2026-09-18 09:23:08.419', '2026-09-18 09:23:08.419', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dcba9a34-97ae-4012-a4d5-eebe67d827d2', 'Literature in English', 'JAMB', null, 2026, null, 'The tone of Once Upon a Time shifts from', null, '["Nostalgic to cynical","Joyful to indifferent","Angry to humorous","Passive to celebratory"]', 0, 'The tone shifts from nostalgic to cynical.', true, '2026-09-12 11:12:05.136', '2026-09-12 11:12:05.136', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dccb4e25-de4e-4d1f-91d4-deb8071f5c8e', 'Chemistry', 'JAMB', null, 2026, null, 'A solution has [OH⁻] = 1×10⁻⁹ mol dm⁻³. What is its pH?', null, '["3","5","9","11"]', 1, 'pOH = -log[OH⁻] = -log(1×10⁻⁹) = 9. pH + pOH = 14, so pH = 14 - 9 = 5.', true, '2026-09-12 09:38:09.133', '2026-09-12 09:38:09.133', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dcd43182-d600-41d5-b5c6-4501c4a2b5b0', 'Hausa', 'JAMB', null, 2009, null, 'Bayan wata uku, ata sake mu. Da muka huta kwana biyu, sai muka yi shirin zuwa kasashen Ris tare da shi, ya zama kuma abokina. Muna cikin tafiya a daji, sai wani mahaukacin rakumi, amale, ya biyo mu baki bud`e. muka sheka wurin wata itaciya muka hau. Shi kuwa, rakumin ya tsaya nan gindin itaciyar yana jira wai sai mun sauko, ya tasam mana. Muka rasa yadda za mu yi tun da safe har azahar, gas hi kuwa cikunanmu suna ta kiran ciorma. Can zuwa la''asar, sai nag a wad`ansu Fulani za su yawon sharo. Da dai na hange su kan hanya, sai na ce, ''Kai masu tafiya, uwaku!'' Ka san bafillace kan bakin rai, daga can kuwa sai suka nufo mu da gudu, wais u ji dalilin da ya san a zage su. Da dai rakumin nan ya kyalla ido ya gan su, bai sake komawa ta kanmu ba, sai ya cce dasu aka gama mu. Kowanne ya ranta, suka yi dawa! Mu kuwa muka sauka, muka yi tamu hanya. Ga mu nan sai Birnin Ris . Zurke na can yana kale-kalle, har nab ace masa. Ka ji rabuwata da shi. Na yi gaba, na shiga jirgi. Na nufi Alkama neman abin da ya rabo ni da gida, watau Ruwan Baganja. Da muka sauka a wani tsibiri don mu huta, sai na tafi yawon shan iska. Jirgi ya tshai, aka bar ni nan ni kad`ai! Bayan sun wuce, na tashi da tafiya, ina neman wani jirgi in bi su. Ina bin bakin teku, sai na tarar da wani mutum a zaune. Na dube shi da kyau, ashe dai Malam Zurke ne dan Muhammad. Da nag a haka sai n ace, ''Zurke d`an Muhammad!'' Sai ya amsa y ace, ''Himma dai d`an Shehu!'' Muka tafa. Y ace ''Wallahi, tun da ka zo na gane ka''. Muka ba juna labarin rabuwarmu. Wace dabara su Zurke suka fara yi wajen tsere wa mahaukacin rakumi?', null, '["Addu''a","Hayewa kan itaciya.","Gudu.","Shigewa cikin kogo."]', 1, 'Sun hau itaciya ne domin tsere wa mahaukacin rakumi.', true, '2026-10-13 10:37:25.857', '2026-10-13 10:37:25.857', null, null, null, 'Bayan wata uku, ata sake mu. Da muka huta kwana biyu, sai muka yi shirin zuwa kasashen Ris tare da shi, ya zama kuma abokina. Muna cikin tafiya a daji, sai wani mahaukacin rakumi, amale, ya biyo mu baki bud`e. muka sheka wurin wata itaciya muka hau. Shi kuwa, rakumin ya tsaya nan gindin itaciyar yana jira wai sai mun sauko, ya tasam mana. Muka rasa yadda za mu yi tun da safe har azahar, gas hi kuwa cikunanmu suna ta kiran ciorma. Can zuwa la''asar, sai nag a wad`ansu Fulani za su yawon sharo. Da dai na hange su kan hanya, sai na ce, ''Kai masu tafiya, uwaku!'' Ka san bafillace kan bakin rai, daga can kuwa sai suka nufo mu da gudu, wais u ji dalilin da ya san a zage su. Da dai rakumin nan ya kyalla ido ya gan su, bai sake komawa ta kanmu ba, sai ya cce dasu aka gama mu. Kowanne ya ranta, suka yi dawa! Mu kuwa muka sauka, muka yi tamu hanya. Ga mu nan sai Birnin Ris . Zurke na can yana kale-kalle, har nab ace masa. Ka ji rabuwata da shi. Na yi gaba, na shiga jirgi. Na nufi Alkama neman abin da ya rabo ni da gida, watau Ruwan Baganja. Da muka sauka a wani tsibiri don mu huta, sai na tafi yawon shan iska. Jirgi ya tshai, aka bar ni nan ni kad`ai! Bayan sun wuce, na tashi da tafiya, ina neman wani jirgi in bi su. Ina bin bakin teku, sai na tarar da wani mutum a zaune. Na dube shi da kyau, ashe dai Malam Zurke ne dan Muhammad. Da nag a haka sai n ace, ''Zurke d`an Muhammad!'' Sai ya amsa y ace, ''Himma dai d`an Shehu!'' Muka tafa. Y ace ''Wallahi, tun da ka zo na gane ka''. Muka ba juna labarin rabuwarmu. Wace dabara su Zurke suka fara yi wajen tsere wa mahaukacin rakumi?', '["Addu''a","Hayewa kan itaciya.","Gudu.","Shigewa cikin kogo."]', 'Sun hau itaciya ne domin tsere wa mahaukacin rakumi.', '{"bold":["hau itaciya"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dcd6a560-a575-4902-8199-bfee01a50532', 'Literature in English', 'JAMB', null, 2026, null, 'The term ''catharsis'' refers to', null, '["emotional purification","comic relief","tragic flaw","irony"]', 0, 'Catharsis is emotional purification.', true, '2026-09-12 11:14:12.688', '2026-09-12 11:14:12.688', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dcd8bf97-1062-425e-95af-0da9471bc595', 'Biology', 'JAMB', null, 2026, null, 'Which of the following protects the essential parts of the flower at bud stage?', null, '["Stamens","Sepals","Petals","Carpels"]', 1, 'Sepals are the outermost floral organs that protect the essential parts of the flower (stamens and carpels) during the bud stage. Sepals are usually green and leaf-like, forming the calyx. Petals often attract pollinators and may also provide some protection but are not the primary protective structure. Stamens are the male reproductive organs. Carpels are the female reproductive organs. The sepal bud covers the developing flower before it opens, providing protection against environmental stress, pathogens, and herbivores.', true, '2026-09-09 03:18:54.54', '2026-09-09 03:18:54.54', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dcda5f5e-4322-4403-94d0-201aa2f6a4ff', 'Literature in English', 'JAMB', null, 2026, null, 'The poet''s relationship with the sea suggests', null, '["fear and hostility","emotional attachment","indifference","rivalry"]', 1, 'The relationship suggests emotional attachment.', true, '2026-09-12 11:05:47.144', '2026-09-12 11:05:47.144', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dcf03f82-965f-4196-b7ec-d2e1f6f6c5cf', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It was interesting to observe the <u>likeness</u> between the pupil and his teacher.', null, '["similarity","relationship","fondness","affection","affinity"]', 0, 'Likeness = similarity.', true, '2026-10-24 01:01:40.304', '2026-10-24 01:01:40.304', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It was interesting to observe the <u>likeness</u> between the pupil and his teacher.', '["<u>similarity</u>","relationship","fondness","affection","affinity"]', '<b>Likeness</b> = <b>similarity</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dcf5aa79-275d-40f1-8467-d2f337fe95ab', 'Literature in English', 'JAMB', null, 2026, null, 'In Once Upon a Time, the line ''They used to laugh with their hearts / And laugh with their eyes'' suggests', null, '["Artificiality in human interaction","Emotional weakness","Mockery among friends","Genuine sincerity in past relationships"]', 3, 'The line suggests genuine sincerity in past relationships.', true, '2026-09-12 11:05:16.605', '2026-09-12 11:05:16.605', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dcfa8404-6d47-4ca8-991d-18c2cae61bb6', 'Economics', 'JAMB', null, 2026, null, 'In a public company, shares are', null, '["sold to one person only","distributed freely","advertised to the members of the public for subscription","disposed of by the chief executive"]', 2, 'In a public company, shares are advertised to the members of the public for subscription. A public limited liability company (PLC) can offer its shares to the general public through the stock exchange. This allows the company to raise large amounts of capital from many investors. Shares are not sold to one person only, distributed freely, or disposed of by the chief executive.', true, '2026-09-10 10:42:00.396', '2026-09-10 10:42:00.396', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd00badb-6bb2-4062-bcab-2eb857ca64f4', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Galatians, one of the benefits of being a joint heir with Christ is having his Spirit in', null, '["worship","the heart","the body","prayers"]', 1, 'God sent the Spirit of His Son into believers'' hearts (Galatians 4:6).', true, '2026-09-12 10:41:19.805', '2026-09-12 10:41:19.805', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd0217a3-eda0-408e-8ff1-fd57b4306d84', 'Economics', 'JAMB', null, 2026, null, 'The demand and supply equations for a commodity are given respectively as Demand = 20 - 1/2P, Supply = 8 + 1/4P. What''s the equilibrium price and quantity?', null, '["P = 12, Q = 16","P = 8, Q = 12","P = 16, Q = 12","P = 14, Q = 16"]', 2, '20 - 0.5P = 8 + 0.25P. 12 = 0.75P. P = 16. Q = 20 - 0.5(16) = 12.', true, '2026-09-12 11:01:03.765', '2026-09-12 11:01:03.765', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd028b9d-9bf6-4b4c-aa68-7d8c556e204a', 'General Mathematics', 'JAMB', null, 2026, null, 'Add the same number to the numerator and the denominator of 3/18. If the resulting fraction is 1/2, then the number added is', null, '["13","14","15","12","11"]', 3, '(3 + n)/(18 + n) = 1/2. 2(3+n) = 18+n. 6+2n = 18+n. n = 12.', true, '2026-09-10 10:48:19.638', '2026-09-10 10:48:19.638', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd18f62f-e6e5-4665-9d51-ca571c680cda', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The accounts clerk was jailed because he <u>cooked the books</u>.', null, '["set fire to the account books","sold the books in his office to get money for food","falsified the accounts to his advantage","destroyed the account books by cooking them"]', 2, '''Cooked the books'' = falsified accounts.', true, '2026-10-24 01:02:03.733', '2026-10-24 01:02:03.733', null, null, null, '(Choose the most appropriate interpretation). The accounts clerk was jailed because he <u>cooked the books</u>.', '["set fire to the account books","sold the books in his office to get money for food","<u>falsified the accounts to his advantage</u>","destroyed the account books by cooking them"]', '''<b>Cooked the books</b>'' = <b>falsified accounts</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd1b66f8-f541-41b3-967d-100a6839b79f', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'When Jesus was born, He was laid in a manger because', null, '["there was no place in the inn","It had been prophesied","His parents were poor","His parents wanted it so","He was of humble origin"]', 0, 'There was no room for them in the inn.', true, '2026-09-12 10:42:09.301', '2026-09-12 10:42:09.301', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd1c4c2d-bd75-40e7-8daf-3b7a11efdfa7', 'English Language', 'JAMB', null, 2024, null, 'According to the result from the research carried out by Roffo', null, '["Nicotine is a substance that easily causes cancer","A cigarette with no nicotine is safe for smokers","With or without nicotine, mere exposure to tars from tobacco may cause cancer","Tars from only cigarettes with nicotine may cause cancer"]', 2, 'Roffo''s research showed that tars from tobacco cause cancer regardless of nicotine content.', true, '2026-09-18 09:34:04.031', '2026-09-18 09:34:04.031', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd1e08fc-16f9-486d-ae17-a8e3e528e92b', 'Biology', 'JAMB', null, 2013, null, 'Which of the following describes a characteristic of arthropods?', null, '["The body is not divided into a number of segments","The body is covered by chitin","The organism finds it easy to grow freely","The organism has a pair of jointed appendages"]', 1, 'Arthropods have a body covered by chitin.', true, '2026-10-12 20:59:46.365', '2026-10-12 20:59:46.365', null, null, null, 'Which of the following describes a characteristic of arthropods?', '["The body is not divided into a number of segments","The body is covered by chitin","The organism finds it easy to grow freely","The organism has a pair of jointed appendages"]', 'Arthropods have a body covered by chitin.', '{"bold":["covered by chitin"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd2205c0-fe9b-4d60-8e7b-5c2fe1871143', 'Biology', 'JAMB', null, 2026, null, 'Which of the above are true regarding hypogeal germination? I. Hypocotyl elongates faster than the epicotyl II. Epicotyl elongates faster than hypocotyl III. Cotyledons are left within the soil IV. Cotyledons are carried above the soil', null, '["I & V","I & III","II & III","II & IV"]', 2, 'In hypogeal germination, the epicotyl elongates faster than the hypocotyl (II), and the cotyledons are left within the soil (III). The epicotyl elongates to push the plumule (first true leaves) above the soil while the cotyledons remain below ground. This is opposite to epigeal germination where the hypocotyl elongates faster and pushes the cotyledons above the soil. Hypogeal germination is typical of plants like maize, pea, and mango where the cotyledons stay underground and serve as nutrient sources during early seedling development.', true, '2026-09-09 03:18:36.811', '2026-09-09 03:18:36.811', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd2ea89e-1361-4c25-96a5-a76282a5d4f4', 'English Language', 'JAMB', null, 2007, null, 'I have applied for <u>__________</u> on the campus and I am almost certain I shall get it.', null, '["acommodation","accommodation","accomodation","accomoddation","accomodation"]', 1, 'Correct spelling: accommodation (double c, double m).', true, '2026-10-24 07:21:32.038', '2026-10-24 07:21:32.038', null, null, null, 'I have applied for <u>__________</u> on the campus and I am almost certain I shall get it.', '["acommodation","accommodation","accomodation","accomoddation","accomodation"]', 'Correct spelling: accommodation (double c, double m).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd41bcff-7e25-4b34-b73e-85a4ae1b54f5', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Why was Paul imprisoned in the Synagogue in Philippi?', null, '["for preaching in the synagogue","for arguing with roman guards","for opposing the worship of idols","for healing a possessed girl"]', 3, 'Paul and Silas were imprisoned in Philippi for healing a slave girl who had a spirit of divination. Her owners, who made money from her fortune-telling, accused Paul and Silas of disturbing the city.', true, '2026-09-12 09:45:51.618', '2026-09-12 09:45:51.618', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd4e3505-e4a0-45d2-8dda-d52d78b8897b', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following particles has no electric charge?', null, '["Proton","Electron","Neutron","Nucleon"]', 2, 'The neutron is electrically neutral (no charge). Protons are positively charged, electrons are negatively charged, and nucleons include both protons and neutrons.', true, '2026-09-12 11:32:52.939', '2026-09-12 11:32:52.939', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd4f27c9-54bc-4494-b64a-d225ff3a527d', 'Biology', 'JAMB', null, 2005, null, 'The organelle common to both plant and animal cells is the', null, '["centriole","plasmalemma","cell wall","chloroplast"]', 1, 'The plasmalemma (cell membrane) is found in both plant and animal cells.', true, '2026-10-12 20:05:11.657', '2026-10-12 20:05:11.657', null, null, null, 'The organelle common to both plant and animal cells is the', '["centriole","plasmalemma","cell wall","chloroplast"]', 'The plasmalemma (cell membrane) is found in both plant and animal cells.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd6008c0-8152-44e7-8b94-e5882df5f40d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). His attempts were <u>nipped in the bud</u>.', null, '["unsuccessful","cut short","frustrated","disqualified"]', 1, '''Nipped in the bud'' = stopped early.', true, '2026-10-24 01:04:16.537', '2026-10-24 01:04:16.537', null, null, null, '(Choose the most appropriate interpretation). His attempts were <u>nipped in the bud</u>.', '["unsuccessful","<u>cut short</u>","frustrated","disqualified"]', '''<b>Nipped in the bud</b>'' = <b>stopped early</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd67e01e-9c6b-4ad6-9ae3-23abf16bcbfe', 'Physics', 'JAMB', null, 2026, null, 'Rainbow is formed when sunlight undergoes', null, '["reflection","refraction","dispersion","diffraction"]', 2, 'A rainbow is formed when sunlight undergoes dispersion by water droplets in the atmosphere. The water droplets act as tiny prisms, splitting white light into its component colours. Refraction and reflection also occur, but the primary phenomenon is dispersion.', true, '2026-09-10 10:56:39.621', '2026-09-10 10:56:39.621', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd6a09c0-cc69-40a5-bf2a-1a580daf8391', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase "Sierra Leone won''t be worth a raped woman''s cry" expresses a sense of', null, '["Hope for the nation''s future","indifference towards the nation''s suffering","profound despair over the nation''s trauma","anger at the perpetrators of violence"]', 2, 'The phrase "Sierra Leone won''t be worth a raped woman''s cry" expresses a sense of profound despair over the nation''s trauma. It suggests that the nation''s value has been so degraded by violence and suffering that it cannot compensate for the pain inflicted on women. The phrase conveys deep sorrow and hopelessness about the nation''s condition, not hope, indifference, or mere anger.', true, '2026-09-10 10:47:54.462', '2026-09-10 10:47:54.462', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd73ca8d-c403-4cb7-bef0-7fbb9091bacf', 'Financial Accounting', 'UTME', null, 2002, null, 'The concise statement used to explain entries in general journal is known as', null, '["narration","summary","information","commentary"]', 0, 'The concise statement used to explain entries in general journal is known as narration.', true, '2026-10-12 21:59:57.335', '2026-10-12 21:59:57.335', null, null, null, 'The concise statement used to explain entries in general journal is known as', '["<b>narration</b>","summary","information","commentary"]', 'The concise statement used to explain entries in general journal is known as <b>narration</b>.', '{"bold":["narration"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd7b7a11-0568-4575-923f-9a30de4a29e3', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Samson, as a Nazirite, was required to avoid alcohol,...', null, '["women and dead lions","unclean things and shaving","shaving and swearing","shaving and women"]', 1, 'Numbers 6:1-8 and Judges 13 specify that Nazirites must refrain from grape products/alcohol, touching corpses/unclean things, and cutting their hair with a razor.', true, '2026-09-09 17:18:26.894', '2026-09-09 17:18:26.894', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd7ff127-53a0-403f-b7db-90a14298bb9d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The dancing troupe put up <u>a flawless</u> performance.', null, '["an interesting","an imperfect","a satisfactory","a careless"]', 1, 'Flawless = perfect; opposite = imperfect.', true, '2026-10-24 07:21:19.527', '2026-10-24 07:21:19.527', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The dancing troupe put up <u>a flawless</u> performance.', '["an interesting","an imperfect","a satisfactory","a careless"]', 'Flawless = perfect; opposite = imperfect.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd8d9bee-1f52-4e00-bca0-5165f6655521', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following is not allotrope of carbon?', null, '["diamond","graphite","buck minsterfullerene","all of the above","none of the above"]', 4, 'All listed are allotropes of carbon.', true, '2026-09-12 11:36:12.735', '2026-09-12 11:36:12.735', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd8f925b-5a3f-4983-8843-51c61a187a66', 'Biology', 'JAMB', null, 2011, null, 'Habitats are generally classified into', null, '["biotic and abiotic","aquatic and terrestrial","aboreal and marine biomes","microhabitats and microhabitats."]', 1, 'Habitats are classified into aquatic and terrestrial.', true, '2026-10-12 20:59:43.271', '2026-10-12 20:59:43.271', null, null, null, 'Habitats are generally classified into', '["biotic and abiotic","aquatic and terrestrial","aboreal and marine biomes","microhabitats and microhabitats."]', 'Habitats are classified into aquatic and terrestrial.', '{"bold":["aquatic and terrestrial"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd9d0148-6bab-4b78-b01e-a0ed2aca20a0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Before embarking on his current research, the professor carried out a <u>feasibility</u> study of the area.', null, '["thorough","perfectibility","complete","practicability"]', 3, 'Feasibility = practicability.', true, '2026-10-24 01:01:49.709', '2026-10-24 01:01:49.709', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Before embarking on his current research, the professor carried out a <u>feasibility</u> study of the area.', '["thorough","perfectibility","complete","<u>practicability</u>"]', '<b>Feasibility</b> = <b>practicability</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd9d320f-7b3c-4687-92a5-f5453095bf36', 'Physics', 'JAMB', null, 2002, null, 'Which of the following statements is true of the properties of a moving coil galvanometer?', null, '["It has a small number of turns of coil","There is a strong permanent magnet to give high magnetic flux","The coil has a small area.","There are strong hair springs to give a large control couple"]', 1, 'A moving coil galvanometer uses a strong permanent magnet (with a radial field) so that a small current gives a large deflection.', true, '2026-10-12 19:15:54.62', '2026-10-12 19:15:54.62', null, null, null, 'Which of the following statements is true of the properties of a moving coil galvanometer?', '["It has a small number of turns of coil","There is a strong permanent magnet to give high magnetic flux","The coil has a small area.","There are strong hair springs to give a large control couple"]', 'A moving coil galvanometer uses a strong permanent magnet (with a radial field) so that a small current gives a large deflection.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dd9f898d-c656-458b-bb5e-5b1447ac131a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The testimony of the witness was <u>vague</u>', null, '["disturbing","ambiguous","true","clear"]', 3, 'Vague = unclear; opposite = clear.', true, '2026-10-24 07:21:31.938', '2026-10-24 07:21:31.938', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The testimony of the witness was <u>vague</u>', '["disturbing","ambiguous","true","clear"]', 'Vague = unclear; opposite = clear.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ddad2369-f6ff-4857-bd7b-2fe6b394eff5', 'English Language', 'JAMB', null, 2007, null, 'Neither the chairman nor the board members <u>______</u> aware of the development.', null, '["was","is","are","has been"]', 2, 'Nearest subject ''members'' plural â†’ are.', true, '2026-10-24 01:02:16.059', '2026-10-24 01:02:16.059', null, null, null, 'Neither the chairman nor the board members <u>______</u> aware of the development.', '["was","is","<u>are</u>","has been"]', 'Nearest subject ''<b>members</b>'' plural â†’ <b>are</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ddb5f606-571a-481a-ac9a-21faf5211783', 'Physics', 'JAMB', null, 2026, null, 'The defect of the eye lens which occurs when the ciliary muscles are weak is', null, '["Spherical aberration","Astigmatism","Presbyopia","Myopia"]', 2, 'Presbyopia is the defect of the eye lens that occurs when the ciliary muscles are weak, usually with age. The lens loses its elasticity, making it difficult to focus on near objects. It is corrected with reading glasses (convex lenses).', true, '2026-09-10 10:56:39.405', '2026-09-10 10:56:39.405', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ddcc7687-33f5-4c06-a002-b2c302999324', 'Government', 'JAMB', null, 2026, null, 'Judges in the International Court of Justice are appointed for a period of .... years.', null, '["twelve","five","four","nine"]', 3, 'ICJ judges are appointed for 9 years.', true, '2026-09-12 11:24:29.561', '2026-09-12 11:24:29.561', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ddd5da14-d516-49cd-a609-8690bd192086', 'Physics', 'JAMB', null, 1986, null, 'The wavelength of ultraviolet radiation is 400 nm. If the speed of light in air is 3 x 10⁸ m s⁻¹, then the frequency of the ultraviolet radiation is', null, '["1.3 x 10⁻¹⁵ Hz","7.5 x 10⁵ Hz","1.2 x 10¹¹ Hz","7.5 x 10¹⁴ Hz."]', 3, 'f = c/λ = (3 x 10⁸)/(400 x 10⁻⁹) = 7.5 x 10¹⁴ Hz.', true, '2026-10-12 19:15:24.487', '2026-10-12 19:15:24.487', null, null, null, 'The wavelength of ultraviolet radiation is 400 nm. If the speed of light in air is 3 x 10<sup>8</sup> m s<sup>-1</sup>, then the frequency of the ultraviolet radiation is', '["1.3 x 10<sup>-15</sup> Hz","7.5 x 10<sup>5</sup> Hz","1.2 x 10<sup>11</sup> Hz","7.5 x 10<sup>14</sup> Hz."]', 'f = c/λ = (3 x 10<sup>8</sup>)/(400 x 10<sup>-9</sup>) = 7.5 x 10<sup>14</sup> Hz.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ddd83c44-06fd-45e4-906f-db9a2b805793', 'Physics', 'JAMB', null, 2026, null, 'Which of the following is the best absorber of x-ray?', null, '["lead","boron","oxygen","hydrogen"]', 0, 'Lead is the best absorber of X-rays. It has a high atomic number and high density, making it effective for shielding against X-rays and gamma rays. Lead aprons are used in radiology for protection.', true, '2026-09-10 10:56:41.193', '2026-09-10 10:56:41.193', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dddb3010-23bf-4ebe-b7e7-83fdbe2f0a80', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The response to the advertisement has been <u>phenomenal</u>.', null, '["spiritual","frightened","unimpressive","catastrophic"]', 2, 'Phenomenal = extraordinary; opposite = unimpressive.', true, '2026-10-24 07:21:28.106', '2026-10-24 07:21:28.106', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The response to the advertisement has been <u>phenomenal</u>.', '["spiritual","frightened","unimpressive","catastrophic"]', 'Phenomenal = extraordinary; opposite = unimpressive.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dddce05d-6c63-42d5-8d76-a59d1415b780', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Smiling broadly, she explained why she always <u>took exception to</u> being referred to as an old maid.', null, '["objected to","preferred very much","felt specially honoured by","liked nothing excepts"]', 0, '''Took exception to'' = objected to.', true, '2026-10-24 01:04:21.416', '2026-10-24 01:04:21.416', null, null, null, '(Choose the most appropriate interpretation). Smiling broadly, she explained why she always <u>took exception to</u> being referred to as an old maid.', '["<u>objected to</u>","preferred very much","felt specially honoured by","liked nothing excepts"]', '''<b>Took exception to</b>'' = <b>objected to</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dde7d5b9-fd57-4761-b737-8621357d4723', 'Physics', 'JAMB', null, 2026, null, 'The dielectric of a capacitor is used to', null, '["balance the energy","regulate the current flow","boost the voltage between the plate","increase the energy stored"]', 3, 'The dielectric of a capacitor is used to increase the energy stored. A dielectric material increases the capacitance by reducing the electric field between the plates, allowing more charge to be stored for the same voltage.', true, '2026-09-10 10:56:46.546', '2026-09-10 10:56:46.546', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ddec85c3-7f1d-4d51-b467-a68b74badad6', 'Literature in English', 'JAMB', null, 2026, null, 'CANTO in poetry is similar to in prose', null, '["Chapter","Paragraph","Sentence","Stanza"]', 0, 'CANTO in poetry is similar to a chapter in prose. A canto is a major division of a long poem, corresponding to a chapter in a novel. It is used in epic poems like Dante''s Divine Comedy and Byron''s Don Juan. A paragraph is a smaller unit, a sentence is a grammatical unit, and a stanza is a group of lines in a poem.', true, '2026-09-10 10:47:53.873', '2026-09-10 10:47:53.873', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ddf3bd2c-2dad-4050-b555-aadbd68e8b31', 'Physics', 'JAMB', null, 2003, null, 'In a semiconductor junction diode, as the depletion or barrier layer is forward-biased, the layer', null, '["Narrows","Remains constant","Widens then narrows","Widens"]', 0, 'Forward bias pushes charge carriers towards the junction, so the depletion layer becomes narrower.', true, '2026-10-12 19:15:57.493', '2026-10-12 19:15:57.493', null, null, null, 'In a semiconductor junction diode, as the depletion or barrier layer is forward-biased, the layer', '["Narrows","Remains constant","Widens then narrows","Widens"]', 'Forward bias pushes charge carriers towards the junction, so the depletion layer becomes narrower.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ddff3999-b27b-4296-8949-da09139ef429', 'Chemistry', 'JAMB', null, 2026, null, 'Diamond and graphite differ in hardness mainly because', null, '["graphite contains ionic bonds","graphite has layered structures held by weak forces","diamond contains free electrons","graphite forms metallic bonds"]', 1, 'Graphite has a layered structure where each layer is held together by weak van der Waals forces. These layers can slide over each other, making graphite soft and slippery. Diamond has a rigid three-dimensional covalent network, making it extremely hard.', true, '2026-09-12 09:38:11.595', '2026-09-12 09:38:11.595', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('de000384-6c45-43be-83f4-afb6c15d69fe', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''no room for elders'' signifies', null, '["retirement from family","hatred of old age","rejection of traditional authority","disagreement with community leaders"]', 2, 'The phrase signifies rejection of traditional authority.', true, '2026-09-12 11:10:41.901', '2026-09-12 11:10:41.901', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('de090740-05f7-4f56-9f34-ef5221251591', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The retired army officer did <u>a yeoman''s service to the nation</u>', null, '["His activity brought disrepute to the nation","His service to the nation was not exemplary","He was showered with the responsibility of the yeoman","He was very loyal to the nation"]', 3, '''Yeoman''s service'' = valuable, loyal service.', true, '2026-10-24 01:02:10.152', '2026-10-24 01:02:10.152', null, null, null, '(Choose the most appropriate interpretation). The retired army officer did <u>a yeoman''s service to the nation</u>', '["His activity brought disrepute to the nation","His service to the nation was not exemplary","He was showered with the responsibility of the yeoman","<u>He was very loyal to the nation</u>"]', '''<b>Yeoman''s service</b>'' = <b>valuable, loyal service</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('de103174-4125-4c0e-b515-8fd17ad4a5fd', 'Physics', 'JAMB', null, 2026, null, 'In a series R-L-C circuit at resonance, impedance is', null, '["maximum","Minimum","capacitive","inductive"]', 1, 'In a series R-L-C circuit at resonance, impedance is minimum. At resonance, the inductive reactance equals the capacitive reactance (XL = XC), so they cancel each other out. The impedance is then purely resistive and at its minimum value (Z = R).', true, '2026-09-10 10:56:38.919', '2026-09-10 10:56:38.919', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('de1bce29-b1ff-47b5-85a4-92eac6f0107a', 'English Language', 'JAMB', null, 2007, null, '<u>__________</u> bomb had earlier been defused', null, '["A leaf","An alive","A life","A live"]', 3, 'Correct form: A live bomb.', true, '2026-10-24 07:21:37.275', '2026-10-24 07:21:37.275', null, null, null, '<u>__________</u> bomb had earlier been defused', '["A leaf","An alive","A life","A live"]', 'Correct form: A live bomb.', '{}');
