insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('de684ae4-6634-4b90-98bb-5649249bb82c', 'Economics', 'JAMB', null, 2026, null, 'The supply and demand for goods and services are influenced by the', null, '["supermarket","entrepreneurs","mechanism of the law","price mechanism"]', 3, 'The supply and demand for goods and services are influenced by the price mechanism. The price mechanism is the system where prices are determined by the interaction of demand and supply, and these prices in turn influence the allocation of resources. When demand exceeds supply, prices rise, encouraging more supply and reducing demand. When supply exceeds demand, prices fall. This is the invisible hand at work.', true, '2026-09-10 10:42:55.454', '2026-09-10 10:42:55.454', null, null, null, null, null, null, null);
