insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ded2dd21-293a-4e38-9bc2-83aaed45cab2', 'Physics', 'JAMB', null, 1997, null, 'If the load at the end of a sonometer wire is immersed in a bucket of water, the original fundamental frequency of the wire could be restored by', null, '["Decreasing the length of the wire","Increasing the length of the wire","Increasing the mass per unit length of the wire","Changing the temperature of the water."]', 0, 'Immersion reduces the tension (upthrust), which lowers the frequency. Since f is inversely proportional to length, shortening the wire raises the frequency back.', true, '2026-10-12 19:15:43.853', '2026-10-12 19:15:43.853', null, null, null, 'If the load at the end of a sonometer wire is immersed in a bucket of water, the original fundamental frequency of the wire could be restored by', '["Decreasing the length of the wire","Increasing the length of the wire","Increasing the mass per unit length of the wire","Changing the temperature of the water."]', 'Immersion reduces the tension (upthrust), which lowers the frequency. Since f is inversely proportional to length, shortening the wire raises the frequency back.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
