insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('df3201cc-6fdf-4145-8e17-af84cd936f62', 'Chemistry', 'JAMB', null, 2026, null, 'Which metal would not react with dilute hydrochloric acid under normal conditions?', null, '["Zinc","Iron","Copper","Magnesium"]', 2, 'Copper does not react with dilute hydrochloric acid because it is below hydrogen in the reactivity series. Zinc, iron, and magnesium are all above hydrogen and react with dilute HCl to produce hydrogen gas.', true, '2026-09-12 09:38:14.49', '2026-09-12 09:38:14.49', null, null, null, null, null, null, null);
