insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('df55f2be-fc2a-436b-84ca-36010579bcdd', 'Chemistry', 'JAMB', null, 2026, null, 'The main reason why graphite conducts electricity is because', null, '["it contains free protons","each carbon atom has a free electron","of strong covalent bonds","of weak van der Waals forces"]', 1, 'Each carbon atom in graphite bonds to three others in sp2 hybridization, leaving one unbonded delocalized electron per carbon atom to conduct charge.', true, '2026-09-09 17:12:49.468', '2026-09-09 17:12:49.468', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('df58b1f7-6373-4572-9f7f-8c83590fe83a', 'Literature in English', 'JAMB', null, 2026, null, 'The poem suggests that language is important because it', null, '["determines economic success","preserves culture and identity","helps people travel","improves political leadership"]', 1, 'Language preserves culture and identity.', true, '2026-09-12 11:10:24.402', '2026-09-12 11:10:24.402', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('df5a7bc4-9cf5-4c69-8ced-2b15faa7e972', 'Financial Accounting', 'UTME', null, 2004, null, 'Given: Purchases ledger balance Purchases for the period Cash refunded by suppliers Cheques paid to suppliers Returns outwards Discount received from suppliers. The balance of the purchases ledger control account is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841790/questions/xlgim3wsfmjsybqitixw.jpg', '["N10 390","N9 990","N9 590","N9 010"]', 3, 'Purchases Ledger Control Account: Cash Refunded 290, Bal b/d, Cash 42300, Purchases, Return Outward 2000, Discount Received 400, Bal c/d 9010.', true, '2026-10-12 22:00:02.64', '2026-10-12 22:00:02.64', null, null, null, 'Given: Purchases ledger balance Purchases for the period Cash refunded by suppliers Cheques paid to suppliers Returns outwards Discount received from suppliers. The balance of the purchases ledger control account is', '["N10 390","N9 990","N9 590","<b>N9 010</b>"]', 'Purchases Ledger Control Account: Cash Refunded 290, Bal b/d, Cash 42300, Purchases, Return Outward 2000, Discount Received 400, Bal c/d <b>9010</b>.', '{"bold":["9010"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('df64c73b-0131-4219-81d7-522beda5dbe9', 'English Language', 'JAMB', null, 2024, null, '34', null, '["blood","heat","water","sugar"]', 1, 'The liver produces heat.', true, '2026-09-18 10:17:48.941', '2026-09-18 10:17:48.941', '5c9f355e-7680-453e-a8bf-38eba91547e7', 10, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('df821848-4db2-479b-9851-486566ba9fee', 'Economics', 'JAMB', null, 2026, null, 'An electrical engineer who is teaching physics in a secondary school is said to be', null, '["Unemployed","Fully employed","Technologically employed","Underemployed"]', 3, 'An engineer teaching physics is underemployed (working below qualification).', true, '2026-09-12 11:02:14.163', '2026-09-12 11:02:14.163', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('df82bb2c-1f42-4d59-af19-700611a4adcb', 'Physics', 'JAMB', null, 2026, null, 'The distance between two successive trough points of a wave is', null, '["two wavelength","a wavelength","one third wavelength","half wavelength"]', 1, 'The distance between two successive trough points of a wave is one wavelength. The wavelength is the distance between any two consecutive points in phase, such as crest to crest, trough to trough, or compression to compression.', true, '2026-09-10 10:56:39.836', '2026-09-10 10:56:39.836', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('df8eca8e-6ad8-4a5a-8777-63f22b784bf3', 'Government', 'JAMB', null, 2026, null, 'All the following are types of elections except', null, '["Recall","General election","Shadow elections","Bye-elections"]', 2, 'Shadow elections are not a type of election. The main types of elections include general elections (held at regular intervals for all seats), bye-elections (held to fill a vacancy), primary elections (to select party candidates), and recall elections (to remove an official before the end of their term). Shadow elections are not a recognized type of election in political science.', true, '2026-09-10 10:45:06.036', '2026-09-10 10:45:06.036', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('df90117d-a6ec-41e6-9038-ea2863fb8f35', 'Literature in English', 'JAMB', null, 2026, null, 'The extract conveys a mood of', null, '["Dejection","Desperation","Resentment","Resignation"]', 1, 'The extract conveys desperation.', true, '2026-09-12 11:13:52.503', '2026-09-12 11:13:52.503', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('df924d6a-2718-4bbb-9e55-9d26550620b2', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). If experience is anything to go by, this action will prove <u>a political minefield</u>.', null, '["a sources of political benefits","a way out of political trouble","a causes for political joy","an invitation to political problems"]', 3, '''A political minefield'' = invitation to political problems.', true, '2026-10-24 01:04:22.117', '2026-10-24 01:04:22.117', null, null, null, '(Choose the most appropriate interpretation). If experience is anything to go by, this action will prove <u>a political minefield</u>.', '["a sources of political benefits","a way out of political trouble","a causes for political joy","<u>an invitation to political problems</u>"]', '''A <b>political minefield</b>'' = <b>invitation to political problems</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('df94bf56-559f-48f6-a6f3-fc87a39475e7', 'Physics', 'JAMB', null, 1994, null, 'A spring of length 25 cm is extended to 30 cm by a load of 150 N attached to one of its ends. What is the energy stored in the spring?', null, '["3750 J","2500 J","3.75 J","2.50 J"]', 2, 'Extension = 5 cm = 0.05 m. Energy = ½Fx = ½ x 150 x 0.05 = 3.75 J.', true, '2026-10-12 19:15:39.157', '2026-10-12 19:15:39.157', null, null, null, 'A spring of length 25 cm is extended to 30 cm by a load of 150 N attached to one of its ends. What is the energy stored in the spring?', '["3750 J","2500 J","3.75 J","2.50 J"]', 'Extension = 5 cm = 0.05 m. Energy = ½Fx = ½ x 150 x 0.05 = 3.75 J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dfbac82c-ea80-40a6-98ea-27c5e0f62e12', 'Biology', 'JAMB', null, 2026, null, 'The fallacy in Lamarck''s evolutionary theory was the assumption that', null, '["acquired traits are seldom formed","traits are acquired through the use of body parts","traits are acquired through the disuse of body parts","acquired traits are heritable"]', 3, 'The fallacy in Lamarck''s evolutionary theory was the assumption that acquired traits are heritable. Lamarck believed that traits acquired during an organism''s lifetime (like muscles developed through exercise) could be passed on to offspring. This is incorrect because acquired characteristics are not encoded in the gametes (sperm or eggs). Evolution occurs through changes in the genetic makeup of a population, not through acquired traits. This is why Lamarck''s theory was rejected.', true, '2026-09-09 03:19:23.873', '2026-09-09 03:19:23.873', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dfbb64ec-3d20-4d5d-80a1-5608d36b9c24', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Adamu woke up with a start and took to his heels, claiming that something was <u>on his trial</u>.', null, '["in his food","giving him the chase","hiding near the bed","staring at him"]', 1, '''On his trail'' = chasing him.', true, '2026-10-24 01:04:22.385', '2026-10-24 01:04:22.385', null, null, null, '(Choose the most appropriate interpretation). Adamu woke up with a start and took to his heels, claiming that something was <u>on his trial</u>.', '["in his food","<u>giving him the chase</u>","hiding near the bed","staring at him"]', '''<b>On his trail</b>'' = <b>chasing him</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dfcaec6b-cb6d-45eb-9b5c-2d96092ce616', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He lost his voice <u>momentarily</u>.', null, '["in a moment","in a split second","for a brief period of time","without delay","instantly"]', 2, 'Momentarily = for a brief period.', true, '2026-10-24 01:03:53.651', '2026-10-24 01:03:53.651', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He lost his voice <u>momentarily</u>.', '["in a moment","in a split second","<u>for a brief period of time</u>","without delay","instantly"]', '<b>Momentarily</b> = <b>for a brief period</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dfd1d015-ac68-4f87-9fae-c8c8c72061b7', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'God stopped Abraham from sacrificing his son in the land of Moriah because He...', null, '["was enraged at human sacrifice","loved Isaac","preferred Ishmael","was convinced of his obedience"]', 3, 'Genesis 22:12 states: ''Do not lay your hand on the lad... for now I know that you fear God, seeing you have not withheld your son, your only son, from Me.''', true, '2026-09-09 17:18:26.292', '2026-09-09 17:18:26.292', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dfd8a568-12bd-4d51-8ae8-0d0af774b9aa', 'Economics', 'JAMB', null, 2026, null, 'Which of these is not the role of government in agricultural development', null, '["Provision of credit facilities","Establishment of agricultural programmes","Building farmer''s house","Provision of farm''s input"]', 2, 'Building farmers'' houses is not a role of government in agricultural development.', true, '2026-09-12 11:00:33.605', '2026-09-12 11:00:33.605', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('dfd97c4f-dd4b-4074-9355-12c39e0de140', 'Biology', 'JAMB', null, 2011, null, 'The number of alleles controlling blood groups in humans is', null, '["3","4","5","2."]', 0, 'There are 3 alleles controlling blood groups in humans.', true, '2026-10-12 20:59:43.777', '2026-10-12 20:59:43.777', null, null, null, 'The number of alleles controlling blood groups in humans is', '["3","4","5","2."]', 'There are 3 alleles controlling blood groups in humans.', '{"bold":["3"],"italic":[],"underline":[],"fillBlanks":[]}');
