insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e03383d6-30da-4413-b231-5265f90bdead', 'testing', 'JAMB', null, 2024, null, 'Which of the following sentences is correct: A. She has ran five times today B. She has run five times today C. She has being running five times daily D. She has ranned five times today', null, '["She has ran five times today","She has run five times today","She has being running five times daily","She has ranned five times today"]', 1, 'Past participle of ''run'' is ''run''.', true, '2026-10-31 16:48:53.107', '2026-10-31 16:48:53.107', null, null, null, 'Which of the following sentences is correct: A. She has ran five times today B. She has run five times today C. She has being running five times daily D. She has ranned five times today', '["She has ran five times today","She has run five times today","She has being running five times daily","She has ranned five times today"]', 'Past participle of ''run'' is ''run''.', '{}');
