insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e06bc99c-9e23-4a88-ba62-96fb2c07cd4f', 'English Language', 'JAMB', null, 2024, null, 'The phrase the annulment and the phrase ______ in the passage are synonymous', null, '["the advent","a respite","a positive reversal","the cancellation"]', 3, '"The annulment" and "the cancellation" are synonymous.', true, '2026-09-18 09:24:04.93', '2026-09-18 09:24:04.93', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e072df55-5398-40d7-b542-156e432ed9c8', 'Physics', 'JAMB', null, 2002, null, 'The energy associated with the photon of a radio transmission at 3 x 10⁵ Hz is (h = 6.63 x 10⁻³⁴ J s)', null, '["2.00 x 10⁻²⁹ J","2.00 x 10⁻²⁸ J","1.30 x 10⁻²⁹ J","1.30 x 10⁻²⁸ J"]', 1, 'E = hf = 6.63 x 10⁻³⁴ x 3 x 10⁵ ≈ 2.0 x 10⁻²⁸ J.', true, '2026-10-12 19:15:54.78', '2026-10-12 19:15:54.78', null, null, null, 'The energy associated with the photon of a radio transmission at 3 x 10<sup>5</sup> Hz is (h = 6.63 x 10<sup>-34</sup> J s)', '["2.00 x 10<sup>-29</sup> J","2.00 x 10<sup>-28</sup> J","1.30 x 10<sup>-29</sup> J","1.30 x 10<sup>-28</sup> J"]', 'E = hf = 6.63 x 10<sup>-34</sup> x 3 x 10<sup>5</sup> ≈ 2.0 x 10<sup>-28</sup> J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
