insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e0aa88ce-3cb0-46cb-8b53-430819f2206d', 'Physics', 'JAMB', null, 2026, null, 'Which of the following travels in a vacuum with a velocity different from that of light?', null, '["radio wave","alpha particles","x rays","ultra violet radiation","gamma rays"]', 1, 'Alpha particles travel in a vacuum with a velocity different from that of light. They are helium nuclei with mass and travel at speeds much less than the speed of light. Radio waves, X-rays, UV radiation, and gamma rays are all electromagnetic waves that travel at the speed of light.', true, '2026-09-10 10:56:40.598', '2026-09-10 10:56:40.598', null, null, null, null, null, null, null);
