insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e0b2c08b-bab9-4b15-99df-e52b3f8f39ac', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Ola thought that her father was very <u>callous</u>.', null, '["parlous","wicked","compassionate","cheerful"]', 2, 'Callous = unfeeling; opposite = compassionate.', true, '2026-10-24 07:21:27.403', '2026-10-24 07:21:27.403', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Ola thought that her father was very <u>callous</u>.', '["parlous","wicked","compassionate","cheerful"]', 'Callous = unfeeling; opposite = compassionate.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e0b682b9-1c35-4c60-837e-6f7fa3eef63e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The President gave another <u>extemporaneous</u> speech last Friday.', null, '["fascinating","unfavourable","unprepared","planned"]', 3, 'Extemporaneous = impromptu; opposite = planned.', true, '2026-10-24 07:21:23.514', '2026-10-24 07:21:23.514', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The President gave another <u>extemporaneous</u> speech last Friday.', '["fascinating","unfavourable","unprepared","planned"]', 'Extemporaneous = impromptu; opposite = planned.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e0b8d488-0d8d-428e-bfd9-5ef5690ca007', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. ''It is very difficult to know who is <u>entitled to</u> essential commodities these days'', observed the mobbed NNSC official.', null, '["qualified for","disqualified from","eligible","worthy of"]', 0, 'Entitled to = qualified for.', true, '2026-10-24 01:01:42.604', '2026-10-24 01:01:42.604', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. ''It is very difficult to know who is <u>entitled to</u> essential commodities these days'', observed the mobbed NNSC official.', '["<u>qualified for</u>","disqualified from","eligible","worthy of"]', '<b>Entitled to</b> = <b>qualified for</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e0beef01-47a8-4795-b086-f4f603d1d944', 'Physics', 'JAMB', null, 1990, null, 'A stone of mass m kg is held h metres above the floor for 50 s. The work done in joules over the period is', null, '["mh","mgh","mgh/50","0"]', 3, 'Work = force x distance moved. The stone does not move, so no work is done.', true, '2026-10-12 19:15:30.547', '2026-10-12 19:15:30.547', null, null, null, 'A stone of mass m kg is held h metres above the floor for 50 s. The work done in joules over the period is', '["mh","mgh","mgh/50","0"]', 'Work = force x distance moved. The stone does not move, so no work is done.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e0ce6b92-e022-4085-ac1c-e5a630c96683', 'Biology', 'JAMB', null, 2004, null, 'A peculiar characteristic of mammals is that they', null, '["have teeth","are warm-blooded","have lungs","have sebaceous glands"]', 3, 'Sebaceous glands are unique to mammals.', true, '2026-10-12 20:59:34.66', '2026-10-12 20:59:34.66', null, null, null, 'A peculiar characteristic of mammals is that they', '["have teeth","are warm-blooded","have lungs","have sebaceous glands"]', 'Sebaceous glands are unique to mammals.', '{"bold":["Sebaceous glands"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e0ce9238-5b0d-43d5-a095-7f7cfa37ca37', 'Financial Accounting', 'UTME', null, 2001, null, 'What is the bar profits?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791842130/questions/gpedxvu4x3inu0rm2qq5.jpg', '["N20,000","N15,000","N14,000","N10,000"]', 2, 'Bar profits = Bar sales 50,000 - Opening stock 10,000 - Bar credit purchases 40,000 + Closing stock 15,000 - Bar expenses 1,000 = 14,000.', true, '2026-10-12 22:00:05.892', '2026-10-12 22:00:05.892', null, null, null, 'What is the bar profits?', '["N20,000","N15,000","<b>N14,000</b>","N10,000"]', 'Bar profits = Bar sales 50,000 - Opening stock 10,000 - Bar credit purchases 40,000 + Closing stock 15,000 - Bar expenses 1,000 = <b>14,000</b>.', '{"bold":["14,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e0e7bd57-da18-4e5d-a935-89061ff4d9ad', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the probability of a 4 turning up at least once in two tosses of a fair die.', null, '["5/36","11/36","1/9","2/9"]', 1, 'P(at least one 4) = 1 - P(no 4) = 1 - (5/6)² = 1 - 25/36 = 11/36.', true, '2026-09-12 11:43:57.253', '2026-09-12 11:43:57.253', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e0ed64c0-a114-4be3-ac3a-23b594781921', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The new employee is so humble and friendly that he will soon <u>make himself popular</u>.', null, '["welcomed and accepted","hated","estranged","rejected","a personal friend"]', 0, 'Make himself popular = welcomed and accepted.', true, '2026-10-24 01:01:40.47', '2026-10-24 01:01:40.47', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The new employee is so humble and friendly that he will soon <u>make himself popular</u>.', '["<u>welcomed and accepted</u>","hated","estranged","rejected","a personal friend"]', '<b>Make himself popular</b> = <b>welcomed and accepted</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e0f38fd1-9171-48ca-a987-b105d8fe4430', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'For how many years had the lame man at the pool of Bethesda been waiting for help?', null, '["20","39","40","48","38"]', 4, 'The lame man had been ill for 38 years (John 5:5).', true, '2026-09-12 10:42:17.069', '2026-09-12 10:42:17.069', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1008cc7-884b-4534-a22d-3805407c9cf9', 'Physics', 'JAMB', null, 1998, null, 'The force of repulsion between two point positive charges 5 μC and 8 μC separated at a distance of 0.02 m apart is', null, '["1.8 x 10⁻¹⁰ N","9.0 x 10⁻⁸ N","9.0 x 10² N","4.5 x 10³ N"]', 2, 'F = kq₁q₂/r² = (9 x 10⁹ x 5 x 10⁻⁶ x 8 x 10⁻⁶)/(0.02)² = 0.36/(4 x 10⁻⁴) = 9.0 x 10² N.', true, '2026-10-12 19:15:46.323', '2026-10-12 19:15:46.323', null, null, null, 'The force of repulsion between two point positive charges 5 μC and 8 μC separated at a distance of 0.02 m apart is', '["1.8 x 10<sup>-10</sup> N","9.0 x 10<sup>-8</sup> N","9.0 x 10<sup>2</sup> N","4.5 x 10<sup>3</sup> N"]', 'F = kq<sub>1</sub>q<sub>2</sub>/r<sup>2</sup> = (9 x 10<sup>9</sup> x 5 x 10<sup>-6</sup> x 8 x 10<sup>-6</sup>)/(0.02)<sup>2</sup> = 0.36/(4 x 10<sup>-4</sup>) = 9.0 x 10<sup>2</sup> N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e123989f-9112-4bbb-b45e-530029899c40', 'Biology', 'JAMB', null, 2003, null, 'Hermaphroditic reproduction can be found among the', null, '["arthropods and nematodes","pisces and amphibians","annelids and molluscs","coelenterates and platyhelminthes"]', 2, 'Annelids (like earthworms) and many molluscs possess both male and female reproductive organs.', true, '2026-10-12 20:05:09.35', '2026-10-12 20:05:09.35', null, null, null, 'Hermaphroditic reproduction can be found among the', '["arthropods and nematodes","pisces and amphibians","annelids and molluscs","coelenterates and platyhelminthes"]', 'Annelids (like earthworms) and many molluscs possess both male and female reproductive organs.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e12548a2-2bfc-413a-a13c-7ae998e97e37', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The elderly often <u>fulminate against</u> the apparent indolence of the young generation.', null, '["protest bitterly about","complain seriously about","promote vigorously","commend warmly"]', 3, 'Fulminate against = condemn; opposite = commend.', true, '2026-10-24 07:21:16.07', '2026-10-24 07:21:16.07', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The elderly often <u>fulminate against</u> the apparent indolence of the young generation.', '["protest bitterly about","complain seriously about","promote vigorously","commend warmly"]', 'Fulminate against = condemn; opposite = commend.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e12848f3-af5e-46da-aad1-ea1de347d849', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>Recreation</u> is important in contemporary civilization.', null, '["Leisure","Treasure","Freedom","Pleasure"]', 0, 'Recreation = leisure.', true, '2026-10-24 01:03:59.315', '2026-10-24 01:03:59.315', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>Recreation</u> is important in contemporary civilization.', '["<u>Leisure</u>","Treasure","Freedom","Pleasure"]', '<b>Recreation</b> = <b>Leisure</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1298421-324e-45f4-91d2-b691654a0860', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The twelve and seventy disciples were primarily sent out by Jesus to', null, '["restore and minister salvation","preach the gospel","heal the sick and prophesy","cast and bind demons","deliver"]', 1, 'They were sent to preach the gospel and heal the sick.', true, '2026-09-12 10:42:11.183', '2026-09-12 10:42:11.183', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1339a37-9a3c-48c7-a733-4b8f18d9c8a8', 'Financial Accounting', 'UTME', null, 2004, null, 'A piece of equipment costing N120 000 was purchased on 1/1/1996. Depreciation was provided at 20% per annum on a straight-line basis. It was sold on 30/6/1999 for N31 500. The accumulated depreciation provision at the time of sale was', null, '["N12 000","N60 000","N72 000","N84 000"]', 3, '20% of 120,000 = 24,000. Accumulated depreciation for three and half years: 24,000 + 24,000 + 24,000 + 12,000 = 84,000.', true, '2026-10-12 22:00:02.394', '2026-10-12 22:00:02.394', null, null, null, 'A piece of equipment costing N120 000 was purchased on 1/1/1996. Depreciation was provided at 20% per annum on a straight-line basis. It was sold on 30/6/1999 for N31 500. The accumulated depreciation provision at the time of sale was', '["N12 000","N60 000","N72 000","<b>N84 000</b>"]', '20% of 120,000 = 24,000. Accumulated depreciation for three and half years: 24,000 + 24,000 + 24,000 + 12,000 = <b>84,000</b>.', '{"bold":["84,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e135dfa8-5292-4552-bdd4-629e1493c9b9', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The sudden death of the King <u>put paid to</u> the ambition of the Minister.', null, '["encouraged","rewarded","benefited","terminated"]', 3, '''Put paid to'' = terminated.', true, '2026-10-24 01:02:06.01', '2026-10-24 01:02:06.01', null, null, null, '(Choose the most appropriate interpretation). The sudden death of the King <u>put paid to</u> the ambition of the Minister.', '["encouraged","rewarded","benefited","<u>terminated</u>"]', '''<b>Put paid to</b>'' = <b>terminated</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e142a9f7-5510-4ff7-bf6a-4db78d4990b4', 'English Language', 'JAMB', null, 2007, null, 'When we looked up, we <u>__________</u> the plane some miles away.', null, '["cited","sited","sighted","site"]', 2, 'Correct spelling: sighted.', true, '2026-10-24 07:21:36.269', '2026-10-24 07:21:36.269', null, null, null, 'When we looked up, we <u>__________</u> the plane some miles away.', '["cited","sited","sighted","site"]', 'Correct spelling: sighted.', '{}');
