insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e149f973-2689-45ee-9086-8187910538a0', 'Biology', 'JAMB', null, 2010, null, 'Which of the following is true of the transverse section of a dicot stem?', null, '["The epidermis is completely encircled by the cortex.","The xylem is more interiorly located than the phloem.","The cambium lies between the cortex and the vascular bundles.","The vascular bundles are randomly scattered within the cortex."]', 1, 'In a dicot stem, the xylem is more interiorly located than the phloem.', true, '2026-10-12 20:59:39.221', '2026-10-12 20:59:39.221', null, null, null, 'Which of the following is true of the transverse section of a dicot stem?', '["The epidermis is completely encircled by the cortex.","The xylem is more interiorly located than the phloem.","The cambium lies between the cortex and the vascular bundles.","The vascular bundles are randomly scattered within the cortex."]', 'In a dicot stem, the xylem is more interiorly located than the phloem.', '{"bold":["xylem is more interiorly located than the phloem"],"italic":[],"underline":[],"fillBlanks":[]}');
