insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e15dff46-6f12-4385-aaf3-1fa3e4b16821', 'Biology', 'JAMB', null, 2001, null, 'The transportation of oxygen and carbon (IV) oxide in mammals is carried out by', null, '["phagocytes","leucocytes","erythrocytes","thrombocytes"]', 2, 'Erythrocytes (red blood cells) transport oxygen and carbon dioxide.', true, '2026-10-12 20:59:28.487', '2026-10-12 20:59:28.487', null, null, null, 'The transportation of oxygen and carbon (IV) oxide in mammals is carried out by', '["phagocytes","leucocytes","erythrocytes","thrombocytes"]', 'Erythrocytes (red blood cells) transport oxygen and carbon dioxide.', '{"bold":["Erythrocytes"],"italic":[],"underline":[],"fillBlanks":[]}');
