insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e162b587-206c-45c7-971a-190104068614', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. I was advised to stay away from cities that are <u>ravaged by crime</u>.', null, '["spoilt by","free from","suffering from","haven of"]', 1, 'Ravaged by crime; opposite = free from.', true, '2026-10-24 07:21:17.449', '2026-10-24 07:21:17.449', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. I was advised to stay away from cities that are <u>ravaged by crime</u>.', '["spoilt by","free from","suffering from","haven of"]', 'Ravaged by crime; opposite = free from.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e16e4a9d-2be9-4632-9d6f-b0bb45c441a7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. This is an <u>abridged</u> edition of Oliver Twist.', null, '["reprinted","enlarged","outdated","extinct","banned"]', 1, 'Abridged = shortened; opposite = enlarged.', true, '2026-10-24 07:21:11.217', '2026-10-24 07:21:11.217', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. This is an <u>abridged</u> edition of Oliver Twist.', '["reprinted","enlarged","outdated","extinct","banned"]', 'Abridged = shortened; opposite = enlarged.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e16f434d-0f04-4d31-8093-268384fb46ce', 'Literature in English', 'JAMB', null, 2026, null, 'The poem''s setting is most likely during a period of', null, '["economic prosperity and national unity","democratic transition and political stability","military dictatorship and civil unrest","social reform and judicial independence"]', 2, 'The setting is during military dictatorship and civil unrest.', true, '2026-09-12 11:10:39.631', '2026-09-12 11:10:39.631', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e16f8965-afb7-462e-a7e8-d07cb1ed03a8', 'Chemistry', 'JAMB', null, 2026, null, 'The ion that can be used as an oxidizing agent is?', null, '["Fe³⁺","F⁻","Ca²⁺","Au³⁺"]', 0, 'Fe³⁺ can act as an oxidizing agent.', true, '2026-09-12 11:36:24.256', '2026-09-12 11:36:24.256', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e17c8003-fe3a-4c77-afdc-b2c14f69350b', 'Biology', 'JAMB', null, 2026, null, 'When a sickle cell carrier marries a normal woman the probability of them having a normal offspring is', null, '["0.75","0.25","0.5","1"]', 2, 'When a sickle cell carrier (AS) marries a normal woman (AA), the probability of having a normal offspring is 50% (0.5). The cross is AS × AA. The possible offspring genotypes are: AS (50%) and AA (50%). The AS offspring are carriers (not affected), and the AA offspring are normal. Both are phenotypically normal. None of the offspring will have sickle cell disease (SS). The probability of a child being a carrier is 50%, and the probability of being completely normal is 50%, so the probability of a normal offspring overall is 100%, but the probability of a non-carrier normal (AA) is 50%.', true, '2026-09-09 03:18:52.168', '2026-09-09 03:18:52.168', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1871c29-e169-4a8d-9f69-3fc8ab72b1b2', 'Hausa', 'JAMB', null, 2010, null, 'Mene ne jigon Jatau Na Kyallu na S. Makarfi?', null, '["Auren karuwa.","Butulcin mata.","Neman haihuwa.","Neman karuwa."]', 0, 'Jigon wasan shi ne auren karuwa.', true, '2026-10-13 10:37:25.643', '2026-10-13 10:37:25.643', null, null, null, 'Mene ne jigon Jatau Na Kyallu na S. Makarfi?', '["Auren karuwa.","Butulcin mata.","Neman haihuwa.","Neman karuwa."]', 'Jigon wasan shi ne auren karuwa.', '{"bold":["auren karuwa"],"italic":[],"underline":[],"fillBlanks":[]}');
