insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e19d040b-a278-4877-9298-3bef9afa59b2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Joke gave Muhammed <u>a jaunty</u> smile', null, '["a discouraging","an inviting","a frightful","a cheerful"]', 3, 'Jaunty = cheerful.', true, '2026-10-24 01:04:12.241', '2026-10-24 01:04:12.241', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Joke gave Muhammed <u>a jaunty</u> smile', '["a discouraging","an inviting","a frightful","<u>a cheerful</u>"]', '<b>Jaunty</b> = <b>a cheerful</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e19ec587-31f8-4ce2-b239-63e373e3ac77', 'English Language', 'JAMB', null, 2007, null, 'Ndem was suspended from work because he showed no <u>__________</u> in dealing with the customers', null, '["love","interest","character","finesse"]', 3, 'Correct spelling: finesse.', true, '2026-10-24 07:21:45.475', '2026-10-24 07:21:45.475', null, null, null, 'Ndem was suspended from work because he showed no <u>__________</u> in dealing with the customers', '["love","interest","character","finesse"]', 'Correct spelling: finesse.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1a8b775-6f1f-4a47-a9cd-2382f13c75fb', 'English Language', 'JAMB', null, 2024, null, 'Choose the option that has the same consonant sound: Yan', null, '["physics","of","off","often"]', 0, 'The "y" in "Yan" sounds like /j/, same as the "ph" in "physics."', true, '2026-09-18 09:43:02.925', '2026-09-18 09:43:02.925', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1b190a7-9011-451b-b2ee-c0f54120999d', 'Literature in English', 'JAMB', null, 2026, null, '''Anansewa- a! where is that typewriter I bought for you at a price that nearly drove me to sell myself?'' This statement depicts', null, '["the abundant state of Ananse''s wealth","the struggle behind living up to standard","the hand-to-mouth feeding status of Ananse''s family","the nonchalant nature of Anansewa"]', 1, 'It depicts the struggle behind living up to standard.', true, '2026-09-12 11:10:00.637', '2026-09-12 11:10:00.637', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1b8c36a-f021-458c-96af-4be9af449552', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Amedu''s actions <u>provoked severe criticism</u>', null, '["His actions were seriously rejected","His actions were severe and accepted","His actions were itemized because he was young","His actions provoked the humour"]', 0, '''Provoked severe criticism'' = seriously rejected.', true, '2026-10-24 01:02:10.634', '2026-10-24 01:02:10.634', null, null, null, '(Choose the most appropriate interpretation). Amedu''s actions <u>provoked severe criticism</u>', '["<u>His actions were seriously rejected</u>","His actions were severe and accepted","His actions were itemized because he was young","His actions provoked the humour"]', '''<b>Provoked severe criticism</b>'' = <b>seriously rejected</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1bcd848-0ccd-42ef-8013-84d6a31ee2e4', 'Government', 'JAMB', null, 2026, null, 'In Nigeria, public corporations are also known as', null, '["co-operative societies","multinational companies","private enterprises","parastatals"]', 3, 'Public corporations are also known as parastatals.', true, '2026-09-12 11:24:43.807', '2026-09-12 11:24:43.807', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1c4f9bc-43b1-48fd-8cb3-25c2375d9372', 'Biology', 'JAMB', null, 2026, null, 'What is the genetic ratio of a cross between a homozygous tall plant and a homozygous dwarf plant?', null, '["0 tall, 4 short","3 tall, 1 short","2 short, 2 tall","1 tall, 1 short","4 tall, 0 short"]', 4, 'The genetic ratio of a cross between a homozygous tall (TT) and a homozygous dwarf (tt) plant is 4 tall, 0 short. All F1 offspring will be Tt (heterozygous) and will be tall because tallness is dominant. The phenotype ratio is 100% tall. The 3:1 ratio appears in the F2 generation when two heterozygous plants are crossed (Tt × Tt). The 1:1 ratio appears in a test cross (Tt × tt). All F1 offspring from true-breeding parents will show the dominant trait.', true, '2026-09-09 03:19:14.755', '2026-09-09 03:19:14.755', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1cdddf1-276b-468c-8f33-6a5fcc3847b0', 'General Mathematics', 'JAMB', null, 2026, null, 'The perimeter of a semicircle is 72cm. Find the radius. (Take π = 22/7)', null, '["16cm","14cm","21cm","28cm"]', 1, 'Perimeter = πr + 2r = r(π+2) = r(22/7+2) = r(36/7). 72 = 36r/7. r = 14cm.', true, '2026-09-12 11:43:50.264', '2026-09-12 11:43:50.264', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1d14dde-bb29-47c8-aa9b-400cd381719b', 'Physics', 'JAMB', null, 1991, null, 'Which of the following statements is CORRECT about the earth''s magnetic field?', null, '["The angle of dip is the angle which a freely suspended magnet makes with the vertical","The angle of declination is the angle between the magnetic meridian and the geographic meridian","The angle of declination is the angle which a magnetic compass makes with the magnetic meridian.","The angle of inclination is the difference between the angle of dip and the angle of declination."]', 1, 'Declination is the angle between the magnetic meridian and the geographic meridian. Dip (inclination) is the angle between the earth''s field and the horizontal.', true, '2026-10-12 19:15:33.945', '2026-10-12 19:15:33.945', null, null, null, 'Which of the following statements is <b>CORRECT</b> about the earth''s magnetic field?', '["The angle of dip is the angle which a freely suspended magnet makes with the vertical","The angle of declination is the angle between the magnetic meridian and the geographic meridian","The angle of declination is the angle which a magnetic compass makes with the magnetic meridian.","The angle of inclination is the difference between the angle of dip and the angle of declination."]', 'Declination is the angle between the magnetic meridian and the geographic meridian. Dip (inclination) is the angle between the earth''s field and the horizontal.', '{"bold":["CORRECT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1d68e7f-6b32-42fe-b9f3-cfa378e9bf4f', 'Literature in English', 'JAMB', null, 2026, null, 'A word or gesture which serves as a signal to an actor to do or say something is called', null, '["Reminder","Correction","Over-act","Cue"]', 3, 'A cue is a signal for an actor.', true, '2026-09-12 11:07:26.035', '2026-09-12 11:07:26.035', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1ec882e-16c7-44ad-98d9-64a6b66b080b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Some people consider the leather upholstery and thick rugs a bit <u>sumptuous</u>.', null, '["simple","lavish","expensive","desirable"]', 0, 'Sumptuous = luxurious; opposite = simple.', true, '2026-10-24 07:21:25.432', '2026-10-24 07:21:25.432', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Some people consider the leather upholstery and thick rugs a bit <u>sumptuous</u>.', '["simple","lavish","expensive","desirable"]', 'Sumptuous = luxurious; opposite = simple.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1f67c24-c227-4002-b598-7be89d755bca', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The vice-chancellor <u>relinquished</u> power at the end of his terms.', null, '["clung on to","abandoned","gave up","wielded"]', 3, 'Relinquished = gave up; opposite = wielded.', true, '2026-10-24 07:21:28.413', '2026-10-24 07:21:28.413', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The vice-chancellor <u>relinquished</u> power at the end of his terms.', '["clung on to","abandoned","gave up","wielded"]', 'Relinquished = gave up; opposite = wielded.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e1fab3bb-5617-41e1-a08a-bf2ae487d76b', 'Biology', 'JAMB', null, 2003, null, 'The part of the mammalian digestive system where absorption of nutrients take place is the', null, '["ileum","colon","oesophagus","duodenum"]', 0, 'The ileum is specialized with villi and microvilli for the primary absorption of digested nutrients.', true, '2026-10-12 20:05:09.711', '2026-10-12 20:05:09.711', null, null, null, 'The part of the mammalian digestive system where absorption of nutrients take place is the', '["ileum","colon","oesophagus","duodenum"]', 'The ileum is specialized with villi and microvilli for the primary absorption of digested nutrients.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e20684b7-2050-4998-96ff-9e13cdeaab7e', 'Biology', 'JAMB', null, 2005, null, 'Secondary succession is much faster than primary succession because', null, '["pioneer colonizers are more in number","soil is already present","secondary seres require less nutrients","species competition is increased"]', 1, 'Soil is already present in secondary succession.', true, '2026-10-12 20:59:37.888', '2026-10-12 20:59:37.888', null, null, null, 'Secondary succession is much faster than primary succession because', '["pioneer colonizers are more in number","soil is already present","secondary seres require less nutrients","species competition is increased"]', 'Soil is already present in secondary succession.', '{"bold":["Soil is already present"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e20890c3-1819-4832-8932-09ce5b6d6813', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Since mortality is the lot of man argued the preacher, we must all accept death with <u>equanimity</u>.', null, '["concern","uncertainty","serenity","anxiety"]', 3, 'Equanimity = calmness; opposite = anxiety.', true, '2026-10-24 07:21:17.348', '2026-10-24 07:21:17.348', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Since mortality is the lot of man argued the preacher, we must all accept death with <u>equanimity</u>.', '["concern","uncertainty","serenity","anxiety"]', 'Equanimity = calmness; opposite = anxiety.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e2096c07-7ca4-4823-a8e9-fcc7e490549a', 'Biology', 'JAMB', null, 2010, null, 'The sheet of muscle that separates the thoracic and the abdominal cavities is the', null, '["diaphragm","intercostal muscle","pleural membrane","pericardium"]', 0, 'The diaphragm separates the thoracic and abdominal cavities.', true, '2026-10-12 20:59:39.74', '2026-10-12 20:59:39.74', null, null, null, 'The sheet of muscle that separates the thoracic and the abdominal cavities is the', '["diaphragm","intercostal muscle","pleural membrane","pericardium"]', 'The diaphragm separates the thoracic and abdominal cavities.', '{"bold":["diaphragm"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e20a7dbc-543e-4750-8cc6-f1cb0acd119a', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following is an amphoteric oxides', null, '["MgO","CO2","Al2O3","Na2O"]', 2, 'Aluminium oxide (Al2O3) exhibits both acidic and basic properties, reacting with both acids and bases to form salts.', true, '2026-09-09 17:12:44.831', '2026-09-09 17:12:44.831', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e217e9ef-5940-48a2-a3b8-6c442f47c227', 'Chemistry', 'JAMB', null, 2026, null, 'A divalent metal M reacts with dilute hydrochloric acid to produce hydrogen gas. 0.65 g of M produced 240 cm³ of hydrogen measured at room temperature and pressure. What is the relative atomic mass of M? [1 mole of gas occupies 24 dm³ at r.t.p]', null, '["24","39","56","65"]', 3, 'M + 2HCl -> MCl2 + H2. Moles H2 = 0.240 / 24 = 0.01 mol. Moles M = 0.01 mol. Relative atomic mass = 0.65 / 0.01 = 65.', true, '2026-09-09 17:12:48.104', '2026-09-09 17:12:48.104', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e224b798-1d44-4bdd-bf1c-080b72a216e0', 'English Language', 'JAMB', null, 2024, null, 'The students did the assignment, but not ______ the way I had expected', null, '["just","quite","hardly","as"]', 1, '"Quite" means completely or exactly.', true, '2026-09-18 09:43:02.538', '2026-09-18 09:43:02.538', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e2255567-46e1-4d60-a417-65816da95bb5', 'Literature in English', 'JAMB', null, 2026, null, 'The character addressed is', null, '["Lepidus","Pompey","Menas","Caesar"]', 2, 'The character addressed is Menas.', true, '2026-09-12 11:14:06.526', '2026-09-12 11:14:06.526', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e239985b-a290-4a56-8cd4-60689c365e58', 'Government', 'JAMB', null, 2026, null, 'The western zone of Sokoto caliphate was administered from', null, '["Ilorin","Bida","Gwandu","Kebbi"]', 2, 'The western zone of the Sokoto Caliphate was administered from Gwandu. After the death of Usman Dan Fodio, the Sokoto Caliphate was divided into two administrative zones: the eastern zone administered from Sokoto and the western zone administered from Gwandu. Gwandu was the capital of the western emirates, including Ilorin, Kebbi, and Yauri. This division helped in the effective administration of the vast caliphate.', true, '2026-09-10 10:44:18.187', '2026-09-10 10:44:18.187', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e241144b-c585-4f63-bdd2-d905f86fac38', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''Firmament'' as used in the creation story means', null, '["Water","Sun, moon and stars","Sea creatures","Heaven"]', 3, 'God called the firmament Heaven.', true, '2026-09-12 10:42:00.825', '2026-09-12 10:42:00.825', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e2852d99-954f-4622-91b0-fc9b691ae3fa', 'Yoruba', 'JAMB', null, 2007, null, 'Nínú Iyanjélódi, àwòn tí kò jẹ kílé-ékò dahoro ni', null, '["ejò àtewúrẹ","çran àtaláygbá","àwòn àgbà òjẹ","àwòn òtókùlú."]', 0, 'Ejò àtewúrẹ ni kò jẹ kílé-ékò dahoro.', true, '2026-10-13 13:23:32.285', '2026-10-13 13:23:32.285', null, null, null, 'Nínú Iyanjélódi, àwòn tí kò jẹ kílé-ékò dahoro ni', '["ejò àtewúrẹ","çran àtaláygbá","àwòn àgbà òjẹ","àwòn òtókùlú."]', 'Ejò àtewúrẹ ni kò jẹ kílé-ékò dahoro.', '{"bold":["ejò àtewúrẹ"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e292a0f0-ca38-42f1-a498-e39e72e3d113', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She gave a <u>caustic</u> remark on the occasion.', null, '["tangible","friendly","polite","sarcastic"]', 3, 'Caustic = sarcastic.', true, '2026-10-24 01:01:59.19', '2026-10-24 01:01:59.19', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She gave a <u>caustic</u> remark on the occasion.', '["tangible","friendly","polite","<u>sarcastic</u>"]', '<b>Caustic</b> = <b>sarcastic</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e2a13f5e-42bc-431a-b7fe-16d56def2a37', 'English Language', 'JAMB', null, 2024, null, 'From the words lettered A to D, choose the word that best completes each of the following sentences: Mr. Jato is a regular visitor of ______', null, '["our own","our''s","ours","ours"]', 2, '"Ours" is the correct possessive pronoun.', true, '2026-09-18 09:24:04.91', '2026-09-18 09:24:04.91', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e2afb116-c111-49b0-bb45-50ae41023049', 'General Mathematics', 'JAMB', null, 2026, null, 'A jar contains a mixture of two liquids, A and B, in the ratio 7:5. When 9 liters of the mixture are drawn off and the jar is filled with liquid B, the ratio of A to B becomes 7:9. How many liters of liquid A were in the jar initially?', null, '["21 liters","28 liters","42 liters","35 liters"]', 0, 'Let total = 12x. A = 7x, B = 5x. After removing 9L: A = 7x - 9(7/12) = 7x - 5.25. B = 5x - 9(5/12) + 9 = 5x - 3.75 + 9 = 5x + 5.25. (7x-5.25)/(5x+5.25) = 7/9. 63x - 47.25 = 35x + 36.75. 28x = 84. x = 3. A = 21 liters.', true, '2026-09-12 11:43:53.894', '2026-09-12 11:43:53.894', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e2bdb986-43ee-4f50-8675-44e2ec75ffb1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. No wonder Sikemi later became a detective; she has been very <u>observant</u>.', null, '["inquisitive","inductive","curious","perceptive"]', 3, 'Observant = perceptive.', true, '2026-10-24 01:04:05.9', '2026-10-24 01:04:05.9', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. No wonder Sikemi later became a detective; she has been very <u>observant</u>.', '["inquisitive","inductive","curious","<u>perceptive</u>"]', '<b>Observant</b> = <b>perceptive</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e2d31725-8560-4683-a439-c92ae6698d2c', 'English Language', 'JAMB', null, 2024, null, 'The farmer in the passage', null, '["used to be self-sufficient","had a dream to expand his farm","is more envied than the astronauts","lives a life too simple"]', 0, 'The passage states that the farmer was self-sufficient and could live without a car, television, or newspaper.', true, '2026-09-18 09:43:02.206', '2026-09-18 09:43:02.206', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e2d46dae-5d7e-412b-a6f8-d82db870a82c', 'Physics', 'JAMB', null, 1990, null, 'The photocell works on the principle of the', null, '["Voltaic cell","Emission of electrons by incident radiation","Emission of protons by incident electrons.","Photographic plate."]', 1, 'A photocell uses the photoelectric effect: electrons are emitted from a surface when radiation falls on it.', true, '2026-10-12 19:15:32.327', '2026-10-12 19:15:32.327', null, null, null, 'The photocell works on the principle of the', '["Voltaic cell","Emission of electrons by incident radiation","Emission of protons by incident electrons.","Photographic plate."]', 'A photocell uses the photoelectric effect: electrons are emitted from a surface when radiation falls on it.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e2dc31c9-114b-4cd4-963d-afc2a18772e6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The old woman is suffering from <u>dementia</u>.', null, '["lucidity","senility","insanity","sagacity"]', 1, 'Dementia = senility.', true, '2026-10-24 01:01:57.814', '2026-10-24 01:01:57.814', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The old woman is suffering from <u>dementia</u>.', '["lucidity","<u>senility</u>","insanity","sagacity"]', '<b>Dementia</b> = <b>senility</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e2dffe33-b2a0-4ff8-a17c-ad7b3d2e2999', 'English Language', 'JAMB', null, 2024, null, 'Which is true according to the passage?', null, '["Cigarettes with less irritating, smooth and mild smoke may not have a detrimental effect on smokers'' health","Cigarettes with less irritating, smooth and mild smoke are much more injurious to health","Certain tobacco companies produce tobaccos which may not be injurious to health","The tobacco companies in the US produce tobaccos which much health benefits"]', 1, 'The passage states that making smoke lighter and milder caused smokers to inhale more deeply, negating any health benefit.', true, '2026-09-18 09:34:04.024', '2026-09-18 09:34:04.024', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e2f7de1a-1097-445c-8298-5b1c16cd391a', 'Hausa', 'JAMB', null, 2011, null, 'Hausawa wasu mutane ne da suka ba abinci muhimmanci a rayuwarasu, domin duk wata fathomka da gwama numfashi da ba hammata iska, ana yi wa ciki ne. Wato cikin biyu: d''aya ya yiwu an ci an koshi, ko kuma ana cikin halin nema ne. Kullum, da zaran gari ya waye, wasu tun da jijjifi, za a ga sun fita neman abin da za su ci, su da iyalansu, domin a samu rufin asiri. Saboda haka, ba a barin kowa a gida sai tsofaffi da mata da yara da kuma ragwage, kowa ya tafi neman halaliya. A al''adance, Hausawa suna da lokuta uku na cin abinci a kowace rana, wato safe da rana da dare. A mafi yawan lokuta da safe akan sha abu mai ruwa-ruwa, kamar koko da kosai ko kunu. Wasu kuma, sukan dumama abin da aka ci a daren da ya gabata. Da rana, kuma akan dafa duk irin abin da ya samu kamar shinkafa da wake ko dambu ko kuma danwake. Da daddare kuma, kusan kowane gida za a sa mu cewa ana dafa tuwo da miya ne, ko miyar kuka ko ku bewa ko taushe ko kalkashi da dai sauransu, da nama ko babu nama. Duk ko ma mene ne ya samu, wato dai ''Daidai ruwa daidai kurji.'' Har ila yau, ko da yake ba kowa yake da karfin dora girki sau uku ba a rana saboda halin yau, amma a kan sami makwabta na gari masu tausayi da lura, su kan kira makwabtansu domin su ci abincin, ko suna da shi ko ba su da shi. Da ma tun- fil-azal, an san Bahaushe da halin taimako ga dan uwansa. A zamanin da, za a ga Bahaushe yana ko karin ya yi noma domin kada gidansa a zauna da yunwa. Amma yanzu, zamananci ya mayar da tunaninsa ya koma kan kasuwanci ko aikin ofis a maimakon aikin gona saboda lalaci da son jiki. A labarin, akan yi dan wake da', null, '["safe","rana","almuru","asuba"]', 1, 'A labarin, akan yi dan wake da rana.', true, '2026-10-13 10:37:20.683', '2026-10-13 10:37:20.683', null, null, null, 'Hausawa wasu mutane ne da suka ba abinci muhimmanci a rayuwarasu, domin duk wata fathomka da gwama numfashi da ba hammata iska, ana yi wa ciki ne. Wato cikin biyu: d''aya ya yiwu an ci an koshi, ko kuma ana cikin halin nema ne. Kullum, da zaran gari ya waye, wasu tun da jijjifi, za a ga sun fita neman abin da za su ci, su da iyalansu, domin a samu rufin asiri. Saboda haka, ba a barin kowa a gida sai tsofaffi da mata da yara da kuma ragwage, kowa ya tafi neman halaliya. A al''adance, Hausawa suna da lokuta uku na cin abinci a kowace rana, wato safe da rana da dare. A mafi yawan lokuta da safe akan sha abu mai ruwa-ruwa, kamar koko da kosai ko kunu. Wasu kuma, sukan dumama abin da aka ci a daren da ya gabata. Da rana, kuma akan dafa duk irin abin da ya samu kamar shinkafa da wake ko dambu ko kuma danwake. Da daddare kuma, kusan kowane gida za a sa mu cewa ana dafa tuwo da miya ne, ko miyar kuka ko ku bewa ko taushe ko kalkashi da dai sauransu, da nama ko babu nama. Duk ko ma mene ne ya samu, wato dai ''Daidai ruwa daidai kurji.'' Har ila yau, ko da yake ba kowa yake da karfin dora girki sau uku ba a rana saboda halin yau, amma a kan sami makwabta na gari masu tausayi da lura, su kan kira makwabtansu domin su ci abincin, ko suna da shi ko ba su da shi. Da ma tun- fil-azal, an san Bahaushe da halin taimako ga dan uwansa. A zamanin da, za a ga Bahaushe yana ko karin ya yi noma domin kada gidansa a zauna da yunwa. Amma yanzu, zamananci ya mayar da tunaninsa ya koma kan kasuwanci ko aikin ofis a maimakon aikin gona saboda lalaci da son jiki. A labarin, akan yi dan wake da', '["safe","rana","almuru","asuba"]', 'A labarin, akan yi dan wake da rana.', '{"bold":["rana"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e2ff115d-32ae-44ac-a579-128c84413c92', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The doctor tried to <u>alleviate</u> his patient''s pain.', null, '["relieve","worsen","kill","cure"]', 1, 'Alleviate = relieve; opposite = worsen.', true, '2026-10-24 07:21:14.683', '2026-10-24 07:21:14.683', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The doctor tried to <u>alleviate</u> his patient''s pain.', '["relieve","worsen","kill","cure"]', 'Alleviate = relieve; opposite = worsen.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e305a439-7d6d-415a-93dc-9ffc25e10f12', 'Physics', 'JAMB', null, 1993, null, 'Which of the following devices may be used to step up the voltage in a d.c. circuit?', null, '["A step-up transformer","A d.c. generator","A wattmeter","An induction coil."]', 3, 'A transformer needs a.c. An induction coil, with its interrupter, turns a d.c. supply into a changing current and steps the voltage up.', true, '2026-10-12 19:15:38.512', '2026-10-12 19:15:38.512', null, null, null, 'Which of the following devices may be used to step up the voltage in a d.c. circuit?', '["A step-up transformer","A d.c. generator","A wattmeter","An induction coil."]', 'A transformer needs a.c. An induction coil, with its interrupter, turns a d.c. supply into a changing current and steps the voltage up.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e305e61e-2f46-4e2b-bb73-ed95e934ae1a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He is <u>a stringer for</u> a newspaper.', null, '["a financier of","a reporter for","an editor of","a freelancer for"]', 3, 'A stringer = a freelancer for.', true, '2026-10-24 01:01:51.875', '2026-10-24 01:01:51.875', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He is <u>a stringer for</u> a newspaper.', '["a financier of","a reporter for","an editor of","<u>a freelancer for</u>"]', 'A <b>stringer</b> = <b>a freelancer for</b>.', '{}');
