insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e315bb2f-89cf-470f-b64b-75b87058d57f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Nigeria is gradually experiencing economic <u>recession</u>.', null, '["birth","discovery","recovery","destruction"]', 2, 'Recession = downturn; opposite = recovery.', true, '2026-10-24 07:21:16.176', '2026-10-24 07:21:16.176', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Nigeria is gradually experiencing economic <u>recession</u>.', '["birth","discovery","recovery","destruction"]', 'Recession = downturn; opposite = recovery.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e3168b00-bca8-4191-8b50-da30755fc43a', 'Economics', 'JAMB', null, 2026, null, '______ is the branch of agriculture that deals with the cultivation of crops', null, '["Crop production","Aquaculture","Livestock farming","fish farming"]', 0, 'Crop production is the branch of agriculture dealing with cultivation of crops.', true, '2026-09-12 11:00:30.737', '2026-09-12 11:00:30.737', null, null, null, null, null, null, null);
