insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e32473e8-0d35-4610-8f36-59ace0cec9d0', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the volume of a cube with side 5 cm.', null, '["25 cm³","75 cm³","100 cm³","125 cm³"]', 3, 'V = 5³ = 125 cm³.', true, '2026-09-12 11:44:11.826', '2026-09-12 11:44:11.826', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e328843d-e5d6-46a9-9a6f-698d5237c39b', 'Physics', 'JAMB', null, 2026, null, 'Calculate the depth of a swimming pool if the apparent depth is 10cm. (Refractive index of water = 1.33)', null, '["7.5cm","10.0cm","13.3cm","6.87cm"]', 2, 'Real depth = Refractive index × Apparent depth. Real depth = 1.33 × 10 = 13.3cm.', true, '2026-09-10 10:56:39.675', '2026-09-10 10:56:39.675', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e32eb9ef-89b9-4a5e-bda5-83a0fc9e88dd', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The police <u>ran the criminal to earth</u>.', null, '["jailed him","knocked him down","discovered him","buried him"]', 2, '''Ran to earth'' = discovered after search.', true, '2026-10-24 01:02:04.054', '2026-10-24 01:02:04.054', null, null, null, '(Choose the most appropriate interpretation). The police <u>ran the criminal to earth</u>.', '["jailed him","knocked him down","<u>discovered him</u>","buried him"]', '''<b>Ran to earth</b>'' = <b>discovered after search</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e3339a7f-c9ed-43fd-a704-d6e2705e43d4', 'Physics', 'JAMB', null, 1995, null, 'Which of the following is required to convert a milliammeter to an ammeter?', null, '["A high resistance in parallel","A high resistance in series","A low resistance in parallel","A low resistance in series."]', 2, 'A low-resistance shunt in parallel with the meter takes most of the current, extending its range.', true, '2026-10-12 19:15:42.379', '2026-10-12 19:15:42.379', null, null, null, 'Which of the following is required to convert a milliammeter to an ammeter?', '["A high resistance in parallel","A high resistance in series","A low resistance in parallel","A low resistance in series."]', 'A low-resistance shunt in parallel with the meter takes most of the current, extending its range.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e33490f8-349f-4d67-8250-2fbb1c1a0dc4', 'Physics', 'JAMB', null, 1984, null, 'A galvanometer of resistance 5.0 Ω has full-scale deflection for a current of 100 mA. How would its range be extended to 1.0 A by placing a resistance of', null, '["5/9 Ω in parallel","9/5 Ω in series","45 Ω in parallel","45 Ω in series","9/5 Ω in parallel."]', 0, 'The shunt must carry 1.0 - 0.1 = 0.9 A while the galvanometer carries 0.1 A. Rs = (0.1 x 5)/0.9 = 5/9 Ω, in parallel.', true, '2026-10-12 19:15:20.441', '2026-10-12 19:15:20.441', null, null, null, 'A galvanometer of resistance 5.0 Ω has full-scale deflection for a current of 100 mA. How would its range be extended to 1.0 A by placing a resistance of', '["5/9 Ω in parallel","9/5 Ω in series","45 Ω in parallel","45 Ω in series","9/5 Ω in parallel."]', 'The shunt must carry 1.0 - 0.1 = 0.9 A while the galvanometer carries 0.1 A. R<sub>s</sub> = (0.1 x 5)/0.9 = 5/9 Ω, in parallel.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e33b46a0-5224-417a-8055-c055bcedc55c', 'English Language', 'JAMB', null, 2024, null, 'From the child''s point of view, in what way is death likened to a divorce?', null, '["Both are losses","Both are temporary","Both would involve his mother","He feels responsible in each case"]', 1, 'The passage states that death is often seen by a child as an impermanent thing, similar to divorce.', true, '2026-09-18 09:43:02.645', '2026-09-18 09:43:02.645', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e34214e8-d378-4f7a-96f2-dbe2e03343ed', 'Physics', 'JAMB', null, 2026, null, 'In order to view the sun, the most suitable instrument to use is', null, '["helioscope","telescope","stroboscope","sun meter"]', 0, 'A helioscope is the most suitable instrument for viewing the sun. It is designed to safely observe the sun by reducing the intensity of sunlight to prevent eye damage. A telescope, stroboscope, and sun meter are not designed for safe solar viewing.', true, '2026-09-10 10:56:39.351', '2026-09-10 10:56:39.351', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e3451d20-717a-4420-a566-f6161b2e0907', 'Chemistry', 'JAMB', null, 2026, null, 'An example of aromatic compound is?', null, '["Ethanol","Ether","Phenol","Ethanoate"]', 2, 'Phenol is an aromatic compound.', true, '2026-09-12 11:36:28.295', '2026-09-12 11:36:28.295', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e34c262d-420f-455c-8db3-39e3c98ec0be', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You can <u>learn</u> a great deal just from watching other players.', null, '["invent","accumulate","allow","discover"]', 3, 'Learn = discover.', true, '2026-10-24 01:04:12.454', '2026-10-24 01:04:12.454', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You can <u>learn</u> a great deal just from watching other players.', '["invent","accumulate","allow","<u>discover</u>"]', '<b>Learn</b> = <b>discover</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e34c33ad-1de2-4d8d-8afd-6a1e7429b74d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The dressmaker <u>unpicked</u> the seam of the shirt', null, '["threaded","sewed up","picked up","tore up"]', 1, 'Unpicked = undid; opposite = sewed up.', true, '2026-10-24 07:21:31.888', '2026-10-24 07:21:31.888', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The dressmaker <u>unpicked</u> the seam of the shirt', '["threaded","sewed up","picked up","tore up"]', 'Unpicked = undid; opposite = sewed up.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e34c7785-23d0-4547-9ab6-34e4833393df', 'Physics', 'JAMB', null, 1995, null, 'The volume of an air bubble increases from the bottom to the top of a lake at constant temperature because', null, '["Atmospheric pressure acts on the surface of the lake.","Pressure increases with depth of the lake.","Density remains constant with pressure","The bubble experiences an upthrust."]', 1, 'Pressure increases with depth, so the pressure on the bubble falls as it rises. By Boyle''s law its volume increases.', true, '2026-10-12 19:15:41.094', '2026-10-12 19:15:41.094', null, null, null, 'The volume of an air bubble increases from the bottom to the top of a lake at constant temperature because', '["Atmospheric pressure acts on the surface of the lake.","Pressure increases with depth of the lake.","Density remains constant with pressure","The bubble experiences an upthrust."]', 'Pressure increases with depth, so the pressure on the bubble falls as it rises. By Boyle''s law its volume increases.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e35f73ec-a0ea-48cf-a040-14dd0941a8aa', 'English Language', 'JAMB', null, 2007, null, 'You should read all the <u>__________</u> carefully before you decide where to go on holiday', null, '["brochures","prospectuses","tickets","handouts"]', 0, 'Correct spelling: brochures.', true, '2026-10-24 07:21:44.267', '2026-10-24 07:21:44.267', null, null, null, 'You should read all the <u>__________</u> carefully before you decide where to go on holiday', '["brochures","prospectuses","tickets","handouts"]', 'Correct spelling: brochures.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e36ff641-7153-46a2-ac3d-cad22d34d8c9', 'Literature in English', 'JAMB', null, 2026, null, 'The poet''s use of the second-person address ''you'' in the latter part of the poem refers to', null, '["his father","his son","society","his childhood self"]', 1, 'The second-person address refers to his son.', true, '2026-09-12 11:13:43.296', '2026-09-12 11:13:43.296', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e397fcd3-bfab-4de3-bc73-ed0ec56f9f7d', 'Chemistry', 'JAMB', null, 2026, null, 'Consider the equilibrium CO + H₂O ⇌ CO₂ + H₂. Which change would increase the amount of hydrogen produced?', null, '["Removing hydrogen as it forms","Increasing carbon dioxide concentration","Decreasing temperature drastically","Adding a catalyst only"]', 1, 'Increasing the concentration of CO₂ (a reactant) shifts the equilibrium to the right, producing more H₂. Removing hydrogen would also shift equilibrium right, but the question asks which change would increase hydrogen production. Adding a catalyst does not shift equilibrium. The answer based on the options is increasing CO₂ concentration.', true, '2026-09-12 09:38:13.352', '2026-09-12 09:38:13.352', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e39f63bd-7409-4c0c-b538-52071336a872', 'English Language', 'JAMB', null, 2007, null, 'After the accused was found guilty by the court, his counsel <u>__________</u> before sentence was passed', null, '["begged for mercy","made a please for mitigation","made an ovation","made a plea of mitigation"]', 3, 'Correct form: made a plea of mitigation.', true, '2026-10-24 07:21:40.831', '2026-10-24 07:21:40.831', null, null, null, 'After the accused was found guilty by the court, his counsel <u>__________</u> before sentence was passed', '["begged for mercy","made a please for mitigation","made an ovation","made a plea of mitigation"]', 'Correct form: made a plea of mitigation.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e3a1086a-0fa1-4ce8-b584-7caf26eb9bf6', 'Physics', 'JAMB', null, 2003, null, 'If 1.2 x 10⁶ J of heat energy is given off in 1 s from a vessel maintained at a temperature gradient of 30 K m⁻¹, the surface area of the vessel is [Thermal conductivity of the vessel = 400 W m⁻¹ K⁻¹]', null, '["1.0 x 10³ m²","1.0 x 10² m²","9.0 x 10⁴ m²","9.0 x 10² m²"]', 1, 'Q/t = kA(dθ/dx), so A = 1.2 x 10⁶/(400 x 30) = 100 m².', true, '2026-10-12 19:15:56.17', '2026-10-12 19:15:56.17', null, null, null, 'If 1.2 x 10<sup>6</sup> J of heat energy is given off in 1 s from a vessel maintained at a temperature gradient of 30 K m<sup>-1</sup>, the surface area of the vessel is [Thermal conductivity of the vessel = 400 W m<sup>-1</sup> K<sup>-1</sup>]', '["1.0 x 10<sup>3</sup> m<sup>2</sup>","1.0 x 10<sup>2</sup> m<sup>2</sup>","9.0 x 10<sup>4</sup> m<sup>2</sup>","9.0 x 10<sup>2</sup> m<sup>2</sup>"]', 'Q/t = kA(dθ/dx), so A = 1.2 x 10<sup>6</sup>/(400 x 30) = 100 m<sup>2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('e3ca6849-c15c-44cc-a228-02fe472d84b6', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'When the wall of Jerusalem was broken down, the survivors who escaped the exile were in great', null, '["Frustration","trouble and shame","disappointment","confusion and dismay"]', 1, 'When the wall of Jerusalem was broken down, the survivors who escaped the exile were in great trouble and shame. Nehemiah received this report and wept, fasted, and prayed to God.', true, '2026-09-12 09:46:15.313', '2026-09-12 09:46:15.313', null, null, null, null, null, null, null);
