insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ea5ce2d0-d23e-4d3a-a07f-e8e6502e80f5', 'Government', 'JAMB', null, 2026, null, 'Before Nigeria became a republic, the highest body charged with the administration of justice was the', null, '["Privy council","High court","Supreme court","Court of appeal"]', 0, 'The Privy Council in London was the highest court of appeal before Nigeria became a republic.', true, '2026-09-12 11:23:54.729', '2026-09-12 11:23:54.729', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ea5e70d5-c2b1-48b3-bc6f-e270ab063d0b', 'Biology', 'JAMB', null, 2026, null, 'The flippers of a whale and the fins of a fish are examples of', null, '["Divergent evolution","Coevolution","Continuous variation","Convergent evolution"]', 3, 'The flippers of a whale and the fins of a fish are examples of convergent evolution. They have similar functions (swimming) and similar forms (flattened, paddle-like structures) but evolved independently from different ancestral structures. Whales are mammals (evolved from land animals), while fish are aquatic vertebrates. This is convergent evolution because similar environmental pressures led to the evolution of similar structures in unrelated organisms. Divergent evolution produces homologous structures from a common ancestor. Coevolution involves reciprocal evolutionary changes between interacting species.', true, '2026-09-09 03:18:57.243', '2026-09-09 03:18:57.243', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ea5f69c3-eef2-496d-a44f-40968b9ee63b', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The new leader <u>hands out an olive branch</u>.', null, '["sues for peace","gives out branches of the olive tree","challenges his opponents to a fight","blesses his supporters"]', 0, '''An olive branch'' = offer of peace.', true, '2026-10-24 01:04:17.875', '2026-10-24 01:04:17.875', null, null, null, '(Choose the most appropriate interpretation). The new leader <u>hands out an olive branch</u>.', '["<u>sues for peace</u>","gives out branches of the olive tree","challenges his opponents to a fight","blesses his supporters"]', '''<b>An olive branch</b>'' = <b>offer of peace</b>.', '{}');
