insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ea6b4b95-8905-43ae-a7f8-280e2e50dd59', 'Physics', 'JAMB', null, 1983, null, 'A force of 16 N is applied to a 4.0 kg block that is at rest on a smooth horizontal surface. What is the velocity of the block at t = 5 seconds?', null, '["4 m/s","10 m/s","20 m/s","50 m/s","80 m/s"]', 2, 'a = F/m = 16/4 = 4 m/s². Then v = u + at = 0 + 4 x 5 = 20 m/s.', true, '2026-10-12 19:15:17.205', '2026-10-12 19:15:17.205', null, null, null, 'A force of 16 N is applied to a 4.0 kg block that is at rest on a smooth horizontal surface. What is the velocity of the block at t = 5 seconds?', '["4 m/s","10 m/s","20 m/s","50 m/s","80 m/s"]', 'a = F/m = 16/4 = 4 m/s<sup>2</sup>. Then v = u + at = 0 + 4 x 5 = 20 m/s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
