insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eb1b028f-1614-4cc0-b6fb-fd7e8dc8155c', 'Physics', 'JAMB', null, 1994, null, 'A cone in an unstable equilibrium has its potential energy', null, '["Decreased","Increased","Unchanged","Oscillating"]', 0, 'A cone balanced on its apex falls when slightly disturbed, and its centre of gravity moves lower, so its potential energy decreases.', true, '2026-10-12 19:15:39.05', '2026-10-12 19:15:39.05', null, null, null, 'A cone in an unstable equilibrium has its potential energy', '["Decreased","Increased","Unchanged","Oscillating"]', 'A cone balanced on its apex falls when slightly disturbed, and its centre of gravity moves lower, so its potential energy decreases.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eb21c170-0bb3-42e7-a5e1-b2bc3794f40e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Permanent Secretary left his job <u>under a cloud</u>.', null, '["on a cloudy day","with a clear record","in disgrace","on a sunny day"]', 1, 'Under a cloud = in disgrace; opposite = with a clear record.', true, '2026-10-24 07:21:22.104', '2026-10-24 07:21:22.104', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Permanent Secretary left his job <u>under a cloud</u>.', '["on a cloudy day","with a clear record","in disgrace","on a sunny day"]', 'Under a cloud = in disgrace; opposite = with a clear record.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eb2349ff-5b13-43f0-8d16-df31b1e07127', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. His <u>antipathy</u> affected the growth of his business.', null, '["hatred","receptiveness","loyalty","hostility"]', 1, 'Antipathy = hostility; opposite = receptiveness.', true, '2026-10-24 07:21:29.822', '2026-10-24 07:21:29.822', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. His <u>antipathy</u> affected the growth of his business.', '["hatred","receptiveness","loyalty","hostility"]', 'Antipathy = hostility; opposite = receptiveness.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eb2addf7-451e-40b1-829d-faefa5f3f867', 'Chemistry', 'JAMB', null, 2026, null, 'For the reaction: 2NO₂(g) ⇌ N₂O₄(g). At equilibrium, [NO₂] = 0.40 mol dm⁻³ and [N₂O₄] = 0.20 mol dm⁻³. Calculate Kc.', null, '["0.50","1.25","2.00","0.80"]', 1, 'Kc = [N₂O₄] / [NO₂]² = 0.20 / (0.40)² = 0.20 / 0.16 = 1.25.', true, '2026-09-12 11:32:53.606', '2026-09-12 11:32:53.606', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eb2d6051-f85c-4506-be6b-fc9f890c2367', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following are mixtures (I) petroleum (II) rubber latex (III) vulcanizer solution (IV) carbon sulphide', null, '["I, II, III","I, II, IV","I, II","I, IV"]', 0, 'Petroleum, rubber latex, and vulcanizer solution are complex chemical mixtures, whereas carbon disulfide (CS2) is a pure chemical compound.', true, '2026-09-09 17:12:45.84', '2026-09-09 17:12:45.84', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eb2f4939-fc5c-45e9-a491-28696fea23c1', 'Physics', 'JAMB', null, 2003, null, 'The most suitable cell used for short interval switches in electric bells is a', null, '["Nickel iron accumulator","Lead-acid accumulator","Daniell cell","Leclanché cell"]', 3, 'A Leclanché cell recovers quickly after short periods of use, so it suits intermittent loads like electric bells.', true, '2026-10-12 19:15:57.192', '2026-10-12 19:15:57.192', null, null, null, 'The most suitable cell used for short interval switches in electric bells is a', '["Nickel iron accumulator","Lead-acid accumulator","Daniell cell","Leclanché cell"]', 'A Leclanché cell recovers quickly after short periods of use, so it suits intermittent loads like electric bells.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eb38a6af-5828-41a8-9461-175fbe8b8334', 'Financial Accounting', 'UTME', null, 2002, null, 'The working capital of the club is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841030/questions/vodapl1yykmthcpisqrh.jpg', '["N5000","N4000","N3000","N7000"]', 2, 'Working Capital = CA - CL. Stock 3500 + Debtors 1000 + Bank 1500 = 6000. Creditors 1000 + Sub.Advance 2000 = 3000. 6000 - 3000 = 3000.', true, '2026-10-12 21:59:58.252', '2026-10-12 21:59:58.252', null, null, null, 'The working capital of the club is', '["N5000","N4000","<b>N3000</b>","N7000"]', 'Working Capital = CA - CL. Stock 3500 + Debtors 1000 + Bank 1500 = 6000. Creditors 1000 + Sub.Advance 2000 = 3000. 6000 - 3000 = <b>3000</b>.', '{"bold":["3000"],"italic":[],"underline":[],"fillBlanks":[]}');
