insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eb3fbec4-5de7-453a-bee6-3f3d7a0e1df6', 'Literature in English', 'JAMB', null, 2026, null, 'In the play, ''The marriage of Anansenwa'', Anansewa opposes her father''s matchmaking attempt, arguing that she won''t be sold like a', null, '["maid","parcel","goat","commodity"]', 3, 'She argues she won''t be sold like a commodity.', true, '2026-09-12 11:11:01.987', '2026-09-12 11:11:01.987', null, null, null, null, null, null, null);
