insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eb636950-7713-4cdf-842b-e279c04ffb0e', 'Chemistry', 'JAMB', null, 2026, null, 'The role of manganese(IV) oxide in the laboratory preparation of oxygen from potassium chlorate is to', null, '["increase the yield of oxygen","reduce the activation energy","take part in the reaction","absorb heat"]', 1, 'MnO2 acts as a catalyst, offering an alternative pathway with lower activation energy to speed up decomposition.', true, '2026-09-09 17:12:49.017', '2026-09-09 17:12:49.017', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eb653861-03ec-4dad-bb84-d827f84f3ce5', 'Physics', 'JAMB', null, 1985, null, 'Two liquids, P at a temperature of 20 °C and Q at a temperature of 80 °C have specific heat capacities of 1.0 J kg⁻¹ °C⁻¹ and 1.5 J kg⁻¹ °C⁻¹ respectively. If equal masses of P and Q are mixed in a lagged calorimeter, then the equilibrium temperature is', null, '["44 °C","50 °C","56 °C","60 °C","70 °C"]', 2, 'Heat gained = heat lost: 1.0(θ - 20) = 1.5(80 - θ), so 2.5θ = 140 and θ = 56 °C.', true, '2026-10-12 19:15:21.312', '2026-10-12 19:15:21.312', null, null, null, 'Two liquids, P at a temperature of 20 °C and Q at a temperature of 80 °C have specific heat capacities of 1.0 J kg<sup>-1</sup> °C<sup>-1</sup> and 1.5 J kg<sup>-1</sup> °C<sup>-1</sup> respectively. If equal masses of P and Q are mixed in a lagged calorimeter, then the equilibrium temperature is', '["44 °C","50 °C","56 °C","60 °C","70 °C"]', 'Heat gained = heat lost: 1.0(θ - 20) = 1.5(80 - θ), so 2.5θ = 140 and θ = 56 °C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
