insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ec0358d5-e679-4d02-b7c7-928ae9ec3739', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Who was the first judge of Israel after Joshua''s death?', null, '["Ehud","Othniel","Deborah","Gideon"]', 1, 'Othniel was the first judge after Joshua''s death.', true, '2026-09-12 10:40:57.145', '2026-09-12 10:40:57.145', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ec0bc594-d968-497d-ae25-7cf7d013c497', 'Literature in English', 'JAMB', null, 2026, null, 'The structure of the poem contributes mainly to the feeling of', null, '["tension and suspense","happiness and calmness","romance and affection","celebration and pride"]', 0, 'The structure contributes to tension and suspense.', true, '2026-09-12 11:05:45.582', '2026-09-12 11:05:45.582', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ec182fd1-884d-467d-8eb9-f3105e473398', 'English Language', 'JAMB', null, 2007, null, 'Many a candidate <u>------------</u> to realise the difference between written and spoken English.', null, '["fails","fail","have failed","is failing"]', 0, '''Many a'' takes singular verb.', true, '2026-10-24 01:02:11.951', '2026-10-24 01:02:11.951', null, null, null, 'Many a candidate <u>------------</u> to realise the difference between written and spoken English.', '["<u>fails</u>","fail","have failed","is failing"]', '''<b>Many a</b>'' takes singular verb.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ec1ec272-8f74-454f-888a-3a0e01c3fbaa', 'Physics', 'JAMB', null, 1985, null, 'An electric kettle, connected to a 240 V mains, produces 6.0 x 10⁵ J of heat energy to boil a quantity of water in 5 minutes. Find the resistance of the kettle.', null, '["14.4 ohms","28.8 ohms","144 ohms","288 ohms","2 880 ohms"]', 1, 'Power = 6.0 x 10⁵/300 = 2000 W. R = V²/P = 240²/2000 = 28.8 ohms.', true, '2026-10-12 19:15:22.283', '2026-10-12 19:15:22.283', null, null, null, 'An electric kettle, connected to a 240 V mains, produces 6.0 x 10<sup>5</sup> J of heat energy to boil a quantity of water in 5 minutes. Find the resistance of the kettle.', '["14.4 ohms","28.8 ohms","144 ohms","288 ohms","2 880 ohms"]', 'Power = 6.0 x 10<sup>5</sup>/300 = 2000 W. R = V<sup>2</sup>/P = 240<sup>2</sup>/2000 = 28.8 ohms.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ec2731ea-6f0c-4743-ade3-63d9a6294610', 'Literature in English', 'JAMB', null, 2026, null, '______ is otherwise referred to as blank verse', null, '["irregular meter","regular meter","meter","rhyme scheme"]', 0, 'Blank verse is also called irregular meter.', true, '2026-09-12 11:10:08.05', '2026-09-12 11:10:08.05', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ec364482-5816-428b-b484-900f906de767', 'Physics', 'JAMB', null, 1991, null, 'A man hears his echo from a nearby hill 2 s after he shouted. If the frequency of his voice is 260 Hz and the wavelength is 1.29 m, how far away is the hill?', null, '["330.0 m","335.4 m","660.0 m","670.8 m"]', 1, 'v = fλ = 260 x 1.29 = 335.4 m s⁻¹. The sound travels to the hill and back in 2 s, so distance = 335.4 x 2/2 = 335.4 m.', true, '2026-10-12 19:15:33.838', '2026-10-12 19:15:33.838', null, null, null, 'A man hears his echo from a nearby hill 2 s after he shouted. If the frequency of his voice is 260 Hz and the wavelength is 1.29 m, how far away is the hill?', '["330.0 m","335.4 m","660.0 m","670.8 m"]', 'v = fλ = 260 x 1.29 = 335.4 m s<sup>-1</sup>. The sound travels to the hill and back in 2 s, so distance = 335.4 x 2/2 = 335.4 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ec56fa1f-c23b-4474-a837-258e35a8f0ab', 'Biology', 'JAMB', null, 2003, null, 'A man and his wife are both heterozygous for the sickle-cell trait. The likely percentage of their offspring that will be either carriers or sicklers is', null, '["75%","50%","25%","100%"]', 0, '75% of offspring will be carriers or sicklers.', true, '2026-10-12 20:59:33.691', '2026-10-12 20:59:33.691', null, null, null, 'A man and his wife are both heterozygous for the sickle-cell trait. The likely percentage of their offspring that will be either carriers or sicklers is', '["75%","50%","25%","100%"]', '75% of offspring will be carriers or sicklers.', '{"bold":["75%"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ec66b8a8-36ac-443a-b014-7eecfeff8204', 'Economics', 'JAMB', null, 2026, null, 'Excess supply over demand will place a price advantage on', null, '["government","foreign investors","suppliers","consumers"]', 3, 'Excess supply puts price advantage on consumers because prices fall.', true, '2026-09-12 11:01:02.053', '2026-09-12 11:01:02.053', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ec6a74d4-6563-490e-8e48-2a66806381cc', 'Biology', 'JAMB', null, 2003, null, 'In the internal structure of plants, a wide pith in the center is common to', null, '["dicot stems and monocot stems","dicot stems and monocot roots","dicot roots and monocot roots","dicot roots and monocot stems"]', 1, 'Dicot stems and monocot roots typically feature a prominent central pith.', true, '2026-10-12 20:05:10.562', '2026-10-12 20:05:10.562', null, null, null, 'In the internal structure of plants, a wide pith in the center is common to', '["dicot stems and monocot stems","dicot stems and monocot roots","dicot roots and monocot roots","dicot roots and monocot stems"]', 'Dicot stems and monocot roots typically feature a prominent central pith.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ec8f80ba-6b72-4a7b-88d8-5aa08286ac15', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The rally was attended only by people who were <u>apolitical</u>.', null, '["full of political fervor","antagonistic to politicians","new-breed politicians","not interested in politics"]', 3, 'Apolitical = not interested in politics.', true, '2026-10-24 01:04:00.281', '2026-10-24 01:04:00.281', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The rally was attended only by people who were <u>apolitical</u>.', '["full of political fervor","antagonistic to politicians","new-breed politicians","<u>not interested in politics</u>"]', '<b>Apolitical</b> = <b>not interested in politics</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eca42ccf-f3cd-4375-9ff8-f1379fbb846a', 'General Mathematics', 'JAMB', null, 2026, null, 'Solve the equations m² + n² = 29, m + n = 7', null, '["(2,5) and (5,2)","(2,3) and (3,5)","(5,3) and (3,5)","(5,2) and (5,3)"]', 0, 'From m+n=7, n=7-m. Substitute: m²+(7-m)²=29. m²+49-14m+m²=29. 2m²-14m+20=0. m²-7m+10=0. (m-2)(m-5)=0. m=2 or 5. When m=2, n=5. When m=5, n=2. So solutions are (2,5) and (5,2).', true, '2026-09-10 10:48:19.835', '2026-09-10 10:48:19.835', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ecad1ce4-1f42-4222-ac09-05bf499abf21', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. As a journalist, Bala has always has <u>a nose for stories</u>.', null, '["cynical statement","an instinct","a command","soft comment"]', 1, 'A nose for stories = an instinct.', true, '2026-10-24 01:01:58.609', '2026-10-24 01:01:58.609', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. As a journalist, Bala has always has <u>a nose for stories</u>.', '["cynical statement","<u>an instinct</u>","a command","soft comment"]', 'A <b>nose for stories</b> = <b>an instinct</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ecae7cb3-d6e6-4e71-91a7-51bb02b31e59', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His <u>taciturnity</u> amazed everyone in the court during the legal tussle.', null, '["sensibility","pervasiveness","obliviousness","reticence"]', 3, 'Taciturnity = reticence.', true, '2026-10-24 01:04:06.382', '2026-10-24 01:04:06.382', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His <u>taciturnity</u> amazed everyone in the court during the legal tussle.', '["sensibility","pervasiveness","obliviousness","<u>reticence</u>"]', '<b>Taciturnity</b> = <b>reticence</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ecbfeb9f-3f29-4268-8cbd-2816bec582c8', 'Economics', 'JAMB', null, 2026, null, 'An economic system whereby the resources are owned and distributed by the government is?', null, '["Private individuals","Centrally planned economy","mixed economy","Capitalism"]', 1, 'In a centrally planned economy, resources are owned and distributed by the government.', true, '2026-09-12 11:00:51.857', '2026-09-12 11:00:51.857', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ecc40333-2940-4f32-ba88-a4560a84625e', 'Government', 'JAMB', null, 2026, null, 'The Oyomesi is headed by the', null, '["Aare Ona Kakanfo","Alaafin","Bashorun","Baale"]', 2, 'The Oyomesi is headed by the Bashorun. The Oyomesi was the council of seven chiefs in the Oyo Empire that advised the Alaafin (king). The Bashorun was the head of the Oyomesi and the most powerful chief, often acting as a check on the Alaafin''s power. The Aare Ona Kakanfo was the military commander, the Alaafin was the king, and the Baale was a local chief.', true, '2026-09-10 10:45:06.196', '2026-09-10 10:45:06.196', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ecc8fa23-3f84-46bb-9ecc-7d8c80855367', 'Government', 'JAMB', null, 2026, null, 'Under the 1963 constitution, items not listed in the exclusive and concurrent list were within the exclusive competence of the', null, '["Executive","federal parliament","regional legislatures","Judiciary"]', 2, 'Items not listed were within the exclusive competence of regional legislatures (residual matters).', true, '2026-09-12 11:23:54.506', '2026-09-12 11:23:54.506', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eccc1472-e9fb-413a-a601-4f319aa495f0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Once he has decided that something needs doing, my brother is very <u>unswerving</u> of purpose.', null, '["erratic","tenacious","stubborn","simple"]', 0, 'Unswerving = steady; opposite = erratic.', true, '2026-10-24 07:21:18.871', '2026-10-24 07:21:18.871', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Once he has decided that something needs doing, my brother is very <u>unswerving</u> of purpose.', '["erratic","tenacious","stubborn","simple"]', 'Unswerving = steady; opposite = erratic.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ece3dde3-0c14-4b8e-8265-02b4b208e639', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The manager was impressed by the man''s <u>eagerness</u>.', null, '["impatient","indifferences","negligence","calmness"]', 1, 'Eagerness = enthusiasm; opposite = indifference.', true, '2026-10-24 07:21:27.719', '2026-10-24 07:21:27.719', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The manager was impressed by the man''s <u>eagerness</u>.', '["impatient","indifferences","negligence","calmness"]', 'Eagerness = enthusiasm; opposite = indifference.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ece4368c-e525-4333-9dac-523b7f44113f', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''garlands'' symbolises', null, '["weapons of war","symbols of praise and honour","tools for farming","signs of punishment"]', 1, 'Garlands symbolize praise and honour.', true, '2026-09-12 11:12:10.059', '2026-09-12 11:12:10.059', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ecf56872-875e-42a6-9b76-4219972fd2e9', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is used to describe a payment representing a surplus in excess of transfer earnings?', null, '["interest rates","opportunity costs","economic rent","indirect costs","wages"]', 2, 'Economic rent is the payment made to a factor of production that exceeds its transfer earnings (the minimum amount needed to keep the factor in its current use). It represents a surplus above what is necessary to keep the factor employed in its present occupation. For example, if a worker would accept N50,000 to do a job but is paid N80,000, the economic rent is N30,000.', true, '2026-09-10 10:41:58.507', '2026-09-10 10:41:58.507', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ed0029f7-16d3-41aa-8b3e-70657f4955bb', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What was God''s purpose in creating man?', null, '["to be master of all creation","to help him look after the garden","to name the things he created","to multiply and fill the earth"]', 0, 'God''s purpose in creating man was to be master of all creation. God gave man dominion over the fish of the sea, the birds of the air, and every living thing that moves on the earth.', true, '2026-09-12 09:45:56.765', '2026-09-12 09:45:56.765', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ed045605-0974-4ce0-95f9-84d863e592cc', 'Literature in English', 'JAMB', null, 2026, null, 'The use of professional tools (clowns) in drama is primarily to', null, '["heighten emotion","create comic relief","develop plot","cause commotion"]', 1, 'Clowns create comic relief.', true, '2026-09-12 11:11:07.839', '2026-09-12 11:11:07.839', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ed0c17f4-4781-45b6-a029-aee8306be2a4', 'Literature in English', 'JAMB', null, 2026, null, 'In the play, "The Marriage of Anansewa", Anansewa opposes her father''s matchmaking attempt, arguing that she won''t be sold like a', null, '["maid","parcel","goat","commodity"]', 3, 'In "The Marriage of Anansewa," Anansewa opposes her father''s matchmaking attempt, arguing that she won''t be sold like a commodity. She objects to being treated as a piece of merchandise to be traded for her father''s financial gain. The word ''commodity'' emphasizes her refusal to be objectified and treated as property. This reflects the play''s theme of women''s rights and autonomy.', true, '2026-09-10 10:45:34.667', '2026-09-10 10:45:34.667', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ed0f9ddb-9c91-4304-a105-6b1f738bb738', 'Physics', 'JAMB', null, 1998, null, 'The force of attraction between two point masses is 10⁻⁴ N when the distance between them is 0.18 m. If the distance is reduced to 0.06 m, calculate the force.', null, '["1.1 x 10⁻⁵ N","3.3 x 10⁻⁵ N","3.0 x 10⁻⁴ N","9.0 x 10⁻⁴ N"]', 3, 'F is proportional to 1/r². The distance falls to one-third, so F rises by 3² = 9: 9 x 10⁻⁴ N.', true, '2026-10-12 19:15:44.87', '2026-10-12 19:15:44.87', null, null, null, 'The force of attraction between two point masses is 10<sup>-4</sup> N when the distance between them is 0.18 m. If the distance is reduced to 0.06 m, calculate the force.', '["1.1 x 10<sup>-5</sup> N","3.3 x 10<sup>-5</sup> N","3.0 x 10<sup>-4</sup> N","9.0 x 10<sup>-4</sup> N"]', 'F is proportional to 1/r<sup>2</sup>. The distance falls to one-third, so F rises by 3<sup>2</sup> = 9: 9 x 10<sup>-4</sup> N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ed198c8a-2190-424e-8ad7-cc060939b220', 'English Language', 'JAMB', null, 2007, null, 'The warring factions need words of <u>__________</u>', null, '["advise","adverse","advises","advice"]', 3, 'Correct spelling: advice.', true, '2026-10-24 07:21:45.676', '2026-10-24 07:21:45.676', null, null, null, 'The warring factions need words of <u>__________</u>', '["advise","adverse","advises","advice"]', 'Correct spelling: advice.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ed1cf1d6-a98e-417c-ab43-366b3a8d0645', 'Financial Accounting', 'UTME', null, 2002, null, 'The closing stock for the company is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791840819/questions/agxwxfwhdbkanunxjgdj.jpg', '["N72000","N45000","N42500","N31250"]', 3, 'The closing stock for the company is N31250.', true, '2026-10-12 21:59:57.434', '2026-10-12 21:59:57.434', null, null, null, 'The closing stock for the company is', '["N72000","N45000","N42500","<b>N31250</b>"]', 'The closing stock for the company is <b>N31250</b>.', '{"bold":["N31250"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ed363010-28ad-4461-941f-9c45ae5f0cf0', 'Physics', 'JAMB', null, 1991, null, 'Which of the following is the most suitable for use as an altimeter?', null, '["A mercury barometer","A fortin barometer","A mercury manometer","An aneroid barometer."]', 3, 'An aneroid barometer is portable and robust. Its dial can be calibrated in height, since atmospheric pressure falls with altitude.', true, '2026-10-12 19:15:32.382', '2026-10-12 19:15:32.382', null, null, null, 'Which of the following is the most suitable for use as an altimeter?', '["A mercury barometer","A fortin barometer","A mercury manometer","An aneroid barometer."]', 'An aneroid barometer is portable and robust. Its dial can be calibrated in height, since atmospheric pressure falls with altitude.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ed476beb-d6ec-43f9-bd82-08255156834c', 'Economics', 'JAMB', null, 2026, null, 'The Economic Commission for Africa was set up by the?', null, '["UNO","ECOWAS","WTO","OPEC"]', 0, 'The Economic Commission for Africa was set up by the UNO.', true, '2026-09-12 11:01:41.448', '2026-09-12 11:01:41.448', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ed480cea-6234-4faa-8c99-bb2fc100d3ff', 'Literature in English', 'JAMB', null, 2026, null, 'The picture presented is one of', null, '["quiet sea","dark sky","stormy weather","calm season"]', 2, 'The picture is of stormy weather.', true, '2026-09-12 11:11:04.057', '2026-09-12 11:11:04.057', null, null, null, null, null, null, null);
