insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ed6cb2dc-6c6d-497d-9fd0-1bd4dab9e2ee', 'Literature in English', 'JAMB', null, 2026, null, 'Ananse''s scheme to send identical letters to multiple chiefs is an example of', null, '["Dramatic irony and opportunistic manipulation","Catharsis leading to emotional purification","A tragic flaw resulting in his downfall","Symbolism representing colonial resistance"]', 0, 'Ananse''s scheme is an example of dramatic irony and opportunistic manipulation.', true, '2026-09-12 11:09:50.37', '2026-09-12 11:09:50.37', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ed93891a-983a-4c38-94d9-e39f3f5ac67c', 'Chemistry', 'JAMB', null, 2026, null, '25.0 cm³ of 0.20 mol/dm³ NaOH completely neutralizes 20.0 cm³ of H₂SO₄. Find the concentration of the acid.', null, '["0.10 mol/dm³","0.125 mol/dm³","0.20 mol/dm³","0.25 mol/dm³"]', 1, '2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O. Moles NaOH = 0.025 × 0.20 = 0.005 mol. Moles H₂SO₄ = 0.005/2 = 0.0025 mol. Concentration = 0.0025/0.020 = 0.125 mol/dm³.', true, '2026-09-12 11:35:47.497', '2026-09-12 11:35:47.497', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ed9e46b4-de7e-4dfd-b3d2-e5b80ac40a23', 'Government', 'JAMB', null, 2026, null, 'A major issue that distinguishes pressure groups from political party is', null, '["membership","objective","voting patterns","ideology"]', 1, 'The objective distinguishes pressure groups (influence policy) from political parties (capture power).', true, '2026-09-12 11:24:16.147', '2026-09-12 11:24:16.147', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eda29d49-d6ff-4b60-800f-c2d8549bbf96', 'Government', 'JAMB', null, 2026, null, 'As part of the reforms in the UN, two slots were proposed in the Security Council for', null, '["Africa","America","Asia","Europe"]', 0, 'Two slots were proposed for Africa in the UN Security Council.', true, '2026-09-12 11:24:41.122', '2026-09-12 11:24:41.122', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eda6c866-e944-40d7-b596-0bf820510b36', 'Financial Accounting', 'UTME', null, 2003, null, 'PQ Manufacturing Company: Raw materials (1/1/2001) 3 500, Raw materials (31/12/2001) 4 900, Purchases of raw materials 56 000, Salary 63 000, Wages 148 050, Factory lighting 3 080, Plant Depreciation 2 800, Factory insurance 2 170. The overhead cost is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841364/questions/nosxrvm114y656byywjh.jpg', '["N71 050","N68 250","N67 970","N66 080"]', 0, 'Overhead cost: Factory lighting 3080 + Plant Depreciation 2800 + Factory Insurance 2170 = 8050.', true, '2026-10-12 22:00:00.52', '2026-10-12 22:00:00.52', null, null, null, 'PQ Manufacturing Company: Raw materials (1/1/2001) 3 500, Raw materials (31/12/2001) 4 900, Purchases of raw materials 56 000, Salary 63 000, Wages 148 050, Factory lighting 3 080, Plant Depreciation 2 800, Factory insurance 2 170. The overhead cost is', '["<b>N71 050</b>","N68 250","N67 970","N66 080"]', 'Overhead cost: Factory lighting 3080 + Plant Depreciation 2800 + Factory Insurance 2170 = <b>8050</b>.', '{"bold":["8050"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('edae637e-e12a-4265-bdcf-8b721beb7df9', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation).) Olu promised to <u>look out for</u> her next time he is in town.', null, '["watch for","visit","greet","take care of"]', 3, '''Look out for'' = take care of.', true, '2026-10-24 01:04:16.429', '2026-10-24 01:04:16.429', null, null, null, '(Choose the most appropriate interpretation).) Olu promised to <u>look out for</u> her next time he is in town.', '["watch for","visit","greet","<u>take care of</u>"]', '''<b>Look out for</b>'' = <b>take care of</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('edafb550-117b-4593-b175-d06eafe1cf7a', 'Chemistry', 'JAMB', null, 2026, null, 'The following substances are non-electrolytes except', null, '["chloroform","sugar cane","acetic acid","NaCl","C and D"]', 4, 'Acetic acid and NaCl are electrolytes.', true, '2026-09-12 11:36:11.8', '2026-09-12 11:36:11.8', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('edb490d4-0050-423d-aae1-5f84d6a23935', 'Government', 'JAMB', null, 2026, null, 'The final interpretation of the provisions of a federal constitution is vested in the', null, '["highest legislative body","highest court of the land","head of state","council of state"]', 1, 'The highest court of the land interprets the constitution.', true, '2026-09-12 11:24:56.331', '2026-09-12 11:24:56.331', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('edb8818f-640d-4234-8295-b9d5728ecd9f', 'Physics', 'JAMB', null, 2026, null, 'A gold leaf electroscope is an instrument used to measure', null, '["Current","Charge","Size","Voltage","Relative Charge"]', 1, 'A gold leaf electroscope is used to detect and measure electric charge. It can also indicate the sign of the charge. It does not measure current, voltage, or size.', true, '2026-09-10 10:56:44.819', '2026-09-10 10:56:44.819', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('edbfa99a-f715-4145-84c0-2f7787d8d20f', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The judge <u>came down heavily</u> on the accused person in his judgment.', null, '["crashed heavily","fell down heading","descended upon heavily","imposed a stiff penalty","crash landed on"]', 3, '''Came down heavily on'' = imposed severe penalty.', true, '2026-10-24 01:04:16.268', '2026-10-24 01:04:16.268', null, null, null, '(Choose the most appropriate interpretation). The judge <u>came down heavily</u> on the accused person in his judgment.', '["crashed heavily","fell down heading","descended upon heavily","<u>imposed a stiff penalty</u>","crash landed on"]', '''<b>Came down heavily on</b>'' = <b>imposed severe penalty</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eddd2053-ff45-4115-b389-a1df2eba2fbf', 'Yoruba', 'JAMB', null, 2007, null, 'Ìwé Àkójópò Ewi Alohùn Yorùbá ni ìbéèrè 29-31 dá lé. Nínú Dadakúàdà, oríki Aáji Báyò ni', null, '["Àjàò Àgbé","Òmò Lómò","Àtàndá òmò Jìnádù","òkõ Wúrà."]', 0, 'Oríki Aáji Báyò ni Àjàò Àgbé.', true, '2026-10-13 13:23:31.959', '2026-10-13 13:23:31.959', null, null, null, 'Ìwé Àkójópò Ewi Alohùn Yorùbá ni ìbéèrè 29-31 dá lé. Nínú Dadakúàdà, oríki Aáji Báyò ni', '["Àjàò Àgbé","Òmò Lómò","Àtàndá òmò Jìnádù","òkõ Wúrà."]', 'Oríki Aáji Báyò ni Àjàò Àgbé.', '{"bold":["Àjàò Àgbé"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('edf305bb-7246-45a7-bc6d-e795f157d526', 'Physics', 'JAMB', null, 1995, null, 'A temperature scale has a lower fixed point of 40 mm and an upper fixed point of 200 mm. What is the reading on this scale when a thermometer reads 60 °C?', null, '["33.3 mm","36.0 mm","96.0 mm","136.0 mm"]', 3, 'Reading = 40 + (60/100) x (200 - 40) = 40 + 96 = 136.0 mm.', true, '2026-10-12 19:15:41.361', '2026-10-12 19:15:41.361', null, null, null, 'A temperature scale has a lower fixed point of 40 mm and an upper fixed point of 200 mm. What is the reading on this scale when a thermometer reads 60 °C?', '["33.3 mm","36.0 mm","96.0 mm","136.0 mm"]', 'Reading = 40 + (60/100) x (200 - 40) = 40 + 96 = 136.0 mm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('edfb99ac-7695-42e7-af70-df42f61f22be', 'Hausa', 'JAMB', null, 2010, null, 'A karkara da ma wasu manyan garuruwa kalilan, mutane kan hadu su rika cin abinci tare. Akan zabi gidan mutum daya daga cikinsu ya zama shi ne matattara. Mutumin da aka zabi gidansa, kusan shi ne shugaba, kuma ya fi kowa yawan shekaru. A wasu lokuta kuma, ana duba gidan da ya fi yalwa, ko ya fi zama kan hanya, babu wahala sosi zuwa gidan, musamman da damina. A wurin haduwa a ci abinci tare, kowane magidanci zai kawo abincin da aka dafa a gidansa, wanda ya fi shiga. Nan fa matan da suka kware suke shan yabo da godiya. Wadanda ba su iya ba kuwa, aiki ya gan su da kuma takaici. Saboda wasu mazan kan yi wa matansu gori. Ba nan ma abin ya tsaya ba, rashin iya abincin nan na iya haddasa mutuwar aure, idan ba a kai hankali nesa ba. Al''amari ya yi muni ke nan. Cikin abubuwan da ake kawowa, akwai tuwo da shinkafa da fate da dan wake da dambu da alkubus da doya da taliya da kuma makaroni. Ana kawo wasu daga cikin wadannan nau''o''in abinci tare da miya, wasu kuma a siffar dafa-duka. Duka dai wannan, ya danganta da irin cefanen da maigida ya yi. Akwai alfanu babba game da wannan zama. Da farko, akwai kyautata dangantaka da zaman tare. Ana kuma taimakon juna ta hanyar tattaua matsalolin da suka addabe su. Wanda ma ba ya da karfin yin abinci wani lokaci, ba zai tagayyara ba, zai sami abin da zai ci a wajen. A labarin, nau''o''in abinci nawa aka lissafa?', null, '["Shida.","Bakwai.","Takwas.","Tara."]', 3, 'An lissafa nau''o''in abinci tara a labarin.', true, '2026-10-13 10:37:23.341', '2026-10-13 10:37:23.341', null, null, null, 'A karkara da ma wasu manyan garuruwa kalilan, mutane kan hadu su rika cin abinci tare. Akan zabi gidan mutum daya daga cikinsu ya zama shi ne matattara. Mutumin da aka zabi gidansa, kusan shi ne shugaba, kuma ya fi kowa yawan shekaru. A wasu lokuta kuma, ana duba gidan da ya fi yalwa, ko ya fi zama kan hanya, babu wahala sosi zuwa gidan, musamman da damina. A wurin haduwa a ci abinci tare, kowane magidanci zai kawo abincin da aka dafa a gidansa, wanda ya fi shiga. Nan fa matan da suka kware suke shan yabo da godiya. Wadanda ba su iya ba kuwa, aiki ya gan su da kuma takaici. Saboda wasu mazan kan yi wa matansu gori. Ba nan ma abin ya tsaya ba, rashin iya abincin nan na iya haddasa mutuwar aure, idan ba a kai hankali nesa ba. Al''amari ya yi muni ke nan. Cikin abubuwan da ake kawowa, akwai tuwo da shinkafa da fate da dan wake da dambu da alkubus da doya da taliya da kuma makaroni. Ana kawo wasu daga cikin wadannan nau''o''in abinci tare da miya, wasu kuma a siffar dafa-duka. Duka dai wannan, ya danganta da irin cefanen da maigida ya yi. Akwai alfanu babba game da wannan zama. Da farko, akwai kyautata dangantaka da zaman tare. Ana kuma taimakon juna ta hanyar tattaua matsalolin da suka addabe su. Wanda ma ba ya da karfin yin abinci wani lokaci, ba zai tagayyara ba, zai sami abin da zai ci a wajen. A labarin, nau''o''in abinci nawa aka lissafa?', '["Shida.","Bakwai.","Takwas.","Tara."]', 'An lissafa nau''o''in abinci tara a labarin.', '{"bold":["tara"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('edfc3d4f-abdf-4546-9ffb-2d86684095d1', 'Economics', 'JAMB', null, 2026, null, 'The effect of an increase in demand for a commodity accompanied by a decrease in supply will be to', null, '["raise the price of the commodity and affect the quantity in an indeterminate way","decrease the equilibrium quantity and affect the price in an indeterminate way","raise its price as well as the equilibrium quantity","lower its price while affecting the equilibrium quantity in an indeterminate way"]', 0, 'An increase in demand accompanied by a decrease in supply will raise the price of the commodity and affect the quantity in an indeterminate way. Both changes (increase in demand and decrease in supply) put upward pressure on price, so price definitely rises. However, the effect on quantity is indeterminate because the increase in demand raises quantity while the decrease in supply lowers it. The net effect depends on the relative magnitudes of the changes.', true, '2026-09-10 10:41:59.277', '2026-09-10 10:41:59.277', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ee0287e0-e543-4608-911c-9209242cda90', 'Physics', 'JAMB', null, 1984, null, 'Which of the following properties of matter CANNOT be utilized for temperature measurement? The', null, '["Length of a liquid column","Volume of a gas at constant pressure.","Pressure of a gas at constant volume","Resistance of a metallic wire","Current produced in a photoelectric effect."]', 4, 'Liquid expansion, gas volume, gas pressure and wire resistance all vary predictably with temperature. Photoelectric current depends on light frequency and intensity, not temperature.', true, '2026-10-12 19:15:19.666', '2026-10-12 19:15:19.666', null, null, null, 'Which of the following properties of matter <b>CANNOT</b> be utilized for temperature measurement? The', '["Length of a liquid column","Volume of a gas at constant pressure.","Pressure of a gas at constant volume","Resistance of a metallic wire","Current produced in a photoelectric effect."]', 'Liquid expansion, gas volume, gas pressure and wire resistance all vary predictably with temperature. Photoelectric current depends on light frequency and intensity, not temperature.', '{"bold":["CANNOT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ee16a825-45fc-4757-9336-fdb0a37f5761', 'Yoruba', 'JAMB', null, 2007, null, 'Ka àwôn àyókà ìsàlẹ yìí, Kí o sì dáhùn àwòn ìbéèrè tí ó tẹlé wòn. Babárində nífèè Föláyadé púpõ. Föláyadé náà sì rèé, òrékelèwà òmõge, çlèyinjú-çgè, çlèrin-ín èyc! Òun náà sì dá ìfè yìí padà pèlú ayõ àti ìdùnnú. Bùgbòn bàbá Föláyadé ni igì wòròkò tí p da iná rú nídìí òrõ yìí: ó kórìíra Babárində nítorí pé ó kà á sí òtòyì ènìyàn. Bèè òmólójú rè sì ni Föláyadé í ÿe. Baba gbàgbò pé bí òmò òun bá fè Babárində, inú ìyà ni tòkòtaya wòn yóò wà. Kì í kúkú í ÿe pé Babárində jë tálákà bëë náà: ó p ÿiyë gëgë bí òÿìÿë kékere nílë-iÿë plá kan, bëë nì kò sì tòrò jç, ÿùgbòn ó kàn jë pé kò lówò tó Ayõkúnlé Atáyëwá, oníÿòwò kan tí baba Föláyadé fë kí òmò rë fë. Ìyá Föláyadé náà sì rèé, ìbi tí òkò rë bá të sí nì òun náà p të sí. Bé ojúbõrõ kò ni a sì fì p gbòmò lòwò ëkùrò: àwòn òbí Föláyadé fì toògùn-toògùn fa òmò wòn fún Ayõkúnlé Atáyëwá ÿaya. Babárində banùjë nídìí òrõ yìí, ëdùn-òkàn sì ni Föláyadé gbé wòlé òkò. Òjò þ gori ójò, òdún þ gori òdún, bèè ni ìgbà sì þ rékòjà lo. Fòláyadé bí akò, ó bi abo nílé òkò, ÿúgbòn nykan ò lò déédé fún òkò rè mò lënu òwò rè. Àwòn oníbodè ti gbèsè lé òjà rè tó jè çgbëlègbè náírà. Ó yáwó nílé-ìfowópamò, ÿúgbòn kò rí i san padà. Àwòn báykì bá gba ilé, òkò àti àwòn dúkiá rè mìíràn. Àtijç-àtimu wá di ìjòro fún òun àti ìyàwó rè àti àwon òmò wòn pèlú. Níha kejì, Babárində náà ti gbéyàwó, ó sì tí bímò. Lénu ìyê rê wàyìí, ó ti di ògá, orí sì ti sún un sólá. Àwòn òbí Föláyadé wá p wò sùn- ùn, wòn rí i bí ìgbé-ayé Ayõkúnlé Atáyéwá ÿe p lò, wòn sì tún wo ti Föláyadé òmò wòn, bákan náà ni wòn sì p gbókèèrè wo ti Babárində bó ÿe p dùn sí i fún un. Wòn wá fika àbámò bónu: ìwájú ò ÿeé lò, èyìn ò sì ÿeé padà sí fún wòn. Babárində, eni tí wòn rò pé kò lè pàgò ló wá dçni tí p kòlé aláruru. Ó wá hàn kedere sí wòn pé çni tí yóò dòlòlà lòla, orí ló mõ òn. Ohun tó mú àyípadà burúkú bá Atáyéwá ni pé', null, '["ó yáwó nílé-ìfowópamò","kõ jára mòyè mò","òwò rê lò sílè","wòn ÿàkóbá fún un"]', 2, 'Ohun tó mú àyípadà burúkú bá Atáyéwá ni pé òwò rê lò sílè.', true, '2026-10-13 13:23:30.696', '2026-10-13 13:23:30.696', null, null, null, 'Ka àwôn àyókà ìsàlẹ yìí, Kí o sì dáhùn àwòn ìbéèrè tí ó tẹlé wòn. Babárində nífèè Föláyadé púpõ. Föláyadé náà sì rèé, òrékelèwà òmõge, çlèyinjú-çgè, çlèrin-ín èyc! Òun náà sì dá ìfè yìí padà pèlú ayõ àti ìdùnnú. Bùgbòn bàbá Föláyadé ni igì wòròkò tí p da iná rú nídìí òrõ yìí: ó kórìíra Babárində nítorí pé ó kà á sí òtòyì ènìyàn. Bèè òmólójú rè sì ni Föláyadé í ÿe. Baba gbàgbò pé bí òmò òun bá fè Babárində, inú ìyà ni tòkòtaya wòn yóò wà. Kì í kúkú í ÿe pé Babárində jë tálákà bëë náà: ó p ÿiyë gëgë bí òÿìÿë kékere nílë-iÿë plá kan, bëë nì kò sì tòrò jç, ÿùgbòn ó kàn jë pé kò lówò tó Ayõkúnlé Atáyëwá, oníÿòwò kan tí baba Föláyadé fë kí òmò rë fë. Ìyá Föláyadé náà sì rèé, ìbi tí òkò rë bá të sí nì òun náà p të sí. Bé ojúbõrõ kò ni a sì fì p gbòmò lòwò ëkùrò: àwòn òbí Föláyadé fì toògùn-toògùn fa òmò wòn fún Ayõkúnlé Atáyëwá ÿaya. Babárində banùjë nídìí òrõ yìí, ëdùn-òkàn sì ni Föláyadé gbé wòlé òkò. Òjò þ gori ójò, òdún þ gori òdún, bèè ni ìgbà sì þ rékòjà lo. Fòláyadé bí akò, ó bi abo nílé òkò, ÿúgbòn nykan ò lò déédé fún òkò rè mò lënu òwò rè. Àwòn oníbodè ti gbèsè lé òjà rè tó jè çgbëlègbè náírà. Ó yáwó nílé-ìfowópamò, ÿúgbòn kò rí i san padà. Àwòn báykì bá gba ilé, òkò àti àwòn dúkiá rè mìíràn. Àtijç-àtimu wá di ìjòro fún òun àti ìyàwó rè àti àwon òmò wòn pèlú. Níha kejì, Babárində náà ti gbéyàwó, ó sì tí bímò. Lénu ìyê rê wàyìí, ó ti di ògá, orí sì ti sún un sólá. Àwòn òbí Föláyadé wá p wò sùn- ùn, wòn rí i bí ìgbé-ayé Ayõkúnlé Atáyéwá ÿe p lò, wòn sì tún wo ti Föláyadé òmò wòn, bákan náà ni wòn sì p gbókèèrè wo ti Babárində bó ÿe p dùn sí i fún un. Wòn wá fika àbámò bónu: ìwájú ò ÿeé lò, èyìn ò sì ÿeé padà sí fún wòn. Babárində, eni tí wòn rò pé kò lè pàgò ló wá dçni tí p kòlé aláruru. Ó wá hàn kedere sí wòn pé çni tí yóò dòlòlà lòla, orí ló mõ òn. Ohun tó mú àyípadà burúkú bá Atáyéwá ni pé', '["ó yáwó nílé-ìfowópamò","kõ jára mòyè mò","òwò rê lò sílè","wòn ÿàkóbá fún un"]', 'Ohun tó mú àyípadà burúkú bá Atáyéwá ni pé òwò rê lò sílè.', '{"bold":["òwò rê lò sílè"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ee36a360-d666-4b51-a8f6-17b44a871685', 'Government', 'JAMB', null, 2026, null, 'The arm of Government that is responsible for safeguarding the rights and liberties of individuals is the', null, '["Cabinet","Judiciary","Legislature","Executive"]', 1, 'The arm of government responsible for safeguarding the rights and liberties of individuals is the judiciary. The judiciary interprets laws, resolves disputes, and ensures that the rights and liberties of citizens are protected. Through judicial review, courts can declare laws or actions of the executive unconstitutional if they violate citizens'' rights. The legislature makes laws, and the executive implements them, but the judiciary protects rights through interpretation and enforcement.', true, '2026-09-10 10:45:07.105', '2026-09-10 10:45:07.105', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ee3abd5f-16be-4b4e-8f35-7e5fe4b90f13', 'General Mathematics', 'JAMB', null, 2026, null, 'Madam Kofi imported a quantity of frozen food costing $400.00. The goods attracted an import duty of 15% of its cost. She also paid the sales tax 10% of the total cost of the goods including import duty. If she sells the total goods as $660.00, calculate her percentage profit', null, '["30.43%","50.29%","33.43%","0.01%","29.2%"]', 0, 'Import duty = 15% of 400 = 60. Total after duty = 460. Sales tax = 10% of 460 = 46. Total cost = 506. Profit = 660 - 506 = 154. Percentage profit = 154/506 × 100 = 30.43%.', true, '2026-09-12 11:43:41.752', '2026-09-12 11:43:41.752', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ee4bc33d-25d3-470e-b0bb-86d6dde2bc46', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. This year''s harvest is <u>surplus</u>.', null, '["enough for our need","limitless","more than enough","plenty"]', 2, 'Surplus = more than enough.', true, '2026-10-24 01:03:54.564', '2026-10-24 01:03:54.564', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. This year''s harvest is <u>surplus</u>.', '["enough for our need","limitless","<u>more than enough</u>","plenty"]', '<b>Surplus</b> = <b>more than enough</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ee51b17f-1bcc-4372-8b37-fb65222561a8', 'Physics', 'JAMB', null, 2026, null, 'Which of the following is not affected by friction in machines?', null, '["efficiency","effort","velocity ratio","mechanical advantage"]', 2, 'The velocity ratio is not affected by friction in machines. It is determined purely by the geometry of the machine. Efficiency, effort, and mechanical advantage are all affected by friction. Friction reduces efficiency and increases the effort required.', true, '2026-09-10 10:56:42.438', '2026-09-10 10:56:42.438', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ee5bc8b6-2783-4053-983f-059f282614c2', 'Biology', 'JAMB', null, 2001, null, 'Carbon (IV) oxide content of the atmosphere is least affected by', null, '["burning of fossil fuel","cutting down and clearing of forests","plant and animal respiration","forest fires"]', 2, 'Plant and animal respiration has the least effect on atmospheric CO2.', true, '2026-10-12 20:59:28.902', '2026-10-12 20:59:28.902', null, null, null, 'Carbon (IV) oxide content of the atmosphere is least affected by', '["burning of fossil fuel","cutting down and clearing of forests","plant and animal respiration","forest fires"]', 'Plant and animal respiration has the least effect on atmospheric CO2.', '{"bold":["Plant and animal respiration"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ee5f442c-f1f4-45e2-a5fc-84c36c28c08f', 'Physics', 'JAMB', null, 1987, null, 'If the angle of declination in a place is 10° E, calculate the true geographic bearing if the compass reads N 40° E.', null, '["N 50° E","N 40° E","N 30° E","N 25° E"]', 0, 'With easterly declination, the magnetic north lies 10° east of true north, so true bearing = 40° + 10° = N 50° E.', true, '2026-10-12 19:15:26.192', '2026-10-12 19:15:26.192', null, null, null, 'If the angle of declination in a place is 10° E, calculate the true geographic bearing if the compass reads N 40° E.', '["N 50° E","N 40° E","N 30° E","N 25° E"]', 'With easterly declination, the magnetic north lies 10° east of true north, so true bearing = 40° + 10° = N 50° E.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ee655967-365a-45c1-8e1c-a4c8f035639c', 'English Language', 'JAMB', null, 2024, null, 'Despite all preparations, the wedding did not ______', null, '["come up","come along","come by","come off","come on"]', 3, '"Come off" means to take place or happen successfully.', true, '2026-09-18 09:24:04.946', '2026-09-18 09:24:04.946', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ee6beae9-0e45-4696-aaa6-b96528492c15', 'Yoruba', 'JAMB', null, 2007, null, 'Ìwé Iyán Ogún Òdún ni ìbéèrè 38-40 dá lé. Çni tó kó gbogbo òmò-ogun jó tó sì ÿètò ìjagun ni', null, '["Balógun","Ògúnlérè","Agbégépbé","Arówóná."]', 0, 'Balógun ni ó kó gbogbo òmò-ogun jó tó sì ÿètò ìjagun.', true, '2026-10-13 13:23:32.395', '2026-10-13 13:23:32.395', null, null, null, 'Ìwé Iyán Ogún Òdún ni ìbéèrè 38-40 dá lé. Çni tó kó gbogbo òmò-ogun jó tó sì ÿètò ìjagun ni', '["Balógun","Ògúnlérè","Agbégépbé","Arówóná."]', 'Balógun ni ó kó gbogbo òmò-ogun jó tó sì ÿètò ìjagun.', '{"bold":["Balógun"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ee8474ab-919e-41df-94c4-80224b42b591', 'Economics', 'JAMB', null, 2026, null, 'In order to increase revenue, the seller of a commodity whose demand is fairly elastic is advised to', null, '["retain price","reduce output","increase price","reduce price"]', 3, 'In order to increase revenue, the seller of a commodity whose demand is fairly elastic is advised to reduce price. When demand is elastic (PED > 1), a decrease in price leads to a proportionately larger increase in quantity demanded, so total revenue rises. Conversely, an increase in price would lead to a proportionately larger fall in quantity demanded, reducing total revenue. This is the relationship between price elasticity of demand and total revenue.', true, '2026-09-10 10:42:00.877', '2026-09-10 10:42:00.877', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ee8eae30-ceba-4fb0-bd7a-c5a29bf2937d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The new ruler is <u>big-hearted</u> in his dealings with the people.', null, '["generous","cruel","soft","proud"]', 0, 'Big-hearted = generous.', true, '2026-10-24 01:01:50.397', '2026-10-24 01:01:50.397', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The new ruler is <u>big-hearted</u> in his dealings with the people.', '["<u>generous</u>","cruel","soft","proud"]', '<b>Big-hearted</b> = <b>generous</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ee936949-9025-4f22-91bf-3b0a3f0cb658', 'Hausa', 'JAMB', null, 2011, null, '''Ita ko bante ta ketara sai ta haihu, In ka san kudi su kare a suna'' Wannan tsakure na ''WaKar Zambon Kazama'' ta Mal. Aliyu Namangi, ta ZaBaßßun WaKokin Da Da Na Yanzu, na D. Abdulkadir yana Magana ne a kan', null, '["tsofaffi","masu gwanne","mata karuwai","zawarawa."]', 1, 'Yana magana ne a kan masu gwanne.', true, '2026-10-13 10:37:22.804', '2026-10-13 10:37:22.804', null, null, null, '''Ita ko bante ta ketara sai ta haihu, In ka san kudi su kare a suna'' Wannan tsakure na ''WaKar Zambon Kazama'' ta Mal. Aliyu Namangi, ta ZaBaßßun WaKokin Da Da Na Yanzu, na D. Abdulkadir yana Magana ne a kan', '["tsofaffi","masu gwanne","mata karuwai","zawarawa."]', 'Yana magana ne a kan masu gwanne.', '{"bold":["masu gwanne"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eeab2edf-a1c8-44bf-a371-ddae19db663f', 'General Mathematics', 'JAMB', null, 2026, null, 'The nth term of the progression: 4/2, 7/3, 10/4, 13/5', null, '["(1-3n)/(n+1)","(3n+1)/(n+1)","(3n+1)/(n-1)","(3n-1)/(n+1)"]', 3, 'Numerator: 4,7,10,13 = 3n+1. Denominator: 2,3,4,5 = n+1. So nth term = (3n+1)/(n+1).', true, '2026-09-12 11:43:47.363', '2026-09-12 11:43:47.363', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eebc0691-4056-48d0-a7a6-1448b9dde6a8', 'General Mathematics', 'JAMB', null, 2026, null, 'Simplify (3ⁿ - 3ⁿ⁻¹)/(3³ × 3ⁿ - 3³ × 3ⁿ⁻¹)', null, '["1/27","-1/27","27","-27"]', 0, 'Numerator = 3ⁿ⁻¹(3-1) = 2×3ⁿ⁻¹. Denominator = 27×3ⁿ⁻¹(3-1) = 54×3ⁿ⁻¹. Ratio = 2/54 = 1/27.', true, '2026-09-12 11:43:46.913', '2026-09-12 11:43:46.913', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eec635a8-5379-410c-8d81-b5a9fa728a16', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The confused student found himself <u>in a spot</u>.', null, '["in a particular place","in a normal situation","in a pleasant situation","in a difficult situation"]', 3, '''In a spot'' = in a difficult situation.', true, '2026-10-24 01:04:21.255', '2026-10-24 01:04:21.255', null, null, null, '(Choose the most appropriate interpretation). The confused student found himself <u>in a spot</u>.', '["in a particular place","in a normal situation","in a pleasant situation","<u>in a difficult situation</u>"]', '''<b>In a spot</b>'' = <b>in a difficult situation</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eecfff5e-2877-466d-a3f1-778fccf64e6e', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Moses, after killing the Egyptian, fled to...', null, '["the land of Canaan","the land of Midian","the land of Philistines","the land of the Hittites"]', 1, 'Exodus 2:15 states that when Pharaoh heard of the killing, he sought to kill Moses, but Moses fled and dwelt in the land of Midian.', true, '2026-09-09 17:18:25.363', '2026-09-09 17:18:25.363', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eeeb0f78-da23-42a4-b9b4-e1a2f1bf6987', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Eli fell down and died because of the', null, '["defeat of the Israelites","behavior of his delinquent children","capture of the Ark of Covenant","death of his two children"]', 2, 'Eli died when he heard the Ark of God was captured.', true, '2026-09-12 10:41:39.596', '2026-09-12 10:41:39.596', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eeeed57b-5e1b-4854-acc6-2bd7e036d606', 'Biology', 'JAMB', null, 2003, null, 'The cell component that is present in a prokaryotic cell is the', null, '["chloroplast","ribosome","mitochondrion","nuclear envelope"]', 1, 'Prokaryotes lack membrane-bound organelles but possess ribosomes for protein synthesis.', true, '2026-10-12 20:05:09.45', '2026-10-12 20:05:09.45', null, null, null, 'The cell component that is present in a prokaryotic cell is the', '["chloroplast","ribosome","mitochondrion","nuclear envelope"]', 'Prokaryotes lack membrane-bound organelles but possess ribosomes for protein synthesis.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eef0d3ec-f51b-40f9-93f3-fe4d21d0feda', 'English Language', 'JAMB', null, 2007, null, 'The patient is suffering from <u>__________</u>', null, '["reumatism","rheumantism","rhuematism","rheumatism"]', 3, 'Correct spelling: rheumatism.', true, '2026-10-24 07:21:33.652', '2026-10-24 07:21:33.652', null, null, null, 'The patient is suffering from <u>__________</u>', '["reumatism","rheumantism","rhuematism","rheumatism"]', 'Correct spelling: rheumatism.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eef2da76-9efc-44c4-9ee9-607f3bfd4330', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She <u>scowled</u> furiously at his back as he walked away.', null, '["whispered","grimaced","screeched","screamed"]', 1, 'Scowled = grimaced.', true, '2026-10-24 01:04:11.223', '2026-10-24 01:04:11.223', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She <u>scowled</u> furiously at his back as he walked away.', '["whispered","<u>grimaced</u>","screeched","screamed"]', '<b>Scowled</b> = <b>grimaced</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('eef9c50f-ef95-4bd1-8c70-3cc82d82bd85', 'Government', 'JAMB', null, 2026, null, 'The formation of ECOMOG was spearheaded by', null, '["Sanni Abacha","Muhammadu Buhari","Abdulsalam Abubakar","Ibrahim Babangida"]', 3, 'Ibrahim Babangida spearheaded the formation of ECOMOG.', true, '2026-09-12 11:24:41.79', '2026-09-12 11:24:41.79', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ef085b8e-0f1b-47b8-9156-7866b3bd1664', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He <u>detests</u> honesty', null, '["likes","hates","encourages","commands"]', 1, 'Detests = hates.', true, '2026-10-24 01:01:59.614', '2026-10-24 01:01:59.614', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He <u>detests</u> honesty', '["likes","<u>hates</u>","encourages","commands"]', '<b>Detests</b> = <b>hates</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ef23a42e-881e-4781-b873-c459cbb11815', 'Chemistry', 'JAMB', null, 2026, null, 'Aluminum oxide is?', null, '["Basic","Acidic","Neutral","Amphoteric"]', 3, 'Al₂O₃ is amphoteric.', true, '2026-09-12 11:36:21.998', '2026-09-12 11:36:21.998', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ef3993af-bd17-4db1-bbc9-4a196c2501e1', 'Hausa', 'JAMB', null, 2010, null, 'A karkara da ma wasu manyan garuruwa kalilan, mutane kan hadu su rika cin abinci tare. Akan zabi gidan mutum daya daga cikinsu ya zama shi ne matattara. Mutumin da aka zabi gidansa, kusan shi ne shugaba, kuma ya fi kowa yawan shekaru. A wasu lokuta kuma, ana duba gidan da ya fi yalwa, ko ya fi zama kan hanya, babu wahala sosi zuwa gidan, musamman da damina. A wurin haduwa a ci abinci tare, kowane magidanci zai kawo abincin da aka dafa a gidansa, wanda ya fi shiga. Nan fa matan da suka kware suke shan yabo da godiya. Wadanda ba su iya ba kuwa, aiki ya gan su da kuma takaici. Saboda wasu mazan kan yi wa matansu gori. Ba nan ma abin ya tsaya ba, rashin iya abincin nan na iya haddasa mutuwar aure, idan ba a kai hankali nesa ba. Al''amari ya yi muni ke nan. Cikin abubuwan da ake kawowa, akwai tuwo da shinkafa da fate da dan wake da dambu da alkubus da doya da taliya da kuma makaroni. Ana kawo wasu daga cikin wadannan nau''o''in abinci tare da miya, wasu kuma a siffar dafa-duka. Duka dai wannan, ya danganta da irin cefanen da maigida ya yi. Akwai alfanu babba game da wannan zama. Da farko, akwai kyautata dangantaka da zaman tare. Ana kuma taimakon juna ta hanyar tattaua matsalolin da suka addabe su. Wanda ma ba ya da karfin yin abinci wani lokaci, ba zai tagayyara ba, zai sami abin da zai ci a wajen. Mata na kubuta daga gorin mazansu saboda iya', null, '["dafa abinci","magana","kyauta","cin abinci."]', 0, 'Mata na kubuta daga gorin mazansu saboda iya dafa abinci.', true, '2026-10-13 10:37:23.234', '2026-10-13 10:37:23.234', null, null, null, 'A karkara da ma wasu manyan garuruwa kalilan, mutane kan hadu su rika cin abinci tare. Akan zabi gidan mutum daya daga cikinsu ya zama shi ne matattara. Mutumin da aka zabi gidansa, kusan shi ne shugaba, kuma ya fi kowa yawan shekaru. A wasu lokuta kuma, ana duba gidan da ya fi yalwa, ko ya fi zama kan hanya, babu wahala sosi zuwa gidan, musamman da damina. A wurin haduwa a ci abinci tare, kowane magidanci zai kawo abincin da aka dafa a gidansa, wanda ya fi shiga. Nan fa matan da suka kware suke shan yabo da godiya. Wadanda ba su iya ba kuwa, aiki ya gan su da kuma takaici. Saboda wasu mazan kan yi wa matansu gori. Ba nan ma abin ya tsaya ba, rashin iya abincin nan na iya haddasa mutuwar aure, idan ba a kai hankali nesa ba. Al''amari ya yi muni ke nan. Cikin abubuwan da ake kawowa, akwai tuwo da shinkafa da fate da dan wake da dambu da alkubus da doya da taliya da kuma makaroni. Ana kawo wasu daga cikin wadannan nau''o''in abinci tare da miya, wasu kuma a siffar dafa-duka. Duka dai wannan, ya danganta da irin cefanen da maigida ya yi. Akwai alfanu babba game da wannan zama. Da farko, akwai kyautata dangantaka da zaman tare. Ana kuma taimakon juna ta hanyar tattaua matsalolin da suka addabe su. Wanda ma ba ya da karfin yin abinci wani lokaci, ba zai tagayyara ba, zai sami abin da zai ci a wajen. Mata na kubuta daga gorin mazansu saboda iya', '["dafa abinci","magana","kyauta","cin abinci."]', 'Mata na kubuta daga gorin mazansu saboda iya dafa abinci.', '{"bold":["dafa abinci"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ef427db1-ccf8-4cf5-a095-f44efab9c1b6', 'Government', 'JAMB', null, 2026, null, 'The highest grade in the civil service is known as the', null, '["clerical cadre","executive cadre","technical cadre","administrative cadre"]', 3, 'The highest grade in the civil service is known as the administrative cadre. The administrative class occupies the top of the civil service hierarchy. Its members are responsible for policy formulation, advising ministers, coordinating government activities, and overseeing the implementation of policies. They are the elite of the civil service and are involved in high-level decision-making. The clerical, executive, and technical cadres are lower grades.', true, '2026-09-10 10:44:18.08', '2026-09-10 10:44:18.08', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ef42c1d1-d38b-4146-a473-b798571b586c', 'Hausa', 'JAMB', null, 2011, null, 'Wakar ''Gadar Zare'' ta ZaBaßßun Wakokin Da Da Na Yanzu na D. Abdulkadir ''yar kwar nawa ce?', null, '["Biyu.","Uku.","Hudu.","Biyar."]', 0, 'Wakar ''Gadar Zare'' ''yar kwar biyu ce.', true, '2026-10-13 10:37:22.858', '2026-10-13 10:37:22.858', null, null, null, 'Wakar ''Gadar Zare'' ta ZaBaßßun Wakokin Da Da Na Yanzu na D. Abdulkadir ''yar kwar nawa ce?', '["Biyu.","Uku.","Hudu.","Biyar."]', 'Wakar ''Gadar Zare'' ''yar kwar biyu ce.', '{"bold":["biyu"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ef4cb4aa-dd9f-4a95-a81d-b42399fcd14e', 'Biology', 'JAMB', null, 0, null, 'answer the image above ', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791839002/questions/oalwoej0a4dlu8nsbpwv.jpg', '["a","b","c","d"]', 3, 'Part IV points to the small spot on the yolk where embryonic development begins', true, '2026-10-12 21:04:27.867', '2026-10-12 21:04:27.867', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ef4f0591-cd8c-4989-8e16-380e2cce9348', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). He suddenly <u>found himself in the thick of the situation.</u>', null, '["He did not agree with the situation","He used his experience to settle the situation","He saved himself out of the situation","He found himself deeply involved in the situation"]', 3, '''In the thick of'' = deeply involved.', true, '2026-10-24 01:04:23.987', '2026-10-24 01:04:23.987', null, null, null, '(Choose the most appropriate interpretation). He suddenly <u>found himself in the thick of the situation.</u>', '["He did not agree with the situation","He used his experience to settle the situation","He saved himself out of the situation","<u>He found himself deeply involved in the situation</u>"]', '''<b>In the thick of</b>'' = <b>deeply involved</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ef5516b4-3af3-45b3-8fdb-6267c00d2985', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). We will surely <u>buy this idea of</u> introducing an entirely new product.', null, '["pay for","accept","trade in","barter"]', 1, '''Buy an idea'' = accept it.', true, '2026-10-24 01:04:16.911', '2026-10-24 01:04:16.911', null, null, null, '(Choose the most appropriate interpretation). We will surely <u>buy this idea of</u> introducing an entirely new product.', '["pay for","<u>accept</u>","trade in","barter"]', '''<b>Buy an idea</b>'' = <b>accept it</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ef7034b6-b0cb-49b6-a0b3-730c65cf8bfd', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). <u>For all he cared, the game was as good as lost</u>.', null, '["He did not care if the game was lost","He could not care less if the game was lost","He was almost certain that the game would be lost","He was afraid the game would be lost","The game was very good, and he cared very much about losing it"]', 0, '''For all he cared'' = did not care.', true, '2026-10-24 01:02:01.635', '2026-10-24 01:02:01.635', null, null, null, '(Choose the most appropriate interpretation). <u>For all he cared, the game was as good as lost</u>.', '["<u>He did not care if the game was lost</u>","He could not care less if the game was lost","He was almost certain that the game would be lost","He was afraid the game would be lost","The game was very good, and he cared very much about losing it"]', '''<b>For all he cared</b>'' = <b>did not care</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ef96c484-a2b1-4f1b-aad2-32acc9eed0f9', 'Physics', 'JAMB', null, 2026, null, 'The distance between two successive crests of a water wave is 0.25m. If a particle on the surface of the water makes four complete vertical oscillations in one second. Calculate the speed of the wave.', null, '["4ms⁻¹","3ms⁻¹","2ms⁻¹","1ms⁻¹"]', 3, 'Wavelength = 0.25m. Frequency = 4 Hz. Speed = frequency × wavelength = 4 × 0.25 = 1 ms⁻¹.', true, '2026-09-10 10:56:43.469', '2026-09-10 10:56:43.469', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('efae6bc9-a978-4b6c-b50b-ceecf6524923', 'Physics', 'JAMB', null, 2004, null, 'What types of mirrors are capable of producing parallel beams of light such as those arising from the headlamps of a car?', null, '["Cylindrical mirrors","Parabolic mirrors","Spherical mirrors","Plane mirrors"]', 1, 'A parabolic reflector sends light from a source at its focus out as a truly parallel beam, which is why it is used in headlamps.', true, '2026-10-12 19:15:58.177', '2026-10-12 19:15:58.177', null, null, null, 'What types of mirrors are capable of producing parallel beams of light such as those arising from the headlamps of a car?', '["Cylindrical mirrors","Parabolic mirrors","Spherical mirrors","Plane mirrors"]', 'A parabolic reflector sends light from a source at its focus out as a truly parallel beam, which is why it is used in headlamps.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('efb18278-4749-4224-9f5a-cbd777da8927', 'English Language', 'JAMB', null, 2007, null, 'It is African for a younger person to show <u>__________</u> to elders.', null, '["satisfaction","deference","understanding","indifference"]', 1, 'Correct spelling: deference.', true, '2026-10-24 07:21:39.066', '2026-10-24 07:21:39.066', null, null, null, 'It is African for a younger person to show <u>__________</u> to elders.', '["satisfaction","deference","understanding","indifference"]', 'Correct spelling: deference.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('efbf2c13-293e-4a82-9ce7-84e86cbd85db', 'Physics', 'JAMB', null, 1992, null, 'After three half-lives, the fraction of a radioactive material that has decayed is', null, '["1/8","1/3","2/3","7/8"]', 3, 'After three half-lives (1/2)³ = 1/8 remains, so 7/8 has decayed.', true, '2026-10-12 19:15:36.788', '2026-10-12 19:15:36.788', null, null, null, 'After three half-lives, the fraction of a radioactive material that has decayed is', '["1/8","1/3","2/3","7/8"]', 'After three half-lives (1/2)<sup>3</sup> = 1/8 remains, so 7/8 has decayed.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('efc05210-2bb5-4770-a9e9-21d552d8a602', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''Do not be afraid, but speak and do not be silent for I am with you, and no man shall attack you to harm you; for I have many people in this city.'' The city referred to was', null, '["Corinth","Ephesus","Athens","Troas"]', 0, 'The Lord appeared to Paul in Corinth with this encouragement.', true, '2026-09-12 10:41:50.462', '2026-09-12 10:41:50.462', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('efda1e1f-f017-425c-82c9-c63cc61630ae', 'Biology', 'JAMB', null, 2004, null, 'A caterpillar and an aphid living in different parts of the same plant can be said to', null, '["occupy the same ecological niche","be in different habitats","occupy different ecological niches","be in similar microhabitats"]', 2, 'They occupy different ecological niches.', true, '2026-10-12 20:59:35.375', '2026-10-12 20:59:35.375', null, null, null, 'A caterpillar and an aphid living in different parts of the same plant can be said to', '["occupy the same ecological niche","be in different habitats","occupy different ecological niches","be in similar microhabitats"]', 'They occupy different ecological niches.', '{"bold":["occupy different ecological niches"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f000f8f0-f55e-4979-b766-4bed2e3494ab', 'Physics', 'JAMB', null, 2000, null, 'A rope is being used to pull a mass of 10 kg vertically upward. Determine the tension in the rope if, starting from rest, the mass acquires a velocity of 4 m s⁻¹ in 8 s. [g = 10 m s⁻²]', null, '["105 N","95 N","50 N","5 N"]', 0, 'a = 4/8 = 0.5 m s⁻². T - mg = ma, so T = 10(10 + 0.5) = 105 N.', true, '2026-10-12 19:15:49.374', '2026-10-12 19:15:49.374', null, null, null, 'A rope is being used to pull a mass of 10 kg vertically upward. Determine the tension in the rope if, starting from rest, the mass acquires a velocity of 4 m s<sup>-1</sup> in 8 s. [g = 10 m s<sup>-2</sup>]', '["105 N","95 N","50 N","5 N"]', 'a = 4/8 = 0.5 m s<sup>-2</sup>. T - mg = ma, so T = 10(10 + 0.5) = 105 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f004edec-a845-4abb-8310-0dbf88276ff1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Chihuzor gave a <u>curt</u> nod and walked away.', null, '["gentle","rude","polite","shocking"]', 2, 'Curt = abrupt; opposite = polite.', true, '2026-10-24 07:21:29.922', '2026-10-24 07:21:29.922', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Chihuzor gave a <u>curt</u> nod and walked away.', '["gentle","rude","polite","shocking"]', 'Curt = abrupt; opposite = polite.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0071657-4f4c-47f7-a5bb-cdc6143fffb1', 'English Language', 'JAMB', null, 2007, null, 'His mother always reprimands him for being a <u>__________</u> reader of cheap novels', null, '["vicious","veracious","vivacious","voracious"]', 3, 'Correct spelling: voracious.', true, '2026-10-24 07:21:40.077', '2026-10-24 07:21:40.077', null, null, null, 'His mother always reprimands him for being a <u>__________</u> reader of cheap novels', '["vicious","veracious","vivacious","voracious"]', 'Correct spelling: voracious.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f00914ff-470c-4400-8575-b82eaef0d090', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Our party is <u>wielding</u> potent political power.', null, '["assuming","renouncing","restoring","reappraising"]', 1, 'Wielding = exercising; opposite = renouncing.', true, '2026-10-24 07:21:16.842', '2026-10-24 07:21:16.842', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Our party is <u>wielding</u> potent political power.', '["assuming","renouncing","restoring","reappraising"]', 'Wielding = exercising; opposite = renouncing.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f032d3f1-c5f4-4577-9139-4a5bed6fc053', 'Physics', 'JAMB', null, 2003, null, 'If the uncertainty in the measurement of the position of a particle is 5 x 10⁻¹⁰ m, the uncertainty in the momentum of the particle is [h = 6.6 x 10⁻³⁴ J s]', null, '["3.30 x 10⁻⁴⁴ N s","3.30 x 10⁻²⁴ N s","1.32 x 10⁻⁴⁴ N s","1.32 x 10⁻²⁴ N s"]', 3, 'Using Δx Δp ≈ h: Δp = h/Δx = (6.6 x 10⁻³⁴)/(5 x 10⁻¹⁰) = 1.32 x 10⁻²⁴ N s.', true, '2026-10-12 19:15:57.908', '2026-10-12 19:15:57.908', null, null, null, 'If the uncertainty in the measurement of the position of a particle is 5 x 10<sup>-10</sup> m, the uncertainty in the momentum of the particle is [h = 6.6 x 10<sup>-34</sup> J s]', '["3.30 x 10<sup>-44</sup> N s","3.30 x 10<sup>-24</sup> N s","1.32 x 10<sup>-44</sup> N s","1.32 x 10<sup>-24</sup> N s"]', 'Using Δx Δp ≈ h: Δp = h/Δx = (6.6 x 10<sup>-34</sup>)/(5 x 10<sup>-10</sup>) = 1.32 x 10<sup>-24</sup> N s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f035b646-f544-4abd-8f13-bcf019a98b28', 'Government', 'JAMB', null, 2026, null, 'The first political party in Nigeria was formed after the introduction of the', null, '["Richards Constitution","Clifford Constitution","Bourdillon Constitution","Macpherson Constitution"]', 1, 'The first political party was formed after the Clifford Constitution.', true, '2026-09-12 11:24:26.761', '2026-09-12 11:24:26.761', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f046e3d6-a51f-4bf2-894a-49dd5ea2670b', 'Economics', 'JAMB', null, 2026, null, 'An economic system in which most capital goods are owned by individuals and private firms is known as', null, '["planned economy","capitalist economy","Mixed economy","socialist economy"]', 1, 'An economic system in which most capital goods are owned by individuals and private firms is known as a capitalist economy. In capitalism, the means of production are privately owned and operated for profit. Market forces of supply and demand determine what is produced, how it is produced, and for whom. The government plays a minimal role in economic decisions. A planned economy has state ownership, a mixed economy combines both, and a socialist economy has collective ownership.', true, '2026-09-10 10:42:56.041', '2026-09-10 10:42:56.041', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f04c7c3e-bd7e-4af6-a478-239b0d97ccc7', 'General Mathematics', 'JAMB', null, 2026, null, 'Calculate the area of the major sector of a circle which subtends an angle of 130° at the centre and having radius 14cm (take π = 3.14)', null, '["220cm²","222.24cm²","224.33cm²","334cm²"]', 2, 'Major sector angle = 360-130 = 230°. Area = (230/360)πr² = (23/36)(3.14)(196) = 224.33 cm².', true, '2026-09-12 11:44:02.93', '2026-09-12 11:44:02.93', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f04de8db-9129-4864-8c51-d46f56a4f93c', 'English Language', 'JAMB', null, 2024, null, 'Which of the following sentences is correct?', null, '["the crates of eggs were offloaded from the car with extreme, slowly care","the crates of eggs were offloaded from the car with slowly extreme care","the crates of eggs were offloaded from the car slowly, with extreme care","the crates of eggs were offloaded from the car extreme slowly, with care"]', 2, 'Adverbs of manner ("slowly") and prepositional phrases ("with extreme care") should be placed logically and not combined awkwardly. Option C reads naturally and grammatically correctly.', true, '2026-09-18 09:23:08.224', '2026-09-18 09:23:08.224', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f04e921b-c4a9-4d44-81f5-62924700a31a', 'Literature in English', 'JAMB', null, 2026, null, 'What is the approximate age of the celebrant in the poem?', null, '["fifty-five","five and eighty","eighty-five","ninety-five"]', 2, 'The celebrant is approximately eighty-five.', true, '2026-09-12 11:13:46.845', '2026-09-12 11:13:46.845', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f05edcb2-d8d8-415a-86f3-554200fe17e2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Dupe was promoted by her <u>efficiency</u>.', null, '["ability","inconsistency","incompetence","rudeness"]', 2, 'Efficiency = competence; opposite = incompetence.', true, '2026-10-24 07:21:26.997', '2026-10-24 07:21:26.997', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Dupe was promoted by her <u>efficiency</u>.', '["ability","inconsistency","incompetence","rudeness"]', 'Efficiency = competence; opposite = incompetence.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f066b859-c623-40b9-a972-24767c4207bf', 'Literature in English', 'JAMB', null, 2026, null, '''Genres of literature'' aptly discusses', null, '["tragedy, comedy and tragic-comedy","Poem, ballad and picaresque","prose, drama and poetry","romance, Shakespearean drama and epitaph"]', 2, 'Genres of literature are prose, drama, and poetry.', true, '2026-09-12 11:13:41.044', '2026-09-12 11:13:41.044', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f067617e-3798-4fde-8adf-60d5db6020c0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The accident victim received <u>a superficial</u> wound from the crash.', null, '["a painless","a serious","an external","an internal"]', 2, 'Superficial = external.', true, '2026-10-24 01:04:06.113', '2026-10-24 01:04:06.113', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The accident victim received <u>a superficial</u> wound from the crash.', '["a painless","a serious","<u>an external</u>","an internal"]', '<b>Superficial</b> = <b>an external</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f06d998c-f3cd-4311-840b-99c456253fe2', 'Chemistry', 'JAMB', null, 2026, null, 'The method used in extracting sodium is:', null, '["Blast furnace","Electrolysis","Roasting","Smelting"]', 1, 'Sodium is extracted by electrolysis of molten sodium chloride.', true, '2026-09-12 11:35:58.042', '2026-09-12 11:35:58.042', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0741add-47fe-4a87-a8db-0fac49ae831e', 'Physics', 'JAMB', null, 1991, null, 'When the bottom tip of a vibrating tuning fork is held in contact with a wooden box, a louder sound is heard. This phenomenon is known as', null, '["Beats","Echoing","Resonance","Reverberation"]', 2, 'The box is forced to vibrate at the fork''s frequency and, having a larger area, sets a bigger volume of air in motion. This is resonance (forced vibration).', true, '2026-10-12 19:15:33.891', '2026-10-12 19:15:33.891', null, null, null, 'When the bottom tip of a vibrating tuning fork is held in contact with a wooden box, a louder sound is heard. This phenomenon is known as', '["Beats","Echoing","Resonance","Reverberation"]', 'The box is forced to vibrate at the fork''s frequency and, having a larger area, sets a bigger volume of air in motion. This is resonance (forced vibration).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
