insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f07d6fe8-ea23-41d0-8f39-4ee7b4e77d7f', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''Put off your shoes from your feet; for the place where you stand is holy.'' Where was this statement made?', null, '["Mount Horeb","Mount Sinai","Jericho","Gilgal"]', 0, 'This statement was made at Mount Horeb (also called Mount Sinai). When God appeared to Moses in the burning bush, He said, ''Do not come near; put off your shoes from your feet, for the place on which you are standing is holy ground.''', true, '2026-09-12 09:46:09.847', '2026-09-12 09:46:09.847', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f07e80ce-13ad-4ec2-8606-28c0b75a61d9', 'Literature in English', 'JAMB', null, 2026, null, 'What is the meaning of Spatial setting?', null, '["The physical location and environment where a story takes place","The time period of a story","The social context of a story","The emotional atmosphere of a story"]', 0, 'Spatial setting refers to the physical location and environment where a story takes place. It includes the geographical place, the specific surroundings, and the physical space in which the action occurs. This is distinct from temporal setting (time period) and social setting (social context). Spatial setting helps establish atmosphere and influences characters'' actions.', true, '2026-09-10 10:47:55.493', '2026-09-10 10:47:55.493', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f082f302-5b6e-45b5-9244-eb2e20124930', 'Government', 'JAMB', null, 2026, null, 'Before 1945, the component units of Nigeria were', null, '["regions","districts","provinces","states"]', 2, 'Before 1945, the component units of Nigeria were provinces. Nigeria was administered as a single unit with provinces as the main administrative divisions. The Richards Constitution of 1946 divided Nigeria into three regions (Northern, Western, and Eastern) for the first time. Before 1946, the country was divided into provinces and districts. States were created much later, starting in 1967.', true, '2026-09-10 10:44:18.986', '2026-09-10 10:44:18.986', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f08e7713-3978-4905-93d9-443bc6c8e0b1', 'Chemistry', 'JAMB', null, 2026, null, 'An element X forms the following compounds with chlorine XCl₄, XCl₃, XCl₂. This illustrates the', null, '["law of multiple proportion","law of chemical proportion","law of simple proportion","law of conversation of mass","law of definite proportion"]', 0, 'This illustrates the law of multiple proportions.', true, '2026-09-12 11:36:01.155', '2026-09-12 11:36:01.155', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0905688-d5e6-4a43-814d-3e8bb3a8813d', 'Physics', 'JAMB', null, 2026, null, 'Three vectors A, B, and C add together to yield zero: A + B + C = 0. The vectors A and C point in opposite directions and their magnitudes are related by the expression: A = 2C. Which one of the following conclusions is correct?', null, '["A and B have equal magnitudes and point in opposite directions","B and C have equal magnitudes and point in the same direction","B and C have equal magnitudes and point in opposite directions","A and B point in the same direction, but A has twice the magnitude of B"]', 0, 'A + B + C = 0. A = 2C and A and C are opposite. So A - 2A + B = 0 (if C = -A/2). B = A/2. Not matching. Let A and C be opposite: A + C = A - C (magnitudes). Since A = 2C, A - C = C. So B = C. B and C have equal magnitudes and point in opposite directions to A. The correct answer is (C).', true, '2026-09-10 10:56:44.441', '2026-09-10 10:56:44.441', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f09f332a-7661-4459-9bd7-2e6298e2863e', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Usman needs to <u>get his act together</u> if he wants to pass the examination', null, '["He needs to put all points down in the examination","He needs to organize himself","He needs to be fast when writing the examination","He needs to put on his stage costume"]', 1, '''Get his act together'' = organize himself.', true, '2026-10-24 01:02:09.767', '2026-10-24 01:02:09.767', null, null, null, '(Choose the most appropriate interpretation). Usman needs to <u>get his act together</u> if he wants to pass the examination', '["He needs to put all points down in the examination","<u>He needs to organize himself</u>","He needs to be fast when writing the examination","He needs to put on his stage costume"]', '''<b>Get his act together</b>'' = <b>organize himself</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0a7f091-fa7f-48d6-8785-a948edd44b33', 'Christian Religious Studies', 'JAMB', null, 2026, null, '“But I will be with you and you will smite the Midianites as one man” was said by God to...', null, '["Moses","Joshua","Gideon","Deborah"]', 2, 'Judges 6:16 records God''s encouragement to Gideon when commissioning him to deliver Israel from Midian.', true, '2026-09-09 17:18:25.909', '2026-09-09 17:18:25.909', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0a94772-f53a-4b71-a3e0-f36e57c7c72a', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The terms of the contract <u>stuck in my throat</u>.', null, '["were beyond me","were not clear","were ambiguous","became obsolete"]', 0, '''Stuck in my throat'' = beyond my understanding.', true, '2026-10-24 01:02:04.16', '2026-10-24 01:02:04.16', null, null, null, '(Choose the most appropriate interpretation). The terms of the contract <u>stuck in my throat</u>.', '["<u>were beyond me</u>","were not clear","were ambiguous","became obsolete"]', '''<b>Stuck in my throat</b>'' = <b>beyond my understanding</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0ab2346-c99c-446b-a40e-8600ed5e5830', 'Biology', 'JAMB', null, 2002, null, 'In corms, food is usually stored in the', null, '["leaves","stems","roots","buds"]', 1, 'Corms are modified stems that store food.', true, '2026-10-12 20:59:29.982', '2026-10-12 20:59:29.982', null, null, null, 'In corms, food is usually stored in the', '["leaves","stems","roots","buds"]', 'Corms are modified stems that store food.', '{"bold":["stems"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0abdfdc-f478-4696-94c0-a080867851ae', 'Biology', 'JAMB', null, 2010, null, 'A pair of genes that control a trait is referred to as', null, '["an allele","recessive","dominant","a hybrid"]', 0, 'A pair of genes controlling a trait is an allele.', true, '2026-10-12 20:59:41.241', '2026-10-12 20:59:41.241', null, null, null, 'A pair of genes that control a trait is referred to as', '["an allele","recessive","dominant","a hybrid"]', 'A pair of genes controlling a trait is an allele.', '{"bold":["an allele"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0cabd30-87c8-4c95-8d9d-786683d5cf5f', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What are two emblems Jesus used during the Last Supper?', null, '["the bread and the blood of the lamb","the bread and the wine","the unleavened bread and the fruit of the vine","his blood and his body"]', 2, 'Jesus used unleavened bread and the fruit of the vine.', true, '2026-09-12 10:41:27.945', '2026-09-12 10:41:27.945', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0cbfcfe-a8fa-4d9d-84dc-597b176f0f1e', 'English Language', 'JAMB', null, 2007, null, 'The police claim that a number of stolen cars <u>------------</u> recovered.', null, '["has being","is being","has been","have been"]', 3, '''A number of cars'' plural â†’ have been.', true, '2026-10-24 01:02:15.5', '2026-10-24 01:02:15.5', null, null, null, 'The police claim that a number of stolen cars <u>------------</u> recovered.', '["has being","is being","has been","<u>have been</u>"]', '''<b>A number of cars</b>'' plural â†’ <b>have been</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0cfcce1-6c60-4ad9-a572-f047e0fe0fce', 'Literature in English', 'JAMB', null, 2026, null, 'Sludge in the extract means', null, '["Water","Fire","Snow","Mud"]', 3, 'Sludge means mud.', true, '2026-09-12 11:10:53.113', '2026-09-12 11:10:53.113', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0d0c81d-792b-471b-a7c5-cee35da67265', 'Biology', 'JAMB', null, 2026, null, 'A monocot root is different from a dicot root by having', null, '["endodermis","cambium","wide pith","root hair"]', 2, 'Monocot roots typically have a wide, well-developed pith (central ground tissue), while dicot roots often have a small or absent pith. Both monocot and dicot roots have an endodermis (a layer surrounding the vascular cylinder) and root hairs (epidermal extensions for absorption). Dicot roots often undergo secondary growth due to the presence of cambium, which is usually absent in monocot roots. The presence of a wide pith is a distinguishing characteristic of monocot roots, where it can occupy a large portion of the root''s diameter.', true, '2026-09-09 03:18:26.162', '2026-09-09 03:18:26.162', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0d88768-0e61-45d4-bd8c-36fcd4259227', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In 1 Corinthians, Paul stated that by one Spirit we were...', null, '["free from bondage of sin","united into one church","committed to Christian service","baptized into one body"]', 3, '1 Corinthians 12:13 states: ''For by one Spirit we were all baptized into one body—whether Jews or Greeks, whether slaves or free.''', true, '2026-09-09 17:18:27.603', '2026-09-09 17:18:27.603', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0f763f5-570b-423d-9774-a49a6bba2d04', 'Financial Accounting', 'UTME', null, 2004, null, 'What is the cost of manufactured goods?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841895/questions/vqlnhihcunvaucx6fsy2.jpg', '["N49 125","N48 750","N37 625","N35 250"]', 3, 'Cost of R. materials consumed 14250 + Direct wages 17100 = 31350 + Indirect Wages 5400 = 36750 + Opening WIP 1875 - Closing WIP 3375 = Cost of Manufactured goods 35250.', true, '2026-10-12 22:00:03.084', '2026-10-12 22:00:03.084', null, null, null, 'What is the cost of manufactured goods?', '["N49 125","N48 750","N37 625","<b>N35 250</b>"]', 'Cost of R. materials consumed 14250 + Direct wages 17100 = 31350 + Indirect Wages 5400 = 36750 + Opening WIP 1875 - Closing WIP 3375 = Cost of Manufactured goods <b>35250</b>.', '{"bold":["35250"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0f93e2e-b181-4288-984c-147f71f28f77', 'Biology', 'JAMB', null, 2026, null, 'Which of the following groups of cells is devoid of true nuclei?', null, '["Algae","Monera","Fungi","Viruses"]', 1, 'Monera (bacteria and archaea) are prokaryotic organisms and are devoid of true nuclei (membrane-bound nucleus). Algae and fungi are eukaryotes with true nuclei. Viruses are not cellular and are not considered to have nuclei. Monera organisms have their genetic material in a nucleoid region without a nuclear envelope. They also lack other membrane-bound organelles. The absence of a true nucleus is one of the defining characteristics of prokaryotes.', true, '2026-09-09 03:19:04.896', '2026-09-09 03:19:04.896', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0fa9d86-d73b-49f4-ac31-095aac157e22', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Ayo takes his studies rather <u>lightly</u>.', null, '["humorously","tediously","carefully","seriously"]', 3, 'Lightly = unseriously; opposite = seriously.', true, '2026-10-24 07:21:14.123', '2026-10-24 07:21:14.123', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Ayo takes his studies rather <u>lightly</u>.', '["humorously","tediously","carefully","seriously"]', 'Lightly = unseriously; opposite = seriously.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0fc9f7d-286a-4783-beb7-67648f9b90b3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We have to identify the <u>protagonists</u> of the new movement.', null, '["enemies","leading figures","opponents","believers"]', 1, 'Protagonists = leading figures.', true, '2026-10-24 01:01:42.872', '2026-10-24 01:01:42.872', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We have to identify the <u>protagonists</u> of the new movement.', '["enemies","<u>leading figures</u>","opponents","believers"]', '<b>Protagonists</b> = <b>leading figures</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0fd4d79-744b-4867-8763-9b663f542d66', 'Chemistry', 'JAMB', null, 2026, null, 'What is the volume of carbon dioxide produced in burning 7.8g ethyne in excess air', null, '["74.67dm³","6.72dm³","8.67dm³","13.44dm³"]', 3, '2C₂H₂ + 5O₂ → 4CO₂ + 2H₂O. Moles C₂H₂ = 7.8/26 = 0.3 mol. Moles CO₂ = 0.6 mol. Volume = 0.6 × 22.4 = 13.44 dm³.', true, '2026-09-12 11:36:00.283', '2026-09-12 11:36:00.283', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f0fd5726-82fe-4e1c-98fd-6506a5705b8e', 'Literature in English', 'JAMB', null, 2026, null, 'The first-person narrative style is used when the main character in a novel recounts', null, '["The author''s Story","Other character''s story","His own story","His best friend''s story"]', 2, 'First-person narrative recounts the character''s own story.', true, '2026-09-12 11:10:48.757', '2026-09-12 11:10:48.757', null, null, null, null, null, null, null);
