insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f10bf39c-918e-4ada-afc1-1fe5bbb1d43c', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Amos, the type of famine God would send upon the people of Israel was...', null, '["That of bread","Thirst for water","Not hearing the word of the Lord","Hunger for baskets of summer fruit"]', 2, 'Amos 8:11 states: ''not a famine of bread, nor a thirst for water, but of hearing the words of the Lord.''', true, '2026-09-09 17:18:27.168', '2026-09-09 17:18:27.168', null, null, null, null, null, null, null);
