insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f129bcd5-efec-4f6f-865e-02ab2722220a', 'Chemistry', 'JAMB', null, 2026, null, 'C(s) + H₂O(g) → H₂(g) + CO₂(g). ΔG for this reaction at 1300K is -43KJ. At this temperature, the reaction is?', null, '["not feasible","at equilibrium","feasible","exothermic"]', 2, 'ΔG is negative, so the reaction is feasible.', true, '2026-09-12 11:36:14.976', '2026-09-12 11:36:14.976', null, null, null, null, null, null, null);
