insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f145a4ed-8400-409f-83d9-7819faa0d24d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Hers was <u>a chequered career</u>.', null, '["an interesting and successful career","a career full of sorrow and tears","a bright and memorable career","a career full of ups and downs"]', 3, '''A chequered career'' = full of ups and downs.', true, '2026-10-24 01:02:08.34', '2026-10-24 01:02:08.34', null, null, null, '(Choose the most appropriate interpretation). Hers was <u>a chequered career</u>.', '["an interesting and successful career","a career full of sorrow and tears","a bright and memorable career","<u>a career full of ups and downs</u>"]', '''A <b>chequered career</b>'' = <b>full of ups and downs</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f145cdfd-9354-4b45-a25d-c68637bb5573', 'Biology', 'JAMB', null, 2001, null, 'Which of the following organisms does not exist as a single free living cell?', null, '["volvox","amoeba","chlamydomonas","paramecium"]', 0, 'Volvox exists as a colonial organism made up of many cells rather than as a single free-living cell.', true, '2026-10-12 20:05:08.455', '2026-10-12 20:05:08.455', null, null, null, 'Which of the following organisms does not exist as a single free living cell?', '["volvox","amoeba","chlamydomonas","paramecium"]', 'Volvox exists as a colonial organism made up of many cells rather than as a single free-living cell.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f155d0f4-0412-42c9-b536-ba010814a1f8', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Biola decided to give <u>the task everything he had</u>.', null, '["all his money","all his time","complete attention","complete attendance"]', 2, '''Give everything one has'' = complete attention.', true, '2026-10-24 01:02:06.538', '2026-10-24 01:02:06.538', null, null, null, '(Choose the most appropriate interpretation). Biola decided to give <u>the task everything he had</u>.', '["all his money","all his time","<u>complete attention</u>","complete attendance"]', '''<b>Give everything one has</b>'' = <b>complete attention</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f159537a-abbc-404d-b32a-85893ab5da5e', 'Biology', 'JAMB', null, 2005, null, 'The hyphal wall of fungi is rigid owing to the presence of', null, '["cell wall","lignin","cellulose","chitin"]', 3, 'Chitin provides rigidity to fungal hyphal walls.', true, '2026-10-12 20:59:36.344', '2026-10-12 20:59:36.344', null, null, null, 'The hyphal wall of fungi is rigid owing to the presence of', '["cell wall","lignin","cellulose","chitin"]', 'Chitin provides rigidity to fungal hyphal walls.', '{"bold":["Chitin"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f167bb59-ad1a-4a6c-b1b0-5ceaf6364c9c', 'Biology', 'JAMB', null, 2026, null, 'The nucleus contains all of the following structures except', null, '["mitochondria","chromatin","genes","nucleolus","nuclear membrane"]', 0, 'Mitochondria are not found inside the nucleus; they are separate organelles in the cytoplasm responsible for cellular respiration and ATP production. The nucleus contains chromatin (uncoiled DNA with associated proteins), genes (DNA segments that code for proteins), the nucleolus (where ribosomal RNA is synthesized), and the nuclear membrane (envelope) that encloses the nucleus. The nucleus houses the cell''s genetic material and controls cellular activities, but mitochondria are independent organelles with their own DNA.', true, '2026-09-09 03:18:27.964', '2026-09-09 03:18:27.964', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f1693427-269d-42df-bf99-03d3e14cc493', 'English Language', 'JAMB', null, 2007, null, 'The problems of Nigeria''s worsening economy seem to have <u>__________</u> an immediate solution', null, '["defined","defied","rejected","rewarded","retained"]', 1, 'Correct spelling: defied.', true, '2026-10-24 07:21:40.379', '2026-10-24 07:21:40.379', null, null, null, 'The problems of Nigeria''s worsening economy seem to have <u>__________</u> an immediate solution', '["defined","defied","rejected","rewarded","retained"]', 'Correct spelling: defied.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f16d20dc-0366-4415-a081-56cad527155e', 'Biology', 'JAMB', null, 2026, null, 'The cells of the heart are nourished by the', null, '["carotid arteries","coronary arteries","jugular vein","portal vein","pulmonary arteries"]', 1, 'The coronary arteries branch from the aorta just above the aortic valve and supply oxygenated blood to the heart muscle (myocardium). The heart has its own circulatory system (coronary circulation) because the blood inside the heart chambers does not directly nourish the cardiac muscle. The carotid arteries supply blood to the head and brain. The jugular vein drains blood from the head. The portal vein carries blood from the digestive organs to the liver. The pulmonary arteries carry deoxygenated blood to the lungs.', true, '2026-09-09 03:18:27.741', '2026-09-09 03:18:27.741', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f17efc03-316f-4cae-9b7b-f3edf1d77767', 'English Language', 'JAMB', null, 2007, null, 'The Federal Government has <u>__________</u> child trafficking.', null, '["projected","prescribed","proscribed","postulated"]', 2, 'Correct spelling and meaning: proscribed.', true, '2026-10-24 07:21:39.166', '2026-10-24 07:21:39.166', null, null, null, 'The Federal Government has <u>__________</u> child trafficking.', '["projected","prescribed","proscribed","postulated"]', 'Correct spelling and meaning: proscribed.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f198df09-c182-441f-9334-3aa8a0ea45f4', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What is the meaning of Pentecost?', null, '["40 days after Passover","30 days after Passover","7 days after Passover","50 days after Passover"]', 3, 'Pentecost means ''fiftieth'' and refers to the Feast of Weeks, which occurred 50 days after Passover. It was on the day of Pentecost that the Holy Spirit descended upon the apostles in Jerusalem.', true, '2026-09-12 09:45:50.271', '2026-09-12 09:45:50.271', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f199b0d1-8e4e-401a-88a2-de8bac964057', 'Economics', 'JAMB', null, 2026, null, '______ refers to the physical limit on the quantity of a product that can be imported into a country over a period of time', null, '["Quota","Import duties","Export duties","indirect tax"]', 0, 'A quota is a physical limit on the quantity of a product that can be imported.', true, '2026-09-12 11:00:58.477', '2026-09-12 11:00:58.477', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f1a053b0-8d48-4052-9fac-c0b253cef715', 'Physics', 'JAMB', null, 1985, null, 'A quantity of gas occupies a certain volume when the temperature is -73 °C and the pressure is 1.5 atmospheres. If the pressure is increased to 4.5 atmospheres and the volume is halved at the same time, what will be the new temperature of the gas?', null, '["573 °C","327 °C","300 °C","110 °C","27 °C"]', 4, 'T₁ = -73 + 273 = 200 K. T₂ = T₁ x (P₂V₂)/(P₁V₁) = 200 x 3 x ½ = 300 K = 27 °C.', true, '2026-10-12 19:15:21.366', '2026-10-12 19:15:21.366', null, null, null, 'A quantity of gas occupies a certain volume when the temperature is -73 °C and the pressure is 1.5 atmospheres. If the pressure is increased to 4.5 atmospheres and the volume is halved at the same time, what will be the new temperature of the gas?', '["573 °C","327 °C","300 °C","110 °C","27 °C"]', 'T<sub>1</sub> = -73 + 273 = 200 K. T<sub>2</sub> = T<sub>1</sub> x (P<sub>2</sub>V<sub>2</sub>)/(P<sub>1</sub>V<sub>1</sub>) = 200 x 3 x ½ = 300 K = 27 °C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f1a4c898-6c5b-4130-9669-eb70be569013', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. There was a general <u>acquiescence</u> on the new drug law.', null, '["discrepancy","compromise","agreement","resistance"]', 3, 'Acquiescence = agreement; opposite = resistance.', true, '2026-10-24 07:21:26.537', '2026-10-24 07:21:26.537', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. There was a general <u>acquiescence</u> on the new drug law.', '["discrepancy","compromise","agreement","resistance"]', 'Acquiescence = agreement; opposite = resistance.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f1a8bb2e-49f3-4d2f-a575-5dac5fea8bf0', 'English Language', 'JAMB', null, 2007, null, 'The students had a <u>__________</u> on Independence Day.', null, '["match pass","march pass","match past","march past"]', 3, 'Correct form: march past.', true, '2026-10-24 07:21:36.62', '2026-10-24 07:21:36.62', null, null, null, 'The students had a <u>__________</u> on Independence Day.', '["match pass","march pass","match past","march past"]', 'Correct form: march past.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f1ab630f-a863-4975-be4e-f62f9a056dae', 'Biology', 'JAMB', null, 2026, null, 'Which of the following are ways in which desert animals adapt to extreme heat? I. Adoption of appropriate nocturnal habits II. Burrowing III. Adjusting their internal body temperature IV. Possession of many sweat pores', null, '["I and IV only","II and III only","I and II only","I, II and III only"]', 3, 'Desert animals adapt to extreme heat through adopting nocturnal habits (I), burrowing (II), and adjusting their internal body temperature (III). Nocturnal habits allow animals to avoid daytime heat. Burrowing provides a cooler microclimate underground. Temperature adjustment includes physiological and behavioral thermoregulation. Possession of many sweat pores (IV) is NOT a desert adaptation because excessive sweating would lead to dehydration. Desert animals have adaptations to conserve water, not increase sweating.', true, '2026-09-09 03:19:00.139', '2026-09-09 03:19:00.139', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f1cec951-c169-4049-8550-17de340d4280', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The man''s health has <u>deteriorated</u> in the hospital.', null, '["collapsed","improved","worsened","revived"]', 1, 'Deteriorated = worsened; opposite = improved.', true, '2026-10-24 07:21:13.362', '2026-10-24 07:21:13.362', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The man''s health has <u>deteriorated</u> in the hospital.', '["collapsed","improved","worsened","revived"]', 'Deteriorated = worsened; opposite = improved.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f1f63de4-9ff6-4c8f-bb5a-a4a8e49c62df', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The minister''s anger was <u>aggravated</u> by the news of the disaster.', null, '["abated","magnified","intensified","impeded"]', 2, 'Aggravated = intensified.', true, '2026-10-24 01:01:48.494', '2026-10-24 01:01:48.494', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The minister''s anger was <u>aggravated</u> by the news of the disaster.', '["abated","magnified","<u>intensified</u>","impeded"]', '<b>Aggravated</b> = <b>intensified</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f2030ea3-4627-4c57-9eae-68ffecc25f4a', 'Financial Accounting', 'UTME', null, 2003, null, 'In a control account, provision for bad debt is found on the', null, '["debit side of the purchase ledger control account","debit side of the sales ledger control account","credit side of the purchases ledger control account","credit side of the sales ledger control account"]', 3, 'Provision for bad debt is found on the credit side of the sales ledger control account as a deduction from total debtors.', true, '2026-10-12 22:00:00.224', '2026-10-12 22:00:00.224', null, null, null, 'In a control account, provision for bad debt is found on the', '["debit side of the purchase ledger control account","debit side of the sales ledger control account","credit side of the purchases ledger control account","<b>credit side of the sales ledger control account</b>"]', 'Provision for bad debt is found on the <b>credit side of the sales ledger control account</b> as a deduction from total debtors.', '{"bold":["credit side of the sales ledger control account"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f2081ed2-d366-4faa-8f95-75e511898c67', 'Biology', 'JAMB', null, 2026, null, 'A major difference between platyhelminthes and coelenterates is that platyhelminthes', null, '["reproduce sexually","have developed mesoderm","are multicellular","reproduce asexually"]', 1, 'Platyhelminthes (flatworms) are triploblastic animals, meaning they possess three germ layers: ectoderm, mesoderm, and endoderm. The mesoderm gives rise to muscles and other internal organs. Coelenterates (cnidarians) are diploblastic, having only ectoderm and endoderm with a jelly-like mesoglea in between. While both groups can reproduce both sexually and asexually, and both are multicellular, the presence of a true mesoderm is the defining difference that places platyhelminthes at a higher level of organization.', true, '2026-09-09 03:18:15.017', '2026-09-09 03:18:15.017', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f214c4df-137b-4037-a3e9-873e3f06f428', 'Chemistry', 'JAMB', null, 2026, null, 'What is the time taken for 6.0g of gold to be deposited if a current if 5A is passed through a solution of gold(I) Nitrate? (Au=197, 1 Faraday=96500C)', null, '["12.4mins","9.8mins","8.9mins","6.7mins"]', 1, 'Au⁺ + e⁻ → Au. Moles Au = 6/197 = 0.0305 mol. Charge = 0.0305 × 96500 = 2943C. Time = 2943/5 = 588.6s = 9.8 mins.', true, '2026-09-12 11:36:21.771', '2026-09-12 11:36:21.771', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f24139dd-a532-467f-b374-89ecb973a50b', 'Biology', 'JAMB', null, 2003, null, 'An organism that has been extensively used to test the chromosome theory of heredity is', null, '["Drosophila melanogaster","Musca domestica","Zea mays","Homo sapiens"]', 0, 'Drosophila melanogaster is used to test the chromosome theory of heredity.', true, '2026-10-12 20:59:33.795', '2026-10-12 20:59:33.795', null, null, null, 'An organism that has been extensively used to test the chromosome theory of heredity is', '["Drosophila melanogaster","Musca domestica","Zea mays","Homo sapiens"]', 'Drosophila melanogaster is used to test the chromosome theory of heredity.', '{"bold":["Drosophila melanogaster"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f2493427-9c7b-47bf-8180-1a5bd2a07dbc', 'Chemistry', 'JAMB', null, 2026, null, 'When magnesium reacts with dilute hydrochloric acid, the rate of hydrogen evolution decreases with time mainly because', null, '["the surface area of magnesium increases","the acid concentration decreases as the reaction proceeds","magnesium becomes more reactive","the activation energy increases"]', 1, 'As the reaction proceeds, the concentration of hydrochloric acid decreases because it is being used up. Lower reactant concentration means fewer collisions per unit time, so the rate of reaction decreases. The surface area of magnesium decreases (not increases), and the activation energy remains constant.', true, '2026-09-12 09:38:09.618', '2026-09-12 09:38:09.618', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f259600c-0e33-40f2-b8b0-bc14f1f13e09', 'English Language', 'JAMB', null, 2024, null, 'What was the reaction of the students when Mr. Bepo interrupted Fafore''s lesson?', null, '["they were confused","they remained silent","they laughed and teased him","they were angry"]', 2, 'The students laughed and teased him.', true, '2026-09-18 09:43:02.761', '2026-09-18 09:43:02.761', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f25980d0-682a-435d-bee1-a7a8162d6d19', 'Biology', 'JAMB', null, 2010, null, 'A dilute solution of phenylthiocarbamide tastes bitter to some people and is tasteless to others. This is an example of', null, '["taste bud variation","discontinuous variation","morphological variation","continuous variation"]', 1, 'This is an example of discontinuous variation.', true, '2026-10-12 20:59:41.139', '2026-10-12 20:59:41.139', null, null, null, 'A dilute solution of phenylthiocarbamide tastes bitter to some people and is tasteless to others. This is an example of', '["taste bud variation","discontinuous variation","morphological variation","continuous variation"]', 'This is an example of discontinuous variation.', '{"bold":["discontinuous variation"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f2627a78-12be-4cc1-92d1-9b010fc0703a', 'Physics', 'JAMB', null, 2026, null, 'If a resistance is halved in value and the potential difference across it is tripled, then the ratio of the new current to the old is', null, '["1:6","1:3","2:1","6:1"]', 3, 'I = V/R. New current = 3V/(R/2) = 6V/R = 6I. So the ratio of new current to old current is 6:1.', true, '2026-09-10 10:56:41.897', '2026-09-10 10:56:41.897', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f2644761-da0d-4746-aa2a-7648d65bb48e', 'Government', 'JAMB', null, 2026, null, 'The name of the electoral body under the 1979 constitution was', null, '["NEC","INEC","FEDECO","NECO"]', 2, 'The name of the electoral body under the 1979 constitution was FEDECO (Federal Electoral Commission). FEDECO was established under the 1979 Constitution to conduct elections in Nigeria. It was later replaced by NEC (National Electoral Commission) and then INEC (Independent National Electoral Commission). NECO is the National Examinations Council, not an electoral body.', true, '2026-09-10 10:45:05.395', '2026-09-10 10:45:05.395', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f2839a53-0cea-40ec-95cc-bf20ab344107', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It is <u>ludicrous</u> to suggest that she was a government agent', null, '["odd","exciting","farcical","sensible"]', 3, 'Ludicrous = ridiculous; opposite = sensible.', true, '2026-10-24 07:21:30.624', '2026-10-24 07:21:30.624', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It is <u>ludicrous</u> to suggest that she was a government agent', '["odd","exciting","farcical","sensible"]', 'Ludicrous = ridiculous; opposite = sensible.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f2867b52-299b-4946-bd67-15651b24365f', 'English Language', 'JAMB', null, 2024, null, 'Choose the option opposite in meaning to the underlined word: Ojo''s response infuriated his wife.', null, '["annoyed","pleased","surprised","confused"]', 1, '"Infuriated" means made very angry; the opposite is "pleased."', true, '2026-09-18 09:23:08.475', '2026-09-18 09:23:08.475', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f28a3324-af5b-49a4-b4c5-90baffc16386', 'Economics', 'JAMB', null, 2026, null, 'The population theory that is concerned with the cases of over population and shortage of food production is', null, '["Malthusian Population theory","Demographic Transition theory","National Population theory","Population density"]', 0, 'The Malthusian theory states that population grows geometrically while food supply grows arithmetically, leading to overpopulation and food shortage.', true, '2026-09-12 10:58:42.442', '2026-09-12 10:58:42.442', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f28bb612-23f9-4088-ac85-7e4537825b12', 'Biology', 'JAMB', null, 2002, null, 'Birds which are large with long straight pointed beaks, long necks and long legs are likely to be', null, '["insect eaters","fish catchers","nectar feeders","fruit eaters"]', 1, 'Long straight pointed beaks and long legs are adaptations for fish catching.', true, '2026-10-12 20:59:31.061', '2026-10-12 20:59:31.061', null, null, null, 'Birds which are large with long straight pointed beaks, long necks and long legs are likely to be', '["insect eaters","fish catchers","nectar feeders","fruit eaters"]', 'Long straight pointed beaks and long legs are adaptations for fish catching.', '{"bold":["fish catching"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f28e6958-ef85-41ac-8760-2111e402bce4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The man found his wife physically <u>repellent</u>.', null, '["attractive","fatuous","unpleasant","flamboyant"]', 0, 'Repellent = repulsive; opposite = attractive.', true, '2026-10-24 07:21:27.99', '2026-10-24 07:21:27.99', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The man found his wife physically <u>repellent</u>.', '["attractive","fatuous","unpleasant","flamboyant"]', 'Repellent = repulsive; opposite = attractive.', '{}');
