insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f2ddcffe-d832-4298-9fe8-d0791d3b3380', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We all have both good and bad characteristics. Either is, however, easily <u>manifested</u> in times of crisis.', null, '["demanded","highlighted","submerged","determined"]', 1, 'Manifested = highlighted/shown.', true, '2026-10-24 01:01:46.267', '2026-10-24 01:01:46.267', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We all have both good and bad characteristics. Either is, however, easily <u>manifested</u> in times of crisis.', '["demanded","<u>highlighted</u>","submerged","determined"]', '<b>Manifested</b> = <b>highlighted</b>/shown.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f2efc365-479b-4fd6-81a7-03a5ec9f781a', 'Biology', 'JAMB', null, 2003, null, 'The function of the long-winged reproductives in a termite colony is to', null, '["disperse the population","feed the young","participate in swarming","protect the young"]', 2, 'Long-winged reproductive termites take part in nuptial swarming to establish new colonies.', true, '2026-10-12 20:05:10.462', '2026-10-12 20:05:10.462', null, null, null, 'The function of the long-winged reproductives in a termite colony is to', '["disperse the population","feed the young","participate in swarming","protect the young"]', 'Long-winged reproductive termites take part in nuptial swarming to establish new colonies.', '{}');
