insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f2f642ac-546f-4ec6-b4a1-b893b30a1c80', 'Physics', 'JAMB', null, 2026, null, 'Which of the following statements about cathode rays is not correct?', null, '["they are bent by a strong field","they are streams of electrons","they are bent by a magnetic field","they are more penetrating than gamma ray","they cause florescences"]', 3, 'The statement that cathode rays are more penetrating than gamma rays is not correct. Gamma rays are far more penetrating than cathode rays (electrons). Cathode rays are streams of electrons that can be bent by electric and magnetic fields and cause fluorescence.', true, '2026-09-10 10:56:41.355', '2026-09-10 10:56:41.355', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f2f68d38-5969-404e-8379-87e389dc7673', 'English Language', 'JAMB', null, 2007, null, 'My advice to Tolu was; <u>look before you leap</u>.', null, '["Tolu was advised to consider the possible consequences before taking action","Tolu was advised to consider her opinion before reaching any decision","Tolu was advised to weigh her decision by looking and leaping","Tolu was advised to leap only after looking"]', 0, '''Look before you leap'' = consider consequences before acting.', true, '2026-10-24 01:04:23.72', '2026-10-24 01:04:23.72', null, null, null, 'My advice to Tolu was; <u>look before you leap</u>.', '["<u>Tolu was advised to consider the possible consequences before taking action</u>","Tolu was advised to consider her opinion before reaching any decision","Tolu was advised to weigh her decision by looking and leaping","Tolu was advised to leap only after looking"]', '''<b>Look before you leap</b>'' = <b>consider consequences before acting</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f2fb2652-72cb-4570-b0b1-b08a5434eaca', 'English Language', 'JAMB', null, 2024, null, 'I ______ him before he came to the room', null, '["Have seen","Saw","Used to see him","Had seen"]', 3, '"Had seen" is the past perfect tense, indicating an action completed before another past action.', true, '2026-09-18 09:34:03.972', '2026-09-18 09:34:03.972', null, null, 'STANDALONE', null, null, null, null);
