insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f32373d4-1962-464e-aeef-2b05aff87560', 'Literature in English', 'JAMB', null, 2026, null, 'What is the predominant theme of the poem ''Night''?', null, '["the beauty and mystery of the night","the dangers of the dark","the loneliness of humans","the chaos of the world"]', 0, 'The predominant theme of the poem ''Night'' is the beauty and mystery of the night. The poem explores the night as a powerful, mystical presence that evokes both awe and reflection. It is not primarily about dangers, loneliness, or chaos. The night is portrayed as a beautiful and mysterious force that inspires contemplation. The poem celebrates the enigmatic qualities of the night.', true, '2026-09-10 10:45:35.526', '2026-09-10 10:45:35.526', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f327e45c-7320-4897-82f3-02a0351fd119', 'Chemistry', 'JAMB', null, 2026, null, 'Which of these gases may not be dried with Concentrated sulphuric acid', null, '["HCl","N₂","Cl₂","SO₂","NH₃"]', 4, 'NH₃ reacts with concentrated H₂SO₄ and cannot be dried with it.', true, '2026-09-12 11:36:04.463', '2026-09-12 11:36:04.463', null, null, null, null, null, null, null);
