insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f35043e6-631c-4482-b231-58a127ea9cb9', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. My father was at the <u>apogee</u> of his career when he was retired.', null, '["terminal point","highest point","least productive stage","redundant stage"]', 1, 'Apogee = highest point.', true, '2026-10-24 01:04:02.374', '2026-10-24 01:04:02.374', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. My father was at the <u>apogee</u> of his career when he was retired.', '["terminal point","<u>highest point</u>","least productive stage","redundant stage"]', '<b>Apogee</b> = <b>highest point</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f351c7c1-1349-4c3b-86c2-c63d41966a22', 'Physics', 'JAMB', null, 1985, null, 'Two divers G and H are at depths 20 m and 40 m respectively below the water surface in a lake. The pressure on G is P₁ while the pressure on H is P₂. If the atmospheric pressure is equivalent to 10 m of water, then the value of P₂/P₁ is', null, '["0.50","0.60","1.67","2.00","3.00"]', 2, 'Total pressure (in metres of water): P₁ = 10 + 20 = 30 and P₂ = 10 + 40 = 50. P₂/P₁ = 50/30 = 1.67.', true, '2026-10-12 19:15:21.04', '2026-10-12 19:15:21.04', null, null, null, 'Two divers G and H are at depths 20 m and 40 m respectively below the water surface in a lake. The pressure on G is P<sub>1</sub> while the pressure on H is P<sub>2</sub>. If the atmospheric pressure is equivalent to 10 m of water, then the value of P<sub>2</sub>/P<sub>1</sub> is', '["0.50","0.60","1.67","2.00","3.00"]', 'Total pressure (in metres of water): P<sub>1</sub> = 10 + 20 = 30 and P<sub>2</sub> = 10 + 40 = 50. P<sub>2</sub>/P<sub>1</sub> = 50/30 = 1.67.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
