insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f3793500-0273-4aed-9418-38a8cb72a9eb', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to John, the accusation of the Jews levelled against Jesus before Pilate was that he was', null, '["an evildoer","an imposter","a perverter","a blasphemer"]', 0, 'The Jews accused Jesus of being an evildoer.', true, '2026-09-12 10:41:38.591', '2026-09-12 10:41:38.591', null, null, null, null, null, null, null);
