insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f37cd056-90a1-4550-9dcc-72fec2bf783c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ngozi spoke to her father quite <u>candidly</u> on her proposed marriage.', null, '["frankly","faithfully","rudely","respectfully"]', 0, 'Candidly = frankly.', true, '2026-10-24 01:03:57.84', '2026-10-24 01:03:57.84', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ngozi spoke to her father quite <u>candidly</u> on her proposed marriage.', '["<u>frankly</u>","faithfully","rudely","respectfully"]', '<b>Candidly</b> = <b>frankly</b>.', '{}');
