insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f39dde06-3a42-4ff7-82e9-ea478e4afdfd', 'Physics', 'JAMB', null, 2002, null, 'The property that is propagated in a travelling wave is', null, '["Amplitude","Wavelength","Frequency","Energy"]', 3, 'A travelling wave transfers energy from one place to another without transferring the medium itself.', true, '2026-10-12 19:15:53.323', '2026-10-12 19:15:53.323', null, null, null, 'The property that is propagated in a travelling wave is', '["Amplitude","Wavelength","Frequency","Energy"]', 'A travelling wave transfers energy from one place to another without transferring the medium itself.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
