insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f3e7c0c4-2f1c-4943-9f56-88853daa2bd0', 'Physics', 'JAMB', null, 2026, null, 'What is the period of the thinnest hand of the clock (the second hand)?', null, '["1 hour","1 minute","60 seconds","12 hours"]', 1, 'The period of the second hand is 1 minute (60 seconds). The second hand makes one complete revolution in 60 seconds.', true, '2026-09-10 10:56:45.414', '2026-09-10 10:56:45.414', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f3ed773a-c444-4fc5-9742-c1c0608d7f09', 'English Language', 'JAMB', null, 2007, null, 'More than one student <u>_______</u>complained about the new rule.', null, '["have","are","has","were"]', 2, '''More than one'' singular â†’ has.', true, '2026-10-24 01:04:30.35', '2026-10-24 01:04:30.35', null, null, null, 'More than one student <u>_______</u>complained about the new rule.', '["have","are","<u>has</u>","were"]', '''<b>More than one</b>'' singular â†’ <b>has</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f3fc73f2-9ea0-470f-afed-08f49fec4cae', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I have always believed that my mother is a very <u>impassioned</u> woman.', null, '["emotive","impartial","impassive","emotional"]', 3, 'Impassioned = emotional.', true, '2026-10-24 01:01:50.183', '2026-10-24 01:01:50.183', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I have always believed that my mother is a very <u>impassioned</u> woman.', '["emotive","impartial","impassive","<u>emotional</u>"]', '<b>Impassioned</b> = <b>emotional</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f40091cc-527a-4616-996c-d0fc664174b2', 'Literature in English', 'JAMB', null, 2026, null, 'The official term for age eighty to eighty-nine is', null, '["Octogenre","Octogenarian","Orthopedic","Octogenary"]', 1, 'The term is octogenarian.', true, '2026-09-12 11:07:22.806', '2026-09-12 11:07:22.806', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f41b227d-aa1e-4b9c-b4a4-7f0c178d0a59', 'Literature in English', 'JAMB', null, 2026, null, 'The livid and snarled waters roared and lapped / At the poor battered and weeping Yatch. The dominant literary device in the lines is', null, '["simile","alliteration","assonance","personification"]', 3, 'The dominant device is personification.', true, '2026-09-12 11:14:00.624', '2026-09-12 11:14:00.624', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f422eb16-6702-4828-b9c7-37dd5ae3f5a6', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is the most complex according to the cellular level of organization?', null, '["Heart","Hair","Euglena","Hydra"]', 0, 'The heart is an organ composed of multiple tissue types (muscle, connective, nervous, epithelial) working together to perform a specific function, making it the most complex. Hair is a non-living structure from specialized epidermal cells. Euglena is a unicellular organism. Hydra is at the tissue level of organization with two tissue layers. Levels of biological organization: cell (Euglena) → tissue → organ (heart) → organ system. The heart represents the organ level of organization, which is higher than the cellular (Euglena) or tissue level (Hydra).', true, '2026-09-09 03:18:22.757', '2026-09-09 03:18:22.757', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f42fb404-21f9-4795-a5ec-80dbb460136d', 'English Language', 'JAMB', null, 2024, null, '(Choose the Synonym) Before embarking on his current research, the professor carried out a feasibility study of the area', null, '["thorough","Perfectibility","Complete","Practicability"]', 3, '"Feasibility" means practicability or the possibility of being achieved.', true, '2026-09-18 09:34:03.959', '2026-09-18 09:34:03.959', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f436c0a0-2a08-4a2c-99b5-bfa4e629f1b6', 'Biology', 'JAMB', null, 2026, null, 'From which group of animals are the mammals generally believed to have most recently evolved?', null, '["reptiles","fishes","amphibians","birds"]', 0, 'Mammals are generally believed to have most recently evolved from reptiles (specifically therapsid reptiles). Mammals evolved from a group of reptiles called synapsids during the Mesozoic era. While birds also evolved from reptiles (dinosaurs), the line leading to mammals diverged from reptiles. The evolutionary sequence is: fishes → amphibians → reptiles → mammals and birds. Mammals and birds evolved independently from different reptile lineages.', true, '2026-09-09 03:19:20.214', '2026-09-09 03:19:20.214', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f438c8cb-f622-4516-a20a-5ac7d2931fd3', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following is not peculiar to matter?', null, '["Kinetic energy of particles increase from solid to gas","Random motion of particles increase from gas to solid","Orderliness of particles increase from gas to liquid","Random motion of particles increase from liquid to gas"]', 1, 'Random motion decreases from gas to solid.', true, '2026-09-12 11:36:26.577', '2026-09-12 11:36:26.577', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f43bc8bd-7d45-49ff-88f3-d363bf8687c2', 'English Language', 'JAMB', null, 2007, null, 'Ali goes to the stadium regularly, but he <u>------------</u> to the church for months.', null, '["hasn''t been","haven''t been","didn''t go","hadn''t been"]', 0, '''For months'' present relevance â†’ hasn''t been.', true, '2026-10-24 01:04:28.93', '2026-10-24 01:04:28.93', null, null, null, 'Ali goes to the stadium regularly, but he <u>------------</u> to the church for months.', '["<u>hasn''t been</u>","haven''t been","didn''t go","hadn''t been"]', '''<b>For months</b>'' present relevance â†’ <b>hasn''t been</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f43f5960-ad4d-4771-8b2a-99e41dbb6988', 'Physics', 'JAMB', null, 1984, null, 'The resistance of a wire depends on', null, '["The length of the wire","The diameter of the wire","The temperature of the wire","The resistivity of the wire","All of the above."]', 4, 'R = ρL/A, so resistance depends on length, cross-sectional area (diameter) and resistivity, and resistivity itself varies with temperature.', true, '2026-10-12 19:15:18.693', '2026-10-12 19:15:18.693', null, null, null, 'The resistance of a wire depends on', '["The length of the wire","The diameter of the wire","The temperature of the wire","The resistivity of the wire","All of the above."]', 'R = ρL/A, so resistance depends on length, cross-sectional area (diameter) and resistivity, and resistivity itself varies with temperature.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f4443f11-3fc5-46b5-be70-f18bf67ecdfe', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Adayi is a <u>die-hard</u> criminal.', null, '["hard to kill","hard to arrest","remorseless","relentless"]', 2, '''Die-hard'' = hardened/remorseless.', true, '2026-10-24 01:02:08.445', '2026-10-24 01:02:08.445', null, null, null, '(Choose the most appropriate interpretation). Adayi is a <u>die-hard</u> criminal.', '["hard to kill","hard to arrest","<u>remorseless</u>","relentless"]', '''<b>Die-hard</b>'' = <b>hardened/remorseless</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f4487238-d763-496f-b7f9-f2b63cd90f1d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The main message of Hosea is that God desires', null, '["love and sacrifice","sacrifice and thanksgiving","steadfast love and not sacrifice","sacrifice and worship","love with little sacrifice"]', 2, 'God desires steadfast love and not sacrifice (Hosea 6:6).', true, '2026-09-12 10:42:08.803', '2026-09-12 10:42:08.803', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f4515bd1-902e-4d68-9b86-c8c27f4664c1', 'Physics', 'JAMB', null, 2000, null, 'An electron of charge 1.6 x 10⁻¹⁹ C and mass 9.1 x 10⁻³¹ kg is accelerated between two metal plates with a velocity of 4 x 10⁷ m s⁻¹. The potential difference between the plates is', null, '["4.55 x 10¹ V","9.10 x 10¹ V","4.55 x 10² V","4.55 x 10³ V"]', 3, 'eV = ½mv², so V = (9.1 x 10⁻³¹ x 16 x 10¹⁴)/(2 x 1.6 x 10⁻¹⁹) = 4.55 x 10³ V.', true, '2026-10-12 19:15:49.964', '2026-10-12 19:15:49.964', null, null, null, 'An electron of charge 1.6 x 10<sup>-19</sup> C and mass 9.1 x 10<sup>-31</sup> kg is accelerated between two metal plates with a velocity of 4 x 10<sup>7</sup> m s<sup>-1</sup>. The potential difference between the plates is', '["4.55 x 10<sup>1</sup> V","9.10 x 10<sup>1</sup> V","4.55 x 10<sup>2</sup> V","4.55 x 10<sup>3</sup> V"]', 'eV = ½mv<sup>2</sup>, so V = (9.1 x 10<sup>-31</sup> x 16 x 10<sup>14</sup>)/(2 x 1.6 x 10<sup>-19</sup>) = 4.55 x 10<sup>3</sup> V.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f4540ff6-98e8-4049-bf8a-e521d828b118', 'Economics', 'JAMB', null, 2026, null, '______ refers to the movement of people from one geographical area to another', null, '["Immigration","Emigration","Migration","Immigration and emigration"]', 2, 'Migration is the movement of people from one geographical area to another.', true, '2026-09-12 11:00:57.145', '2026-09-12 11:00:57.145', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f45c830b-abe1-40e1-b85a-4c66632ca40c', 'Biology', 'JAMB', null, 2001, null, 'Both recessive and dominant characters are found', null, '["at the same locus of a homologous chromosome","at different loci of homologous chromosome","on different chromosomes in the cell","on the same chromatid in a chromosome"]', 0, 'Alleles for a trait are found at the same locus on homologous chromosomes.', true, '2026-10-12 20:59:29.414', '2026-10-12 20:59:29.414', null, null, null, 'Both recessive and dominant characters are found', '["at the same locus of a homologous chromosome","at different loci of homologous chromosome","on different chromosomes in the cell","on the same chromatid in a chromosome"]', 'Alleles for a trait are found at the same locus on homologous chromosomes.', '{"bold":["at the same locus on homologous chromosomes"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f46fec89-7ee5-4d19-994c-5e0bf367d16e', 'Physics', 'JAMB', null, 1995, null, 'The difference between sound waves and light waves is that sound waves', null, '["Are transverse while light waves are longitudinal.","Require a medium to travel while light waves do not.","Can be diffracted but light waves cannot","Cannot be reflected but light waves can."]', 1, 'Sound is a mechanical wave and needs a material medium. Light is electromagnetic and can travel through a vacuum.', true, '2026-10-12 19:15:41.683', '2026-10-12 19:15:41.683', null, null, null, 'The difference between sound waves and light waves is that sound waves', '["Are transverse while light waves are longitudinal.","Require a medium to travel while light waves do not.","Can be diffracted but light waves cannot","Cannot be reflected but light waves can."]', 'Sound is a mechanical wave and needs a material medium. Light is electromagnetic and can travel through a vacuum.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f478f5c1-cb26-436f-baaf-ada9a7040266', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>cynics</u> feared that the nation''s nascent democracy would fail.', null, '["pessimists","delinquents","critics","illusionists"]', 0, 'Cynics = pessimists.', true, '2026-10-24 01:04:04.724', '2026-10-24 01:04:04.724', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>cynics</u> feared that the nation''s nascent democracy would fail.', '["<u>pessimists</u>","delinquents","critics","illusionists"]', '<b>Cynics</b> = <b>pessimists</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f49978ec-1666-4412-9a16-54c30f9007ac', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The decision we have taken is <u>irrevocable</u>.', null, '["responsible","irresponsible","reversible","irreversible"]', 2, 'Irrevocable = unchangeable; opposite = reversible.', true, '2026-10-24 07:21:15.349', '2026-10-24 07:21:15.349', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The decision we have taken is <u>irrevocable</u>.', '["responsible","irresponsible","reversible","irreversible"]', 'Irrevocable = unchangeable; opposite = reversible.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f4aade24-dd7f-4e02-a228-9a7a8616a471', 'Government', 'JAMB', null, 2026, null, 'The machinery through which the will of the state is formulated, expressed and attained is known as', null, '["Government","Pressure Group","Public Opinion","Rule of Law","Sovereignty"]', 0, 'The machinery through which the will of the state is formulated, expressed and attained is known as government. This definition emphasizes government as the instrument of the state. Government formulates policies (the will of the state), expresses them through laws and pronouncements, and attains them through implementation. Pressure groups, public opinion, rule of law, and sovereignty are related concepts but not the machinery of the state.', true, '2026-09-10 10:45:07.212', '2026-09-10 10:45:07.212', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f4ae6b57-3f7b-4ad8-9a07-355cf693f3aa', 'Biology', 'JAMB', null, 2013, null, 'Which question paper Type of Biology is given to you?', null, '["Type D","Type I","Type B","Type U"]', 0, 'The question paper type is Type D.', true, '2026-10-12 20:59:46.061', '2026-10-12 20:59:46.061', null, null, null, 'Which question paper Type of Biology is given to you?', '["Type D","Type I","Type B","Type U"]', 'The question paper type is Type D.', '{"bold":["Type D"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f4af1185-2f76-4b81-baf9-be82f098c7c4', 'Economics', 'JAMB', null, 2026, null, 'As a firm increases its output, the average fixed cost', null, '["tends to rise continuously","remains constant","rises and then falls","tends to decrease continuously"]', 3, 'As a firm increases its output, average fixed cost (AFC) tends to decrease continuously. AFC = Total Fixed Cost / Output. Since total fixed cost is constant, dividing it by an increasing output results in a continuously decreasing AFC. This is why the AFC curve is a rectangular hyperbola that slopes downward throughout. It never touches the axes because AFC can never be zero.', true, '2026-09-10 10:41:59.228', '2026-09-10 10:41:59.228', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f4c9c467-f27e-4205-940e-4ba720380e36', 'Biology', 'JAMB', null, 2012, null, 'Which of the following is the lowest category of classification?', null, '["Class","Species","Family","Genus."]', 1, 'Species is the lowest category of classification.', true, '2026-10-12 20:59:44.134', '2026-10-12 20:59:44.134', null, null, null, 'Which of the following is the lowest category of classification?', '["Class","Species","Family","Genus."]', 'Species is the lowest category of classification.', '{"bold":["Species"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f4d387dc-8018-429a-af32-690bfffc6691', 'Physics', 'JAMB', null, 1997, null, 'The colours seen in thin films of oil on the road and in soap bubbles are due to', null, '["Reflection","Interference","Diffraction","Polarization."]', 1, 'Light reflected from the top and bottom surfaces of the thin film interferes, so some colours are reinforced and others cancelled.', true, '2026-10-12 19:15:43.799', '2026-10-12 19:15:43.799', null, null, null, 'The colours seen in thin films of oil on the road and in soap bubbles are due to', '["Reflection","Interference","Diffraction","Polarization."]', 'Light reflected from the top and bottom surfaces of the thin film interferes, so some colours are reinforced and others cancelled.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f4d4f89f-5a9e-4a8a-aa69-5b3c51d16493', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). It was evident to whoever listened to his speech that he also had <u>an axe to grind</u>.', null, '["an account to settle with someone","a tool or something to sharpen","a bone to pick with someone","a personal objective to achieve"]', 3, '''An axe to grind'' = personal objective.', true, '2026-10-24 01:02:07.336', '2026-10-24 01:02:07.336', null, null, null, '(Choose the most appropriate interpretation). It was evident to whoever listened to his speech that he also had <u>an axe to grind</u>.', '["an account to settle with someone","a tool or something to sharpen","a bone to pick with someone","<u>a personal objective to achieve</u>"]', '''An <b>axe to grind</b>'' = <b>personal objective</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f4e0f2a1-92ae-4f62-9a84-f5e4a4f4b7db', 'Financial Accounting', 'UTME', null, 2004, null, 'Calculate the closing stock under FIFO method.', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841741/questions/pe6ay1tyhtii1es09q5m.jpg', '["N875","N675","N600","N300"]', 1, 'The closing stock under FIFO method is N675.', true, '2026-10-12 22:00:02.542', '2026-10-12 22:00:02.542', null, null, null, 'Calculate the closing stock under FIFO method.', '["N875","<b>N675</b>","N600","N300"]', 'The closing stock under FIFO method is <b>N675</b>.', '{"bold":["N675"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f4f17812-c57b-4c6e-8c3b-76d3d65a0ab4', 'Biology', 'JAMB', null, 2026, null, 'Fossil records found in sedimentary rocks offer some explanation for the theory of evolution because', null, '["the deposits have remains of organisms characteristic of when they were formed","most animal and plant fossils bear little resemblance to present-day living specimens","different strata have remains of organisms of the same kind","only organisms with strong parts are fossilized"]', 0, 'Sedimentary rock layers (strata) form sequentially over time, with deeper layers being older. Fossils found in each layer represent organisms that lived during that specific geological period, providing a chronological record of life''s history. This stratigraphic succession demonstrates that life forms have changed over time, with simpler organisms found in older layers and more complex ones in newer layers, supporting evolutionary theory. The other options contain inaccuracies or incomplete statements about fossils.', true, '2026-09-09 03:18:16.759', '2026-09-09 03:18:16.759', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f512f636-7020-4bba-bf34-005203afafaa', 'Biology', 'JAMB', null, 2011, null, 'The conversion of a nutrient into a molecule in the body of a consumer is referred to as', null, '["digestion","assimilation","absorption","inhibition."]', 1, 'Conversion of nutrients into molecules is assimilation.', true, '2026-10-12 20:59:42.103', '2026-10-12 20:59:42.103', null, null, null, 'The conversion of a nutrient into a molecule in the body of a consumer is referred to as', '["digestion","assimilation","absorption","inhibition."]', 'Conversion of nutrients into molecules is assimilation.', '{"bold":["assimilation"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f51cfae8-93ef-4424-9498-2de75d9da8b1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Members of the panel were working <u>at cross purposes</u>.', null, '["in harmony","in disunity","for selfish purpose","for selfless purposes"]', 1, 'At cross purposes = in disunity.', true, '2026-10-24 01:04:01.245', '2026-10-24 01:04:01.245', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Members of the panel were working <u>at cross purposes</u>.', '["in harmony","<u>in disunity</u>","for selfish purpose","for selfless purposes"]', '<b>At cross purposes</b> = <b>in disunity</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f522fd35-8740-4eb6-b6c4-bb7a94f97741', 'Hausa', 'JAMB', null, 2010, null, 'Abin da ya mamaye labarin Shahiu Umar shi ne', null, '["noma da kiwo","bauta da cinikin bayi","karatu da almajiranci","farauta da noman rake."]', 1, 'Abin da ya mamaye labarin shi ne bauta da cinikin bayi.', true, '2026-10-13 10:37:25.211', '2026-10-13 10:37:25.211', null, null, null, 'Abin da ya mamaye labarin Shahiu Umar shi ne', '["noma da kiwo","bauta da cinikin bayi","karatu da almajiranci","farauta da noman rake."]', 'Abin da ya mamaye labarin shi ne bauta da cinikin bayi.', '{"bold":["bauta da cinikin bayi"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5298702-4847-4634-822a-7a8c321d939c', 'Physics', 'JAMB', null, 1990, null, 'One of the properties of the earth''s magnetic field is that the', null, '["North pole lies in the northern hemisphere","Geographic and magnetic meridians coincide","Earth''s magnetic flux is entirely horizontal at a place where the magnetic vertical dip is zero.","Earth''s magnetic flux is entirely vertical at a place where the magnetic dip is zero."]', 2, 'At the magnetic equator the dip angle is zero, so the field lines are parallel to the surface (horizontal).', true, '2026-10-12 19:15:31.571', '2026-10-12 19:15:31.571', null, null, null, 'One of the properties of the earth''s magnetic field is that the', '["North pole lies in the northern hemisphere","Geographic and magnetic meridians coincide","Earth''s magnetic flux is entirely horizontal at a place where the magnetic vertical dip is zero.","Earth''s magnetic flux is entirely vertical at a place where the magnetic dip is zero."]', 'At the magnetic equator the dip angle is zero, so the field lines are parallel to the surface (horizontal).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f53676c1-93e0-40e5-89f6-e2f4dd5d315b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The professor''s thesis was the <u>precursor</u> of nuclear studies.', null, '["preliminary","climax","developer","forerunner"]', 3, 'Precursor = forerunner.', true, '2026-10-24 01:03:58.054', '2026-10-24 01:03:58.054', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The professor''s thesis was the <u>precursor</u> of nuclear studies.', '["preliminary","climax","developer","<u>forerunner</u>"]', '<b>Precursor</b> = <b>forerunner</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f547f5bb-c4eb-4387-8ac5-66e55c6b2509', 'Biology', 'JAMB', null, 2011, null, 'The type of asexual reproduction that is common to both Paramecium and protists is', null, '["budding","sporulation","fragmentation","fission."]', 3, 'Fission is common to both Paramecium and protists.', true, '2026-10-12 20:59:42.813', '2026-10-12 20:59:42.813', null, null, null, 'The type of asexual reproduction that is common to both Paramecium and protists is', '["budding","sporulation","fragmentation","fission."]', 'Fission is common to both Paramecium and protists.', '{"bold":["Fission"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f54b15d9-4b9d-4235-b53f-f432ae93e222', 'Economics', 'JAMB', null, 2026, null, '______ states that as more and more units of a variable factor are used with a given quantity of fixed factors, the average and marginal product of the variable factor will eventually decline', null, '["Law of diminishing returns","law of diminishing marginal productivity","Law of diminishing marginal utility","Law of variable proportions","A and D"]', 4, 'The law of diminishing returns (also called law of variable proportions) states this principle.', true, '2026-09-12 11:00:54.387', '2026-09-12 11:00:54.387', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f55f1d2c-062d-432f-9515-e67fc208970f', 'Literature in English', 'JAMB', null, 2026, null, '"The pen is mightier than the sword" is an example of', null, '["Metonymy","Alliteration","Paradox","Metaphor"]', 0, '"The pen is mightier than the sword" is an example of metonymy. Metonymy is a figure of speech where one thing is substituted for something closely associated with it. ''Pen'' represents writing, ideas, and communication, while ''sword'' represents military force, violence, and war. The statement means that communication and ideas are more powerful than violence.', true, '2026-09-10 10:45:33.538', '2026-09-10 10:45:33.538', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f56db34d-bd62-4000-8ec4-9586921e5316', 'Physics', 'JAMB', null, 2003, null, 'When a nucleus is formed by bringing protons and neutrons together, the actual mass of the formed nucleus is less than the sum of the masses of the constituent protons and neutrons. The energy equivalent of this mass difference is the', null, '["Stability","Lost energy","Work function","Binding energy"]', 3, 'The mass defect, converted to energy by E = mc², is the binding energy of the nucleus.', true, '2026-10-12 19:15:57.559', '2026-10-12 19:15:57.559', null, null, null, 'When a nucleus is formed by bringing protons and neutrons together, the actual mass of the formed nucleus is less than the sum of the masses of the constituent protons and neutrons. The energy equivalent of this mass difference is the', '["Stability","Lost energy","Work function","Binding energy"]', 'The mass defect, converted to energy by E = mc<sup>2</sup>, is the binding energy of the nucleus.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f57bb11c-35b2-4f5e-83a1-d64e6b5ffc5c', 'Government', 'JAMB', null, 2026, null, 'A party can be said to have national outlook if', null, '["it is ethnical but has branches all over the state","its membership cut across ethnic boundaries","it is registered by the electoral commission as a national party","it is headed by individuals who are famous within and without the country"]', 1, 'A party can be said to have a national outlook if its membership cuts across ethnic boundaries. A truly national party draws members from all ethnic groups, regions, and sections of the country. This ensures that the party represents the interests of the entire nation rather than a particular ethnic or regional group. Registration by the electoral commission is a legal requirement but does not guarantee national outlook if membership remains ethnically homogeneous.', true, '2026-09-10 10:44:17.493', '2026-09-10 10:44:17.493', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f57c8157-d9fb-4646-ba56-a45ee0a4098c', 'Economics', 'JAMB', null, 2026, null, 'Middlemen in the economy perform the function of', null, '["protection","distribution","hoarding","exchange"]', 1, 'Middlemen in the economy perform the function of distribution. Middlemen (wholesalers and retailers) bridge the gap between producers and consumers. They transport goods, store them, break bulk, and make goods available to consumers at convenient locations. While they facilitate exchange, their primary function is distribution. They do not primarily perform protection or hoarding functions.', true, '2026-09-10 10:42:55.56', '2026-09-10 10:42:55.56', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f582dafa-c45a-4837-a5a7-c7e75c939ef4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Aduke: Ngozi, let''s visit the market. Ngozi: <u>If you insist</u>, Aduke.', null, '["is very willing to accompany Aduke","must accompany Aduke","is not keen on going with Aduke","is pretending not to be interested in going with Aduke"]', 2, '''If you insist'' shows reluctance.', true, '2026-10-24 01:03:58.135', '2026-10-24 01:03:58.135', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Aduke: Ngozi, let''s visit the market. Ngozi: <u>If you insist</u>, Aduke.', '["is very willing to accompany Aduke","must accompany Aduke","<u>is not keen on going with Aduke</u>","is pretending not to be interested in going with Aduke"]', '''<b>If you insist</b>'' shows <b>reluctance</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5833b1d-5685-4045-8ab8-d0ad9c8200fa', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Tolu and Chinedu <u>live in each other''s pockets</u>.', null, '["They are long-term business partners","They steal from each other","They blackmail each other","They are very close to each other"]', 3, '''Live in each other''s pockets'' = very close to each other.', true, '2026-10-24 01:04:23.186', '2026-10-24 01:04:23.186', null, null, null, '(Choose the most appropriate interpretation). Tolu and Chinedu <u>live in each other''s pockets</u>.', '["They are long-term business partners","They steal from each other","They blackmail each other","<u>They are very close to each other</u>"]', '''<b>Live in each other''s pockets</b>'' = <b>very close to each other</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f58a6463-cbbf-4943-8a1e-4437889e1f97', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Science may be a complicated area of learning, but its teaching needs to be <u>demystified</u>.', null, '["simplified","twisted","made difficult","distorted"]', 2, 'Demystified = simplified; opposite = made difficult.', true, '2026-10-24 07:21:15.193', '2026-10-24 07:21:15.193', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Science may be a complicated area of learning, but its teaching needs to be <u>demystified</u>.', '["simplified","twisted","made difficult","distorted"]', 'Demystified = simplified; opposite = made difficult.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f58d484a-a31d-49b3-a4f5-4b9f7da8431a', 'English Language', 'JAMB', null, 2024, null, 'Yesterday, my mother asked me ______?', null, '["are you tired?","If I am tired?","whether was I tired?","if I was tired?"]', 3, 'In reported speech, the question becomes a statement with "if I was tired."', true, '2026-09-18 09:24:04.722', '2026-09-18 09:24:04.722', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5a0e818-23f5-43f5-88e9-d8f08677f248', 'English Language', 'JAMB', null, 2007, null, 'The police <u>--------------</u> happy about the dwindling crime rate.', null, '["says they are","say it is","say they are","says it is"]', 2, '''Police'' plural â†’ say they are.', true, '2026-10-24 01:02:13.754', '2026-10-24 01:02:13.754', null, null, null, 'The police <u>--------------</u> happy about the dwindling crime rate.', '["says they are","say it is","<u>say they are</u>","says it is"]', '''<b>Police</b>'' plural â†’ <b>say they are</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5a2cdce-b0fd-47cb-b749-f6b8959a2317', 'English Language', 'JAMB', null, 2024, null, 'If I had seen you, I ______ the mail. I) will send II) would send III) would had sent IV) would have sent', null, '["ii & iv","ii only","iii only","iv only"]', 3, 'The third conditional uses "would have sent."', true, '2026-09-18 09:34:04.014', '2026-09-18 09:34:04.014', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5a4ff1d-45bc-46f2-a31b-6bc4dc1a29df', 'Economics', 'JAMB', null, 2026, null, 'In the long-run, a firm must shut down if its average revenue is;', null, '["Greater than average cost","Less than average variable cost","Equal to average cost","Equal to total cost"]', 1, 'A firm shuts down if average revenue is less than average variable cost.', true, '2026-09-12 11:02:11.917', '2026-09-12 11:02:11.917', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5ab45d6-ee4e-48a1-b06b-38220cc78571', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''In a short time, you think to make me a Christian?'' Who said this statement?', null, '["Claudius Lysias","Felix the governor","King Agrippa","Festus the governor"]', 2, 'King Agrippa said this statement to Paul. After Paul presented his defense and testimony, Agrippa said, ''In a short time you think to make me a Christian!''', true, '2026-09-12 09:46:06.893', '2026-09-12 09:46:06.893', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5b54a2a-89fa-44c0-8e07-52fb1ea269d8', 'Financial Accounting', 'UTME', null, 2002, null, 'The value of closing stock as at February 14th by simple average method is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841114/questions/jppok8cniimdsihdbc6k.jpg', '["N3900","N2500","N4100","N2700"]', 1, 'There is only one supply between Jan and Feb 14th. The balance as at the date is 100 units @ 25. Thus, we have 25 x 100 = 2500.', true, '2026-10-12 21:59:58.696', '2026-10-12 21:59:58.696', null, null, null, 'The value of closing stock as at February 14th by simple average method is', '["N3900","<b>N2500</b>","N4100","N2700"]', 'There is only one supply between Jan and Feb 14th. The balance as at the date is 100 units @ 25. Thus, we have 25 x 100 = <b>2500</b>.', '{"bold":["2500"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5b94137-582a-4589-a803-9cc2aa63fe3d', 'Literature in English', 'JAMB', null, 2026, null, 'The repetition of consonant sounds at the end of words is called', null, '["Alliteration","Assonance","Consonance","Refrain"]', 2, 'It is consonance.', true, '2026-09-12 11:14:14.601', '2026-09-12 11:14:14.601', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5bf38e4-74db-4a7c-bb65-c753276935ae', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. In May 1978 the rain fell <u>incessantly</u> and made life drab.', null, '["at intervals","recurrently","repeatedly","concurrently","continuously"]', 4, 'Incessantly = continuously.', true, '2026-10-24 01:03:53.382', '2026-10-24 01:03:53.382', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. In May 1978 the rain fell <u>incessantly</u> and made life drab.', '["at intervals","recurrently","repeatedly","concurrently","<u>continuously</u>"]', '<b>Incessantly</b> = <b>continuously</b>.', '{}');
