insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5da93f8-4b0d-468b-af56-8669f87fb9c5', 'General Mathematics', 'JAMB', null, 2026, null, 'The gradient of the line joining (x,4) and (1,2) is 1/2. Find the value of x', null, '["5","3","-3","-5"]', 0, '(4-2)/(x-1) = 1/2. 2/(x-1) = 1/2. x-1 = 4. x = 5.', true, '2026-09-12 11:44:25.304', '2026-09-12 11:44:25.304', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5e11c5c-8c61-4a39-95c4-f310aef9a03b', 'Chemistry', 'JAMB', null, 2026, null, 'It''s not desirable to use lead tetraethyl as an anti-knock agents because', null, '["it''s expensive","of pollution effects from the exhaust fumes","it lowers the octane rating of petrol","it''s explosive"]', 1, 'Tetraethyl lead releases toxic lead compounds into the air via engine exhaust, posing severe environmental and neurological health hazards.', true, '2026-09-09 17:12:45.336', '2026-09-09 17:12:45.336', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5e47d99-ff86-4d93-ad14-46674e048b71', 'English Language', 'JAMB', null, 2024, null, 'It can be inferred from the passage that', null, '["Every task can eventually result in fatigue","Only difficult lessons lead to fatigue","A labourer must work all day before expressing fatigue","Rest is needed only when you experience fatigue"]', 0, 'The passage states that everyone is tired or fatigued at some time, implying every task can result in fatigue.', true, '2026-09-18 10:16:10.298', '2026-09-18 10:16:10.298', '02a05385-eb73-4b9c-9707-f8f4d3c6be8c', 3, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5e637b9-6f96-46b5-9f8a-197392016f8e', 'Economics', 'JAMB', null, 2026, null, '______ refers to the total number of people living within a country a geographical area at a particular time', null, '["Total number of people","population","Popular opinion","none of the above"]', 1, 'Population is the total number of people living in a geographical area at a particular time.', true, '2026-09-12 11:00:56.193', '2026-09-12 11:00:56.193', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f5fa2bcc-5523-4e13-956f-24458127f25c', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'When the wall of Jerusalem was broken down, the survivors who escaped the exile were in great', null, '["Frustration","trouble and shame","disappointment","confusion and dismay"]', 1, 'Nehemiah received a report that the survivors were in great trouble and shame.', true, '2026-09-12 10:41:42.595', '2026-09-12 10:41:42.595', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f60e2c8f-d206-4e59-9848-c4663fab3911', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Moses'' reluctance at his call was primarily due to his', null, '["lack of faith","old age","speech impediment","ignorance of God"]', 2, 'Moses was reluctant at his call because he had a speech impediment. He said to God, ''Oh, my Lord, I am not eloquent, either heretofore or since thou hast spoken to thy servant; but I am slow of speech and of tongue'' (Exodus 4:10).', true, '2026-09-12 09:45:45.871', '2026-09-12 09:45:45.871', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f60ec434-1dd0-41a1-8cea-6e592ce3a2f2', 'Physics', 'JAMB', null, 1998, null, 'Find the work done in moving a 2 C charge between two points X and Y in an electric field if the potential difference is 100 volts.', null, '["50 J","100 J","200 J","400 J"]', 2, 'W = QV = 2 x 100 = 200 J.', true, '2026-10-12 19:15:46.483', '2026-10-12 19:15:46.483', null, null, null, 'Find the work done in moving a 2 C charge between two points X and Y in an electric field if the potential difference is 100 volts.', '["50 J","100 J","200 J","400 J"]', 'W = QV = 2 x 100 = 200 J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f60efb51-5b3d-477b-81b0-761670c16d4b', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What did God use to confirm His promise to Abraham in Genesis 15?', null, '["thunder and lightning","a rainbow","a flaming torch and a smoking firepot","a burning bush"]', 2, 'God confirmed His promise to Abraham in Genesis 15 by passing between the divided animal pieces as a flaming torch and a smoking firepot. This was a covenant ratification ceremony.', true, '2026-09-12 09:45:51.406', '2026-09-12 09:45:51.406', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f616d659-693b-440a-b629-029a5e224e47', 'English Language', 'JAMB', null, 2024, null, 'What was Bepo''s experience after leaving Beesway?', null, '["he left the teaching profession","he immediately started a new school","he struggled to find a job","he joined a new school as a teacher"]', 2, 'Bepo struggled to find a job after leaving Beesway.', true, '2026-09-18 09:43:02.776', '2026-09-18 09:43:02.776', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f61cce12-90f0-4ead-b4f6-e0110d8692d4', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Amos emphasised that true religion must include', null, '["sacrifices","fasting","temple worship","justice and righteousness"]', 3, 'Amos declared, ''Let justice roll down like waters, and righteousness like an ever-flowing stream.''', true, '2026-09-12 10:40:55.559', '2026-09-12 10:40:55.559', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f62dce1d-3661-410e-b768-590195240ce4', 'Economics', 'JAMB', null, 2026, null, 'An economic system in which most capital goods are owned by individuals and private firms is known as', null, '["planned economy","capitalist economy","Mixed economy","socialist economy"]', 1, 'An economic system in which most capital goods are owned by individuals and private firms is known as a capitalist economy. In capitalism, the means of production are privately owned and operated for profit. Market forces of supply and demand determine what is produced, how it is produced, and for whom. The government plays a minimal role in economic decisions. A planned economy has state ownership, a mixed economy combines both, and a socialist economy has collective ownership.', true, '2026-09-10 10:42:00.45', '2026-09-10 10:42:00.45', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f6338926-6d5a-4403-bd02-458bb0322b4d', 'Government', 'JAMB', null, 2026, null, 'Promotion and discipline of civil servants is the responsibility of the', null, '["federal Character Commission","Ministry of Labour","Civil Service Commission","Public Complaints"]', 2, 'Promotion and discipline of civil servants is the responsibility of the Civil Service Commission. The Civil Service Commission is the body responsible for the recruitment, promotion, discipline, and welfare of civil servants. It ensures that appointments and promotions are based on merit and that disciplinary procedures are fair. The Federal Character Commission ensures equitable representation, the Ministry of Labour deals with labor matters, and the Public Complaints Commission handles maladministration complaints.', true, '2026-09-10 10:44:17.867', '2026-09-10 10:44:17.867', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f634081f-6a2b-4502-90d1-9fdbef221cf3', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The headmaster decided to <u>make good</u> his promise to the students.', null, '["fulfill","improve","complete","realize"]', 0, '''Make good'' = fulfill.', true, '2026-10-24 01:04:18.307', '2026-10-24 01:04:18.307', null, null, null, '(Choose the most appropriate interpretation). The headmaster decided to <u>make good</u> his promise to the students.', '["<u>fulfill</u>","improve","complete","realize"]', '''<b>Make good</b>'' = <b>fulfill</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f63d19f5-961c-4536-9efc-2661bf43d80b', 'Physics', 'JAMB', null, 1999, null, 'In Fleming''s right-hand rule, the thumb, the forefinger and the middle finger held mutually at right angles represent respectively the', null, '["Motion, the field and induced current","Induced current, the motion and the field","Field, the induced current and the motion","Induced current, the field and the motion."]', 0, 'Fleming''s right-hand (dynamo) rule: thumb = motion of the conductor, forefinger = magnetic field, middle finger = induced current.', true, '2026-10-12 19:15:48.253', '2026-10-12 19:15:48.253', null, null, null, 'In Fleming''s right-hand rule, the thumb, the forefinger and the middle finger held mutually at right angles represent respectively the', '["Motion, the field and induced current","Induced current, the motion and the field","Field, the induced current and the motion","Induced current, the field and the motion."]', 'Fleming''s right-hand (dynamo) rule: thumb = motion of the conductor, forefinger = magnetic field, middle finger = induced current.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f645785d-01de-4f0c-905d-3a0417276ece', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adebayo''s plans for the future are <u>in the air</u>.', null, '["suspended","uncertain","empty","floating"]', 1, 'In the air = uncertain.', true, '2026-10-24 01:01:48.018', '2026-10-24 01:01:48.018', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adebayo''s plans for the future are <u>in the air</u>.', '["suspended","<u>uncertain</u>","empty","floating"]', '<b>In the air</b> = <b>uncertain</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f649c500-ccd4-4824-afd7-67e40ec8334c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The circular <u>supersedes</u> all previous correspondence on the matter.', null, '["supports","displaces","eliminates","circumvent"]', 1, 'Supersedes = displaces.', true, '2026-10-24 01:01:58.029', '2026-10-24 01:01:58.029', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The circular <u>supersedes</u> all previous correspondence on the matter.', '["supports","<u>displaces</u>","eliminates","circumvent"]', '<b>Supersedes</b> = <b>displaces</b>.', '{}');
