insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f66d8126-9c83-4648-bdc5-0ca05220b9cf', 'Government', 'JAMB', null, 2026, null, 'The structure of the African Union includes', null, '["The Court of Justice, Pan Africa Congress and People''s Assembly","People''s Assembly, Humanitarian Board and the Peace and Security Council","Pan African Parliament, the Court of Justice, and the Peace and Security Council","Specialized Technical Commission, the Court of Justice and Humanitarian Board"]', 2, 'The AU structure includes the Pan African Parliament, Court of Justice, and Peace and Security Council.', true, '2026-09-12 11:24:40.453', '2026-09-12 11:24:40.453', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f6728459-fedf-4d8e-9f27-d03c7e410077', 'Biology', 'JAMB', null, 2026, null, 'Which of the following organisms is mainly found in the marine habitat?', null, '["Achatina","Tilapia","Dog fish","Tortoise"]', 2, 'Dog fish (a type of small shark) is mainly found in the marine (saltwater) habitat. Achatina is a land snail found in terrestrial habitats. Tilapia is primarily found in freshwater habitats. Tortoises are terrestrial reptiles. Dogfish are elasmobranch fish (cartilaginous fish) that live in marine environments. They are named for their dog-like teeth and are common in coastal waters. Their marine habitat is defined by saltwater conditions.', true, '2026-09-09 03:19:00.356', '2026-09-09 03:19:00.356', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f68dbb87-7b2f-4e4f-9145-2230d1607b7a', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Joshua''s first victory was over the people of', null, '["Ai","Gibeon","Gilgal","Jericho"]', 3, 'Joshua''s first victory was over Jericho.', true, '2026-09-12 10:41:34.807', '2026-09-12 10:41:34.807', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f690ed7d-8782-4f27-98b2-411e3f58f9f5', 'Physics', 'JAMB', null, 1994, null, 'An object of mass 50 kg is released from a height of 2 m. Find the kinetic energy just before it strikes the ground.', null, '["250 J","1 000 J","10 000 J","100 000 J"]', 1, 'KE = mgh = 50 x 10 x 2 = 1 000 J.', true, '2026-10-12 19:15:38.997', '2026-10-12 19:15:38.997', null, null, null, 'An object of mass 50 kg is released from a height of 2 m. Find the kinetic energy just before it strikes the ground.', '["250 J","1 000 J","10 000 J","100 000 J"]', 'KE = mgh = 50 x 10 x 2 = 1 000 J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f69248e6-db6b-419e-9e95-ef7595cd7cf7', 'Physics', 'JAMB', null, 2002, null, 'The radiator of a motor car is cooled by', null, '["Radiation and conduction","Radiation","Conduction","Convection"]', 3, 'Hot water circulates in the radiator by convection, and the air stream carries heat away.', true, '2026-10-12 19:15:53.487', '2026-10-12 19:15:53.487', null, null, null, 'The radiator of a motor car is cooled by', '["Radiation and conduction","Radiation","Conduction","Convection"]', 'Hot water circulates in the radiator by convection, and the air stream carries heat away.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f69879a2-de7b-4197-9103-4344c45f2d19', 'Physics', 'JAMB', null, 1993, null, 'A plane inclined at angle θ has a velocity ratio of 10 : 1. The inclination of the plane to the horizontal is given by', null, '["tan θ = 1/10","cot θ = 1/10","cos θ = 1/10","sin θ = 1/10"]', 3, 'For an inclined plane VR = 1/sin θ = 10, so sin θ = 1/10.', true, '2026-10-12 19:15:37.27', '2026-10-12 19:15:37.27', null, null, null, 'A plane inclined at angle θ has a velocity ratio of 10 : 1. The inclination of the plane to the horizontal is given by', '["tan θ = 1/10","cot θ = 1/10","cos θ = 1/10","sin θ = 1/10"]', 'For an inclined plane VR = 1/sin θ = 10, so sin θ = 1/10.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f69907a3-7dac-433b-8b98-878b7b99d2c7', 'Biology', 'JAMB', null, 2026, null, 'Which of the following organs produces bile?', null, '["Gall bladder","Pancreas","Spleen","Liver","Stomach"]', 3, 'Bile is produced by the liver. The liver cells (hepatocytes) synthesize bile continuously, which is then stored and concentrated in the gall bladder until needed for digestion. Bile contains bile salts, bilirubin, cholesterol, and other substances that help emulsify fats during digestion. The pancreas produces digestive enzymes and hormones like insulin and glucagon. The spleen is involved in immune function and blood filtration. The stomach produces gastric juices containing pepsin and hydrochloric acid.', true, '2026-09-09 03:18:25.72', '2026-09-09 03:18:25.72', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f69be40b-9197-4745-b9dd-68bd57f5983e', 'English Language', 'JAMB', null, 2007, null, 'The child''s recent training has not been very effective; he is likely to <u>__________</u> to his old habits', null, '["revert","convert","reverse","revise"]', 0, 'Correct spelling: revert.', true, '2026-10-24 07:21:41.295', '2026-10-24 07:21:41.295', null, null, null, 'The child''s recent training has not been very effective; he is likely to <u>__________</u> to his old habits', '["revert","convert","reverse","revise"]', 'Correct spelling: revert.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f6a29455-ba22-4f0b-8a5d-d64d72b38a20', 'English Language', 'JAMB', null, 2024, null, 'Choose the option that best completes the gap: Is it true that Okoro ______ when the gates were closed?', null, '["had returned","would return","should return","would have returned"]', 0, '"Had returned" is the past perfect tense appropriate for an action completed before another past action.', true, '2026-09-18 09:24:04.877', '2026-09-18 09:24:04.877', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f6a9d0b0-53d2-4e2b-b44e-8741beded1d3', 'Biology', 'JAMB', null, 2026, null, 'An organism having one pair of identical genes is', null, '["A heterozygote","A hybrid","An allelomorph","A homozygote","A diploid"]', 3, 'A homozygote is an organism that has two identical alleles for a particular gene (e.g., TT for tallness or tt for shortness). These identical alleles occupy the same locus on homologous chromosomes. A heterozygote (or hybrid) has two different alleles for a gene (Tt). Allelomorph is another term for an allele, referring to alternative forms of a gene. A diploid refers to having two sets of chromosomes, which is not specific to having identical or different alleles.', true, '2026-09-09 03:18:20.762', '2026-09-09 03:18:20.762', null, null, null, null, null, null, null);
