insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('f71710f4-e27f-4314-b09f-183e172eeb17', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Everybody <u>respects</u> the team leader.', null, '["looks up for","looks up on","looks up to","looks up at"]', 2, 'Respects = looks up to.', true, '2026-10-24 01:01:41.834', '2026-10-24 01:01:41.834', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Everybody <u>respects</u> the team leader.', '["looks up for","looks up on","<u>looks up to</u>","looks up at"]', '<b>Respects</b> = <b>looks up to</b>.', '{}');
