insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fb341337-e412-436e-b531-75eb1907fbf6', 'Physics', 'JAMB', null, 1995, null, 'The pitch of an acoustic device can be increased by', null, '["Increasing the frequency","Increasing the amplitude","Decreasing the loudness","Decreasing the intensity"]', 0, 'Pitch depends on frequency. A higher frequency gives a higher pitch.', true, '2026-10-12 19:15:41.736', '2026-10-12 19:15:41.736', null, null, null, 'The pitch of an acoustic device can be increased by', '["Increasing the frequency","Increasing the amplitude","Decreasing the loudness","Decreasing the intensity"]', 'Pitch depends on frequency. A higher frequency gives a higher pitch.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
