insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fb451c0c-da99-4c07-ae36-bc07271e0565', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The principal warned us against <u>burning the candle at both ends</u>.', null, '["being careless with candles","wearing ourselves out","being too generous","disloyalty"]', 1, '''Burning candle at both ends'' = exhausting oneself.', true, '2026-10-24 01:02:06.485', '2026-10-24 01:02:06.485', null, null, null, '(Choose the most appropriate interpretation). The principal warned us against <u>burning the candle at both ends</u>.', '["being careless with candles","<u>wearing ourselves out</u>","being too generous","disloyalty"]', '''<b>Burning candle at both ends</b>'' = <b>exhausting oneself</b>.', '{}');
