insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fb4e9491-b003-4148-9ba9-d45881b85f9a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He was not able to <u>withstand</u> the attack from his immediate family.', null, '["survive","overcome","match","resist"]', 3, 'Withstand = resist.', true, '2026-10-24 01:01:55.862', '2026-10-24 01:01:55.862', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He was not able to <u>withstand</u> the attack from his immediate family.', '["survive","overcome","match","<u>resist</u>"]', '<b>Withstand</b> = <b>resist</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fb512f9d-d3d7-4af1-b192-0899efaf0c76', 'Physics', 'JAMB', null, 2026, null, 'Which of the following is false?', null, '["a body''s mass is constant while its weight is variable","the larger the gap between two masses the smaller the attractive force of gravity between them","gravitational force is always attractive","A body''s weight is directly proportional to its mass","none of the above"]', 4, 'All the statements are true. Mass is constant, weight varies with gravity. Gravitational force decreases with distance. Gravitational force is always attractive. Weight is directly proportional to mass (W=mg). So ''none of the above'' is false, meaning it''s the correct answer.', true, '2026-09-10 10:56:44.388', '2026-09-10 10:56:44.388', null, null, null, null, null, null, null);
