insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fbaca5d1-55b5-412a-b17a-e5b9b261f6b6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ngozi spoke to her father quite <u>candidly</u> on her proposed marriage.', null, '["frankly","faithfully","rudely","respectfully"]', 0, 'Candidly = frankly.', true, '2026-10-24 01:01:45.791', '2026-10-24 01:01:45.791', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ngozi spoke to her father quite <u>candidly</u> on her proposed marriage.', '["<u>frankly</u>","faithfully","rudely","respectfully"]', '<b>Candidly</b> = <b>frankly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fbada7d2-38e8-420f-8341-5e4c53d8a5e2', 'Physics', 'JAMB', null, 2026, null, 'Fluid pressure is', null, '["Horizontally constant and varies co-sinusly vertically","Vertically constant and directly proportional to Horizontal position and not proportional to shape","Vertically constant and inversely proportional to Horizontal position","Horizontally constant and Constantly vertical","Pressure at all points at the same level is the same"]', 4, 'Fluid pressure at all points at the same level is the same. This is a fundamental property of fluids at rest. Pressure increases with depth but is constant horizontally at any given depth. This is why liquid levels in connected vessels are the same.', true, '2026-09-10 10:56:43.793', '2026-09-10 10:56:43.793', null, null, null, null, null, null, null);
