insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fbb85096-c2f6-485e-906c-4a0f1c709479', 'Literature in English', 'JAMB', null, 2026, null, 'What does Antony mean by ''bridegroom in my death''?', null, '["He plans to marry before dying","He welcomes death as lovingly as meeting a bride","He dreams of a royal wedding","He wants to be buried beside Cleopatra"]', 1, 'He welcomes death as lovingly as meeting a bride.', true, '2026-09-12 11:11:26.319', '2026-09-12 11:11:26.319', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fbbfa539-705a-40fa-91bb-eb8a2adca9e1', 'Financial Accounting', 'UTME', null, 2002, null, 'Determine the club''s excess of income over expenditure.', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791840989/questions/oioxmewg1xbk9becrace.jpg', '["N12000","N13800","N15000","N16000"]', 1, 'Excess of income over expenditure = N13800.', true, '2026-10-12 21:59:58.104', '2026-10-12 21:59:58.104', null, null, null, 'Determine the club''s excess of income over expenditure.', '["N12000","<b>N13800</b>","N15000","N16000"]', 'Excess of income over expenditure = <b>N13800</b>.', '{"bold":["N13800"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fbd1090b-6c97-41c4-8f6d-942fe8a2fdda', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The director''s remark was extremely <u>apposite</u> to the issue being discussed.', null, '["inconsequential","emphatic","adequate","appropriate"]', 3, 'Apposite = appropriate.', true, '2026-10-24 01:04:07.082', '2026-10-24 01:04:07.082', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The director''s remark was extremely <u>apposite</u> to the issue being discussed.', '["inconsequential","emphatic","adequate","<u>appropriate</u>"]', '<b>Apposite</b> = <b>appropriate</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fbd500ae-cfff-4026-a460-79433da46b1c', 'Physics', 'JAMB', null, 1991, null, 'The spiral spring of a spring balance is 25.0 cm long when 5 N hangs on it and 30.0 cm long when the weight is 10 N. What is the length of the spring if the weight is 3 N, assuming Hooke''s Law is obeyed?', null, '["15.0 cm","17.0 cm","20.0 cm","23.0 cm"]', 3, 'An extra 5 N gives 5 cm, so 1 cm per newton. At 5 N the extension is 5 cm, so the natural length is 20 cm. At 3 N the length is 20 + 3 = 23.0 cm.', true, '2026-10-12 19:15:32.866', '2026-10-12 19:15:32.866', null, null, null, 'The spiral spring of a spring balance is 25.0 cm long when 5 N hangs on it and 30.0 cm long when the weight is 10 N. What is the length of the spring if the weight is 3 N, assuming Hooke''s Law is obeyed?', '["15.0 cm","17.0 cm","20.0 cm","23.0 cm"]', 'An extra 5 N gives 5 cm, so 1 cm per newton. At 5 N the extension is 5 cm, so the natural length is 20 cm. At 3 N the length is 20 + 3 = 23.0 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fbd935af-927b-4ce0-9daa-3f2d24c97d16', 'Biology', 'JAMB', null, 2026, null, 'A mammal with red fur and long ears was crossed with another having white fur and short ears. If the offspring had red fur and short ears, the', null, '["characters are linked","characters are not linked","parents are not related","parents are related"]', 0, 'The traits for fur color and ear length were inherited together, indicating they are linked genes on the same chromosome.', true, '2026-09-09 02:56:41.324', '2026-09-09 02:56:41.324', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fbe585df-9b50-4e6d-bad5-13e379b3cef1', 'Literature in English', 'JAMB', null, 2026, null, 'Which of the following best explains the effect of alliteration in poetry?', null, '["It creates rhythm and musicality","It compares two unlike things directly","It exaggerates reality","It contradicts meaning"]', 0, 'Alliteration creates rhythm and musicality.', true, '2026-09-12 11:14:13.659', '2026-09-12 11:14:13.659', null, null, null, null, null, null, null);
