insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fc181885-0197-4fa7-a1f8-efa87f0c1834', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Who was the first judge of Israel after Joshua''s death?', null, '["Ehud","Othniel","Deborah","Gideon"]', 1, 'Othniel was the first judge of Israel after Joshua''s death. He was Caleb''s nephew and delivered Israel from the hand of Cushan-rishathaim, king of Mesopotamia.', true, '2026-09-12 09:45:49.71', '2026-09-12 09:45:49.71', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fc193a5f-e9c8-479b-886e-a6ed51ffb4f3', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is used to test for the presence of lime in a soil sample?', null, '["NaOH","H2SO4","HCl","HNO3"]', 2, 'Hydrochloric acid (HCl) reacts with calcium carbonate (lime) to produce effervescence (carbon dioxide gas).', true, '2026-09-09 02:56:44.894', '2026-09-09 02:56:44.894', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fc3014c9-d550-4f58-a161-24f513c23a95', 'Biology', 'JAMB', null, 2026, null, 'The chromosome number of a cell before and after meiosis is conventionally represented as', null, '["2n → 2n","n → n","n → 2n","2n → n"]', 3, 'Meiosis is a reductional division where the chromosome number is halved. A diploid cell (2n) divides to form four haploid cells (n). Before meiosis, the cell has 2n chromosomes (homologous pairs). After meiosis, the gametes have n chromosomes. This reduction is essential for sexual reproduction, ensuring that when gametes fuse during fertilization, the diploid number is restored in the zygote. Mitosis maintains the chromosome number (2n → 2n).', true, '2026-09-09 03:18:57.891', '2026-09-09 03:18:57.891', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fc3871fb-1915-4bb1-a881-8147c578ace9', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The president made a <u>passionate</u> appeal for calm.', null, '["inflamed","disturbing","intense","lively"]', 2, 'Passionate = intense.', true, '2026-10-24 01:01:44.262', '2026-10-24 01:01:44.262', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The president made a <u>passionate</u> appeal for calm.', '["inflamed","disturbing","<u>intense</u>","lively"]', '<b>Passionate</b> = <b>intense</b>.', '{}');
