insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fcddfda8-b8ab-4ac7-845a-a74d8e74fcae', 'Hausa', 'JAMB', null, 2010, null, 'Jigon wakar ''Mu Sha Falala'' ta Sarkin Zazzau Aliyu Dansidi a WaKoŝin Hausa, shi ne', null, '["yabo","kasuwanci","fađakarwa","siyasa."]', 0, 'Jigon wakar shi ne yabo.', true, '2026-10-13 10:37:25.481', '2026-10-13 10:37:25.481', null, null, null, 'Jigon wakar ''Mu Sha Falala'' ta Sarkin Zazzau Aliyu Dansidi a WaKoŝin Hausa, shi ne', '["yabo","kasuwanci","fađakarwa","siyasa."]', 'Jigon wakar shi ne yabo.', '{"bold":["yabo"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fce07c99-ced4-466a-ae7d-073e36096ae3', 'Physics', 'JAMB', null, 1990, null, 'Three cells each of e.m.f. 1.5 V and an internal resistance of 1.0 Ω are connected in parallel across a load resistance of 2.67 Ω. Calculate the current in the load.', null, '["0.26 A","0.41 A","0.50 A","0.79 A."]', 2, 'Three identical cells in parallel give e.m.f. 1.5 V with internal resistance 1/3 = 0.33 Ω. I = 1.5/(2.67 + 0.33) = 0.50 A.', true, '2026-10-12 19:15:31.732', '2026-10-12 19:15:31.732', null, null, null, 'Three cells each of e.m.f. 1.5 V and an internal resistance of 1.0 Ω are connected in parallel across a load resistance of 2.67 Ω. Calculate the current in the load.', '["0.26 A","0.41 A","0.50 A","0.79 A."]', 'Three identical cells in parallel give e.m.f. 1.5 V with internal resistance 1/3 = 0.33 Ω. I = 1.5/(2.67 + 0.33) = 0.50 A.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fce2fe04-e5ed-4fa9-9bf6-d690672c6011', 'Physics', 'JAMB', null, 2002, null, 'A ray of light which strikes a glass slab from air at normal incidence passes through the slab', null, '["Undeviated and displaced at a faster speed","Undeviated and undisplaced at a lower speed","Deviated and undisplaced at a lower speed","Deviated and displaced at a lower speed."]', 1, 'At normal incidence the angle of incidence is zero, so the ray goes straight through without bending or sideways shift. Its speed is lower in glass.', true, '2026-10-12 19:15:53.214', '2026-10-12 19:15:53.214', null, null, null, 'A ray of light which strikes a glass slab from air at normal incidence passes through the slab', '["Undeviated and displaced at a faster speed","Undeviated and undisplaced at a lower speed","Deviated and undisplaced at a lower speed","Deviated and displaced at a lower speed."]', 'At normal incidence the angle of incidence is zero, so the ray goes straight through without bending or sideways shift. Its speed is lower in glass.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fceb8be5-4e83-4c60-b8c6-e29dd6b5b318', 'Physics', 'JAMB', null, 1985, null, 'A 45° triangular glass prism can be used as a reflector of light because', null, '["Refraction never takes place in such a prism","The angle of reflection equals the angle of incidence.","The refractive index of glass is less than 1","It is transparent","The critical angle for glass is less than 45°"]', 4, 'Light entering the 45° prism meets the long face at 45°. Since the critical angle of glass (about 42°) is less than 45°, total internal reflection occurs.', true, '2026-10-12 19:15:21.907', '2026-10-12 19:15:21.907', null, null, null, 'A 45° triangular glass prism can be used as a reflector of light because', '["Refraction never takes place in such a prism","The angle of reflection equals the angle of incidence.","The refractive index of glass is less than 1","It is transparent","The critical angle for glass is less than 45°"]', 'Light entering the 45° prism meets the long face at 45°. Since the critical angle of glass (about 42°) is less than 45°, total internal reflection occurs.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fcf5f435-b15b-401d-a097-0192293fe3ec', 'Financial Accounting', 'UTME', null, 2002, null, 'Control accounts help to verify the arithmetic accuracy of the postings from the', null, '["subsidiary book into the trial balance","ledgers into the trial balance","Journals into the ledger","subsidiary books into the ledgers"]', 3, 'Figures in control accounts are posted from subsidiary books. It can easily detect from control account if there is any mistake.', true, '2026-10-12 21:59:58.794', '2026-10-12 21:59:58.794', null, null, null, 'Control accounts help to verify the arithmetic accuracy of the postings from the', '["subsidiary book into the trial balance","ledgers into the trial balance","Journals into the ledger","<b>subsidiary books into the ledgers</b>"]', 'Figures in control accounts are posted from subsidiary books. It can easily detect from control account if there is any mistake, verifying postings from <b>subsidiary books into the ledgers</b>.', '{"bold":["subsidiary books into the ledgers"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fcf84651-3447-4c1b-834b-89ce7573ae0b', 'Literature in English', 'JAMB', null, 2026, null, 'Which of the following themes is most central to the poem Night?', null, '["friendship","fear of the unknown","love for nature","political oppression"]', 1, 'The most central theme is fear of the unknown.', true, '2026-09-12 11:12:13.607', '2026-09-12 11:12:13.607', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fcf99b9d-6bd4-497a-8366-b35c3a459f0d', 'English Language', 'JAMB', null, 2024, null, '(Emphatic Stress) The traditional chief NARRATED the story to the children.', null, '["The children heard the story from the traditional chief","who narrated the story to the children?","The children could not listen to the story by the chief","Did the chief hide the story from the children?"]', 1, 'The emphasis on "NARRATED" answers the question of who performed the action.', true, '2026-09-18 09:34:04.003', '2026-09-18 09:34:04.003', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fcfcc8a0-a1ac-49b1-b3d2-8adc1e28d14f', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''But you will receive power when the Holy Spirit will come upon you and you will be my witness in Jerusalem and in all Judea and Samaria and to the end of the earth.'' This statement commissions the apostles to', null, '["establish the church in Jewish cities","preach only to the Jews","carry the gospel to all continents","preach to the Gentiles in and outside Palestine"]', 3, 'This statement commissions the apostles to preach to the Gentiles in and outside Palestine. The commission includes Jerusalem, Judea, Samaria, and to the end of the earth, indicating a universal mission.', true, '2026-09-12 09:45:55.829', '2026-09-12 09:45:55.829', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fcfe7930-7a9a-433c-8217-61717cc16d41', 'Economics', 'JAMB', null, 2026, null, 'If two bags of rice were sold for #1,250 a month ago and two weeks later, the same amount was used to procure one bag. This simply means that the value of money is:', null, '["Increasing","Fluctuating","Decreasing","Constant"]', 2, 'The value of money is decreasing due to inflation.', true, '2026-09-12 11:01:33.674', '2026-09-12 11:01:33.674', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fd0118a5-df1c-485c-b409-1b60da9f8c68', 'Literature in English', 'JAMB', null, 2026, null, 'One of the important means available to writer of a literary work is', null, '["Diction","Fiction","Stage","Stanza"]', 0, 'Diction is an important means for a writer.', true, '2026-09-12 11:14:00.185', '2026-09-12 11:14:00.185', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fd0c2b47-8fab-40ed-b616-df2c3cb59753', 'Government', 'JAMB', null, 2026, null, 'Which of the following is not an organ of OAU?', null, '["Economic and social council","Secretariat","Council of ministers","Economic and social commission"]', 3, 'Economic and Social Commission is not an organ of the OAU (Organization of African Unity). The main organs of the OAU were the Assembly of Heads of State and Government, the Council of Ministers, the General Secretariat, and the Commission of Mediation, Conciliation and Arbitration. There was also an Economic and Social Commission, but it was a specialized commission, not a principal organ. The question asks which is not an organ, and the correct answer is Economic and Social Commission.', true, '2026-09-10 10:45:05.715', '2026-09-10 10:45:05.715', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fd186724-42c3-42a5-b628-011f24b957ca', 'Government', 'JAMB', null, 2026, null, 'ECOWAS was established on', null, '["May 25th, 1975 in Lagos","May 28th, 1957, Lome","May 28th, 1975 in Lagos","May 25th, 1975 in Lome"]', 0, 'ECOWAS (Economic Community of West African States) was established on May 25th, 1975 in Lagos, Nigeria. The treaty establishing ECOWAS was signed by 15 West African countries in Lagos. The organization was created to promote economic integration and cooperation among West African states. The correct date and venue are May 25th, 1975 in Lagos.', true, '2026-09-10 10:45:05.768', '2026-09-10 10:45:05.768', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fd2337a1-160b-4709-bc65-84ce135f9261', 'Economics', 'JAMB', null, 2026, null, 'Tight monetary policy refers to', null, '["Increasing government spending","Giving subsidies","Encouraging borrowing","Reducing money supply to curb inflation"]', 3, 'Tight monetary policy reduces money supply to curb inflation.', true, '2026-09-12 10:59:53.788', '2026-09-12 10:59:53.788', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fd25f36e-33bc-4a24-a7af-415a7575cf55', 'Physics', 'JAMB', null, 1994, null, 'The mass of a specific gravity bottle is 15.2 g when it is empty. It is 24.8 g when filled with kerosene and 27.2 g when filled with distilled water. Calculate the relative density of kerosene.', null, '["1.25","1.10","0.90","0.80"]', 3, 'Mass of kerosene = 24.8 - 15.2 = 9.6 g. Mass of water = 27.2 - 15.2 = 12.0 g. Relative density = 9.6/12.0 = 0.80.', true, '2026-10-12 19:15:39.318', '2026-10-12 19:15:39.318', null, null, null, 'The mass of a specific gravity bottle is 15.2 g when it is empty. It is 24.8 g when filled with kerosene and 27.2 g when filled with distilled water. Calculate the relative density of kerosene.', '["1.25","1.10","0.90","0.80"]', 'Mass of kerosene = 24.8 - 15.2 = 9.6 g. Mass of water = 27.2 - 15.2 = 12.0 g. Relative density = 9.6/12.0 = 0.80.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fd26ad3a-d225-4b65-9866-b9441c9eebac', 'Literature in English', 'JAMB', null, 2026, null, 'In the line: ''The silence screamed louder than the thunder,'' which device is most prominently used?', null, '["Paradox","Oxymoron","Personification","Hyperbole"]', 0, 'Paradox is most prominently used.', true, '2026-09-12 11:11:24.176', '2026-09-12 11:11:24.176', null, null, null, null, null, null, null);
