insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fd40a94b-ab42-4099-931f-0fc82deddb42', 'Biology', 'JAMB', null, 2003, null, 'An insect with a mandibulate mouthpart will obtain its food by', null, '["biting and chewing","chewing and sucking","chewing","sucking"]', 0, 'An insect with a mandibulate mouthpart bites and chews food.', true, '2026-10-12 20:59:33.947', '2026-10-12 20:59:33.947', null, null, null, 'An insect with a mandibulate mouthpart will obtain its food by', '["biting and chewing","chewing and sucking","chewing","sucking"]', 'An insect with a mandibulate mouthpart bites and chews food.', '{"bold":["bites and chews"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fd4a1cff-54eb-47d5-a654-e9090fb744ec', 'Physics', 'JAMB', null, 1992, null, 'A concave mirror has a radius of curvature of 36 cm. At what distance from the mirror should an object be placed to give a real image three times the size of the object?', null, '["12 cm","24 cm","48 cm","108 cm"]', 1, 'f = 18 cm. For a real image with m = 3, v = 3u. 1/18 = 1/u + 1/(3u) = 4/(3u), so u = 24 cm.', true, '2026-10-12 19:15:35.926', '2026-10-12 19:15:35.926', null, null, null, 'A concave mirror has a radius of curvature of 36 cm. At what distance from the mirror should an object be placed to give a real image three times the size of the object?', '["12 cm","24 cm","48 cm","108 cm"]', 'f = 18 cm. For a real image with m = 3, v = 3u. 1/18 = 1/u + 1/(3u) = 4/(3u), so u = 24 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
