insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fda6b544-c2a6-4d00-ab59-d1f431d9af94', 'English Language', 'JAMB', null, 2007, null, 'Musa has lived here for five years but he does not seem able to get over the enormously <u>__________</u> and elaborate rules that govern the society.', null, '["absurd","bizarre","fantastic","intricate"]', 3, 'Correct spelling: intricate.', true, '2026-10-24 07:21:38.388', '2026-10-24 07:21:38.388', null, null, null, 'Musa has lived here for five years but he does not seem able to get over the enormously <u>__________</u> and elaborate rules that govern the society.', '["absurd","bizarre","fantastic","intricate"]', 'Correct spelling: intricate.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fdb1131f-659b-4eb3-8171-0f99203099a1', 'Physics', 'JAMB', null, 1987, null, 'A galvanometer of resistance 20 Ω is to be provided with a shunt such that 1/10 of the whole current in a circuit passes through the galvanometer. The resistance of the shunt is', null, '["2.00 Ω","2.22 Ω","18.00 Ω","18.22 Ω"]', 1, 'The galvanometer carries I/10 and the shunt 9I/10. Voltages are equal: 20 x (I/10) = R x (9I/10), so R = 20/9 = 2.22 Ω.', true, '2026-10-12 19:15:26.514', '2026-10-12 19:15:26.514', null, null, null, 'A galvanometer of resistance 20 Ω is to be provided with a shunt such that 1/10 of the whole current in a circuit passes through the galvanometer. The resistance of the shunt is', '["2.00 Ω","2.22 Ω","18.00 Ω","18.22 Ω"]', 'The galvanometer carries I/10 and the shunt 9I/10. Voltages are equal: 20 x (I/10) = R x (9I/10), so R = 20/9 = 2.22 Ω.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fdb7ebbf-be73-4c74-b924-e06c5ee82f6c', 'Financial Accounting', 'UTME', null, 2001, null, 'Where a company acquires controlling shares of another and the consideration is paid in cash, the entries in the books of the purchases are debit', null, '["investment and credit cash","investment and credit shares","purchases and credit cash","purchases and credit shares"]', 0, 'The entries are debit investment and credit cash.', true, '2026-10-12 22:00:07.312', '2026-10-12 22:00:07.312', null, null, null, 'Where a company acquires controlling shares of another and the consideration is paid in cash, the entries in the books of the purchases are debit', '["<b>investment and credit cash</b>","investment and credit shares","purchases and credit cash","purchases and credit shares"]', 'The entries are debit <b>investment and credit cash</b>.', '{"bold":["investment and credit cash"],"italic":[],"underline":[],"fillBlanks":[]}');
