insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fddbce0d-28c8-4b21-84ee-043c93783ab3', 'General Mathematics', 'JAMB', null, 2026, null, 'Simplify (1/x⁻¹ ÷ 1/y⁻¹)⁻¹', null, '["x/y","y/x","-x/y","-y/x"]', 0, '(x ÷ y)⁻¹ = (x/y)⁻¹ = y/x. Wait, (1/x⁻¹ ÷ 1/y⁻¹) = x ÷ y = x/y. Then (x/y)⁻¹ = y/x.', true, '2026-09-12 11:43:47.786', '2026-09-12 11:43:47.786', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fddcc023-5019-4dd1-9962-f679f88e30d7', 'Chemistry', 'JAMB', null, 2026, null, 'The following are decomposed by heat except', null, '["sodium trioxocarbonate (IV)","ammonium trioxocarbonate (IV)","sodium hydrogen trioxocarbonate (IV)","calcium trioxocarbonate (IV)"]', 0, 'Group 1 alkali metal carbonates like sodium carbonate (Na2CO3) are thermally stable and do not decompose under normal laboratory heating conditions.', true, '2026-09-09 17:12:46.142', '2026-09-09 17:12:46.142', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fde18c87-010f-4342-9a4f-1406650fbb66', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Many species in creation have <u>mutated</u> over the years into new forms of life.', null, '["stabilized","manifested","transformed","standardized"]', 0, 'Mutated = changed; opposite = stabilized.', true, '2026-10-24 07:21:16.536', '2026-10-24 07:21:16.536', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Many species in creation have <u>mutated</u> over the years into new forms of life.', '["stabilized","manifested","transformed","standardized"]', 'Mutated = changed; opposite = stabilized.', '{}');
