insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fe4025a9-1149-4d24-b305-1ee268129ba1', 'Chemistry', 'JAMB', null, 2026, null, 'An example of hygroscopic substance is', null, '["NaOH","CuO","MgCl2","CaCl2"]', 1, 'Copper(II) oxide (CuO) absorbs moisture from the atmosphere without dissolving or forming a solution, making it hygroscopic.', true, '2026-09-09 17:12:45.285', '2026-09-09 17:12:45.285', null, null, null, null, null, null, null);
