insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fe5a6775-1696-448c-b301-13b95c493c39', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Paul was accused of apparently being a preacher of foreign divinities in Athens because he preached Jesus and the', null, '["Cross","Law","resurrection","second coming"]', 2, 'Paul preached Jesus and the resurrection in Athens.', true, '2026-09-12 10:41:49.218', '2026-09-12 10:41:49.218', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fe676c2c-39fb-4b98-b67d-12607c0ab496', 'Biology', 'JAMB', null, 2011, null, 'Which of the following organs regulates the levels of water, salts, hydrogen ions and urea in the mammalian blood?', null, '["Liver","Kidney","Bladder","Colon."]', 1, 'The kidney regulates water, salt, hydrogen ion and urea levels.', true, '2026-10-12 20:59:42.663', '2026-10-12 20:59:42.663', null, null, null, 'Which of the following organs regulates the levels of water, salts, hydrogen ions and urea in the mammalian blood?', '["Liver","Kidney","Bladder","Colon."]', 'The kidney regulates water, salt, hydrogen ion and urea levels.', '{"bold":["kidney"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fe913f70-4526-4350-bcd1-eb2136d09ad7', 'Economics', 'JAMB', null, 2026, null, 'Excessive money supply relative to goods and services leads to', null, '["Deflation","Economic growth","Inflation","Devaluation"]', 2, 'Excessive money supply chasing too few goods leads to inflation.', true, '2026-09-12 10:59:54.074', '2026-09-12 10:59:54.074', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('feb7423b-5e84-422d-829b-ffda9f9c6901', 'Government', 'JAMB', null, 2026, null, 'Which of the following countries has withdrawn her membership of the ECOWAS?', null, '["Guinea Bissau","Senegal","Mauritania","Burkina Faso"]', 2, 'Mauritania withdrew its membership from ECOWAS.', true, '2026-09-12 11:24:09.646', '2026-09-12 11:24:09.646', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fec58e81-c249-482c-b96c-adb0c333543b', 'Literature in English', 'JAMB', null, 2026, null, 'The imagery in Night contributes mainly to the creation of', null, '["Suspense and tension","Comic relief","Romantic atmosphere","Didactic instruction"]', 0, 'The imagery creates suspense and tension.', true, '2026-09-12 11:05:26.806', '2026-09-12 11:05:26.806', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fec6e750-f926-4d61-b293-04437f9a4996', 'Biology', 'JAMB', null, 2026, null, 'The average number of individuals of a species per unit area of the habitat is the', null, '["Population density","Population frequency","Population size","Population distribution"]', 0, 'Population density is the average number of individuals of a species per unit area or volume of habitat. It is a measure of how crowded a population is. Population frequency measures how often a species occurs in a given area. Population size refers to the total number of individuals. Population distribution refers to how individuals are spaced in a habitat (clumped, uniform, random). Population density is an important ecological parameter that affects competition, resource use, and population dynamics.', true, '2026-09-09 03:18:59.432', '2026-09-09 03:18:59.432', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fec8b1ad-c923-4864-bb04-582a8db51bac', 'Biology', 'JAMB', null, 2026, null, 'The protozoan Plasmodium falciparum is transmitted by', null, '["Female Anopheles mosquitoes","Female Aedes mosquitoes","Female Culex mosquitoes","Female blackfly"]', 0, 'Plasmodium falciparum, the parasite that causes malaria, is transmitted by female Anopheles mosquitoes. Only female Anopheles mosquitoes transmit malaria because they require a blood meal for egg development. Female Aedes mosquitoes transmit yellow fever and dengue fever. Female Culex mosquitoes transmit filariasis and West Nile virus. Blackflies transmit onchocerciasis (river blindness).', true, '2026-09-09 03:18:58.788', '2026-09-09 03:18:58.788', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fed2999d-ab82-4931-a5ec-3a082319e0f3', 'English Language', 'JAMB', null, 2007, null, 'You can never find Okwu; he is a very <u>__________</u> person', null, '["delusive","elusive","illusive","deceptive"]', 1, 'Correct spelling: elusive.', true, '2026-10-24 07:21:41.397', '2026-10-24 07:21:41.397', null, null, null, 'You can never find Okwu; he is a very <u>__________</u> person', '["delusive","elusive","illusive","deceptive"]', 'Correct spelling: elusive.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fedd5bff-74fe-484e-9a94-a94d2f61d3a4', 'Physics', 'JAMB', null, 1995, null, 'A body is projected from the earth''s surface with the intention of letting it escape from the earth''s gravitational field. What is the minimum escape velocity of the body?', null, '["14 km s⁻¹","13 km s⁻¹","12 km s⁻¹","11 km s⁻¹"]', 3, 'The escape velocity of the earth is about 11.2 km s⁻¹, so 11 km s⁻¹ is the closest.', true, '2026-10-12 19:15:40.826', '2026-10-12 19:15:40.826', null, null, null, 'A body is projected from the earth''s surface with the intention of letting it escape from the earth''s gravitational field. What is the minimum escape velocity of the body?', '["14 km s<sup>-1</sup>","13 km s<sup>-1</sup>","12 km s<sup>-1</sup>","11 km s<sup>-1</sup>"]', 'The escape velocity of the earth is about 11.2 km s<sup>-1</sup>, so 11 km s<sup>-1</sup> is the closest.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fedf5f9b-0150-4a85-a29d-702cfd8ad00c', 'Biology', 'JAMB', null, 2026, null, 'The anatomical evidence usually used in support of an evolutionary relationship among whales, humans, birds and dogs is the possession of', null, '["thick skin","pentadactyl limb","tail","epidermal structure"]', 1, 'The anatomical evidence usually used in support of evolutionary relationship among whales, humans, birds, and dogs is the possession of the pentadactyl limb. The pentadactyl limb is a five-digit limb structure that is homologous in these groups, suggesting a common ancestor. Despite their different functions (swimming, grasping, flying, walking), the underlying bone structure is similar. This is evidence of divergent evolution from a common ancestor.', true, '2026-09-09 03:19:30.768', '2026-09-09 03:19:30.768', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fee0eb4e-fa6f-4909-ab46-d7250e9385b0', 'Chemistry', 'JAMB', null, 2026, null, 'The liquid metal is/are i) mercury ii) potassium iii) sodium iv) silver', null, '["ii only","I only","iii only","iv and ii only"]', 1, 'Mercury is the only liquid metal at room temperature.', true, '2026-09-12 11:36:16.001', '2026-09-12 11:36:16.001', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('fee722c1-f14c-4f83-98c4-e4c209c19ba6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. I am optimistic about the interview though it was <u>a mind-bending</u> exercise.', null, '["a debilitating","a difficult","an easy","an enervating"]', 2, 'Mind-bending = difficult; opposite = easy.', true, '2026-10-24 07:21:26.035', '2026-10-24 07:21:26.035', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. I am optimistic about the interview though it was <u>a mind-bending</u> exercise.', '["a debilitating","a difficult","an easy","an enervating"]', 'Mind-bending = difficult; opposite = easy.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ff00557b-0eed-4fec-86d0-299630a916be', 'Physics', 'JAMB', null, 1987, null, 'Which of the following statements supports the assumption that light travels in straight lines?', null, '["Light can be diffracted","A source of light produces distinct shadows of opaque objects","A source of light produces interference patterns on a suitably placed screen.","Light can be reflected."]', 1, 'Sharp shadows of opaque objects show that light travels in straight lines. Diffraction and interference show wave behaviour.', true, '2026-10-12 19:15:25.87', '2026-10-12 19:15:25.87', null, null, null, 'Which of the following statements supports the assumption that light travels in straight lines?', '["Light can be diffracted","A source of light produces distinct shadows of opaque objects","A source of light produces interference patterns on a suitably placed screen.","Light can be reflected."]', 'Sharp shadows of opaque objects show that light travels in straight lines. Diffraction and interference show wave behaviour.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ff0a9994-ab7d-4729-8f7b-8624e5ec7dc7', 'Economics', 'JAMB', null, 2026, null, 'Which of the following expressions best describes the GDP at factor cost?', null, '["GDP - subsidies + indirect taxes","GDP - Indirect taxes + subsidies","GDP + Indirect taxes + subsidies","Indirect taxes + Subsidies - GDP","Subsidies - indirect taxes + GDP"]', 1, 'GDP at factor cost = GDP at market prices - Indirect taxes + subsidies. GDP at factor cost measures the total income earned by factors of production (wages, rent, interest, profit). GDP at market prices includes indirect taxes and excludes subsidies. To convert from market prices to factor cost, subtract indirect taxes and add subsidies.', true, '2026-09-10 10:41:21.152', '2026-09-10 10:41:21.152', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ff0afb41-c8f7-4e7d-82ef-b2801c2dd3b2', 'Chemistry', 'JAMB', null, 2026, null, 'Smoke is? i) gas dispersed in solid ii) solid dispersed in gas iii) gas dispersed in liquid iv) liquid dispersed in gas', null, '["I only","ii only","iv only","iii only"]', 1, 'Smoke is solid particles dispersed in gas.', true, '2026-09-12 11:36:18.003', '2026-09-12 11:36:18.003', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ff230c61-0cf8-433f-bd93-7a1db9b441ef', 'Physics', 'JAMB', null, 1990, null, 'A 0-10 mA galvanometer with a coil resistance of 30 Ω can be converted to a 0-10 A ammeter by using', null, '["0.03 Ω series resistor","0.03 Ω shunt resistor","9.99 Ω shunt resistor","9.99 Ω series resistor"]', 1, 'The shunt carries 10 - 0.01 = 9.99 A at the same voltage: Rs = (0.01 x 30)/9.99 = 0.03 Ω, connected in parallel (a shunt).', true, '2026-10-12 19:15:32.109', '2026-10-12 19:15:32.109', null, null, null, 'A 0-10 mA galvanometer with a coil resistance of 30 Ω can be converted to a 0-10 A ammeter by using', '["0.03 Ω series resistor","0.03 Ω shunt resistor","9.99 Ω shunt resistor","9.99 Ω series resistor"]', 'The shunt carries 10 - 0.01 = 9.99 A at the same voltage: R<sub>s</sub> = (0.01 x 30)/9.99 = 0.03 Ω, connected in parallel (a shunt).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ff3afd38-7716-4284-8d1f-86dfc15cd542', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The lady who won the beauty contest had <u>a good gait</u>.', null, '["stature","figure","elegance","carriage"]', 3, '''Gait'' = manner of walking/carriage.', true, '2026-10-24 01:04:21.903', '2026-10-24 01:04:21.903', null, null, null, '(Choose the most appropriate interpretation). The lady who won the beauty contest had <u>a good gait</u>.', '["stature","figure","elegance","<u>carriage</u>"]', '''<b>Gait</b>'' = <b>manner of walking/carriage</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ff4040e6-b26b-4d80-900d-77c5e73eb0f8', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The Decalogue was given to the Israelites at', null, '["Horeb","Sinai","Gilgal","Shiloh"]', 1, 'The Ten Commandments were given to Moses on Mount Sinai.', true, '2026-09-12 10:40:53.446', '2026-09-12 10:40:53.446', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ff483f7e-e480-44cc-92ef-6697fe623927', 'Financial Accounting', 'UTME', null, 2003, null, 'Given: I. order of performance II. order of liquidity III. Vertical order IV. Horizontal order. The orders in which a balance assets is arranged are', null, '["I and II","I and IV","II and III","III and IV"]', 3, 'A balance sheet can be arranged whether in vertical or horizontal orders.', true, '2026-10-12 21:59:59.83', '2026-10-12 21:59:59.83', null, null, null, 'Given: I. order of performance II. order of liquidity III. Vertical order IV. Horizontal order. The orders in which a balance assets is arranged are', '["I and II","I and IV","II and III","<b>III and IV</b>"]', 'A balance sheet can be arranged whether in <b>vertical or horizontal orders</b>.', '{"bold":["vertical or horizontal orders"],"italic":[],"underline":[],"fillBlanks":[]}');
