insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ff73da5e-368c-48b2-80c5-b5f6c36bd1a2', 'Literature in English', 'JAMB', null, 2026, null, 'The role of the Storyteller in the play primarily serves to', null, '["Represent colonial authority and control","Provide comic relief without influencing the plot","Bridge the gap between the audience and the dramatic action through commentary and direction","Act as a silent observer of events"]', 2, 'The Storyteller bridges the gap between the audience and the dramatic action.', true, '2026-09-12 11:11:59.828', '2026-09-12 11:11:59.828', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ff7e0c12-da45-4abf-a22f-c533606cb91e', 'Government', 'JAMB', null, 2026, null, 'The head of the districts in the Hausa/Fulani Empire were the', null, '["Emirs of Gwandu and Sokoto","Galadima","Hakimi","Sarkin Ruwa"]', 2, 'The Hakimi was the head of the districts in the Hausa/Fulani Empire.', true, '2026-09-12 11:23:59.132', '2026-09-12 11:23:59.132', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ffa764e9-5315-4649-bc46-8290e1395aa4', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The president said that the country was <u>not out of the _______________ yet</u>', null, '["forest","fog","water","wood"]', 3, '''Not out of the woods'' = still in difficulty.', true, '2026-10-24 01:02:11.424', '2026-10-24 01:02:11.424', null, null, null, '(Choose the most appropriate interpretation). The president said that the country was <u>not out of the _______________ yet</u>', '["forest","fog","water","<u>wood</u>"]', '''<b>Not out of the woods</b>'' = <b>still in difficulty</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ffa9af13-5c50-4979-95c7-dddcc197f61d', 'Financial Accounting', 'UTME', null, 2001, null, 'Determine the total of the trial balance.', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841980/questions/b96fewzclfpctd0d0cql.jpg', '["N335,050","N333,050","N323,050","N230,550"]', 1, 'The total of the trial balance is N333,050.', true, '2026-10-12 22:00:04.313', '2026-10-12 22:00:04.313', null, null, null, 'Determine the total of the trial balance.', '["N335,050","<b>N333,050</b>","N323,050","N230,550"]', 'The total of the trial balance is <b>N333,050</b>.', '{"bold":["N333,050"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ffb204bb-9b14-4195-adf2-32578a5398b0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His has been a life of <u>make-belief</u>.', null, '["faith","fantasy","grandeur","religion"]', 1, 'Make-belief = fantasy.', true, '2026-10-24 01:03:55.487', '2026-10-24 01:03:55.487', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His has been a life of <u>make-belief</u>.', '["faith","<u>fantasy</u>","grandeur","religion"]', '<b>Make-belief</b> = <b>fantasy</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ffb25fec-70aa-4792-b945-68b46f6f010b', 'General Mathematics', 'JAMB', null, 2026, null, 'If the 5th term of an AP is 17 and 9th term is 33, what is the 15th term?', null, '["47","57","53","61"]', 1, 'a+4d = 17. a+8d = 33. 4d = 16. d = 4. a = 1. T15 = 1 + 14(4) = 57.', true, '2026-09-12 11:43:51.155', '2026-09-12 11:43:51.155', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ffb5eaa5-fa9f-47c5-b61f-378ecfc97aba', 'Yoruba', 'JAMB', null, 2007, null, 'Ilé-ayé ò jè nykan, Àlà lásán ni, Òkàn tó þ sùn ti dòkú, Nykan ò rí bí a ti rò ó Ilé-ayé gbçgè. Sàréè ì ýopin èdá. Eérú fún eérú, Eruku fún eruku, Lôba-òkè sô fênìyàn, Tó j’Òlörun nípè. Àmò hùwà bí çni pé, Ojoojúmò lèdá p súnmòlé. Màà gbèkèké òlá Màà nígbçkèlé nínú òrõ. Alágbára ayé, ç rõra ýe. Bí ó ti wù ká ki lòkàn tó, Kìkì ní í lù, Báa bá gbòlù ikú, Àtorin arò ti p kòjá lóde. Ojú ogun layé. Má bojú wèyìn, Jà bí akin lójù ìjà. Rántí ayé àkòni tó kòjà, Wo àwòkòyè wòn fún òjò òla tìrç. Gbé ìgbé-ayé alààyè, Jè kí òkú sunkún ara wòn. Àwé, má ronú mò, Jè ká máa ììyé lò. Máa jagun lò, Má wèyìn, Má ìyìè méjì, Bó pè, bó yá, Ayõ p bõ. Nibo ni akewi fi we ojú ijà?', null, '["Ilé ayé","Ojú ogun","Örun","Sàréè."]', 0, 'Akewi fi ilé ayé we ojú ijà.', true, '2026-10-13 13:23:30.972', '2026-10-13 13:23:30.972', null, null, null, 'Ilé-ayé ò jè nykan, Àlà lásán ni, Òkàn tó þ sùn ti dòkú, Nykan ò rí bí a ti rò ó Ilé-ayé gbçgè. Sàréè ì ýopin èdá. Eérú fún eérú, Eruku fún eruku, Lôba-òkè sô fênìyàn, Tó j’Òlörun nípè. Àmò hùwà bí çni pé, Ojoojúmò lèdá p súnmòlé. Màà gbèkèké òlá Màà nígbçkèlé nínú òrõ. Alágbára ayé, ç rõra ýe. Bí ó ti wù ká ki lòkàn tó, Kìkì ní í lù, Báa bá gbòlù ikú, Àtorin arò ti p kòjá lóde. Ojú ogun layé. Má bojú wèyìn, Jà bí akin lójù ìjà. Rántí ayé àkòni tó kòjà, Wo àwòkòyè wòn fún òjò òla tìrç. Gbé ìgbé-ayé alààyè, Jè kí òkú sunkún ara wòn. Àwé, má ronú mò, Jè ká máa ììyé lò. Máa jagun lò, Má wèyìn, Má ìyìè méjì, Bó pè, bó yá, Ayõ p bõ. Nibo ni akewi fi we ojú ijà?', '["Ilé ayé","Ojú ogun","Örun","Sàréè."]', 'Akewi fi ilé ayé we ojú ijà.', '{"bold":["ilé ayé"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ffb73980-b6d8-4fd2-8a4d-1ae589695dbd', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Solomon’s treaty with Hiram, King of Tyre was meant to...', null, '["Protect Israel when at war","Build Pitham and store cities","Help build the temple","Help establish trade links"]', 2, '1 Kings 5 details Solomon''s agreement with King Hiram of Tyre to supply cedar and cypress timber along with skilled craftsmen to help construct the Temple in Jerusalem.', true, '2026-09-09 17:18:24.545', '2026-09-09 17:18:24.545', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ffc5c721-b380-449f-831c-d166833e6fb0', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Joseph interpreted Pharaoh''s dream as predicting', null, '["famine and war","seven years of abundance and famine","invasion of Egypt","death of Pharaoh"]', 1, 'Joseph interpreted Pharaoh''s dream of seven fat cows and seven thin cows as seven years of abundance followed by seven years of severe famine in Egypt. This interpretation led to Joseph being appointed as governor to prepare for the famine.', true, '2026-09-12 09:45:44.874', '2026-09-12 09:45:44.874', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ffc62f0c-0da6-44bc-a3c0-206cf2e52a8f', 'Biology', 'JAMB', null, 2026, null, 'A farmer''s assumption that the seed from a good harvest will produce a good yield is explained by the theory of', null, '["evolution","adaptation","variation","hereditary"]', 3, 'A farmer''s assumption that the seed from a good harvest will produce a good yield is explained by the theory of heredity. The good traits of the parent plants are passed on to the offspring through genes. Heredity is the transmission of genetic traits from parents to offspring. Evolution is the change in populations over time. Adaptation is the process by which organisms become better suited to their environment. Variation is the differences among individuals.', true, '2026-09-09 03:19:22.117', '2026-09-09 03:19:22.117', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ffd343c1-5be7-4d1a-a8a1-771f22a3c3dd', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The type is <u>typical</u> of a lazy teacher.', null, '["symptomatic","universal","characteristic","incontestable"]', 2, 'Typical = characteristic.', true, '2026-10-24 01:04:07.456', '2026-10-24 01:04:07.456', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The type is <u>typical</u> of a lazy teacher.', '["symptomatic","universal","<u>characteristic</u>","incontestable"]', '<b>Typical</b> = <b>characteristic</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ffd9c56c-5493-48b1-9fa7-f0c0e5364b1b', 'Biology', 'JAMB', null, 0, null, 'answer the question abocve ', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791839966/questions/se1opafngbtxlxewixvk.jpg', '["a","b","c","d"]', 3, 'Part I points to the cervical vertebrae located in the neck region.   Part II points to the lumbar vertebrae located in the lower back region, which are the largest bones of the spinal column responsible for supporting body weight.   ', true, '2026-10-12 21:19:58.721', '2026-10-12 21:19:58.721', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ffffdc00-b6c4-40fc-994e-4f88dc83ba9d', 'Literature in English', 'JAMB', null, 2026, null, 'The technique found in drama in which the audience knows what the actor does not know is called', null, '["stage direction","dramatic irony","setting","improvisation"]', 1, 'The technique found in drama in which the audience knows what the actor does not know is called dramatic irony. Dramatic irony occurs when the audience has information that the characters on stage lack, creating tension, suspense, or humor. For example, in Romeo and Juliet, the audience knows Juliet is not dead, but Romeo does not. Stage direction is instructions in the script, setting is the time and place, and improvisation is unscripted performance.', true, '2026-09-10 10:45:34.344', '2026-09-10 10:45:34.344', null, null, null, null, null, null, null);